{
  "name": "OGM Hava Araçları Yönetim Sistemi",
  "description": "Orman Genel Müdürlüğü hava araçları durum takip, bakım yönetimi ve faaliyet takvimi portalı.",
  "requestFramePermissions": [
    "camera"
  ]
}

export enum PlatformType {
  H = 'H',
  SA = 'S-A',
  DA = 'D-A',
  SL = 'S-L',
  DL = 'D-L'
}

export enum Status {
  FAAL = 'FAAL',
  GAYRI_FAAL = 'GAYRI FAAL'
}

export enum StatusType {
  BAKIM = 'BAKIM',
  ARIZA = 'ARIZA',
  DIGER = 'DIGER',
  NONE = '-'
}

export interface MaintenanceHour {
  bakimTuru: string;
  kalanSaat: number;
}

export interface Aircraft {
  cagriKodu: string;
  kuyrukNo: string;
  platformTipi: PlatformType;
  durum: Status;
  durumTipi: StatusType;
  durumAyrintisi: string;
  konum: string;
  faydaliSaat: number;
  durumBaslangic: string;
  durumBitis?: string;
  aciklama: string;
  guncellemeTarihi: string;
  // Technical Specs
  seriNo: string;
  motor: string;
  uretimYili: number;
  base: string;
  maintenanceHours: MaintenanceHour[];
  photos: string[];
}

export interface ActivityLog {
  tarih: string;
  kuyrukNo: string;
  durum: Status;
  durumTipi: StatusType;
  ayrinti: string;
  konum: string;
  aciklama: string;
}

import { GoogleGenAI } from "@google/genai";
import { Aircraft } from "../types";

const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

export const analyzeFleetStatus = async (fleet: Aircraft[]) => {
  const fleetSummary = fleet.map(a => 
    `${a.kuyrukNo} (${a.cagriKodu}): ${a.durum}, Konum: ${a.konum}, Faydalı Saat: ${a.faydaliSaat}`
  ).join('\n');

  const response = await ai.models.generateContent({
    model: 'gemini-2.0-flash-exp',
    contents: `Aşağıdaki OGM hava araçları filosunu analiz et ve kısa bir özet çıkar. Bakımı yaklaşanları ve gayri faal olanları belirt: \n\n${fleetSummary}`,
  });

  return response.text;
};

import React from 'react';

