          <div className="flex items-center space-x-3">
            <div className="bg-white p-1 rounded-full">
               <img src="https://picsum.photos/seed/ogmlogo/40/40" alt="OGM Logo" className="w-8 h-8 rounded-full" />
            </div>
            <div>
              <h1 className="font-bold text-lg leading-none">OGM HAVA ARAÇLARI</h1>
              <span className="text-xs text-green-200">Durum Takip & Bakım Yönetimi</span>
            </div>
          </div>
          <div className="text-sm font-medium">
             {new Date().toLocaleDateString('tr-TR', { day: '2-digit', month: '2-digit', year: 'numeric' })}
          </div>
