export default Layout;

import React from 'react';
import { PieChart, Pie, Cell, ResponsiveContainer, Tooltip } from 'recharts';
import { Aircraft, Status } from '../types';

interface DashboardProps {
  fleet: Aircraft[];
}

const Dashboard: React.FC<DashboardProps> = ({ fleet }) => {
  const total = fleet.length;
  const faal = fleet.filter(a => a.durum === Status.FAAL).length;
  const gayriFaal = total - faal;

  const chartData = [
    { name: 'Faal', value: faal, color: '#2e7d32' },
    { name: 'Gayrı Faal', value: gayriFaal, color: '#c62828' },
  ];

  return (
    <div className="grid grid-cols-1 md:grid-cols-4 gap-4 mb-8">
      <div className="bg-white p-5 rounded-xl shadow-sm border border-gray-100 flex flex-col justify-center items-center">
        <span className="text-gray-500 text-sm font-medium uppercase">Toplam Filo</span>
        <span className="text-4xl font-bold text-gray-800">{total}</span>
      </div>
      <div className="bg-white p-5 rounded-xl shadow-sm border border-gray-100 flex flex-col justify-center items-center">
        <span className="text-green-600 text-sm font-medium uppercase">Faal</span>
        <span className="text-4xl font-bold text-green-700">{faal}</span>
      </div>
      <div className="bg-white p-5 rounded-xl shadow-sm border border-gray-100 flex flex-col justify-center items-center">
        <span className="text-red-600 text-sm font-medium uppercase">Gayrı Faal</span>
        <span className="text-4xl font-bold text-red-700">{gayriFaal}</span>
      </div>
      <div className="bg-white p-3 rounded-xl shadow-sm border border-gray-100 h-32">
        <ResponsiveContainer width="100%" height="100%">
          <PieChart>
            <Pie
              data={chartData}
              cx="50%"
              cy="50%"
              innerRadius={25}
              outerRadius={40}
              paddingAngle={5}
              dataKey="value"
            >
              {chartData.map((entry, index) => (
                <Cell key={`cell-${index}`} fill={entry.color} />
              ))}
            </Pie>
            <Tooltip />
          </PieChart>
        </ResponsiveContainer>
      </div>
    </div>
  );
};

export default Dashboard;

import React, { useState } from 'react';
import { Aircraft, Status, StatusType } from '../types';

interface MaintenanceFormProps {
  aircraft: Aircraft;
  onSave: (updated: Partial<Aircraft>) => void;
  onCancel: () => void;
}

const MaintenanceForm: React.FC<MaintenanceFormProps> = ({ aircraft, onSave, onCancel }) => {
  const [formData, setFormData] = useState({
    durum: aircraft.durum,
    durumTipi: aircraft.durumTipi,
    durumAyrintisi: aircraft.durumAyrintisi,
    konum: aircraft.konum,
    aciklama: aircraft.aciklama
  });

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    onSave({
      ...formData,
      guncellemeTarihi: new Date().toISOString().replace('T', ' ').substring(0, 16)
    });
  };

  return (
    <div className="fixed inset-0 z-[100] flex items-center justify-center bg-black/50 backdrop-blur-sm p-4">
      <form onSubmit={handleSubmit} className="bg-white w-full max-w-md rounded-2xl overflow-hidden shadow-2xl animate-in fade-in slide-in-from-bottom-4">
        <div className="bg-[#1b5e20] text-white p-4">
          <h2 className="text-lg font-bold">Durum Güncelle: {aircraft.kuyrukNo}</h2>
        </div>

        <div className="p-6 space-y-4">
          <div>
            <label className="block text-xs font-bold text-gray-500 uppercase mb-1">Durum</label>
            <select 
              value={formData.durum}
              onChange={(e) => setFormData({...formData, durum: e.target.value as Status})}
              className="w-full p-2 border rounded-lg bg-gray-50 font-medium"
            >
              <option value={Status.FAAL}>FAAL</option>
              <option value={Status.GAYRI_FAAL}>GAYRI FAAL</option>
            </select>
          </div>

          <div className="grid grid-cols-2 gap-4">
            <div>
              <label className="block text-xs font-bold text-gray-500 uppercase mb-1">Durum Tipi</label>
              <select 
                value={formData.durumTipi}
                onChange={(e) => setFormData({...formData, durumTipi: e.target.value as StatusType})}
                className="w-full p-2 border rounded-lg bg-gray-50 font-medium"
              >
                <option value={StatusType.NONE}>Yok</option>
                <option value={StatusType.BAKIM}>Bakım</option>
                <option value={StatusType.ARIZA}>Arıza</option>
                <option value={StatusType.DIGER}>Diğer</option>
              </select>
            </div>
            <div>
              <label className="block text-xs font-bold text-gray-500 uppercase mb-1">Konum</label>
              <input 
                type="text"
                value={formData.konum}
                onChange={(e) => setFormData({...formData, konum: e.target.value.toUpperCase()})}
                className="w-full p-2 border rounded-lg bg-gray-50 font-medium"
              />
            </div>
          </div>

          <div>
            <label className="block text-xs font-bold text-gray-500 uppercase mb-1">Ayrıntı</label>
            <input 
              type="text"
              value={formData.durumAyrintisi}
              placeholder="Örn: 200H Bakım, Motor Arızası"
              onChange={(e) => setFormData({...formData, durumAyrintisi: e.target.value})}
              className="w-full p-2 border rounded-lg bg-gray-50 font-medium"
            />
          </div>

          <div>
            <label className="block text-xs font-bold text-gray-500 uppercase mb-1">Açıklama</label>
            <textarea 
              value={formData.aciklama}
              onChange={(e) => setFormData({...formData, aciklama: e.target.value})}
              rows={3}
              className="w-full p-2 border rounded-lg bg-gray-50 font-medium"
              placeholder="Arıza detayları veya operasyonel notlar..."
            ></textarea>
          </div>
        </div>

        <div className="bg-gray-50 p-4 border-t flex justify-end space-x-3">
          <button type="button" onClick={onCancel} className="px-4 py-2 text-sm font-bold text-gray-500 hover:text-gray-700">İptal</button>
          <button type="submit" className="px-6 py-2 text-sm font-bold text-white bg-green-600 hover:bg-green-700 rounded-lg shadow-md">Kaydet</button>
        </div>
      </form>
    </div>
  );
};

export default MaintenanceForm;

import React, { useState, useEffect, useMemo } from 'react';
import Layout from './components/Layout';
import Dashboard from './components/Dashboard';
import AircraftDetailModal from './components/AircraftDetailModal';
import MaintenanceForm from './components/MaintenanceForm';
import { MOCK_AIRCRAFT, MOCK_ACTIVITY_LOGS } from './constants';
import { Aircraft, Status, StatusType } from './types';
import { analyzeFleetStatus } from './services/geminiService';

const App: React.FC = () => {
  const [fleet, setFleet] = useState<Aircraft[]>(MOCK_AIRCRAFT);
  const [selectedAircraft, setSelectedAircraft] = useState<Aircraft | null>(null);
  const [editingAircraft, setEditingAircraft] = useState<Aircraft | null>(null);
  const [searchTerm, setSearchTerm] = useState('');
  const [aiAnalysis, setAiAnalysis] = useState<string | null>(null);
  const [isAnalyzing, setIsAnalyzing] = useState(false);

  // Filter fleet based on search
  const filteredFleet = useMemo(() => {
    return fleet.filter(a => 
      a.kuyrukNo.toLowerCase().includes(searchTerm.toLowerCase()) ||
      a.cagriKodu.toLowerCase().includes(searchTerm.toLowerCase()) ||
      a.konum.toLowerCase().includes(searchTerm.toLowerCase())
    );
  }, [fleet, searchTerm]);

  const handleUpdateStatus = (updates: Partial<Aircraft>) => {
    if (!editingAircraft) return;
    setFleet(prev => prev.map(a => 
      a.kuyrukNo === editingAircraft.kuyrukNo ? { ...a, ...updates } : a
    ));
    setEditingAircraft(null);
  };

  const runAiAnalysis = async () => {
    setIsAnalyzing(true);
    try {
      const result = await analyzeFleetStatus(fleet);
      setAiAnalysis(result || "Analiz yapılamadı.");
    } catch (e) {
      setAiAnalysis("AI Analizi şu an kullanılamıyor.");
    } finally {
      setIsAnalyzing(false);
    }
  };

  return (
    <Layout>
      <Dashboard fleet={fleet} />

      {/* AI Assistant Banner */}
      <div className="mb-8 bg-gradient-to-r from-green-800 to-green-600 rounded-2xl p-6 text-white shadow-lg relative overflow-hidden">
        <div className="relative z-10 flex flex-col md:flex-row items-center justify-between gap-4">
           <div className="flex items-center">
             <div className="bg-white/20 p-3 rounded-full mr-4">
                <svg className="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M13 10V3L4 14h7v7l9-11h-7z" /></svg>
             </div>
             <div>
               <h2 className="text-xl font-bold">Akıllı Filo Analizi</h2>
               <p className="text-green-100 text-sm">Gemini AI tüm filonuzun durumunu analiz ederek riskleri raporlar.</p>
             </div>
           </div>
           <button 
             onClick={runAiAnalysis}
             disabled={isAnalyzing}
             className="bg-white text-green-800 px-6 py-2 rounded-full font-bold hover:bg-green-50 transition-colors shadow-xl disabled:opacity-50"
           >
             {isAnalyzing ? 'Analiz Ediliyor...' : 'Şimdi Analiz Et'}
           </button>
        </div>
        {aiAnalysis && (
          <div className="mt-4 p-4 bg-white/10 rounded-xl text-sm border border-white/20 animate-in fade-in slide-in-from-top-2">
             <div className="flex items-start">
                <svg className="w-4 h-4 mr-2 mt-0.5 shrink-0" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path d="M9 12l2 2 4-4m6 2a9 9 0 11-18 0 9 9 0 0118 0z" /></svg>
                <p className="leading-relaxed">{aiAnalysis}</p>
             </div>
          </div>
        )}
        <div className="absolute -right-10 -bottom-10 opacity-10">
          <svg className="w-64 h-64" fill="currentColor" viewBox="0 0 24 24"><path d="M12 2L4.5 20.29l.71.71L12 18l6.79 3 .71-.71L12 2z" /></svg>
        </div>
      </div>

      {/* List Header */}
      <div className="flex flex-col md:flex-row md:items-center justify-between mb-6 gap-4">
        <h3 className="text-lg font-bold text-gray-800 flex items-center">
           <svg className="w-5 h-5 mr-2 text-green-700" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path d="M19 11H5m14 0a2 2 0 012 2v6a2 2 0 01-2 2H5a2 2 0 01-2-2v-6a2 2 0 012-2m14 0V9a2 2 0 00-2-2M5 11V9a2 2 0 012-2m0 0V5a2 2 0 012-2h6a2 2 0 012 2v2M7 7h10" /></svg>
           Durum Özet Tablosu
        </h3>
        <div className="relative">
          <input 
            type="text"
            placeholder="Kuyruk No, Çağrı Kodu veya Konum Ara..."
            value={searchTerm}
            onChange={(e) => setSearchTerm(e.target.value)}
            className="w-full md:w-80 pl-10 pr-4 py-2 border rounded-xl focus:ring-2 focus:ring-green-500 outline-none shadow-sm transition-all"
          />
          <svg className="absolute left-3 top-2.5 w-5 h-5 text-gray-400" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path d="M21 21l-6-6m2-5a7 7 0 11-14 0 7 7 0 0114 0z" /></svg>
        </div>
      </div>

      {/* Main Table Container */}
      <div className="bg-white rounded-2xl shadow-sm border border-gray-100 overflow-hidden">
        <div className="overflow-x-auto">
          <table className="w-full text-left">
            <thead className="bg-gray-50 border-b text-gray-500 text-xs font-bold uppercase tracking-wider">
              <tr>
                <th className="px-6 py-4">Hava Aracı</th>
                <th className="px-6 py-4">Platform</th>
                <th className="px-6 py-4">Durum</th>
                <th className="px-6 py-4">Konum</th>
                <th className="px-6 py-4 text-center">Faydalı Saat</th>
                <th className="px-6 py-4">Son Güncelleme</th>
                <th className="px-6 py-4 text-right">İşlemler</th>
              </tr>
            </thead>
            <tbody className="divide-y divide-gray-100 text-sm">
              {filteredFleet.map((a) => (
                <tr key={a.kuyrukNo} className="hover:bg-green-50/30 transition-colors group">
                  <td className="px-6 py-4">
                    <div className="flex items-center">
                      <div className="w-10 h-10 rounded-lg bg-gray-100 mr-3 flex items-center justify-center overflow-hidden">
                         <img src={a.photos[0]} alt="" className="w-full h-full object-cover" />
                      </div>
                      <div>
                        <div className="font-bold text-gray-900">{a.kuyrukNo}</div>
                        <div className="text-xs text-gray-500">{a.cagriKodu}</div>
                      </div>
                    </div>
                  </td>
                  <td className="px-6 py-4">
                     <span className="px-2 py-1 bg-gray-100 rounded font-bold text-[10px] text-gray-600">{a.platformTipi}</span>
                  </td>
                  <td className="px-6 py-4">
                    <div className="flex flex-col">
                      <div className="flex items-center">
                        <span className={`w-2 h-2 rounded-full mr-2 ${a.durum === Status.FAAL ? 'bg-green-500' : 'bg-red-500'}`}></span>
                        <span className={`font-bold ${a.durum === Status.FAAL ? 'text-green-700' : 'text-red-700'}`}>
                          {a.durum}
                        </span>
                      </div>
                      {a.durumTipi !== '-' && (
                        <span className="text-[10px] text-gray-400 mt-0.5">{a.durumTipi}: {a.durumAyrintisi}</span>
                      )}
                    </div>
                  </td>
                  <td className="px-6 py-4 font-medium text-gray-600">{a.konum}</td>
                  <td className="px-6 py-4 text-center">
                    <span className={`font-bold ${a.faydaliSaat < 50 ? 'text-red-600' : 'text-blue-600'}`}>
                      {a.faydaliSaat}
                    </span>
                  </td>
                  <td className="px-6 py-4 text-gray-500 text-xs">{a.guncellemeTarihi}</td>
                  <td className="px-6 py-4 text-right">
                    <div className="flex items-center justify-end space-x-2">
                      <button 
                        onClick={() => setSelectedAircraft(a)}
                        className="p-2 text-gray-400 hover:text-[#1b5e20] hover:bg-green-50 rounded-lg transition-all"
                        title="Detay"
                      >
                        <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path d="M15 12a3 3 0 11-6 0 3 3 0 016 0z" /><path d="M2.458 12C3.732 7.943 7.523 5 12 5c4.478 0 8.268 2.943 9.542 7-1.274 4.057-5.064 7-9.542 7-4.477 0-8.268-2.943-9.542-7z" /></svg>
                      </button>
                      <button 
                        onClick={() => setEditingAircraft(a)}
                        className="p-2 text-gray-400 hover:text-orange-600 hover:bg-orange-50 rounded-lg transition-all"
                        title="Durum Güncelle"
                      >
                        <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path d="M11 5H6a2 2 0 00-2 2v11a2 2 0 002 2h11a2 2 0 002-2v-5m-1.414-9.414a2 2 0 112.828 2.828L11.828 15H9v-2.828l8.586-8.586z" /></svg>
                      </button>
                    </div>
                  </td>
                </tr>
              ))}
              {filteredFleet.length === 0 && (
                <tr>
                  <td colSpan={7} className="px-6 py-12 text-center text-gray-400 italic">
                    Arama kriterlerine uygun hava aracı bulunamadı.
                  </td>
                </tr>
              )}
            </tbody>
          </table>
        </div>
      </div>

      {/* Activity Logs Section (Placeholder for 4th point in requirements) */}
      <div className="mt-8">
         <h3 className="text-lg font-bold text-gray-800 mb-4 flex items-center">
            <svg className="w-5 h-5 mr-2 text-gray-600" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path d="M9 5H7a2 2 0 00-2 2v12a2 2 0 002 2h10a2 2 0 002-2V7a2 2 0 00-2-2h-2M9 5a2 2 0 002 2h2a2 2 0 002-2M9 5a2 2 0 012-2h2a2 2 0 012 2m-3 7h3m-3 4h3m-6-4h.01M9 16h.01" /></svg>
            Faaliyet Takvimi
         </h3>
         <div className="bg-white rounded-2xl shadow-sm border border-gray-100 p-1">
            <div className="overflow-x-auto">
              <table className="w-full text-left text-sm">
                <thead className="bg-gray-50 border-b text-gray-500 font-semibold">
                  <tr>
                    <th className="px-6 py-3">Tarih</th>
                    <th className="px-6 py-3">Kuyruk</th>
                    <th className="px-6 py-3">Durum</th>
                    <th className="px-6 py-3">Açıklama</th>
                  </tr>
                </thead>
                <tbody className="divide-y divide-gray-50">
                   {MOCK_ACTIVITY_LOGS.map((log, i) => (
                     <tr key={i} className="hover:bg-gray-50">
                        <td className="px-6 py-3 text-gray-600">{log.tarih}</td>
                        <td className="px-6 py-3 font-bold">{log.kuyrukNo}</td>
                        <td className="px-6 py-3">
                           <span className={`px-2 py-0.5 rounded text-[10px] font-bold ${log.durum === Status.FAAL ? 'bg-green-100 text-green-700' : 'bg-red-100 text-red-700'}`}>
                             {log.durum}
                           </span>
                        </td>
                        <td className="px-6 py-3 text-gray-500 truncate max-w-xs">{log.aciklama}</td>
                     </tr>
                   ))}
                </tbody>
              </table>
            </div>
         </div>
      </div>

      {/* Modals */}
      {selectedAircraft && (
        <AircraftDetailModal 
          aircraft={selectedAircraft} 
          onClose={() => setSelectedAircraft(null)} 
        />
      )}

      {editingAircraft && (
        <MaintenanceForm 
          aircraft={editingAircraft} 
          onSave={handleUpdateStatus} 
          onCancel={() => setEditingAircraft(null)} 
        />
      )}
    </Layout>
  );
};

export default App;

import React from 'react';
import ReactDOM from 'react-dom/client';
import App from './App';

const rootElement = document.getElementById('root');
if (!rootElement) {
  throw new Error("Could not find root element to mount to");
}

const root = ReactDOM.createRoot(rootElement);
root.render(
  <React.StrictMode>
    <App />
  </React.StrictMode>
);

export enum PlatformType {
  H = 'H',
  SA = 'S-A',
  DA = 'D-A',
  SL = 'S-L',
  DL = 'D-L'
}

export enum Status {
  FAAL = 'FAAL',
  GAYRI_FAAL = 'GAYRI FAAL'
}

export enum StatusType {
  BAKIM = 'BAKIM',
  ARIZA = 'ARIZA',
  DIGER = 'DIGER',
  NONE = '-'
}

export interface MaintenanceHour {
  bakimTuru: string;
  kalanSaat: number;
}

export interface Aircraft {
  cagriKodu: string;
  kuyrukNo: string;
  platformTipi: string;
  durum: Status;
  durumTipi: StatusType;
  durumAyrintisi: string;
  konum: string;
  faydaliSaat: number;
  durumBaslangic: string;
  durumBitis?: string;
  aciklama: string;
  guncellemeTarihi: string;
  seriNo: string;
  motor: string;
  uretimYili: number;
  base: string;
  maintenanceHours: MaintenanceHour[];
  photos: string[];
}

export type DailyStatusCode = 'PB' | 'B' | 'X' | 'KM' | '' | 'F';

