import React from 'react';
import { AircraftActivity, DailyStatusCode } from '../types';

interface ActivityGridProps {
  activities: AircraftActivity[];
}

const ActivityGrid: React.FC<ActivityGridProps> = ({ activities }) => {
  const days = Array.from({ length: 31 }, (_, i) => i + 1);
  const currentMonth = "MAYIS 2025";

  const getCellColor = (code: DailyStatusCode) => {
    switch (code) {
      case 'PB': return 'bg-yellow-100 text-yellow-800 font-bold'; // Planlı Bakım
      case 'B': return 'bg-orange-100 text-orange-800 font-bold'; // Bakım
      case 'X': return 'bg-red-100 text-red-800 font-bold';    // Arıza
      case 'KM': return 'bg-blue-100 text-blue-800 font-bold';  // Kurulum
      default: return 'bg-white';
    }
  };

  const calculateTotals = (activity: AircraftActivity) => {
    let bakım = 0, arıza = 0, diger = 0;
    Object.values(activity.dailyStatuses).forEach(s => {
      if (s === 'PB' || s === 'B') bakım++;
      else if (s === 'X') arıza++;
      else if (s === 'KM') diger++;
    });
    const totalGFaal = bakım + arıza + diger;
    const totalFaal = 31 - totalGFaal;
    return { bakım, arıza, diger, totalGFaal, totalFaal };
  };

  return (
    <div className="bg-white rounded-xl shadow-2xl overflow-hidden border border-gray-200">
      <div className="bg-[#f59e0b] p-3 text-center border-b border-orange-600">
        <h2 className="text-xl font-black text-white tracking-widest uppercase">{currentMonth} FAALİYET TAKVİMİ</h2>
      </div>
      <div className="overflow-x-auto">
        <table className="w-full border-collapse text-[11px] font-sans">
          <thead>
            <tr className="bg-gray-100 border-b-2 border-gray-300">
              <th className="border p-2 min-w-[100px] sticky left-0 bg-gray-100 z-10">ÇAĞRI KODU</th>
              <th className="border p-2 min-w-[80px] sticky left-[100px] bg-gray-100 z-10">KUYRUK NO</th>
              <th className="border p-2 min-w-[80px]">TİP</th>
              {days.map(d => (
                <th key={d} className="border p-1 w-8 text-center bg-gray-50">{d}</th>
              ))}
              <th className="border p-2 bg-yellow-50 text-yellow-800">BAKIM</th>
              <th className="border p-2 bg-red-50 text-red-800">ARIZA</th>
              <th className="border p-2 bg-blue-50 text-blue-800">DİĞER</th>
              <th className="border p-2 bg-orange-600 text-white">TOP. G.FAAL</th>
              <th className="border p-2 bg-green-600 text-white">TOP. FAAL</th>
            </tr>
          </thead>
          <tbody>
            {activities.map((act, idx) => {
              const totals = calculateTotals(act);
              return (
                <tr key={idx} className="hover:bg-gray-50 transition-colors">
                  <td className="border p-2 font-bold sticky left-0 bg-white z-10">{act.cagriKodu}</td>
                  <td className="border p-2 font-semibold sticky left-[100px] bg-white z-10">{act.kuyrukNo}</td>
                  <td className="border p-2 text-gray-500">{act.tip}</td>
                  {days.map(d => (
                    <td key={d} className={`border p-1 text-center ${getCellColor(act.dailyStatuses[d] || '')}`}>
                      {act.dailyStatuses[d] || ''}
                    </td>
                  ))}
                  <td className="border p-2 text-center font-bold">{totals.bakım}</td>
                  <td className="border p-2 text-center font-bold">{totals.arıza}</td>
                  <td className="border p-2 text-center font-bold">{totals.diger}</td>
                  <td className="border p-2 text-center font-black bg-orange-50">{totals.totalGFaal}</td>
                  <td className="border p-2 text-center font-black bg-green-50">{totals.totalFaal}</td>
                </tr>
              );
            })}
          </tbody>
          <tfoot className="bg-yellow-400 font-bold border-t-2 border-yellow-600">
            <tr>
              <td colSpan={3} className="border p-2 text-right uppercase">GENEL TOPLAM</td>
              {days.map(d => <td key={d} className="border p-1"></td>)}
              <td className="border p-2 text-center">41</td>
              <td className="border p-2 text-center">22</td>
              <td className="border p-2 text-center">15</td>
              <td className="border p-2 text-center bg-orange-500 text-white">78</td>
              <td className="border p-2 text-center bg-green-700 text-white">122</td>
            </tr>
          </tfoot>
        </table>
      </div>
      <div className="p-3 bg-gray-50 flex space-x-4 text-[10px] border-t">
        <div className="flex items-center"><span className="w-3 h-3 bg-yellow-100 border mr-1"></span> PB: Planlı Bakım</div>
        <div className="flex items-center"><span className="w-3 h-3 bg-orange-100 border mr-1"></span> B: Bakım</div>
        <div className="flex items-center"><span className="w-3 h-3 bg-red-100 border mr-1"></span> X: Arıza</div>
        <div className="flex items-center"><span className="w-3 h-3 bg-blue-100 border mr-1"></span> KM: Kurulum / Montaj</div>
      </div>
    </div>
  );
};

export default ActivityGrid;

import React, { useState, useMemo } from 'react';
import Layout from './components/Layout';
import Dashboard from './components/Dashboard';
import AircraftDetailModal from './components/AircraftDetailModal';
import MaintenanceForm from './components/MaintenanceForm';
import ActivityGrid from './components/ActivityGrid';
import { MOCK_AIRCRAFT, MOCK_ACTIVITY_GRID } from './constants';
import { Aircraft, Status } from './types';

const App: React.FC = () => {
  const [fleet, setFleet] = useState<Aircraft[]>(MOCK_AIRCRAFT);
  const [selectedAircraft, setSelectedAircraft] = useState<Aircraft | null>(null);
  const [editingAircraft, setEditingAircraft] = useState<Aircraft | null>(null);
  const [searchTerm, setSearchTerm] = useState('');

  const filteredFleet = useMemo(() => {
    return fleet.filter(a => 
      a.kuyrukNo.toLowerCase().includes(searchTerm.toLowerCase()) ||
      a.cagriKodu.toLowerCase().includes(searchTerm.toLowerCase()) ||
      a.konum.toLowerCase().includes(searchTerm.toLowerCase())
    );
  }, [fleet, searchTerm]);

  const handleUpdateStatus = (updates: Partial<Aircraft>) => {
    if (!editingAircraft) return;
    setFleet(prev => prev.map(a => 
      a.kuyrukNo === editingAircraft.kuyrukNo ? { ...a, ...updates } as Aircraft : a
    ));
    setEditingAircraft(null);
  };

  const exportToExcel = (type: 'summary' | 'activity') => {
    let csvContent = "data:text/csv;charset=utf-8,";

    if (type === 'summary') {
      csvContent += "Cagri Kodu,Kuyruk No,Tip,Durum,Konum,Faydali Saat,Son Guncelleme\n";
      filteredFleet.forEach(a => {
        csvContent += `${a.cagriKodu},${a.kuyrukNo},${a.platformTipi},${a.durum},${a.konum},${a.faydaliSaat},${a.guncellemeTarihi}\n`;
      });
    } else {
      csvContent += "Cagri Kodu,Kuyruk No,Tip," + Array.from({length:31}, (_,i)=>i+1).join(",") + "\n";
      MOCK_ACTIVITY_GRID.forEach(act => {
        const row = [act.cagriKodu, act.kuyrukNo, act.tip];
        for(let i=1; i<=31; i++) row.push(act.dailyStatuses[i] || "");
        csvContent += row.join(",") + "\n";
      });
    }

    const encodedUri = encodeURI(csvContent);
    const link = document.createElement("a");
    link.setAttribute("href", encodedUri);
    link.setAttribute("download", `OGM_${type}_${new Date().toISOString().split('T')[0]}.csv`);
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
  };

  return (
    <Layout>
      <Dashboard fleet={fleet} />

      {/* Durum Özet Tablosu */}
      <div className="mb-12">
        <div className="flex flex-col md:flex-row md:items-center justify-between mb-6 gap-4">
          <div className="flex items-center space-x-3">
             <div className="bg-white p-2 rounded-lg shadow-md border-b-4 border-green-700">
               <svg className="w-6 h-6 text-green-700" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M19 11H5m14 0a2 2 0 012 2v6a2 2 0 01-2 2H5a2 2 0 01-2-2v-6a2 2 0 012-2m14 0V9a2 2 0 00-2-2M5 11V9a2 2 0 012-2m0 0V5a2 2 0 012-2h6a2 2 0 012 2v2M7 7h10" /></svg>
             </div>
             <h3 className="text-xl font-black text-white uppercase tracking-tight shadow-sm">HAVA ARACI DURUM ÖZET TABLOSU</h3>
          </div>
          <div className="flex items-center space-x-3">
            <button 
              onClick={() => exportToExcel('summary')}
              className="bg-white hover:bg-green-50 text-green-800 px-4 py-2 rounded-lg font-bold text-xs flex items-center shadow-lg transition-all border-b-2 border-green-200"
            >
              <svg className="w-4 h-4 mr-2" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M4 16v1a2 2 0 002 2h12a2 2 0 002-2v-1m-4-4l-4 4m0 0l-4-4m4 4V4" /></svg>
              EXCEL İNDİR
            </button>
            <div className="relative">
              <input 
                type="text"
                placeholder="Hızlı Arama..."
                value={searchTerm}
                onChange={(e) => setSearchTerm(e.target.value)}
                className="w-full md:w-64 pl-10 pr-4 py-2 bg-white/90 backdrop-blur border-none rounded-xl focus:ring-4 focus:ring-green-400 outline-none shadow-xl transition-all font-bold placeholder:text-gray-400"
              />
              <svg className="absolute left-3 top-2.5 w-5 h-5 text-gray-400" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path d="M21 21l-6-6m2-5a7 7 0 11-14 0 7 7 0 0114 0z" /></svg>
            </div>
          </div>
        </div>

        <div className="bg-white rounded-2xl shadow-2xl border-b-8 border-green-800 overflow-hidden">
          <div className="overflow-x-auto">
            <table className="w-full text-left">
              <thead className="bg-gray-100 border-b-2 border-gray-200 text-gray-600 text-[11px] font-black uppercase tracking-wider">
                <tr>
                  <th className="px-6 py-5">Hava Aracı Bilgisi</th>
                  <th className="px-6 py-5">Platform Tipi</th>
                  <th className="px-6 py-5">Güncel Durum</th>
                  <th className="px-6 py-5">Konum / Base</th>
                  <th className="px-6 py-5 text-center">Faydalı Saat</th>
                  <th className="px-6 py-5">Gnc. Tarihi</th>
                  <th className="px-6 py-5 text-right">Ayrıntı</th>
                </tr>
              </thead>
              <tbody className="divide-y divide-gray-100 text-sm">
                {filteredFleet.map((a) => (
                  <tr key={a.kuyrukNo} className="hover:bg-green-50 transition-colors group">
                    <td className="px-6 py-4">
                      <div className="flex items-center">
                        <div className="w-12 h-12 rounded-xl bg-gray-100 mr-4 border-2 border-white shadow-md overflow-hidden group-hover:scale-105 transition-transform">
                           <img src={a.photos[0]} alt="" className="w-full h-full object-cover" />
                        </div>
                        <div>
                          <div className="font-black text-gray-900 text-base">{a.kuyrukNo}</div>
                          <div className="text-[11px] font-bold text-green-600 uppercase">{a.cagriKodu}</div>
                        </div>
                      </div>
                    </td>
                    <td className="px-6 py-4">
                       <span className="px-3 py-1 bg-gray-200 rounded-full font-black text-[10px] text-gray-700 tracking-tighter">{a.platformTipi}</span>
                    </td>
                    <td className="px-6 py-4">
                      <div className="flex flex-col">
                        <div className="flex items-center">
                          <span className={`w-3 h-3 rounded-full mr-2 shadow-sm ${a.durum === Status.FAAL ? 'bg-green-500 shadow-green-500/50' : 'bg-red-500 shadow-red-500/50'}`}></span>
                          <span className={`font-black tracking-tight ${a.durum === Status.FAAL ? 'text-green-700' : 'text-red-700'}`}>
                            {a.durum}
                          </span>
                        </div>
                        {a.durumTipi !== '-' && (
                          <span className="text-[10px] font-bold text-gray-400 mt-1 uppercase italic">{a.durumTipi}: {a.durumAyrintisi}</span>
                        )}
                      </div>
                    </td>
                    <td className="px-6 py-4 font-bold text-gray-600 uppercase tracking-tight">{a.konum}</td>
                    <td className="px-6 py-4 text-center">
                      <div className={`inline-block px-3 py-1 rounded-lg font-black text-base ${a.faydaliSaat < 50 ? 'bg-red-50 text-red-600' : 'bg-blue-50 text-blue-600'}`}>
                        {a.faydaliSaat}
                      </div>
                    </td>
                    <td className="px-6 py-4 text-gray-500 text-[10px] font-bold font-mono">{a.guncellemeTarihi}</td>
                    <td className="px-6 py-4 text-right">
                      <button 
                        onClick={() => setSelectedAircraft(a)}
                        className="bg-green-700 hover:bg-green-800 text-white p-2 rounded-xl transition-all shadow-md active:scale-95"
                      >
                        <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M15 12a3 3 0 11-6 0 3 3 0 016 0z" /><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M2.458 12C3.732 7.943 7.523 5 12 5c4.478 0 8.268 2.943 9.542 7-1.274 4.057-5.064 7-9.542 7-4.477 0-8.268-2.943-9.542-7z" /></svg>
                      </button>
                    </td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
        </div>
      </div>

      {/* Faaliyet Takvimi (Yoklama Formatı) */}
      <div className="mb-8">
        <div className="flex flex-col md:flex-row md:items-center justify-between mb-6 gap-4">
          <div className="flex items-center space-x-3">
             <div className="bg-white p-2 rounded-lg shadow-md border-b-4 border-orange-600">
               <svg className="w-6 h-6 text-orange-600" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M8 7V3m8 4V3m-9 8h10M5 21h14a2 2 0 002-2V7a2 2 0 00-2-2H5a2 2 0 00-2 2v12a2 2 0 002 2z" /></svg>
             </div>
             <h3 className="text-xl font-black text-white uppercase tracking-tight">FAALİYET TAKVİM ÇİZELGESİ (YOKLAMA)</h3>
          </div>
          <button 
            onClick={() => exportToExcel('activity')}
            className="bg-white hover:bg-orange-50 text-orange-800 px-4 py-2 rounded-lg font-bold text-xs flex items-center shadow-lg transition-all border-b-2 border-orange-200"
          >
            <svg className="w-4 h-4 mr-2" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M4 16v1a2 2 0 002 2h12a2 2 0 002-2v-1m-4-4l-4 4m0 0l-4-4m4 4V4" /></svg>
            TAKVİM EXCEL İNDİR
          </button>
        </div>

        <ActivityGrid activities={MOCK_ACTIVITY_GRID} />
      </div>

      {/* Modals */}
      {selectedAircraft && (
        <AircraftDetailModal 
          aircraft={selectedAircraft} 
          onClose={() => setSelectedAircraft(null)} 
        />
      )}

      {editingAircraft && (
        <MaintenanceForm 
          aircraft={editingAircraft} 
          onSave={handleUpdateStatus} 
          onCancel={() => setEditingAircraft(null)} 
        />
      )}
    </Layout>
  );
};

export default App;

import React from 'react';
import { PieChart, Pie, Cell, ResponsiveContainer, Tooltip } from 'recharts';
import { Aircraft, Status } from '../types';

interface DashboardProps {
  fleet: Aircraft[];
}

const Dashboard: React.FC<DashboardProps> = ({ fleet }) => {
  const total = fleet.length;
  const faal = fleet.filter(a => a.durum === Status.FAAL).length;
  const gayriFaal = total - faal;

  const chartData = [
    { name: 'Faal', value: faal, color: '#10b981' }, // Emerald 500
    { name: 'Gayrı Faal', value: gayriFaal, color: '#ef4444' }, // Red 500
  ];

  return (
    <div className="grid grid-cols-1 md:grid-cols-4 gap-6 mb-12">
      <div className="bg-white/95 backdrop-blur p-6 rounded-2xl shadow-xl border-b-4 border-gray-300">
        <span className="text-gray-400 text-xs font-black uppercase tracking-widest">Toplam Filo Gücü</span>
        <div className="text-5xl font-black text-gray-800 mt-1">{total} <span className="text-xl font-bold text-gray-400">Ünite</span></div>
      </div>
      <div className="bg-white/95 backdrop-blur p-6 rounded-2xl shadow-xl border-b-4 border-green-500">
        <span className="text-green-600 text-xs font-black uppercase tracking-widest">Göreve Hazır (Faal)</span>
        <div className="text-5xl font-black text-green-700 mt-1">{faal}</div>
      </div>
      <div className="bg-white/95 backdrop-blur p-6 rounded-2xl shadow-xl border-b-4 border-red-500">
        <span className="text-red-600 text-xs font-black uppercase tracking-widest">Gayrı Faal Durum</span>
        <div className="text-5xl font-black text-red-700 mt-1">{gayriFaal}</div>
      </div>
      <div className="bg-white/95 backdrop-blur p-4 rounded-2xl shadow-xl h-32 border-b-4 border-blue-500">
        <ResponsiveContainer width="100%" height="100%">
          <PieChart>
            <Pie
              data={chartData}
              cx="50%"
              cy="50%"
              innerRadius={25}
              outerRadius={40}
              paddingAngle={5}
              dataKey="value"
            >
              {chartData.map((entry, index) => (
                <Cell key={`cell-${index}`} fill={entry.color} stroke="none" />
              ))}
            </Pie>
            <Tooltip 
               contentStyle={{ borderRadius: '12px', border: 'none', boxShadow: '0 10px 15px -3px rgba(0,0,0,0.1)' }}
            />
          </PieChart>
        </ResponsiveContainer>
      </div>
    </div>
  );
};

export default Dashboard;

