import React, { useState, useMemo } from 'react';
import Layout from './components/Layout';
import Dashboard from './components/Dashboard';
import AircraftDetailModal from './components/AircraftDetailModal';
import MaintenanceForm from './components/MaintenanceForm';
import ActivityGrid from './components/ActivityGrid';
import { MOCK_AIRCRAFT, MOCK_ACTIVITY_GRID } from './constants';
import { Aircraft, Status } from './types';

const App: React.FC = () => {
  const [fleet, setFleet] = useState<Aircraft[]>(MOCK_AIRCRAFT);
  const [selectedAircraft, setSelectedAircraft] = useState<Aircraft | null>(null);
  const [editingAircraft, setEditingAircraft] = useState<Aircraft | null>(null);
  const [searchTerm, setSearchTerm] = useState('');

  const filteredFleet = useMemo(() => {
    return fleet.filter(a => 
      a.kuyrukNo.toLowerCase().includes(searchTerm.toLowerCase()) ||
      a.cagriKodu.toLowerCase().includes(searchTerm.toLowerCase()) ||
      a.konum.toLowerCase().includes(searchTerm.toLowerCase())
    );
  }, [fleet, searchTerm]);

  const handleUpdateStatus = (updates: Partial<Aircraft>) => {
    if (!editingAircraft) return;
    setFleet(prev => prev.map(a => 
      a.kuyrukNo === editingAircraft.kuyrukNo ? { ...a, ...updates } as Aircraft : a
    ));
    setEditingAircraft(null);
  };

  const exportTableToExcel = (tableId: string, filename: string) => {
    const table = document.getElementById(tableId);
    if (!table) return;

    // Clone the table to avoid modifying the UI
    const clone = table.cloneNode(true) as HTMLElement;

    // Remove elements with 'no-export' class
    clone.querySelectorAll('.no-export').forEach(el => el.remove());

    // Specific styling for Excel to maintain the design
    const styles = `
      <style>
        table { border-collapse: collapse; width: 100%; font-family: 'Times New Roman', serif; border: 2px solid black; }
        th, td { border: 1px solid black; padding: 4px; text-align: center; font-size: 10pt; }

        /* Background Colors */
        .bg-gray, .bg-\\[\\#d9d9d9\\] { background-color: #d9d9d9 !important; }
        .bg-yellow, .bg-\\[\\#ffff00\\], .status-yellow, .legend-yellow { background-color: #ffff00 !important; }
        .bg-red, .bg-\\[\\#ff0000\\], .status-red, .legend-red { background-color: #ff0000 !important; color: black !important; }
        .bg-purple, .bg-\\[\\#9370db\\], .status-purple, .legend-purple { background-color: #9370db !important; color: black !important; }
        .bg-orange, .bg-\\[\\#ffcc00\\] { background-color: #ffcc00 !important; }
        .bg-blue, .bg-\\[\\#00b0f0\\] { background-color: #00b0f0 !important; }
        .bg-light-yellow, .bg-\\[\\#ffff99\\] { background-color: #ffff99 !important; }
        .bg-pale-yellow, .bg-\\[\\#ffffcc\\] { background-color: #ffffcc !important; }

        /* Text styling */
        .font-bold { font-weight: bold; }
        .font-black { font-weight: 900; }

        /* Layout specifics */
        .vertical-text { mso-rotate: 90; height: 100px; }
      </style>
    `;

    const htmlContent = `
      <html xmlns:o="urn:schemas-microsoft-com:office:office" xmlns:x="urn:schemas-microsoft-com:office:excel" xmlns="http://www.w3.org/TR/REC-html40">
      <head>
        <meta http-equiv="content-type" content="application/vnd.ms-excel; charset=UTF-8">
        ${styles}
      </head>
      <body>
        ${clone.outerHTML}
      </body>
      </html>
    `;

    const blob = new Blob([htmlContent], { type: 'application/vnd.ms-excel' });
    const url = URL.createObjectURL(blob);
    const link = document.createElement("a");
    link.href = url;
    link.download = `${filename}.xls`;
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
    URL.revokeObjectURL(url);
  };

  return (
    <Layout>
      <Dashboard fleet={fleet} />

