import React from 'react';
import { AircraftActivity, DailyStatusCode } from '../types';

interface ActivityGridProps {
  activities: AircraftActivity[];
  startDate: Date;
  endDate: Date;
}

const ActivityGrid: React.FC<ActivityGridProps> = ({ activities, startDate, endDate }) => {
  // Generate array of dates between start and end
  const getDaysInRange = (start: Date, end: Date) => {
    const dates = [];
    let curr = new Date(start);
    // Limit to 62 days to prevent UI exploding, though business-wise a month is typical
    const limit = new Date(start);
    limit.setDate(limit.getDate() + 62);
    const finalEnd = end > limit ? limit : end;

    while (curr <= finalEnd) {
      dates.push(new Date(curr));
      curr.setDate(curr.getDate() + 1);
    }
    return dates;
  };

  const visibleDates = getDaysInRange(startDate, endDate);
  const currentMonthName = startDate.toLocaleDateString('tr-TR', { month: 'long' }).toUpperCase();
  const currentYear = startDate.getFullYear();

  const getCellStyles = (code: DailyStatusCode) => {
    switch (code) {
      case 'B': 
      case 'BB': 
      case 'KM': return 'status-yellow bg-[#ffff00] text-black font-bold'; 
      case 'A': 
      case 'PB': 
      case 'KK': return 'status-red bg-[#ff0000] text-black font-bold';
      case 'X': return 'status-purple bg-[#9370db] text-black font-bold';
      case 'F': return 'status-white bg-white text-gray-800';
      default: return 'status-white bg-white';
    }
  };

  const calculateTotals = (activity: AircraftActivity) => {
    let bakım = 0, arıza = 0, olmadigi = 0;

    visibleDates.forEach(date => {
      const dayNum = date.getDate();
      const s = activity.dailyStatuses[dayNum];
      if (s === 'B' || s === 'BB' || s === 'KM') bakım++;
      else if (s === 'A' || s === 'PB' || s === 'KK') arıza++;
      else if (s === 'X') olmadigi++;
    });

    const totalGFaal = bakım + arıza + olmadigi;
    const totalFaal = visibleDates.length - totalGFaal;
    return { bakım, arıza, olmadigi, totalGFaal, totalFaal };
  };

  const grandTotals = activities.reduce((acc, act) => {
    const t = calculateTotals(act);
    return {
      bakım: acc.bakım + t.bakım,
      arıza: acc.arıza + t.arıza,
      olmadigi: acc.olmadigi + t.olmadigi,
      totalGFaal: acc.totalGFaal + t.totalGFaal,
      totalFaal: acc.totalFaal + t.totalFaal
    };
  }, { bakım: 0, arıza: 0, olmadigi: 0, totalGFaal: 0, totalFaal: 0 });

  return (
    <div id="activity-table-container" className="bg-[#fef9c3] p-1 rounded-sm shadow-2xl overflow-hidden border-2 border-black font-serif">
      <div className="flex justify-between items-end px-10 py-6 bg-white border-b-2 border-black">
        <div className="text-7xl font-bold">{currentYear}</div>
        <div className="text-5xl font-bold tracking-[0.2em]">{currentMonthName} {currentYear}</div>
        <div className="w-20"></div>
      </div>

      <div className="overflow-x-auto">
        <table id="activity-grid-main" className="w-full border-collapse text-[11px] leading-tight bg-white">
          <thead>
            <tr className="bg-white">
              <th className="border border-black p-2 w-28 sticky left-0 bg-[#d9d9d9] z-20" rowSpan={2}>ÇAĞRI KODU</th>
              <th className="border border-black p-2 w-24 sticky left-28 bg-[#d9d9d9] z-20" rowSpan={2}>KUYRUK NO</th>
              <th className="border border-black p-2 w-24 bg-[#d9d9d9]" rowSpan={2}>HAVA ARACI TİPİ</th>
              {visibleDates.map((date, idx) => (
                <th key={idx} className="border border-black p-0.5 w-7 text-center align-middle font-normal bg-white" style={{ writingMode: 'vertical-rl', transform: 'rotate(180deg)' }}>
                  {date.toLocaleDateString('tr-TR', { day: '2-digit', month: '2-digit', year: 'numeric' })}
                </th>
              ))}
              <th className="border border-black bg-[#00b0f0] text-black text-[10px] font-bold p-1" colSpan={3}>TOPLAM G.FAAL</th>
              <th className="border border-black bg-[#00b0f0] text-black text-[10px] font-bold p-1" rowSpan={2}>TOPLAM G.FAAL</th>
              <th className="border border-black bg-[#ffc000] text-black text-[10px] font-bold p-1" rowSpan={2}>TOPLAM FAAL</th>
            </tr>
            <tr className="bg-white">
              {visibleDates.map((_, idx) => <th key={idx} className="border border-black h-2 bg-white"></th>)}
              <th className="border border-black bg-[#ffff00] p-1 vertical-text">BAKIM</th>
              <th className="border border-black bg-[#ff0000] text-black p-1 vertical-text">ARIZA</th>
              <th className="border border-black bg-[#7030a0] text-white p-1 vertical-text">OLMADIĞI</th>
            </tr>
          </thead>
          <tbody>
            {activities.map((act, idx) => {
              const totals = calculateTotals(act);
              return (
                <tr key={idx} className="bg-white">
                  <td className="border border-black px-2 py-4 font-bold text-center bg-[#d9d9d9] sticky left-0 z-10">{act.cagriKodu}</td>
                  <td className="border border-black px-2 py-4 font-bold text-center bg-[#d9d9d9] sticky left-28 z-10">{act.kuyrukNo}</td>
                  <td className="border border-black px-2 py-4 text-center bg-[#d9d9d9]">{act.tip}</td>
                  {visibleDates.map((date, dIdx) => {
                    const status = act.dailyStatuses[date.getDate()] || '';
                    return (
                      <td key={dIdx} className={`border border-black p-0.5 text-center min-w-[28px] ${getCellStyles(status)}`}>
                        {status}
                      </td>
                    );
                  })}
                  <td className="border border-black text-center font-bold bg-[#ffff99]">{totals.bakım}</td>
                  <td className="border border-black text-center font-bold bg-[#ffff99]">{totals.arıza}</td>
                  <td className="border border-black text-center font-bold bg-[#ffff99]">{totals.olmadigi}</td>
                  <td className="border border-black text-center font-black bg-[#ffcc00] text-base">{totals.totalGFaal}</td>
                  <td className="border border-black text-center font-black bg-[#ffffcc] text-base">{totals.totalFaal}</td>
                </tr>
              );
            })}
            {[...Array(2)].map((_, i) => (
              <tr key={`empty-${i}`} className="bg-white h-10">
                <td className="border border-black bg-[#d9d9d9] sticky left-0 z-10"></td>
