            <tr className="font-black text-center">
              <td colSpan={3} className="border border-black p-3 text-right bg-[#ffff00]">TOPLAM</td>
              {visibleDates.map((_, idx) => <td key={idx} className="border border-black bg-[#ffff00]"></td>)}
              <td className="border border-black p-2 bg-[#ffff00]">{grandTotals.bakım}</td>
