              <td className="border border-black p-2 bg-[#ffffcc]">{grandTotals.totalFaal}</td>
            </tr>
          </tfoot>
        </table>
      </div>

      <div className="p-4 grid grid-cols-1 md:grid-cols-3 gap-2 bg-white mt-1 border-t-2 border-black">
