import React from 'react';
import { AircraftActivity, DailyStatusCode } from '../types';

interface ActivityGridProps {
  activities: AircraftActivity[];
  startDate: Date;
  endDate: Date;
}

const ActivityGrid: React.FC<ActivityGridProps> = ({ activities, startDate, endDate }) => {
  // Generate array of dates between start and end
  const getDaysInRange = (start: Date, end: Date) => {
    const dates = [];
    let curr = new Date(start);
    // Limit to 62 days to prevent UI exploding
    const limit = new Date(start);
    limit.setDate(limit.getDate() + 62);
    const finalEnd = end > limit ? limit : end;

    while (curr <= finalEnd) {
      dates.push(new Date(curr));
      curr.setDate(curr.getDate() + 1);
    }
    return dates;
  };

  const visibleDates = getDaysInRange(startDate, endDate);

  // Format header like "Oca.26"
  const monthAbbr = startDate.toLocaleDateString('tr-TR', { month: 'short' });
  const yearAbbr = startDate.getFullYear().toString().slice(-2);
  const headerText = `${monthAbbr}.${yearAbbr}`;

  const getCellStyles = (code: DailyStatusCode) => {
    switch (code) {
      case 'B': 
      case 'BB': 
      case 'KM': return 'bg-[#ffff00] text-black font-bold'; // Yellow
      case 'A': 
      case 'PB': 
      case 'KK': return 'bg-[#ff0000] text-black font-bold'; // Red
      case 'X': return 'bg-[#9370db] text-black font-bold'; // Purple
      case 'F': return 'bg-white text-black';
      default: return 'bg-white';
    }
  };

  // Automated counting logic (EĞERSAY / COUNTIF)
  const calculateRowStats = (activity: AircraftActivity) => {
    let bakımCount = 0;
    let arızaCount = 0;
    let olmadigiCount = 0;

