import React from 'react';
import { AircraftActivity, DailyStatusCode } from '../types';

interface ActivityGridProps {
  activities: AircraftActivity[];
  startDate: Date;
  endDate: Date;
  title: string;
}

const ActivityGrid: React.FC<ActivityGridProps> = ({ activities, startDate, endDate, title }) => {
  const getDaysInRange = (start: Date, end: Date) => {
    const dates = [];
    let curr = new Date(start);
    const limit = new Date(start);
    limit.setDate(limit.getDate() + 62);
    const finalEnd = end > limit ? limit : end;

    while (curr <= finalEnd) {
      dates.push(new Date(curr));
      curr.setDate(curr.getDate() + 1);
    }
    return dates;
  };

  const visibleDates = getDaysInRange(startDate, endDate);

  const monthLabel = startDate.toLocaleDateString('tr-TR', { month: 'long', year: 'numeric' }).toUpperCase();

  const getStatusColorClass = (code: DailyStatusCode) => {
    switch (code) {
      case 'B': 
      case 'BB': 
      case 'KM': return 'bg-yellow-400 text-black font-bold border-yellow-500'; 
      case 'A': 
      case 'PB': 
      case 'KK': return 'bg-red-500 text-white font-bold border-red-600'; 
      case 'X': return 'bg-purple-600 text-white font-bold border-purple-700'; 
      case 'F': return 'bg-emerald-50 text-emerald-800 border-emerald-100';
      default: return 'bg-white border-gray-100';
    }
  };

  const calculateRowStats = (activity: AircraftActivity) => {
    let bakımCount = 0;
    let arızaCount = 0;
    let olmadigiCount = 0;

    visibleDates.forEach(date => {
      const dayKey = date.getDate();
      const status = activity.dailyStatuses[dayKey];

      if (['B', 'BB', 'KM'].includes(status)) bakımCount++;
      else if (['A', 'PB', 'KK'].includes(status)) arızaCount++;
      else if (status === 'X') olmadigiCount++;
    });

    const totalGFaal = bakımCount + arızaCount + olmadigiCount;
    const totalFaal = visibleDates.length - totalGFaal;

    return { bakımCount, arızaCount, olmadigiCount, totalGFaal, totalFaal };
  };

  const grandTotals = activities.reduce((acc, act) => {
    const stats = calculateRowStats(act);
    return {
      bakım: acc.bakım + stats.bakımCount,
      arıza: acc.arıza + stats.arızaCount,
      olmadigi: acc.olmadigi + stats.olmadigiCount,
      totalGFaal: acc.totalGFaal + stats.totalGFaal,
      totalFaal: acc.totalFaal + stats.totalFaal
    };
  }, { bakım: 0, arıza: 0, olmadigi: 0, totalGFaal: 0, totalFaal: 0 });

  if (activities.length === 0) return null;

  return (
    <div className="mb-10 bg-white rounded-2xl shadow-xl border border-gray-200 overflow-hidden group hover:border-green-500/50 transition-all">
      {/* Section Header */}
      <div className="bg-gradient-to-r from-gray-50 to-white px-6 py-4 border-b border-gray-100 flex items-center justify-between">
        <div className="flex items-center space-x-3">
          <div className="w-2 h-8 bg-green-600 rounded-full"></div>
          <div>
            <h4 className="text-lg font-black text-gray-800 tracking-tight">{title} FİLOSU</h4>
            <p className="text-[10px] font-bold text-gray-400 uppercase tracking-widest">{monthLabel}</p>
          </div>
        </div>
        <div className="flex items-center space-x-4">
          <div className="flex -space-x-2">
             {activities.map((a, i) => (
               <div key={i} className="w-8 h-8 rounded-full bg-green-100 border-2 border-white flex items-center justify-center text-[10px] font-black text-green-700 shadow-sm">
                 {a.kuyrukNo.slice(-2)}
               </div>
             ))}
          </div>
          <span className="text-xs font-black px-3 py-1 bg-green-50 text-green-700 rounded-full border border-green-100 uppercase">
            {activities.length} ARAÇ
          </span>
        </div>
      </div>

      <div className="overflow-x-auto">
        <table className="w-full border-collapse text-[11px] font-medium leading-none">
          <thead>
            <tr className="bg-gray-50/50 text-gray-500 uppercase font-black text-[9px] tracking-wider">
              <th className="border-b border-r border-gray-100 p-3 text-center sticky left-0 bg-gray-50/95 z-10 w-24">Çağrı</th>
              <th className="border-b border-r border-gray-100 p-3 text-center sticky left-24 bg-gray-50/95 z-10 w-24">Kuyruk</th>
              {visibleDates.map((date, idx) => (
                <th key={idx} className="border-b border-r border-gray-100 p-2 text-center min-w-[32px] font-mono">
                  {date.getDate()}
                </th>
              ))}
              <th className="border-b border-r border-gray-100 p-3 text-center bg-yellow-50/50 text-yellow-700 w-16">BKM</th>
              <th className="border-b border-r border-gray-100 p-3 text-center bg-red-50/50 text-red-700 w-16">ARZ</th>
              <th className="border-b border-r border-gray-100 p-3 text-center bg-purple-50/50 text-purple-700 w-16">X</th>
              <th className="border-b border-r border-gray-100 p-3 text-center bg-blue-50/50 text-blue-700 w-20">G.FAAL</th>
              <th className="border-b border-gray-100 p-3 text-center bg-emerald-50/50 text-emerald-700 w-20">FAAL</th>
            </tr>
          </thead>
          <tbody className="divide-y divide-gray-50">
            {activities.map((act, idx) => {
              const stats = calculateRowStats(act);
              return (
                <tr key={idx} className="hover:bg-gray-50 transition-colors group/row">
                  <td className="border-r border-gray-100 px-3 py-4 font-black text-center text-gray-800 sticky left-0 bg-white group-hover/row:bg-gray-50 z-10">{act.cagriKodu}</td>
                  <td className="border-r border-gray-100 px-3 py-4 font-black text-center text-green-700 sticky left-24 bg-white group-hover/row:bg-gray-50 z-10">{act.kuyrukNo}</td>
                  {visibleDates.map((date, dIdx) => {
                    const code = act.dailyStatuses[date.getDate()] || '';
                    return (
                      <td key={dIdx} className={`border-r border-gray-50 p-0 text-center relative`}>
                        <div className={`w-full h-full min-h-[40px] flex items-center justify-center border-b-2 transition-all ${getStatusColorClass(code)}`}>
                          {code}
                        </div>
                      </td>
                    );
                  })}
                  <td className="border-r border-gray-100 text-center px-2 font-black text-yellow-700 bg-yellow-50/20">{stats.bakımCount}</td>
                  <td className="border-r border-gray-100 text-center px-2 font-black text-red-700 bg-red-50/20">{stats.arızaCount}</td>
                  <td className="border-r border-gray-100 text-center px-2 font-black text-purple-700 bg-purple-50/20">{stats.olmadigiCount}</td>
                  <td className="border-r border-gray-100 text-center px-2 font-black text-blue-700 bg-blue-50/20 text-xs">{stats.totalGFaal}</td>
                  <td className="text-center px-2 font-black text-emerald-700 bg-emerald-50/20 text-xs">{stats.totalFaal}</td>
                </tr>
              );
            })}
          </tbody>
          <tfoot className="bg-gray-900 text-white font-black text-[10px] uppercase">
            <tr>
              <td colSpan={2} className="px-4 py-3 text-right tracking-[0.2em] border-r border-white/10">TOPLAM {title}</td>
              {visibleDates.map((_, idx) => <td key={idx} className="border-r border-white/5"></td>)}
              <td className="px-2 py-3 text-center bg-yellow-600 text-white">{grandTotals.bakım}</td>
              <td className="px-2 py-3 text-center bg-red-600 text-white">{grandTotals.arıza}</td>
              <td className="px-2 py-3 text-center bg-purple-600 text-white">{grandTotals.olmadigi}</td>
              <td className="px-2 py-3 text-center bg-blue-600 text-white">{grandTotals.totalGFaal}</td>
              <td className="px-2 py-3 text-center bg-emerald-600 text-white">{grandTotals.totalFaal}</td>
            </tr>
          </tfoot>
        </table>
      </div>
    </div>
  );
};

