import React from 'react';
import { AircraftActivity, DailyStatusCode } from '../types';

interface ActivityGridProps {
  activities: AircraftActivity[];
  startDate: Date;
  endDate: Date;
  title: string;
}

const ActivityGrid: React.FC<ActivityGridProps> = ({ activities, startDate, endDate, title }) => {
  const getDaysInRange = (start: Date, end: Date) => {
    const dates = [];
    let curr = new Date(start);
    const limit = new Date(start);
    limit.setDate(limit.getDate() + 62);
    const finalEnd = end > limit ? limit : end;

    while (curr <= finalEnd) {
      dates.push(new Date(curr));
      curr.setDate(curr.getDate() + 1);
    }
    return dates;
  };

  const visibleDates = getDaysInRange(startDate, endDate);
  const monthLabel = startDate.toLocaleDateString('tr-TR', { month: 'short' });
  const yearSuffix = startDate.getFullYear().toString().slice(-2);
  const periodText = `${monthLabel}.${yearSuffix}`;

  const getStatusColorClass = (code: DailyStatusCode) => {
    switch (code) {
      case 'B': 
      case 'BB': 
      case 'KM': return 'bg-[#ffff00] text-black font-bold'; // Yellow
      case 'A': 
      case 'PB': 
      case 'KK': return 'bg-[#ff0000] text-black font-bold'; // Red
      case 'X': return 'bg-[#9370db] text-black font-bold'; // Purple
      case 'F': return 'bg-white text-black';
      default: return 'bg-white text-black';
    }
  };

  const calculateRowStats = (activity: AircraftActivity) => {
    let bkm = 0, arz = 0, x = 0;
    visibleDates.forEach(date => {
      const day = date.getDate();
      const s = activity.dailyStatuses[day];
      if (['B', 'BB', 'KM'].includes(s)) bkm++;
      else if (['A', 'PB', 'KK'].includes(s)) arz++;
      else if (s === 'X') x++;
    });
    const totalGFaal = bkm + arz + x;
    const totalFaal = visibleDates.length - totalGFaal;
    return { bkm, arz, x, totalGFaal, totalFaal };
  };

  const grandTotals = activities.reduce((acc, act) => {
    const s = calculateRowStats(act);
    return {
      bkm: acc.bkm + s.bkm,
      arz: acc.arz + s.arz,
      x: acc.x + s.x,
      totalGFaal: acc.totalGFaal + s.totalGFaal,
      totalFaal: acc.totalFaal + s.totalFaal
    };
  }, { bkm: 0, arz: 0, x: 0, totalGFaal: 0, totalFaal: 0 });

  if (activities.length === 0) return null;

  return (
    <div className="activity-grid-section mb-12 bg-white p-4 rounded-sm shadow-sm border border-gray-200 font-sans">
      <div className="mb-4">
        <h3 className="text-xl font-black text-gray-900 mb-1">{title} FİLOSU</h3>
        <div className="ml-8 text-sm text-gray-600 space-y-1">
          <p className="font-bold">{periodText}</p>
          <div className="space-y-0.5">
            {activities.map(a => (
              <p key={a.kuyrukNo} className="ml-4 font-bold">{a.kuyrukNo.slice(-2)}</p>
            ))}
          </div>
          <p className="font-bold border-t border-black w-fit pr-4 mt-2">{activities.length} ARAÇ</p>
        </div>
      </div>

      <div className="overflow-x-auto">
        <table className="w-full border-collapse border-2 border-black text-[10px] leading-tight bg-white">
          <thead>
            <tr className="bg-white">
              <th className="border border-black px-2 py-1 w-24">Çağrı</th>
              <th className="border border-black px-2 py-1 w-24">Kuyruk</th>
              {visibleDates.map((date, idx) => (
                <th key={idx} className="border border-black w-7 text-center font-black">{date.getDate()}</th>
              ))}
              <th className="border border-black w-10 text-center font-black bg-gray-50">BKM</th>
              <th className="border border-black w-10 text-center font-black bg-gray-50">ARZ</th>
              <th className="border border-black w-10 text-center font-black bg-gray-50">X</th>
              <th className="border border-black w-14 text-center font-black bg-gray-50">G.FAAL</th>
              <th className="border border-black w-14 text-center font-black bg-gray-50">FAAL</th>
            </tr>
          </thead>
          <tbody>
            {activities.map((act, idx) => {
              const s = calculateRowStats(act);
              return (
                <tr key={idx}>
                  <td className="border border-black px-2 py-1 font-bold text-center">{act.cagriKodu}</td>
                  <td className="border border-black px-2 py-1 font-bold text-center text-green-700">{act.kuyrukNo}</td>
                  {visibleDates.map((date, dIdx) => {
                    const status = act.dailyStatuses[date.getDate()] || '';
                    return (
                      <td key={dIdx} className={`border border-black text-center min-w-[24px] ${getStatusColorClass(status)}`}>
                        {status}
                      </td>
                    );
                  })}
                  <td className="border border-black text-center font-black bg-white">{s.bkm}</td>
                  <td className="border border-black text-center font-black bg-white">{s.arz}</td>
                  <td className="border border-black text-center font-black bg-white">{s.x}</td>
                  <td className="border border-black text-center font-black bg-white">{s.totalGFaal}</td>
                  <td className="border border-black text-center font-black bg-white">{s.totalFaal}</td>
                </tr>
              );
            })}
            <tr className="bg-white font-black">
              <td colSpan={2} className="border border-black px-2 py-1 text-center uppercase">TOPLAM {title}</td>
              {visibleDates.map((_, idx) => <td key={idx} className="border border-black"></td>)}
              <td className="border border-black text-center">{grandTotals.bkm}</td>
              <td className="border border-black text-center">{grandTotals.arz}</td>
              <td className="border border-black text-center">{grandTotals.x}</td>
              <td className="border border-black text-center">{grandTotals.totalGFaal}</td>
              <td className="border border-black text-center">{grandTotals.totalFaal}</td>
            </tr>
          </tbody>
        </table>
      </div>
    </div>
  );
};

