           </div>
           <div className="bg-white p-4 rounded-2xl shadow-lg border-l-8 border-red-500">
             <div className="text-[10px] font-black text-gray-400 uppercase tracking-widest mb-2">Arıza Grubu</div>
             <div className="space-y-1 font-black text-xs text-gray-800"><div>A: Arıza</div><div>PB: Parça Bekler</div><div>KK: Kaza Kırım</div></div>
           </div>
           <div className="bg-white p-4 rounded-2xl shadow-lg border-l-8 border-purple-600">
             <div className="text-[10px] font-black text-gray-400 uppercase tracking-widest mb-2">Özel Durum</div>
             <div className="space-y-1 font-black text-xs text-gray-800"><div>X: Olmadığı Günler</div><div>F: Göreve Hazır</div></div>
