import ActivityGrid from './components/ActivityGrid';
import SplashScreen from './components/SplashScreen';
import { MOCK_AIRCRAFT, MOCK_ACTIVITY_GRID } from './constants';
import { Aircraft, Status } from './types';

const App: React.FC = () => {
  const [isSplashVisible, setIsSplashVisible] = useState(true);
  const [fleet, setFleet] = useState<Aircraft[]>(MOCK_AIRCRAFT);
  const [selectedAircraft, setSelectedAircraft] = useState<Aircraft | null>(null);
  const [editingAircraft, setEditingAircraft] = useState<Aircraft | null>(null);
  const [searchTerm, setSearchTerm] = useState('');

  const today = new Date();
  const firstDay = new Date(today.getFullYear(), today.getMonth(), 1);
  const lastDay = new Date(today.getFullYear(), today.getMonth() + 1, 0);

  const [dateRange, setDateRange] = useState({
    start: firstDay.toISOString().split('T')[0],
    end: lastDay.toISOString().split('T')[0]
  });

  const [activeDateRange, setActiveDateRange] = useState({
    start: firstDay,
    end: lastDay
  });

  const handleFilterActivity = () => {
    setActiveDateRange({
      start: new Date(dateRange.start),
      end: new Date(dateRange.end)
    });
  };

  const filteredFleet = useMemo(() => {
    return fleet.filter(a => 
      a.kuyrukNo.toLowerCase().includes(searchTerm.toLowerCase()) ||
      a.cagriKodu.toLowerCase().includes(searchTerm.toLowerCase()) ||
      a.konum.toLowerCase().includes(searchTerm.toLowerCase())
    );
  }, [fleet, searchTerm]);

  const groupedActivities = useMemo(() => {
    const groups: { [type: string]: any[] } = {};
    MOCK_ACTIVITY_GRID.forEach(act => {
      if (!groups[act.tip]) groups[act.tip] = [];
      groups[act.tip].push(act);
    });
    return groups;
  }, []);

  const handleUpdateStatus = (updates: Partial<Aircraft>) => {
    if (!editingAircraft) return;
    setFleet(prev => prev.map(a => 
      a.kuyrukNo === editingAircraft.kuyrukNo ? { ...a, ...updates } as Aircraft : a
    ));
    setEditingAircraft(null);
  };

  /**
   * Universal stylish Excel export function that preserves colors
   */
  const exportToExcel = (elementId: string, filename: string) => {
    const table = document.getElementById(elementId);
    if (!table) return;

    const clone = table.cloneNode(true) as HTMLElement;
    clone.querySelectorAll('.no-export').forEach(el => el.remove());

    const styles = `
      <style>
        table { border-collapse: collapse; width: 100%; font-family: 'Segoe UI', Tahoma, Geneva, Verdana, sans-serif; border: 2px solid #000000; }
        th, td { border: 1px solid #000000; padding: 6px; text-align: center; vertical-align: middle; font-size: 9pt; }

        /* Summary Table Specific */
        .bg-summary-header { background-color: #D9D9D9 !important; font-weight: bold; }
        .text-red { color: #FF0000 !important; }

        /* Activity Grid Colors */
        .status-bkm, .bg-\\[\\#ffff00\\] { background-color: #FFFF00 !important; color: #000000 !important; font-weight: bold; }
        .status-arz, .bg-\\[\\#ff0000\\] { background-color: #FF0000 !important; color: #FFFFFF !important; font-weight: bold; }
        .status-x, .bg-\\[\\#9370db\\] { background-color: #7030A0 !important; color: #FFFFFF !important; font-weight: bold; }
        .status-faal, .bg-emerald-50 { background-color: #E2F0D9 !important; color: #000000 !important; }

        /* Header/Footer Totals */
        .row-total { background-color: #F2F2F2 !important; font-weight: bold; }
        .grand-total { border-top: 3px double #000000 !important; background-color: #FFFFFF !important; font-weight: 900; }
        .header-title { font-size: 14pt; font-weight: bold; color: #000000; margin-bottom: 10px; text-align: center; }
        .date-label { color: #FF0000; font-weight: bold; text-align: right; font-size: 12pt; }
        .type-filo { font-size: 12pt; font-weight: bold; text-align: left; }
      </style>
    `;

    const htmlContent = `
      <html xmlns:o="urn:schemas-microsoft-com:office:office" xmlns:x="urn:schemas-microsoft-com:office:excel" xmlns="http://www.w3.org/TR/REC-html40">
      <head>
        <meta http-equiv="content-type" content="application/vnd.ms-excel; charset=UTF-8">
        ${styles}
      </head>
      <body>
        ${clone.outerHTML}
      </body>
      </html>
    `;

    const blob = new Blob([htmlContent], { type: 'application/vnd.ms-excel' });
    const url = URL.createObjectURL(blob);
    const link = document.createElement("a");
    link.href = url;
    link.download = `${filename}.xls`;
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
    URL.revokeObjectURL(url);
  };

  const exportAllActivities = () => {
