              <button onClick={() => exportToExcel('summary-container', 'OGM_Hava_Araclari_Durum_Ozeti')} className="bg-green-700 hover:bg-green-800 text-white px-6 py-2 rounded-xl font-black text-xs shadow-2xl transition-all border border-green-600/30 flex items-center">
                <svg className="w-4 h-4 mr-2" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M4 16v1a2 2 0 002 2h12a2 2 0 002-2v-1m-4-4l-4 4m0 0l-4-4m4 4V4" /></svg>
                EXCEL İNDİR
