export default App;

import React from 'react';
import { AircraftActivity, DailyStatusCode } from '../types';

interface ActivityGridProps {
  activities: AircraftActivity[];
  startDate: Date;
  endDate: Date;
  title: string;
}

const ActivityGrid: React.FC<ActivityGridProps> = ({ activities, startDate, endDate, title }) => {
  const getDaysInRange = (start: Date) => {
    const dates = [];
    const year = start.getFullYear();
    const month = start.getMonth();
    const daysInMonth = new Date(year, month + 1, 0).getDate();

    for (let i = 1; i <= daysInMonth; i++) {
      dates.push(new Date(year, month, i));
    }
    return dates;
  };

  const visibleDates = getDaysInRange(startDate);

  const getStatusColorClass = (code: DailyStatusCode) => {
    switch (code) {
      case 'B': 
      case 'BB': 
      case 'KM': return 'bg-[#ffff00] text-black font-bold'; // Yellow
      case 'A': 
      case 'PB': 
      case 'KK': return 'bg-[#ff0000] text-white font-bold'; // Red
      case 'X': return 'bg-[#7030a0] text-white font-bold'; // Purple
      default: return 'bg-white text-black';
    }
  };

  const calculateRowStats = (activity: AircraftActivity) => {
    let bkm = 0, arz = 0, x = 0;
    visibleDates.forEach(date => {
      const day = date.getDate();
      const s = activity.dailyStatuses[day];
      if (['B', 'BB', 'KM'].includes(s)) bkm++;
      else if (['A', 'PB', 'KK'].includes(s)) arz++;
      else if (s === 'X') x++;
    });
    const totalGFaal = bkm + arz + x;
    const totalFaal = visibleDates.length - totalGFaal;
    return { bkm, arz, x, totalGFaal, totalFaal };
  };

  const grandTotals = activities.reduce((acc, act) => {
    const s = calculateRowStats(act);
    return {
      bkm: acc.bkm + s.bkm,
      arz: acc.arz + s.arz,
      x: acc.x + s.x,
      totalGFaal: acc.totalGFaal + s.totalGFaal,
      totalFaal: acc.totalFaal + s.totalFaal
    };
  }, { bkm: 0, arz: 0, x: 0, totalGFaal: 0, totalFaal: 0 });

  if (activities.length === 0) return null;

  return (
    <div className="activity-grid-section mb-1 border-b-8 border-black/10 bg-white p-2">
      <div className="overflow-x-auto">
        <table className="w-full border-collapse border-[2px] border-black text-[9px] font-sans bg-white">
          <thead>
            {/* Main Header Row */}
            <tr className="bg-white">
              <th rowSpan={2} className="border border-black px-1 py-1 w-16">ÇAĞRI KODU</th>
              <th rowSpan={2} className="border border-black px-1 py-1 w-20">KUYRUK NO</th>
              <th rowSpan={2} className="border border-black px-1 py-1 w-20">HAVA ARACI TİPİ</th>
              {visibleDates.map((date, idx) => (
                <th key={idx} className="border border-black w-6 text-center font-bold h-12">
                   <div className="[writing-mode:vertical-lr] rotate-180 py-1">
                      {date.toLocaleDateString('tr-TR', { day: '2-digit', month: '2-digit', year: 'numeric' })}
                   </div>
                </th>
              ))}
              <th colSpan={3} className="border border-black bg-[#00b0f0] text-white py-1">TOPLAM G.FAAL</th>
              <th rowSpan={2} className="border border-black bg-[#00b0f0] text-white px-1 w-12">TOPLAM G.FAAL</th>
              <th rowSpan={2} className="border border-black bg-[#ffc000] text-black px-1 w-12">TOPLAM FAAL</th>
            </tr>
            {/* Sub Header Row for Summary */}
            <tr className="bg-white">
              <th className="border border-black bg-[#ffff00] text-black w-8 [writing-mode:vertical-lr] rotate-180 py-1">BAKIM</th>
              <th className="border border-black bg-[#ff0000] text-white w-8 [writing-mode:vertical-lr] rotate-180 py-1">ARIZA</th>
              <th className="border border-black bg-[#7030a0] text-white w-8 [writing-mode:vertical-lr] rotate-180 py-1">OLMADIĞI</th>
            </tr>
          </thead>
          <tbody>
            {activities.map((act, idx) => {
              const s = calculateRowStats(act);
              return (
                <tr key={idx} className="h-6">
                  <td className="border border-black text-center font-bold px-1">{act.cagriKodu}</td>
