import React from 'react';
import { AircraftActivity, DailyStatusCode } from '../types';

interface ActivityGridProps {
  activities: AircraftActivity[];
  startDate: Date;
  endDate: Date;
  title: string;
}

const ActivityGrid: React.FC<ActivityGridProps> = ({ activities, startDate, endDate, title }) => {
  const getDaysInRange = (start: Date) => {
    const dates = [];
    const year = start.getFullYear();
    const month = start.getMonth();
    const daysInMonth = new Date(year, month + 1, 0).getDate();

    for (let i = 1; i <= daysInMonth; i++) {
      dates.push(new Date(year, month, i));
    }
    return dates;
  };

  const visibleDates = getDaysInRange(startDate);

  const getStatusColorClass = (code: DailyStatusCode) => {
    switch (code) {
      case 'B': 
      case 'BB': 
      case 'KM': return 'bg-[#ffff00] text-black font-bold'; // Sarı
      case 'A': 
      case 'PB': 
      case 'KK': return 'bg-[#ff0000] text-white font-bold'; // Kırmızı
      case 'X': return 'bg-[#7030a0] text-white font-bold'; // Mor
      case 'F': return 'bg-white text-black';
      default: return 'bg-white text-black';
    }
  };

  const calculateRowStats = (activity: AircraftActivity) => {
    let bkm = 0, arz = 0, x = 0;
    visibleDates.forEach(date => {
      const day = date.getDate();
      const s = activity.dailyStatuses[day];
      if (['B', 'BB', 'KM'].includes(s)) bkm++;
      else if (['A', 'PB', 'KK'].includes(s)) arz++;
      else if (s === 'X') x++;
    });
    const totalGFaal = bkm + arz + x;
    const totalFaal = visibleDates.length - totalGFaal;
    return { bkm, arz, x, totalGFaal, totalFaal };
  };

  const grandTotals = activities.reduce((acc, act) => {
    const s = calculateRowStats(act);
    return {
      bkm: acc.bkm + s.bkm,
      arz: acc.arz + s.arz,
      x: acc.x + s.x,
      totalGFaal: acc.totalGFaal + s.totalGFaal,
      totalFaal: acc.totalFaal + s.totalFaal
    };
  }, { bkm: 0, arz: 0, x: 0, totalGFaal: 0, totalFaal: 0 });

  if (activities.length === 0) return null;

  return (
    <div className="activity-grid-section mb-6 bg-white p-1">
      <div className="overflow-x-auto">
        <table className="w-full border-collapse border-[2px] border-black text-[9px] font-sans bg-white">
          <thead>
            {/* Üst Başlık Satırı */}
            <tr className="bg-white">
              <th rowSpan={2} className="border border-black px-1 py-1 w-[80px]">ÇAĞRI KODU</th>
              <th rowSpan={2} className="border border-black px-1 py-1 w-[80px]">KUYRUK NO</th>
              <th rowSpan={2} className="border border-black px-1 py-1 w-[100px]">HAVA ARACI TİPİ</th>
              {visibleDates.map((date, idx) => (
                <th key={idx} rowSpan={2} className="border border-black w-8 text-center font-bold h-20 relative min-w-[32px]">
                   <div className="absolute inset-0 flex items-center justify-center">
                     <span className="[writing-mode:vertical-lr] rotate-180 whitespace-nowrap text-[8px] font-bold">
                        {date.toLocaleDateString('tr-TR', { day: '2-digit', month: '2-digit', year: 'numeric' })}
                     </span>
                   </div>
                </th>
              ))}
              <th colSpan={3} className="border border-black bg-[#00b0f0] text-white py-1 text-[8px] font-bold">TOPLAM G.FAAL</th>
              <th rowSpan={2} className="border border-black bg-[#00b0f0] text-white px-0.5 w-12 text-[8px] font-bold">TOPLAM G.FAAL</th>
              <th rowSpan={2} className="border border-black bg-[#ffc000] text-black px-0.5 w-12 text-[8px] font-bold">TOPLAM FAAL</th>
            </tr>
            {/* Alt Başlık Satırı (Kategoriler) */}
            <tr className="bg-white">
              <th className="border border-black bg-[#ffff00] text-black w-9 text-[7px] py-2 font-bold uppercase">Bakım</th>
              <th className="border border-black bg-[#ff0000] text-white w-9 text-[7px] py-2 font-bold uppercase">Arıza</th>
              <th className="border border-black bg-[#7030a0] text-white w-9 text-[7px] py-2 font-bold uppercase">Olmadığı</th>
            </tr>
          </thead>
          <tbody>
            {activities.map((act, idx) => {
              const s = calculateRowStats(act);
              return (
                <tr key={idx} className="h-7 hover:bg-gray-50">
                  <td className="border border-black text-center font-bold px-1">{act.cagriKodu}</td>
                  <td className="border border-black text-center font-bold px-1">{act.kuyrukNo}</td>
                  <td className="border border-black text-center px-1 uppercase whitespace-nowrap overflow-hidden">{act.tip}</td>
                  {visibleDates.map((date, dIdx) => {
                    const status = act.dailyStatuses[date.getDate()] || '';
                    return (
                      <td key={dIdx} className={`border border-black text-center ${getStatusColorClass(status)}`}>
                        {status}
                      </td>
                    );
                  })}
                  <td className="border border-black text-center font-bold bg-[#ffff99]">{s.bkm || '0'}</td>
                  <td className="border border-black text-center font-bold bg-[#ff9999]">{s.arz || '0'}</td>
                  <td className="border border-black text-center font-bold bg-[#d8d8d8]">{s.x || '0'}</td>
                  <td className="border border-black text-center font-bold bg-[#99ccff]">{s.totalGFaal || '0'}</td>
                  <td className="border border-black text-center font-bold bg-[#ffffcc]">{s.totalFaal || '0'}</td>
                </tr>
              );
            })}
            {/* Alt Toplam Satırı */}
            <tr className="bg-white font-bold h-7">
              <td colSpan={3} className="border border-black text-right px-2 uppercase text-[8px]">TOPLAM</td>
              {visibleDates.map((_, idx) => <td key={idx} className="border border-black bg-gray-50"></td>)}
              <td className="border border-black text-center bg-[#ffff00]">{grandTotals.bkm}</td>
              <td className="border border-black text-center bg-[#ff0000] text-white">{grandTotals.arz}</td>
              <td className="border border-black text-center bg-[#7030a0] text-white">{grandTotals.x}</td>
              <td className="border border-black text-center bg-[#00b0f0] text-white">{grandTotals.totalGFaal}</td>
              <td className="border border-black text-center bg-[#ffc000] text-black">{grandTotals.totalFaal}</td>
            </tr>
          </tbody>
        </table>
      </div>
    </div>
  );
};

