import Dashboard from './components/Dashboard';
import AircraftDetailModal from './components/AircraftDetailModal';
import MaintenanceForm from './components/MaintenanceForm';
import ActivityGrid from './components/ActivityGrid';
import SplashScreen from './components/SplashScreen';
import { MOCK_AIRCRAFT, MOCK_ACTIVITY_GRID } from './constants';
import { Aircraft, Status } from './types';

const App: React.FC = () => {
  const [isSplashVisible, setIsSplashVisible] = useState(true);
  const [isActivityVisible, setIsActivityVisible] = useState(false);
  const [fleet, setFleet] = useState<Aircraft[]>(MOCK_AIRCRAFT);
  const [selectedAircraft, setSelectedAircraft] = useState<Aircraft | null>(null);
  const [editingAircraft, setEditingAircraft] = useState<Aircraft | null>(null);
  const [searchTerm, setSearchTerm] = useState('');

  const today = new Date();
  const firstDay = new Date(today.getFullYear(), today.getMonth(), 1);
  const lastDay = new Date(today.getFullYear(), today.getMonth() + 1, 0);

  const aircraftTypes = ["Tümü", "Bell-429", "AT-802", "T-70", "C-650", "B-360"];
  const [filterType, setFilterType] = useState("Tümü");

  const [dateRange, setDateRange] = useState({
    start: firstDay.toISOString().split('T')[0],
    end: lastDay.toISOString().split('T')[0]
  });

  const [activeDateRange, setActiveDateRange] = useState({
    start: firstDay,
    end: lastDay
  });

  const [activeFilterType, setActiveFilterType] = useState("Tümü");

  const handleFilterActivity = () => {
    setActiveDateRange({
      start: new Date(dateRange.start),
      end: new Date(dateRange.end)
    });
    setActiveFilterType(filterType);
    setIsActivityVisible(true);
  };

  const filteredFleet = useMemo(() => {
    return fleet.filter(a => {
      const matchesSearch = a.kuyrukNo.toLowerCase().includes(searchTerm.toLowerCase()) ||
                            a.cagriKodu.toLowerCase().includes(searchTerm.toLowerCase()) ||
                            a.konum.toLowerCase().includes(searchTerm.toLowerCase());
      return matchesSearch;
    });
  }, [fleet, searchTerm]);

  const groupedActivities = useMemo(() => {
    const groups: { [type: string]: any[] } = {};
    MOCK_ACTIVITY_GRID.forEach(act => {
      if (activeFilterType !== "Tümü" && act.tip !== activeFilterType) return;
      if (!groups[act.tip]) groups[act.tip] = [];
      groups[act.tip].push(act);
    });
    return groups;
  }, [activeFilterType]);

  const handleUpdateStatus = (updates: Partial<Aircraft>) => {
    if (!editingAircraft) return;
    setFleet(prev => prev.map(a => 
      a.kuyrukNo === editingAircraft.kuyrukNo ? { ...a, ...updates } as Aircraft : a
    ));
    setEditingAircraft(null);
  };

  /**
   * Durum Özeti Tablosu Excel Dışa Aktarma (WYSIWYG - Arayüzle Birebir Aynı)
   */
  const exportSummaryExcel = () => {
    const table = document.getElementById('summary-table-content');
    if (!table) return;

    const clone = table.cloneNode(true) as HTMLElement;

    // Stil İşleme: Her hücreye inline stiller ekle
    const cells = clone.querySelectorAll('th, td');
    cells.forEach((cell: any) => {
      cell.style.border = '1px solid black';
      cell.style.padding = '8px';
      cell.style.fontSize = '10pt';
      cell.style.fontFamily = 'Arial, sans-serif';

      // Header Özellikleri (Gri Arka Plan)
      if (cell.tagName === 'TH') {
        cell.style.backgroundColor = '#d9d9d9';
        cell.style.fontWeight = 'bold';
        cell.style.textAlign = 'center';
      } else {
        // TD Özellikleri
        if (cell.classList.contains('text-center')) cell.style.textAlign = 'center';
        if (cell.classList.contains('font-black') || cell.classList.contains('font-bold')) cell.style.fontWeight = 'bold';
        if (cell.classList.contains('italic')) cell.style.fontStyle = 'italic';
      }

      // Kırmızı Platform Tipi Parantez İçi Yazıları
      const redSpans = cell.querySelectorAll('.text-red-600');
      redSpans.forEach((span: any) => {
        span.style.color = '#ff0000';
        span.style.fontWeight = 'bold';
      });
    });

    const html = `
      <html xmlns:o="urn:schemas-microsoft-com:office:office" xmlns:x="urn:schemas-microsoft-com:office:excel" xmlns="http://www.w3.org/TR/REC-html40">
      <head><meta charset="UTF-8"></head>
      <body>
        <table style="width: 100%; border: none; border-collapse: collapse;">
          <tr>
            <td style="font-size: 18pt; font-weight: bold; text-align: center; border: none; padding-bottom: 10px;" colspan="7">
              OGM HAVA ARAÇLARI DURUM ÖZETLERİ
            </td>
          </tr>
          <tr>
            <td style="color: #ff0000; font-weight: bold; text-align: right; font-size: 14pt; border: none; padding-bottom: 10px;" colspan="7">
              ${new Date().toLocaleDateString('tr-TR')}
            </td>
          </tr>
        </table>
        ${clone.outerHTML}
      </body>
      </html>
    `;

    const blob = new Blob([html], { type: 'application/vnd.ms-excel' });
    const url = URL.createObjectURL(blob);
    const link = document.createElement("a");
    link.href = url;
    link.download = `OGM_Hava_Araclari_Durum_Ozeti_${new Date().toLocaleDateString('tr-TR')}.xls`;
    link.click();
    URL.revokeObjectURL(url);
  };

  /**
   * Faaliyet Takvimi Renkli Excel Dışa Aktarma (Inline Style ile Kesin Renklendirme)
   */
  const exportColorfulActivityExcel = () => {
    const monthShort = activeDateRange.start.toLocaleDateString('tr-TR', { month: 'short' });
    const yearShort = activeDateRange.start.getFullYear().toString().slice(-2);
    const titleText = `${monthShort}.${yearShort}`;

    const container = document.createElement('div');

    // Üst Başlık
    const headerTitle = document.createElement('div');
    headerTitle.style.fontSize = '36pt';
    headerTitle.style.fontWeight = 'bold';
    headerTitle.style.textAlign = 'left';
    headerTitle.style.paddingBottom = '20px';
    headerTitle.innerText = titleText;
    container.appendChild(headerTitle);

    // Renk Haritası (Excel için inline stiller)
    const colorMap: { [key: string]: { bg: string, text: string } } = {
      'excel-bg-blue': { bg: '#00b0f0', text: '#ffffff' },
      'excel-bg-orange': { bg: '#ffc000', text: '#000000' },
      'excel-bg-yellow': { bg: '#ffff00', text: '#000000' },
      'excel-bg-red': { bg: '#ff0000', text: '#ffffff' },
      'excel-bg-purple': { bg: '#7030a0', text: '#ffffff' },
      'status-yellow': { bg: '#ffff00', text: '#000000' },
      'status-red': { bg: '#ff0000', text: '#ffffff' },
      'status-purple': { bg: '#7030a0', text: '#ffffff' },
      'excel-bg-light-yellow': { bg: '#ffff99', text: '#000000' },
      'excel-bg-light-red': { bg: '#ff9999', text: '#000000' },
      'excel-bg-gray': { bg: '#d8d8d8', text: '#000000' },
      'excel-bg-light-blue': { bg: '#99ccff', text: '#000000' },
      'excel-bg-cream': { bg: '#ffffcc', text: '#000000' }
    };

    // Gridleri Ekle ve Renkleri Inline Yap
    Object.entries(groupedActivities).forEach(([type, _]) => {
      const original = document.getElementById(`activity-group-${type}`);
      if (original) {
        const grid = original.querySelector('.activity-grid-section');
        if (grid) {
          const clone = grid.cloneNode(true) as HTMLElement;

          // Tüm hücreleri gez ve inline style uygula
          const cells = clone.querySelectorAll('th, td');
          cells.forEach((cell: any) => {
            cell.style.border = '1px solid black';
            cell.style.padding = '4px';
            cell.style.textAlign = 'center';
            cell.style.fontSize = '9pt';

            // Klasör bazlı renklendirmeyi inline style'a çevir
            Object.keys(colorMap).forEach(className => {
              if (cell.classList.contains(className)) {
                cell.style.backgroundColor = colorMap[className].bg;
                cell.style.color = colorMap[className].text;
                cell.setAttribute('bgcolor', colorMap[className].bg); 
              }
            });
          });

          container.appendChild(clone);
          container.appendChild(document.createElement('br'));
        }
      }
    });

    // Görseldeki gibi Dikey Lejant (Inline Styles)
    const legend = document.createElement('div');
    legend.style.marginTop = '20px';
    legend.innerHTML = `
      <table style="border: none; width: 250px; border-collapse: separate; border-spacing: 0 1px;">
        <tr><td style="border: 2px solid black; background-color: #ffff00; color: #000000; font-weight: bold; text-align: left; padding: 6px; font-size: 11pt;" bgcolor="#ffff00">B: BAKIM</td></tr>
        <tr><td style="border: 2px solid black; background-color: #ffff00; color: #000000; font-weight: bold; text-align: left; padding: 6px; font-size: 11pt;" bgcolor="#ffff00">BB: BAKIM BEKLER</td></tr>
        <tr><td style="border: 2px solid black; background-color: #ffff00; color: #000000; font-weight: bold; text-align: left; padding: 6px; font-size: 11pt;" bgcolor="#ffff00">KM: KABUL MUAYENESİ</td></tr>
        <tr><td style="height: 12px; border: none;"></td></tr>
        <tr><td style="border: 2px solid black; background-color: #ff0000; color: #ffffff; font-weight: bold; text-align: left; padding: 6px; font-size: 11pt;" bgcolor="#ff0000">A: ARIZA</td></tr>
        <tr><td style="border: 2px solid black; background-color: #ff0000; color: #ffffff; font-weight: bold; text-align: left; padding: 6px; font-size: 11pt;" bgcolor="#ff0000">PB: PARÇA BEKLER</td></tr>
        <tr><td style="border: 2px solid black; background-color: #ff0000; color: #ffffff; font-weight: bold; text-align: left; padding: 6px; font-size: 11pt;" bgcolor="#ff0000">KK: KAZA KIRIM</td></tr>
        <tr><td style="height: 12px; border: none;"></td></tr>
        <tr><td style="border: 2px solid black; background-color: #7030a0; color: #ffffff; font-weight: bold; text-align: left; padding: 6px; font-size: 11pt;" bgcolor="#7030a0">X: OLMADIĞI GÜNLER</td></tr>
      </table>
    `;
    container.appendChild(legend);

    const html = `
      <html xmlns:o="urn:schemas-microsoft-com:office:office" xmlns:x="urn:schemas-microsoft-com:office:excel" xmlns="http://www.w3.org/TR/REC-html40">
      <head>
        <meta charset="UTF-8">
      </head>
      <body style="font-family: Arial, sans-serif;">
        ${container.innerHTML}
      </body>
      </html>
    `;

    const blob = new Blob([html], { type: 'application/vnd.ms-excel' });
    const url = URL.createObjectURL(blob);
    const link = document.createElement("a");
    link.href = url;
    link.download = `OGM_Faaliyet_Takvimi_${titleText}.xls`;
    link.click();
    URL.revokeObjectURL(url);
  };

  if (isSplashVisible) {
    return <SplashScreen onComplete={() => setIsSplashVisible(false)} />;
  }

  return (
    <Layout>
      <Dashboard fleet={fleet} />

      {/* DURUM ÖZETLERİ BÖLÜMÜ */}
      <div className="mb-20">
        <div className="flex justify-between items-center mb-6 no-export">
           <div className="flex items-center space-x-3">
             <div className="bg-white p-2.5 rounded-2xl shadow-xl border-b-4 border-green-700">
               <svg className="w-6 h-6 text-green-700" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2.5} d="M19 11H5m14 0a2 2 0 012 2v6a2 2 0 01-2 2H5a2 2 0 01-2-2v-6a2 2 0 012-2m14 0V9a2 2 0 00-2-2M5 11V9a2 2 0 012-2m0 0V5a2 2 0 012-2h6a2 2 0 012 2v2M7 7h10" /></svg>
             </div>
             <h3 className="text-xl font-black text-white uppercase tracking-tight">DURUM ÖZET PANELİ</h3>
           </div>
           <div className="flex space-x-2">
              <input type="text" placeholder="Tabloda Ara..." value={searchTerm} onChange={(e) => setSearchTerm(e.target.value)} className="px-4 py-2 bg-white/10 text-white rounded-xl border border-white/20 outline-none focus:ring-2 focus:ring-green-400 font-bold" />
              <button 
                onClick={exportSummaryExcel} 
                className="bg-green-700 hover:bg-green-800 text-white px-6 py-2 rounded-xl font-black text-xs shadow-2xl flex items-center transition-all border border-green-600/30"
              >
                <svg className="w-4 h-4 mr-2" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M4 16v1a2 2 0 002 2h12a2 2 0 002-2v-1m-4-4l-4 4m0 0l-4-4m4 4V4" /></svg>
                DURUM ÖZETİ EXCEL
              </button>
           </div>
        </div>

        <div id="summary-container" className="bg-white p-6 rounded-sm shadow-2xl overflow-hidden font-sans border border-gray-300">
          <div className="flex justify-between items-center mb-6">
             <div className="w-1/4"></div>
             <h2 className="text-center text-xl font-black text-gray-800 uppercase flex-grow">OGM HAVA ARAÇLARI DURUM ÖZETLERİ</h2>
             <div className="w-1/4 text-right text-red-600 font-black text-xl">
                {new Date().toLocaleDateString('tr-TR')}
             </div>
          </div>
          <div className="overflow-x-auto">
            <table id="summary-table-content" className="w-full border-collapse border-[1.5px] border-black text-[12px]">
              <thead>
                <tr className="bg-[#d9d9d9]">
                  <th className="border border-black px-3 py-3 text-center font-black">ÇAĞRI KODU</th>
                  <th className="border border-black px-3 py-3 text-center font-black">KUYRUK NUMARASI</th>
                  <th className="border border-black px-3 py-3 text-center font-black">DURUM</th>
                  <th className="border border-black px-3 py-3 text-center font-black">DURUM AYRINTISI</th>
                  <th className="border border-black px-3 py-3 text-center font-black">KONUM</th>
                  <th className="border border-black px-3 py-3 text-center font-black">FAYDALI SAAT</th>
                  <th className="border border-black px-3 py-3 text-left font-black">AÇIKLAMA</th>
                </tr>
              </thead>
              <tbody>
                {filteredFleet.map((a, i) => (
                  <tr key={i} className="hover:bg-gray-100 cursor-pointer" onClick={() => setSelectedAircraft(a)}>
                    <td className="border border-black px-3 py-2 text-center font-bold">{a.cagriKodu}</td>
                    <td className="border border-black px-3 py-2 text-center font-bold">{a.kuyrukNo} <span className="text-red-600 font-black">({a.platformTipi})</span></td>
                    <td className="border border-black px-3 py-2 text-center font-black">{a.durum}</td>
                    <td className="border border-black px-3 py-2 text-center font-bold">{a.durumAyrintisi !== '-' ? a.durumAyrintisi : ''}</td>
                    <td className="border border-black px-3 py-2 text-center">{a.konum}</td>
                    <td className="border border-black px-3 py-2 text-center font-black text-base">{a.faydaliSaat}</td>
                    <td className="border border-black px-3 py-2 text-left italic text-gray-600 leading-tight">{a.aciklama}</td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
        </div>
      </div>

      {/* FAALİYET TAKVİMİ BÖLÜMÜ */}
      <div className="mb-20">
        <div className="flex flex-col md:flex-row md:items-center justify-between mb-8 gap-4 no-export">
           <div className="flex items-center space-x-3">
             <div className="bg-white p-2.5 rounded-2xl shadow-xl border-b-4 border-orange-600">
               <svg className="w-7 h-7 text-orange-600" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2.5} d="M8 7V3m8 4V3m-9 8h10M5 21h14a2 2 0 002-2V7a2 2 0 00-2-2H5a2 2 0 00-2 2v12a2 2 0 002 2z" /></svg>
             </div>
             <div>
               <h3 className="text-2xl font-black text-white uppercase tracking-tight">FAALİYET TAKVİM ÇİZELGELERİ</h3>
               <p className="text-[10px] font-bold text-orange-400 uppercase tracking-widest">Grup Bazlı Çizelge Yönetimi</p>
             </div>
           </div>

           <div className="flex flex-wrap items-center gap-4">
              <div className="flex items-center space-x-3 bg-white/10 p-2 rounded-[1.5rem] border border-white/20 shadow-2xl backdrop-blur-md">
                 <div className="flex flex-col px-3 border-r border-white/10">
                   <label className="text-[9px] font-black text-orange-300 uppercase tracking-widest">Tip Seçimi</label>
                   <select 
                      value={filterType} 
                      onChange={(e) => setFilterType(e.target.value)}
                      className="bg-transparent text-white font-black text-xs outline-none cursor-pointer appearance-none pr-4"
                   >
                     {aircraftTypes.map(t => <option key={t} value={t} className="bg-green-900">{t}</option>)}
                   </select>
                 </div>
                 <div className="flex flex-col px-3 border-r border-white/10">
                   <label className="text-[9px] font-black text-orange-300 uppercase tracking-widest">Başlangıç</label>
                   <input type="date" value={dateRange.start} onChange={(e) => setDateRange({...dateRange, start: e.target.value})} className="bg-transparent text-white font-black text-xs outline-none cursor-pointer" />
                 </div>
                 <div className="flex flex-col px-3 pr-5">
                   <label className="text-[9px] font-black text-orange-300 uppercase tracking-widest">Bitiş</label>
                   <input type="date" value={dateRange.end} onChange={(e) => setDateRange({...dateRange, end: e.target.value})} className="bg-transparent text-white font-black text-xs outline-none cursor-pointer" />
                 </div>
                 <button onClick={handleFilterActivity} className="bg-orange-500 text-white px-6 py-2.5 rounded-2xl font-black text-xs hover:bg-orange-600 transition-all shadow-xl">SORGULA</button>
              </div>
              <button 
                onClick={exportColorfulActivityExcel} 
                className="bg-orange-600 hover:bg-orange-700 text-white px-6 py-3 rounded-2xl font-black text-xs shadow-2xl flex items-center transition-all border border-orange-500/30"
              >
                <svg className="w-4 h-4 mr-2" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M4 16v1a2 2 0 002 2h12a2 2 0 002-2v-1m-4-4l-4 4m0 0l-4-4m4 4V4" /></svg>
                FAALİYET TAKVİMİ EXCEL (RENKLİ)
              </button>
           </div>
        </div>

        {isActivityVisible && (
        <div className="bg-white p-6 rounded-xl shadow-2xl border border-black/10 overflow-hidden animate-in fade-in slide-in-from-top-4 duration-500">
           <h2 className="text-left text-5xl font-black text-gray-900 uppercase mb-8 tracking-tighter">
             {activeDateRange.start.toLocaleDateString('tr-TR', { month: 'short' })}.{activeDateRange.start.getFullYear().toString().slice(-2)}
           </h2>

           <div className="space-y-4">
             {Object.entries(groupedActivities).map(([type, activities]) => (
               <div key={type} id={`activity-group-${type}`}>
                 <ActivityGrid 
                   activities={activities} 
                   startDate={activeDateRange.start}
                   endDate={activeDateRange.end}
                   title={type}
                 />
               </div>
             ))}
             {Object.keys(groupedActivities).length === 0 && (
               <div className="bg-gray-100 p-12 rounded-2xl border-2 border-dashed border-gray-300 text-center">
                 <p className="text-gray-400 font-black text-lg uppercase">Kayıt Bulunamadı.</p>
               </div>
             )}
           </div>

           {/* Sayfa üzerindeki dikey lejant görünümü */}
           <div className="mt-12 flex flex-col items-start space-y-2 max-w-xs">
              <div className="w-full space-y-0.5">
                <div className="bg-[#ffff00] px-3 py-1.5 border-[1.5px] border-black font-bold text-[11px] leading-tight">B: BAKIM</div>
                <div className="bg-[#ffff00] px-3 py-1.5 border-[1.5px] border-black font-bold text-[11px] leading-tight">BB: BAKIM BEKLER</div>
                <div className="bg-[#ffff00] px-3 py-1.5 border-[1.5px] border-black font-bold text-[11px] leading-tight">KM: KABUL MUAYENESİ</div>
              </div>

              <div className="w-full mt-2 space-y-0.5">
                <div className="bg-[#ff0000] px-3 py-1.5 border-[1.5px] border-black font-bold text-[11px] text-white leading-tight">A: ARIZA</div>
                <div className="bg-[#ff0000] px-3 py-1.5 border-[1.5px] border-black font-bold text-[11px] text-white leading-tight">PB: PARÇA BEKLER</div>
                <div className="bg-[#ff0000] px-3 py-1.5 border-[1.5px] border-black font-bold text-[11px] text-white leading-tight">KK: KAZA KIRIM</div>
              </div>

              <div className="w-full mt-2">
                <div className="bg-[#7030a0] px-3 py-1.5 border-[1.5px] border-black font-bold text-[11px] text-white leading-tight">X: OLMADIĞI GÜNLER</div>
              </div>

              <div className="pt-6 opacity-30 italic font-black text-[10px] uppercase tracking-widest text-gray-600">
                T.C. OGM HAVACILIK {activeDateRange.start.getFullYear()}
              </div>
           </div>
        </div>
        )}
      </div>

      {selectedAircraft && <AircraftDetailModal aircraft={selectedAircraft} onClose={() => setSelectedAircraft(null)} />}
      {editingAircraft && <MaintenanceForm aircraft={editingAircraft} onSave={handleUpdateStatus} onCancel={() => setEditingAircraft(null)} />}
    </Layout>
  );
};

export default App;

import React from 'react';
import { AircraftActivity, DailyStatusCode } from '../types';

interface ActivityGridProps {
  activities: AircraftActivity[];
  startDate: Date;
  endDate: Date;
  title: string;
}

const ActivityGrid: React.FC<ActivityGridProps> = ({ activities, startDate, endDate, title }) => {
  const getDaysInRange = (start: Date) => {
    const dates = [];
    const year = start.getFullYear();
    const month = start.getMonth();
    const daysInMonth = new Date(year, month + 1, 0).getDate();

    for (let i = 1; i <= daysInMonth; i++) {
      dates.push(new Date(year, month, i));
    }
    return dates;
  };

  const visibleDates = getDaysInRange(startDate);

  const getStatusClass = (code: DailyStatusCode) => {
    switch (code) {
      case 'B': 
      case 'BB': 
      case 'KM': return 'bg-[#ffff00] text-black font-bold excel-bg-yellow status-yellow'; 
      case 'A': 
      case 'PB': 
      case 'KK': return 'bg-[#ff0000] text-white font-bold excel-bg-red status-red'; 
      case 'X': return 'bg-[#7030a0] text-white font-bold excel-bg-purple status-purple'; 
      case 'F': return 'bg-white text-black';
      default: return 'bg-white text-black';
    }
  };

  const calculateRowStats = (activity: AircraftActivity) => {
    let bkm = 0, arz = 0, x = 0;
    const days = visibleDates.map(d => d.getDate());

    // Geleneksel toplamlar (her gün sayılır)
    visibleDates.forEach(date => {
      const day = date.getDate();
      const s = activity.dailyStatuses[day];
      if (['B', 'BB', 'KM'].includes(s)) bkm++;
      else if (['A', 'PB', 'KK'].includes(s)) arz++;
      else if (s === 'X') x++;
    });

    // 3 GÜN KURALI HESAPLAMA
    // Sadece 3+ gün üst üste gayrı faal (B, BB, KM, A, PB, KK, X) ise yüzdelikten düşülür.
    let countedGayriFaalForPercent = 0;
    let currentSequence = [];

    days.forEach(day => {
      const status = activity.dailyStatuses[day] || '';
      const isGFaal = ['B', 'BB', 'KM', 'A', 'PB', 'KK', 'X'].includes(status);

      if (isGFaal) {
        currentSequence.push(day);
      } else {
        if (currentSequence.length >= 3) {
          countedGayriFaalForPercent += currentSequence.length;
        }
        currentSequence = [];
      }
    });
    // Son sekansı kontrol et
    if (currentSequence.length >= 3) {
      countedGayriFaalForPercent += currentSequence.length;
    }

    const totalDays = visibleDates.length;
    const operationalDaysForPercent = totalDays - countedGayriFaalForPercent;
    const percentage = ((operationalDaysForPercent / totalDays) * 100).toFixed(0);

    const totalGFaal = bkm + arz + x;
    const totalFaal = totalDays - totalGFaal;

    return { bkm, arz, x, totalGFaal, totalFaal, percentage };
  };

  const grandTotals = activities.reduce((acc, act) => {
    const s = calculateRowStats(act);
    return {
      bkm: acc.bkm + s.bkm,
      arz: acc.arz + s.arz,
      x: acc.x + s.x,
      totalGFaal: acc.totalGFaal + s.totalGFaal,
      totalFaal: acc.totalFaal + s.totalFaal
    };
  }, { bkm: 0, arz: 0, x: 0, totalGFaal: 0, totalFaal: 0 });

  if (activities.length === 0) return null;

  return (
    <div className="activity-grid-section mb-6 bg-white p-1">
      <div className="overflow-x-auto">
        <table className="w-full border-collapse border-[2px] border-black text-[9px] font-sans bg-white excel-table">
          <thead>
            <tr className="bg-white">
              <th rowSpan={2} className="border border-black px-1 py-1 w-[80px]">ÇAĞRI KODU</th>
              <th rowSpan={2} className="border border-black px-1 py-1 w-[80px]">KUYRUK NO</th>
              <th rowSpan={2} className="border border-black px-1 py-1 w-[100px]">HAVA ARACI TİPİ</th>
              {visibleDates.map((date, idx) => (
                <th key={idx} rowSpan={2} className="border border-black w-8 text-center font-bold h-20 relative min-w-[32px] excel-date-cell">
                   <div className="absolute inset-0 flex items-center justify-center">
                     <span className="[writing-mode:vertical-lr] rotate-180 whitespace-nowrap text-[8px] font-bold">
                        {date.toLocaleDateString('tr-TR', { day: '2-digit', month: '2-digit', year: 'numeric' })}
                     </span>
                   </div>
                </th>
              ))}
              <th colSpan={3} className="border border-black bg-[#00b0f0] text-white py-1 text-[8px] font-bold excel-bg-blue">TOPLAM G.FAAL</th>
              <th rowSpan={2} className="border border-black bg-[#00b0f0] text-white px-0.5 w-12 text-[8px] font-bold excel-bg-blue">TOPLAM G.FAAL</th>
              <th rowSpan={2} className="border border-black bg-[#ffc000] text-black px-0.5 w-12 text-[8px] font-bold excel-bg-orange">TOPLAM FAAL</th>
              <th rowSpan={2} className="border border-black bg-gray-800 text-white px-0.5 w-14 text-[8px] font-bold excel-bg-gray800">FAALİYET % **</th>
            </tr>
            <tr className="bg-white">
              <th className="border border-black bg-[#ffff00] text-black w-9 text-[7px] py-2 font-bold uppercase excel-bg-yellow">Bakım</th>
              <th className="border border-black bg-[#ff0000] text-white w-9 text-[7px] py-2 font-bold uppercase excel-bg-red">Arıza</th>
              <th className="border border-black bg-[#7030a0] text-white w-9 text-[7px] py-2 font-bold uppercase excel-bg-purple">Olmadığı</th>
            </tr>
          </thead>
          <tbody>
            {activities.map((act, idx) => {
              const s = calculateRowStats(act);
              return (
                <tr key={idx} className="h-7 hover:bg-gray-50">
                  <td className="border border-black text-center font-bold px-1">{act.cagriKodu}</td>
                  <td className="border border-black text-center font-bold px-1">{act.kuyrukNo}</td>
                  <td className="border border-black text-center px-1 uppercase whitespace-nowrap overflow-hidden">{act.tip}</td>
                  {visibleDates.map((date, dIdx) => {
                    const status = act.dailyStatuses[date.getDate()] || '';
                    return (
                      <td key={dIdx} className={`border border-black text-center ${getStatusClass(status)}`}>
                        {status}
                      </td>
                    );
                  })}
                  <td className="border border-black text-center font-bold bg-[#ffff99] excel-bg-light-yellow">{s.bkm || '0'}</td>
                  <td className="border border-black text-center font-bold bg-[#ff9999] excel-bg-light-red">{s.arz || '0'}</td>
                  <td className="border border-black text-center font-bold bg-[#d8d8d8] excel-bg-gray">{s.x || '0'}</td>
                  <td className="border border-black text-center font-bold bg-[#99ccff] excel-bg-light-blue">{s.totalGFaal || '0'}</td>
                  <td className="border border-black text-center font-bold bg-[#ffffcc] excel-bg-cream">{s.totalFaal || '0'}</td>
                  <td className="border border-black text-center font-black bg-gray-100 text-[10px] excel-bg-gray-100">%{s.percentage}</td>
                </tr>
              );
            })}
            <tr className="bg-white font-bold h-7">
              <td colSpan={3} className="border border-black text-right px-2 uppercase text-[8px]">TOPLAM</td>
              {visibleDates.map((_, idx) => <td key={idx} className="border border-black"></td>)}
              <td className="border border-black text-center bg-[#ffff00] excel-bg-yellow">{grandTotals.bkm}</td>
              <td className="border border-black text-center bg-[#ff0000] text-white excel-bg-red">{grandTotals.arz}</td>
              <td className="border border-black text-center bg-[#7030a0] text-white excel-bg-purple">{grandTotals.x}</td>
              <td className="border border-black text-center bg-[#00b0f0] text-white excel-bg-blue">{grandTotals.totalGFaal}</td>
              <td className="border border-black text-center bg-[#ffc000] text-black excel-bg-orange">{grandTotals.totalFaal}</td>
              <td className="border border-black bg-gray-800"></td>
            </tr>
          </tbody>
        </table>
      </div>
    </div>
  );
};

