/**
 * URL'den Spreadsheet ID ve GID ayıklar
 */
export const parseSheetUrl = (url: string) => {
  const idMatch = url.match(/\/d\/([a-zA-Z0-9-_]+)/);
  const gidMatch = url.match(/gid=([0-9]+)/);
  return {
    id: idMatch ? idMatch[1] : '',
    gid: gidMatch ? gidMatch[1] : '0'
  };
};

/**
 * Belirli bir sayfadaki kolon başlıklarını çeker
 */
export const getSheetHeaders = async (sheetId: string, gid: string): Promise<string[]> => {
  try {
    const url = `https://docs.google.com/spreadsheets/d/${sheetId}/gviz/tq?tqx=out:json&tq=SELECT * LIMIT 1&gid=${gid}`;
    const response = await fetch(url);
    const text = await response.text();
    // Google JSON çıktısı başındaki "/*--WvOndH*/google.visualization.Query.setResponse(" kısmını temizle
    const json = JSON.parse(text.substring(text.indexOf("(") + 1, text.lastIndexOf(")")));
    return json.table.cols.map((col: any) => col.label || `Kolon ${col.id}`);
  } catch (error) {
    console.error("Başlıklar çekilemedi:", error);
    return [];
  }
};

/**
 * Eşleştirmeye göre veriyi Aircraft objelerine dönüştürür
 */
export const fetchAircraftData = async (config: SheetConfig): Promise<Aircraft[]> => {
  if (!config.sheetId) return [];

  try {
    const url = `https://docs.google.com/spreadsheets/d/${config.sheetId}/gviz/tq?tqx=out:json&gid=${config.gid}`;
    const response = await fetch(url);
    const text = await response.text();
    const json = JSON.parse(text.substring(text.indexOf("(") + 1, text.lastIndexOf(")")));

    const rows = json.table.rows;
    const cols = json.table.cols;

    // Kolon indexlerini bul
    const getIdx = (label: string) => cols.findIndex((c: any) => c.label === label);
    const map = config.mapping;

    return rows.map((row: any) => {
      const getVal = (label: string) => {
        const idx = getIdx(label);
        return idx !== -1 ? (row.c[idx]?.v || '') : '';
      };

      const durumRaw = getVal(map.durum).toString().toUpperCase();
      const isFaal = durumRaw.includes('FAAL') && !durumRaw.includes('GAYRİ') && !durumRaw.includes('GAYRI');

      return {
        cagriKodu: getVal(map.cagriKodu).toString(),
        kuyrukNo: getVal(map.kuyrukNo).toString(),
        platformTipi: '-', // Varsayılan
        durum: isFaal ? Status.FAAL : Status.GAYRI_FAAL,
        durumTipi: StatusType.NONE,
        durumAyrintisi: getVal(map.durumAyrintisi).toString(),
        konum: getVal(map.konum).toString(),
        faydaliSaat: parseFloat(getVal(map.faydaliSaat)) || 0,
        aciklama: getVal(map.aciklama).toString(),
        durumBaslangic: new Date().toISOString().split('T')[0],
        guncellemeTarihi: new Date().toLocaleString(),
        seriNo: '-',
        motor: '-',
        uretimYili: 2024,
        base: getVal(map.konum).toString(),
        maintenanceHours: [],
        photos: ['https://picsum.photos/seed/aircraft/800/600']
      } as Aircraft;
    }).filter(a => a.kuyrukNo);
  } catch (error) {
    console.error("Veri çekilemedi:", error);
    return [];
  }
};

