                className={`w-full text-left px-4 py-3 rounded-xl font-black text-sm transition-all flex items-center justify-between ${activeType === type ? 'bg-green-700 text-white shadow-lg translate-x-1' : 'text-gray-600 hover:bg-gray-200'}`}
              >
                <span>{type}</span>
                {configs.find(c => c.aircraftType === type)?.sheetUrl && (
                  <div className="w-2 h-2 rounded-full bg-green-400 shadow-[0_0_8px_rgba(74,222,128,0.6)]"></div>
                )}
              </button>
            ))}
          </div>

          {/* Content */}
          <div className="flex-1 p-8 overflow-y-auto bg-white">
            <div className="max-w-3xl space-y-8">
              <section className="space-y-4">
                <label className="block">
                  <span className="text-xs font-black text-gray-500 uppercase tracking-widest block mb-2">Google E-Tablo URL</span>
                  <input
                    type="text"
                    placeholder="https://docs.google.com/spreadsheets/d/..."
                    value={currentConfig?.sheetUrl || ''}
                    onChange={(e) => handleUrlChange(e.target.value)}
                    className="w-full px-5 py-4 bg-gray-50 border-2 border-gray-100 rounded-2xl outline-none focus:border-green-600 focus:bg-white transition-all font-bold text-gray-700 shadow-inner"
                  />
                </label>
                {currentConfig?.sheetId && (
                  <div className="flex items-center space-x-2 text-[10px] font-black text-green-600 bg-green-50 px-3 py-1.5 rounded-lg w-fit">
                    <svg className="w-3 h-3" fill="currentColor" viewBox="0 0 20 20"><path fillRule="evenodd" d="M16.707 5.293a1 1 0 010 1.414l-8 8a1 1 0 01-1.414 0l-4-4a1 1 0 011.414-1.414L8 12.586l7.293-7.293a1 1 0 011.414 0z" clipRule="evenodd" /></svg>
                    <span>ID TESPİT EDİLDİ: {currentConfig.sheetId}</span>
                  </div>
                )}
              </section>

              <section className="space-y-6">
                <div className="flex items-center justify-between border-b pb-4">
                  <h3 className="font-black text-gray-800 uppercase tracking-tight">KOLON EŞLEŞTİRME</h3>
                  {isLoadingHeaders && <div className="text-xs font-bold text-orange-500 animate-pulse uppercase">Başlıklar Okunuyor...</div>}
                </div>

                <div className="grid grid-cols-2 gap-x-8 gap-y-6">
                  {[
                    { label: 'KUYRUK NUMARASI', key: 'kuyrukNo' as keyof ColumnMapping },
                    { label: 'ÇAĞRI KODU', key: 'cagriKodu' as keyof ColumnMapping },
                    { label: 'DURUM (FAAL/GAYRI)', key: 'durum' as keyof ColumnMapping },
                    { label: 'DURUM AYRINTISI', key: 'durumAyrintisi' as keyof ColumnMapping },
                    { label: 'KONUM', key: 'konum' as keyof ColumnMapping },
                    { label: 'FAYDALI SAAT', key: 'faydaliSaat' as keyof ColumnMapping },
                    { label: 'AÇIKLAMA', key: 'aciklama' as keyof ColumnMapping },
                  ].map((field) => (
                    <div key={field.key} className="space-y-2">
                      <label className="text-[10px] font-black text-gray-400 uppercase tracking-widest block">{field.label}</label>
                      <select
                        value={currentConfig?.mapping[field.key] || ''}
                        onChange={(e) => handleMappingChange(field.key, e.target.value)}
                        className="w-full px-4 py-3 bg-gray-50 border-2 border-gray-100 rounded-xl outline-none focus:border-green-600 font-bold text-sm appearance-none cursor-pointer"
                      >
                        <option value="">Seçiniz...</option>
                        {headers.map(h => <option key={h} value={h}>{h}</option>)}
                      </select>
                    </div>
                  ))}
                </div>
              </section>
            </div>
          </div>
        </div>

        {/* Footer */}
        <div className="p-6 bg-gray-50 border-t flex justify-between items-center">
          <p className="text-[10px] font-black text-gray-400 uppercase max-w-md">
            * Ayarlar yerel tarayıcınıza kaydedilir. Senkronizasyon butonuna bastığınızda tüm hava araçları listesi bu eşleştirmelere göre güncellenecektir.
          </p>
          <div className="flex space-x-3">
            <button 
              onClick={onClose}
              className="px-6 py-3 rounded-xl font-black text-gray-500 hover:bg-gray-200 transition-all text-sm"
            >
              İPTAL
            </button>
            <button 
              onClick={handleSave}
              className="bg-[#14532d] hover:bg-[#052e16] text-white px-10 py-3 rounded-xl font-black text-sm shadow-xl transition-all border-b-4 border-[#052e16]"
            >
              AYARLARI KAYDET VE SENKRONİZE ET
            </button>
          </div>
        </div>
      </div>
    </div>
  );
};

