        <tr><td style="border: 2px solid black; background-color: #ff0000; color: #ffffff; font-weight: bold; text-align: left; padding: 6px; font-size: 11pt;" bgcolor="#ff0000">PB: PARÇA BEKLER</td></tr>
        <tr><td style="border: 2px solid black; background-color: #ff0000; color: #ffffff; font-weight: bold; text-align: left; padding: 6px; font-size: 11pt;" bgcolor="#ff0000">KK: KAZA KIRIM</td></tr>
        <tr><td style="height: 12px; border: none;"></td></tr>
        <tr><td style="border: 2px solid black; background-color: #7030a0; color: #ffffff; font-weight: bold; text-align: left; padding: 6px; font-size: 11pt;" bgcolor="#7030a0">X: OLMADIĞI GÜNLER</td></tr>
      </table>
      <div style="margin-top: 20px; font-size: 10pt; font-weight: bold; font-style: italic; color: #374151;">
        ** Üst üste 3 günden az gayrı faal günleri dahil edilmemiştir.
      </div>
    `;
    container.appendChild(legend);

    const html = `<html xmlns:o="urn:schemas-microsoft-com:office:office" xmlns:x="urn:schemas-microsoft-com:office:excel" xmlns="http://www.w3.org/TR/REC-html40"><head><meta charset="UTF-8"></head><body style="font-family: Arial, sans-serif;">${container.innerHTML}</body></html>`;
    const blob = new Blob([html], { type: 'application/vnd.ms-excel' });
    const url = URL.createObjectURL(blob);
    const link = document.createElement("a");
    link.href = url;
    link.download = `OGM_Faaliyet_Takvimi_${titleText}.xls`;
    link.click();
    URL.revokeObjectURL(url);
  };

  if (isSplashVisible) {
    return <SplashScreen onComplete={() => setIsSplashVisible(false)} />;
  }

  return (
    <Layout>
      <div className="flex justify-end mb-4 space-x-2">
         {isSyncing && (
           <div className="flex items-center space-x-2 px-4 py-2 bg-orange-100 text-orange-700 rounded-xl font-bold text-xs animate-pulse">
             <svg className="w-4 h-4 animate-spin" fill="none" viewBox="0 0 24 24"><circle className="opacity-25" cx="12" cy="12" r="10" stroke="currentColor" strokeWidth="4"></circle><path className="opacity-75" fill="currentColor" d="M4 12a8 8 0 018-8V0C5.373 0 0 5.373 0 12h4zm2 5.291A7.962 7.962 0 014 12H0c0 3.042 1.135 5.824 3 7.938l3-2.647z"></path></svg>
             <span>VERİLER SENKRONİZE EDİLİYOR...</span>
           </div>
         )}
         <button 
           onClick={() => setIsAdminOpen(true)}
           className="bg-gray-800 text-white px-5 py-2.5 rounded-xl font-black text-xs hover:bg-black transition-all shadow-xl flex items-center border-b-4 border-gray-900"
         >
           <svg className="w-4 h-4 mr-2" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2.5} d="M10.325 4.317c.426-1.756 2.924-1.756 3.35 0a1.724 1.724 0 002.573 1.066c1.543-.94 3.31.826 2.37 2.37a1.724 1.724 0 001.065 2.572c1.756.426 1.756 2.924 0 3.35a1.724 1.724 0 00-1.066 2.573c.94 1.543-.826 3.31-2.37 2.37a1.724 1.724 0 00-2.572 1.065c-.426 1.756-2.924 1.756-3.35 0a1.724 1.724 0 00-2.573-1.066c-1.543.94-3.31-.826-2.37-2.37a1.724 1.724 0 00-1.065-2.572c-1.756-.426-1.756-2.924 0-3.35a1.724 1.724 0 001.066-2.573c-.94-1.543.826-3.31 2.37-2.37.996.608 2.296.07 2.572-1.065z" /><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2.5} d="M15 12a3 3 0 11-6 0 3 3 0 016 0z" /></svg>
