import { Aircraft, SheetConfig, Status, StatusType } from "../types";

/**
 * URL'den Spreadsheet ID ayıklar
 */
export const parseSheetUrl = (url: string) => {
  const idMatch = url.match(/\/d\/([a-zA-Z0-9-_]+)/);
  return { id: idMatch ? idMatch[1] : '' };
};

/**
 * Apps Script üzerinden sayfa bilgilerini çeker
 */
export const getSheetDetails = async (scriptUrl: string, sheetId: string, sheetName?: string) => {
  if (!scriptUrl) throw new Error("Apps Script URL tanımlanmamış.");

  const url = `${scriptUrl}?id=${sheetId}${sheetName ? `&sheet=${encodeURIComponent(sheetName)}` : ''}`;
  const response = await fetch(url);
  const json = await response.json();

  if (json.error) throw new Error(json.error);
  return json; // { sheetNames: [], headers: [], data: [] }
};

/**
 * Apps Script verisini Aircraft objelerine dönüştürür
 */
export const fetchAircraftDataFromAppsScript = async (scriptUrl: string, config: SheetConfig): Promise<Aircraft[]> => {
  if (!scriptUrl || !config.sheetId) return [];

  try {
    const json = await getSheetDetails(scriptUrl, config.sheetId, config.sheetName);
    const rows = json.data;
    const map = config.mapping;

    return rows.map((row: any) => {
      const getVal = (key: string) => row[key] || '';

      const durumRaw = getVal(map.durum).toString().toUpperCase();
      const isFaal = durumRaw.includes('FAAL') && !durumRaw.includes('GAYRİ') && !durumRaw.includes('GAYRI');

      return {
        cagriKodu: getVal(map.cagriKodu).toString(),
        kuyrukNo: getVal(map.kuyrukNo).toString(),
        platformTipi: '-',
        durum: isFaal ? Status.FAAL : Status.GAYRI_FAAL,
        durumTipi: StatusType.NONE,
        durumAyrintisi: getVal(map.durumAyrintisi).toString(),
        konum: getVal(map.konum).toString(),
        faydaliSaat: parseFloat(getVal(map.faydaliSaat)) || 0,
        aciklama: getVal(map.aciklama).toString(),
        durumBaslangic: new Date().toISOString().split('T')[0],
        guncellemeTarihi: new Date().toLocaleString(),
        seriNo: '-',
        motor: '-',
        uretimYili: 2024,
        base: getVal(map.konum).toString(),
        maintenanceHours: [],
        photos: ['https://picsum.photos/seed/aircraft/800/600']
      } as Aircraft;
    }).filter(a => a.kuyrukNo);
  } catch (error) {
    console.error("Veri çekme hatası:", error);
    return [];
  }
};

import React, { useState, useEffect } from 'react';
import { SheetConfig, ColumnMapping, GlobalSettings } from '../types';
