const AdminPanel: React.FC<AdminPanelProps> = ({ onSave, onClose }) => {
  const aircraftTypes = ["Bell-429", "AT-802", "T-70", "C-650", "B-360"];
  const [configs, setConfigs] = useState<SheetConfig[]>([]);
  const [settings, setSettings] = useState<GlobalSettings>({ appsScriptUrl: '' });
