          <div className="flex items-center space-x-4">
            <h2 className="text-2xl font-black uppercase">ADMiN VERİ YÖNETİMİ</h2>
          </div>
          <button onClick={onClose} className="p-2 hover:bg-white/10 rounded-full">
            <svg className="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={3} d="M6 18L18 6M6 6l12 12" /></svg>
          </button>
        </div>

        <div className="flex flex-1 overflow-hidden">
          <div className="w-64 bg-gray-50 border-r p-4 space-y-2 overflow-y-auto">
             <div className="mb-6">
                <label className="text-[10px] font-black text-gray-400 uppercase tracking-widest block mb-2">Apps Script API URL</label>
                <input 
                  type="text" 
                  placeholder="https://script.google.com/macros/s/..."
                  value={settings.appsScriptUrl}
                  onChange={(e) => setSettings({ appsScriptUrl: e.target.value })}
                  className="w-full px-3 py-2 text-xs border rounded-lg focus:ring-2 focus:ring-green-500 font-bold"
                />
             </div>
            <h3 className="text-[10px] font-black text-gray-400 uppercase tracking-widest mb-4">Uçak Grupları</h3>
            {aircraftTypes.map(type => (
              <button
                key={type}
                onClick={() => setActiveType(type)}
                className={`w-full text-left px-4 py-3 rounded-xl font-black text-sm transition-all ${activeType === type ? 'bg-green-700 text-white shadow-lg' : 'text-gray-600 hover:bg-gray-200'}`}
              >
                {type}
              </button>
            ))}
          </div>

          <div className="flex-1 p-8 overflow-y-auto bg-white">
            <div className="max-w-3xl space-y-8">
              <section className="space-y-4">
                <label className="block">
                  <span className="text-xs font-black text-gray-500 uppercase block mb-2">Google E-Tablo URL</span>
                  <input
                    type="text"
                    placeholder="https://docs.google.com/spreadsheets/d/..."
                    value={currentConfig?.sheetUrl || ''}
                    onChange={(e) => handleUrlChange(e.target.value)}
                    className="w-full px-5 py-4 bg-gray-50 border-2 rounded-2xl outline-none focus:border-green-600 font-bold"
                  />
                </label>

                <div className="grid grid-cols-2 gap-4">
                  <div className="space-y-2">
                    <label className="text-[10px] font-black text-gray-400 uppercase">Sayfa (Sheet) Seçimi</label>
                    <select
                      value={currentConfig?.sheetName || ''}
                      onChange={(e) => handleSheetNameChange(e.target.value)}
                      className="w-full px-4 py-3 bg-gray-50 border-2 rounded-xl font-bold text-sm"
                    >
                      <option value="">Sayfa Seçiniz...</option>
                      {availableSheets.map(s => <option key={s} value={s}>{s}</option>)}
                    </select>
                  </div>
                  {isLoading && <div className="flex items-center text-orange-500 text-xs font-bold animate-pulse">VERİLER OKUNUYOR...</div>}
                </div>
              </section>

              <section className="space-y-6">
