import MaintenanceForm from './components/MaintenanceForm';
import ActivityGrid from './components/ActivityGrid';
import SplashScreen from './components/SplashScreen';
import AdminPanel from './components/AdminPanel';
import { MOCK_AIRCRAFT, MOCK_ACTIVITY_GRID } from './constants';
import { Aircraft, Status, SheetConfig, GlobalSettings } from './types';
import { fetchAircraftDataFromAppsScript } from './services/sheetService';

const App: React.FC = () => {
  const [isSplashVisible, setIsSplashVisible] = useState(true);
  const [isAdminOpen, setIsAdminOpen] = useState(false);
  const [isActivityVisible, setIsActivityVisible] = useState(false);
  const [fleet, setFleet] = useState<Aircraft[]>(MOCK_AIRCRAFT);
  const [selectedAircraft, setSelectedAircraft] = useState<Aircraft | null>(null);
  const [editingAircraft, setEditingAircraft] = useState<Aircraft | null>(null);
  const [searchTerm, setSearchTerm] = useState('');
  const [isSyncing, setIsSyncing] = useState(false);

  useEffect(() => {
    const savedConfigs = localStorage.getItem('ogm_sheet_configs');
    const savedSettings = localStorage.getItem('ogm_global_settings');
    if (savedConfigs && savedSettings) {
      try {
        const parsedConfigs = JSON.parse(savedConfigs);
        const parsedSettings = JSON.parse(savedSettings);
        if (Array.isArray(parsedConfigs) && parsedSettings) {
          handleSync(parsedConfigs, parsedSettings);
        }
      } catch (e) {
        console.error("Başlangıç senkronizasyon hatası:", e);
      }
    }
  }, []);

  const handleSync = async (configs: SheetConfig[], settings: GlobalSettings) => {
    if (!settings || !settings.appsScriptUrl) return;
    setIsSyncing(true);
    try {
      let newFleet: Aircraft[] = [];
      for (const config of configs) {
        // HATA FIX: config objesinin varlığı ve mapping'in güvenli erişimi kontrol ediliyor
        if (config && config.sheetId && config.mapping && config.mapping.kuyrukNo) {
          const data = await fetchAircraftDataFromAppsScript(settings.appsScriptUrl, config);
          const enrichedData = data.map(a => ({
            ...a,
            platformTipi: config.aircraftType === "Bell-429" || config.aircraftType === "T-70" ? "H" : "SA",
            tip: config.aircraftType
          }));
          newFleet = [...newFleet, ...enrichedData];
        }
      }
      if (newFleet.length > 0) setFleet(newFleet);
    } catch (error) {
      console.error("Senkronizasyon hatası:", error);
    } finally {
      setIsSyncing(false);
    }
  };

  const today = new Date();
  const firstDay = new Date(today.getFullYear(), today.getMonth(), 1);
  const lastDay = new Date(today.getFullYear(), today.getMonth() + 1, 0);

  const [filterType, setFilterType] = useState("Tümü");
  const [dateRange, setDateRange] = useState({
    start: firstDay.toISOString().split('T')[0],
    end: lastDay.toISOString().split('T')[0]
  });
  const [activeDateRange, setActiveDateRange] = useState({ start: firstDay, end: lastDay });
  const [activeFilterType, setActiveFilterType] = useState("Tümü");

  const handleFilterActivity = () => {
    setActiveDateRange({ start: new Date(dateRange.start), end: new Date(dateRange.end) });
    setActiveFilterType(filterType);
    setIsActivityVisible(true);
  };

  const filteredFleet = useMemo(() => {
    return fleet.filter(a => {
      const s = searchTerm.toLowerCase();
      return a.kuyrukNo.toLowerCase().includes(s) || a.cagriKodu.toLowerCase().includes(s) || a.konum.toLowerCase().includes(s);
    });
  }, [fleet, searchTerm]);

  const groupedActivities = useMemo(() => {
    const groups: { [type: string]: any[] } = {};
    MOCK_ACTIVITY_GRID.forEach(act => {
      if (activeFilterType !== "Tümü" && act.tip !== activeFilterType) return;
      if (!groups[act.tip]) groups[act.tip] = [];
      groups[act.tip].push(act);
    });
    return groups;
  }, [activeFilterType]);

  const exportSummaryExcel = () => {
    const table = document.getElementById('summary-table-content');
    if (!table) return;
    const clone = table.cloneNode(true) as HTMLElement;
    const html = `<html><head><meta charset="UTF-8"></head><body>${clone.outerHTML}</body></html>`;
    const blob = new Blob([html], { type: 'application/vnd.ms-excel' });
    const url = URL.createObjectURL(blob);
    const link = document.createElement("a");
    link.href = url;
    link.download = `OGM_Hava_Araclari_Durum_Ozeti.xls`;
    link.click();
  };

  if (isSplashVisible) return <SplashScreen onComplete={() => setIsSplashVisible(false)} />;

  return (
    <Layout>
      <div className="flex justify-end mb-4 space-x-2">
         {isSyncing && (
           <div className="flex items-center px-4 py-2 bg-emerald-100 text-emerald-800 rounded-xl font-black text-[10px] animate-pulse shadow-sm border border-emerald-200">
             <div className="w-2 h-2 bg-emerald-500 rounded-full mr-2"></div>
             BULUT SENKRONİZASYONU AKTİF...
           </div>
         )}
         <button 
           onClick={() => setIsAdminOpen(true)} 
           className="bg-gray-900 hover:bg-black text-white px-6 py-2.5 rounded-xl font-black text-[10px] shadow-xl transition-all border-b-4 border-gray-950 flex items-center uppercase tracking-widest"
         >
           <svg className="w-4 h-4 mr-2 text-green-400" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2.5} d="M10.325 4.317c.426-1.756 2.924-1.756 3.35 0a1.724 1.724 0 002.573 1.066c1.543-.94 3.31.826 2.37 2.37a1.724 1.724 0 001.065 2.572c1.756.426 1.756 2.924 0 3.35a1.724 1.724 0 00-1.066 2.573c.94 1.543-.826 3.31-2.37 2.37a1.724 1.724 0 00-2.572 1.065c-.426 1.756-2.924 1.756-3.35 0a1.724 1.724 0 00-2.573-1.066c-1.543.94-3.31-.826-2.37-2.37a1.724 1.724 0 00-1.065-2.572c-1.756-.426-1.756-2.924 0-3.35a1.724 1.724 0 001.066-2.573c-.94-1.543.826-3.31 2.37-2.37.996.608 2.296.07 2.572-1.065z" /><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2.5} d="M15 12a3 3 0 11-6 0 3 3 0 016 0z" /></svg>
           Yönetici Paneli
         </button>
      </div>

      <Dashboard fleet={fleet} />

      <div className="mb-20">
        <div className="flex flex-col md:flex-row justify-between items-start md:items-center mb-8 gap-4">
           <div>
             <h3 className="text-2xl font-black text-white uppercase tracking-tighter">Hava Aracı Durum Paneli</h3>
             <p className="text-green-400 text-[10px] font-bold uppercase tracking-[0.4em] mt-1">Gerçek Zamanlı Filo Takip Sistemi</p>
           </div>
           <div className="flex items-center space-x-3 w-full md:w-auto">
              <div className="relative flex-grow md:w-64">
                <input 
                  type="text" 
                  placeholder="Kuyruk No, Çağrı Kodu veya Konum Ara..." 
                  value={searchTerm} 
                  onChange={(e) => setSearchTerm(e.target.value)} 
                  className="w-full px-5 py-3 bg-[#0a2f1a] text-white rounded-2xl border border-green-800 focus:border-green-400 outline-none font-bold text-xs shadow-inner transition-all placeholder:text-green-900" 
                />
                <svg className="w-4 h-4 absolute right-4 top-1/2 -translate-y-1/2 text-green-700" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path d="M21 21l-6-6m2-5a7 7 0 11-14 0 7 7 0 0114 0z" strokeWidth={3} strokeLinecap="round" strokeLinejoin="round"/></svg>
              </div>
              <button 
                onClick={exportSummaryExcel} 
                className="bg-green-600 hover:bg-green-500 text-white px-8 py-3 rounded-2xl font-black text-xs shadow-xl border-b-4 border-green-800 transition-all uppercase tracking-widest whitespace-nowrap"
