        </div>
      </div>

      {isActivityVisible && (
        <div className="bg-white p-6 rounded-xl shadow-2xl border border-black/10 overflow-hidden">
           {Object.entries(groupedActivities).map(([type, activities]) => (
             <ActivityGrid key={type} activities={activities} startDate={activeDateRange.start} endDate={activeDateRange.end} title={type} />
           ))}
        </div>
      )}

      {selectedAircraft && <AircraftDetailModal aircraft={selectedAircraft} onClose={() => setSelectedAircraft(null)} />}
      {isAdminOpen && <AdminPanel onSave={handleSync} onClose={() => setIsAdminOpen(false)} />}
    </Layout>
  );
};

