import React, { useState, useEffect } from 'react';
import { SheetConfig, ColumnMapping, GlobalSettings } from '../types';
import { parseSheetUrl, getSheetDetails } from '../services/sheetService';

interface AdminPanelProps {
  onSave: (configs: SheetConfig[], settings: GlobalSettings) => void;
  onClose: () => void;
}

const AdminPanel: React.FC<AdminPanelProps> = ({ onSave, onClose }) => {
  const aircraftTypes = ["Bell-429", "AT-802", "T-70", "C-650", "B-360"];

  const createDefaultConfig = (type: string): SheetConfig => ({
    aircraftType: type,
    sheetUrl: '',
    sheetId: '',
    sheetName: '',
    mapping: {
      kuyrukNo: '',
      cagriKodu: '',
      durum: '',
      durumAyrintisi: '',
      konum: '',
      faydaliSaat: '',
      aciklama: ''
    }
  });

  const [configs, setConfigs] = useState<SheetConfig[]>(aircraftTypes.map(createDefaultConfig));
  const [settings, setSettings] = useState<GlobalSettings>({ appsScriptUrl: '' });
  const [activeType, setActiveType] = useState(aircraftTypes[0]);
  const [availableSheets, setAvailableSheets] = useState<string[]>([]);
  const [headers, setHeaders] = useState<string[]>([]);
  const [isLoading, setIsLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);

  useEffect(() => {
    const savedConfigs = localStorage.getItem('ogm_sheet_configs');
    const savedSettings = localStorage.getItem('ogm_global_settings');

    if (savedSettings) {
      try {
        setSettings(JSON.parse(savedSettings));
      } catch (e) {
        console.error("Settings parse error", e);
      }
    }

    if (savedConfigs) {
      try {
        const parsedConfigs = JSON.parse(savedConfigs);
        if (Array.isArray(parsedConfigs) && parsedConfigs.length > 0) {
          // Eğer kaydedilen veri uçak tiplerini eksik içeriyorsa, defaultlarla merge et
          const merged = aircraftTypes.map(type => {
            const found = parsedConfigs.find(c => c.aircraftType === type);
            return found || createDefaultConfig(type);
          });
          setConfigs(merged);
        }
      } catch (e) {
        console.error("Config parse hatası:", e);
      }
    }
  }, []);

  // HATA FIX: currentConfig'in her zaman bir obje olması garanti ediliyor
  const currentConfig = configs.find(c => c.aircraftType === activeType) || createDefaultConfig(activeType);

  const updateConfig = (updates: Partial<SheetConfig>) => {
    setConfigs(prev => prev.map(c => 
      c.aircraftType === activeType ? { ...c, ...updates } : c
    ));
  };

  const fetchDetails = async (id: string, name?: string) => {
    if (!settings?.appsScriptUrl) {
      setError("Lütfen önce Apps Script API URL'sini girin.");
      return;
    }
    setError(null);
    setIsLoading(true);
    try {
      const details = await getSheetDetails(settings.appsScriptUrl, id, name);
      setAvailableSheets(details.sheetNames || []);
      setHeaders(details.headers || []);
      // Eğer sayfa adı seçilmemişse ve gelen veri varsa ilkini seç
      if (!name && details.sheetNames?.length > 0) {
        updateConfig({ sheetName: details.sheetNames[0] });
      }
    } catch (err: any) {
      setError(err.message);
    } finally {
      setIsLoading(false);
    }
  };

  const handleUrlChange = (url: string) => {
    const { id } = parseSheetUrl(url);
    updateConfig({ sheetUrl: url, sheetId: id });
    if (id && settings?.appsScriptUrl) {
      fetchDetails(id);
    }
  };

  const handleSheetNameChange = (name: string) => {
    updateConfig({ sheetName: name });
    if (currentConfig?.sheetId && settings?.appsScriptUrl) {
      fetchDetails(currentConfig.sheetId, name);
    }
  };

  const handleMappingChange = (key: keyof ColumnMapping, value: string) => {
    if (currentConfig) {
      updateConfig({
        mapping: { ...currentConfig.mapping, [key]: value }
      });
    }
  };

  const handleSave = () => {
    localStorage.setItem('ogm_sheet_configs', JSON.stringify(configs));
    localStorage.setItem('ogm_global_settings', JSON.stringify(settings));
    onSave(configs, settings);
    onClose();
  };

  return (
    <div className="fixed inset-0 z-[200] flex items-center justify-center bg-[#052e16]/95 backdrop-blur-xl p-4">
      <div className="bg-white w-full max-w-6xl rounded-3xl shadow-2xl overflow-hidden flex flex-col max-h-[90vh] border border-green-800/30">
        <div className="bg-[#14532d] p-6 text-white flex justify-between items-center border-b-4 border-green-700">
          <div className="flex items-center space-x-4">
             <div className="p-2 bg-white/10 rounded-xl">
                <svg className="w-8 h-8" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2.5} d="M9 19v-6a2 2 0 00-2-2H5a2 2 0 00-2-2v6a2 2 0 002 2h2a2 2 0 002-2zm0 0V9a2 2 0 012-2h2a2 2 0 012 2v10m-6 0a2 2 0 002 2h2a2 2 0 002-2m0 0V5a2 2 0 012-2h2a2 2 0 012 2v14a2 2 0 01-2 2h-2a2 2 0 01-2-2z" /></svg>
             </div>
             <div>
               <h2 className="text-2xl font-black uppercase tracking-tight leading-none">VERİ MERKEZİ ADMİN</h2>
               <p className="text-[10px] text-green-300 font-bold uppercase tracking-[0.3em] mt-1">E-Tablo & Apps Script Entegrasyonu</p>
             </div>
          </div>
          <button onClick={onClose} className="p-3 hover:bg-white/10 rounded-2xl transition-all">
            <svg className="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={3} d="M6 18L18 6M6 6l12 12" /></svg>
          </button>
        </div>

        <div className="flex flex-1 overflow-hidden">
          <div className="w-72 bg-gray-50 border-r border-gray-200 p-6 flex flex-col">
             <div className="mb-8 bg-white p-4 rounded-2xl border border-gray-200 shadow-sm">
                <label className="text-[10px] font-black text-gray-400 uppercase tracking-widest block mb-3">1. Apps Script Web App URL</label>
                <input 
                  type="text" 
                  placeholder="https://script.google.com/..."
                  value={settings?.appsScriptUrl || ''}
                  onChange={(e) => setSettings({ appsScriptUrl: e.target.value })}
                  className="w-full px-3 py-2.5 text-xs border-2 border-gray-100 rounded-xl focus:border-green-600 outline-none font-bold transition-all"
                />
                <p className="text-[9px] text-gray-400 mt-2 leading-relaxed italic">Apps Script'i 'Web Uygulaması' olarak dağıtın.</p>
             </div>

            <h3 className="text-[10px] font-black text-gray-500 uppercase tracking-widest mb-4 px-2">HAVA ARACI GRUPLARI</h3>
            <div className="space-y-2 flex-1 overflow-y-auto pr-2">
              {aircraftTypes.map(type => (
                <button
                  key={type}
                  onClick={() => setActiveType(type)}
                  className={`w-full text-left px-5 py-4 rounded-2xl font-black text-xs transition-all flex items-center justify-between group ${activeType === type ? 'bg-green-700 text-white shadow-lg translate-x-1' : 'text-gray-500 hover:bg-gray-200 hover:text-gray-800'}`}
                >
                  <span>{type.toUpperCase()}</span>
                  <svg className={`w-4 h-4 transition-transform ${activeType === type ? 'translate-x-0' : '-translate-x-2 opacity-0 group-hover:opacity-100 group-hover:translate-x-0'}`} fill="none" stroke="currentColor" viewBox="0 0 24 24"><path d="M9 5l7 7-7 7" strokeWidth={3} strokeLinecap="round" strokeLinejoin="round"/></svg>
                </button>
              ))}
            </div>
          </div>

          <div className="flex-1 p-10 overflow-y-auto bg-white">
            <div className="max-w-4xl">
              {error && (
                <div className="mb-8 p-4 bg-red-50 border-l-4 border-red-600 rounded-r-xl flex items-center space-x-4">
                  <svg className="w-6 h-6 text-red-600 flex-shrink-0" fill="currentColor" viewBox="0 0 20 20"><path fillRule="evenodd" d="M18 10a8 8 0 11-16 0 8 8 0 0116 0zm-7 4a1 1 0 11-2 0 1 1 0 012 0zm-1-9a1 1 0 00-1 1v4a1 1 0 102 0V6a1 1 0 00-1-1z" clipRule="evenodd"/></svg>
                  <div>
                    <h4 className="text-sm font-black text-red-800 uppercase">Hata</h4>
                    <p className="text-xs text-red-700 font-bold mt-1">{error}</p>
                  </div>
                </div>
              )}

              <div className="grid grid-cols-1 gap-10">
                <section>
                  <h3 className="text-xs font-black text-gray-400 uppercase tracking-[0.2em] mb-6 flex items-center">
                    <span className="bg-green-100 text-green-700 w-6 h-6 rounded-full flex items-center justify-center mr-3 text-[10px]">2</span>
                    E-TABLO YAPILANDIRMASI
                  </h3>

                  <div className="space-y-6">
                    <div>
                      <label className="text-[10px] font-black text-gray-500 uppercase block mb-2 px-1">Google E-Tablo URL</label>
                      <input
                        type="text"
                        placeholder="https://docs.google.com/spreadsheets/d/..."
                        value={currentConfig?.sheetUrl || ''}
                        onChange={(e) => handleUrlChange(e.target.value)}
                        className="w-full px-5 py-4 bg-gray-50 border-2 border-gray-100 rounded-2xl outline-none focus:border-green-600 font-bold"
                      />
                    </div>

                    <div className="grid grid-cols-2 gap-6">
                      <div>
                        <label className="text-[10px] font-black text-gray-500 uppercase block mb-2 px-1">Sayfa (Sheet) Adı</label>
                        <select
                          value={currentConfig?.sheetName || ''}
                          onChange={(e) => handleSheetNameChange(e.target.value)}
                          className="w-full px-5 py-4 bg-gray-50 border-2 border-gray-100 rounded-2xl font-bold text-sm outline-none"
                        >
                          <option value="">Seçiniz...</option>
                          {availableSheets.map(s => <option key={s} value={s}>{s}</option>)}
                        </select>
                      </div>
                      <div className="flex items-end">
                        <button 
                          onClick={() => currentConfig?.sheetId && fetchDetails(currentConfig.sheetId, currentConfig.sheetName)}
                          disabled={isLoading || !currentConfig?.sheetId}
                          className="px-6 py-4 bg-gray-100 hover:bg-gray-200 rounded-2xl font-black text-xs transition-all disabled:opacity-50"
                        >
                          {isLoading ? "Bekleyin..." : "Başlıkları Yenile"}
                        </button>
                      </div>
                    </div>
                  </div>
                </section>

                <section>
                  <h3 className="text-xs font-black text-gray-400 uppercase tracking-[0.2em] mb-6 flex items-center">
                    <span className="bg-green-100 text-green-700 w-6 h-6 rounded-full flex items-center justify-center mr-3 text-[10px]">3</span>
                    KOLON EŞLEŞTİRME
                  </h3>

                  <div className="grid grid-cols-2 gap-x-10 gap-y-6 bg-gray-50/50 p-8 rounded-3xl border border-gray-100">
                    {[
                      { label: 'KUYRUK NUMARASI', key: 'kuyrukNo' as keyof ColumnMapping },
                      { label: 'ÇAĞRI KODU', key: 'cagriKodu' as keyof ColumnMapping },
                      { label: 'DURUM', key: 'durum' as keyof ColumnMapping },
                      { label: 'DURUM AYRINTISI', key: 'durumAyrintisi' as keyof ColumnMapping },
                      { label: 'KONUM', key: 'konum' as keyof ColumnMapping },
                      { label: 'FAYDALI SAAT', key: 'faydaliSaat' as keyof ColumnMapping },
                      { label: 'AÇIKLAMA', key: 'aciklama' as keyof ColumnMapping },
                    ].map((field) => (
                      <div key={field.key} className="space-y-2">
                        <label className="text-[10px] font-black text-gray-400 uppercase tracking-widest block px-1">{field.label}</label>
                        <select
                          value={currentConfig?.mapping[field.key] || ''}
                          onChange={(e) => handleMappingChange(field.key, e.target.value)}
                          className="w-full px-4 py-3 bg-white border-2 border-gray-100 rounded-xl outline-none focus:border-green-600 font-bold text-sm"
                        >
                          <option value="">Seçiniz...</option>
                          {headers.map(h => <option key={h} value={h}>{h}</option>)}
                        </select>
                      </div>
                    ))}
                  </div>
                </section>
              </div>
            </div>
          </div>
        </div>

        <div className="p-8 bg-gray-50 border-t flex justify-end space-x-4">
          <button onClick={onClose} className="px-8 py-3 rounded-2xl font-black text-gray-500 uppercase text-xs">İptal</button>
          <button onClick={handleSave} className="bg-[#14532d] text-white px-12 py-4 rounded-2xl font-black text-xs uppercase tracking-widest border-b-4 border-[#052e16]">
            Kaydet ve Senkronize Et
          </button>
        </div>
      </div>
    </div>
  );
};

