interface AdminPanelProps {
  onSave: (configs: SheetConfig[], settings: GlobalSettings) => void;
  onClose: () => void;
}

const AdminPanel: React.FC<AdminPanelProps> = ({ onSave, onClose }) => {
  const aircraftTypes = ["Bell-429", "AT-802", "T-70", "C-650", "B-360"];

  // Varsayılan URL'ler
  const DEFAULT_SCRIPT_URL = "https://script.google.com/macros/s/AKfycbz0yzWM9ZB9d6m7mpaPqDDCdcHsMQTA14tW_vVztMxxSAet2cO4PsCAxfnZNZFz_b6t/exec";
  const DEFAULT_BELL_URL = "https://docs.google.com/spreadsheets/d/1D83TF8K1QG30kBv2sCqnPCMYsdSbaJfcsw-E3S5A9VQ/edit?rm=minimal";

  const createDefaultConfig = (type: string): SheetConfig => ({
    aircraftType: type,
    sheetUrl: type === "Bell-429" ? DEFAULT_BELL_URL : '',
    sheetId: type === "Bell-429" ? parseSheetUrl(DEFAULT_BELL_URL).id : '',
    sheetName: '',
    mapping: {
      kuyrukNo: '',
      cagriKodu: '',
      durum: '',
      durumAyrintisi: '',
      konum: '',
      faydaliSaat: '',
      aciklama: ''
    }
  });

  const [configs, setConfigs] = useState<SheetConfig[]>(aircraftTypes.map(createDefaultConfig));
  const [settings, setSettings] = useState<GlobalSettings>({ appsScriptUrl: DEFAULT_SCRIPT_URL });
  const [activeType, setActiveType] = useState(aircraftTypes[0]);
  const [availableSheets, setAvailableSheets] = useState<string[]>([]);
  const [headers, setHeaders] = useState<string[]>([]);
  const [previewData, setPreviewData] = useState<any>(null);
  const [isLoading, setIsLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);

  useEffect(() => {
    const savedConfigs = localStorage.getItem('ogm_sheet_configs');
    const savedSettings = localStorage.getItem('ogm_global_settings');

    if (savedSettings) {
        try { setSettings(JSON.parse(savedSettings)); } catch(e) {}
    }

    if (savedConfigs) {
      try {
        const parsed = JSON.parse(savedConfigs);
        if (Array.isArray(parsed)) {
            const merged = aircraftTypes.map(type => parsed.find(c => c.aircraftType === type) || createDefaultConfig(type));
            setConfigs(merged);
        }
      } catch (e) {}
    }
  }, []);

  const currentConfig = configs.find(c => c.aircraftType === activeType) || createDefaultConfig(activeType);

  // Excel iFrame URL'sini temizle ve minimal hale getir
  const embedUrl = useMemo(() => {
    if (!currentConfig.sheetUrl) return "";
    let base = currentConfig.sheetUrl.split('/edit')[0];
    return `${base}/edit?rm=minimal&ui=2&chrome=false`;
  }, [currentConfig.sheetUrl]);

  const fetchDetails = async (id: string, name?: string) => {
    if (!settings?.appsScriptUrl) return;
    setIsLoading(true);
    setError(null);
    try {
      const details = await getSheetDetails(settings.appsScriptUrl, id, name);
      setAvailableSheets(details.sheetNames || []);
      setHeaders(details.headers || []);
      if (details.data && details.data.length > 0) {
        setPreviewData(details.data[0]); // İlk satırı önizleme için al
      }
      if (!name && details.sheetNames?.length > 0) {
        updateConfig({ sheetName: details.sheetNames[0] });
      }
    } catch (err: any) {
      setError("Bağlantı başarısız: " + err.message);
    } finally {
      setIsLoading(false);
    }
  };

  useEffect(() => {
    if (currentConfig.sheetId) {
        fetchDetails(currentConfig.sheetId, currentConfig.sheetName);
    }
  }, [activeType]);

  const updateConfig = (updates: Partial<SheetConfig>) => {
    setConfigs(prev => prev.map(c => 
      c.aircraftType === activeType ? { ...c, ...updates } : c
    ));
  };

  const handleUrlChange = (url: string) => {
    const { id } = parseSheetUrl(url);
    updateConfig({ sheetUrl: url, sheetId: id });
    if (id) fetchDetails(id);
  };

  const handleMappingChange = (key: keyof ColumnMapping, value: string) => {
    updateConfig({ mapping: { ...currentConfig.mapping, [key]: value } });
  };

  const handleSave = () => {
    localStorage.setItem('ogm_sheet_configs', JSON.stringify(configs));
    localStorage.setItem('ogm_global_settings', JSON.stringify(settings));
    onSave(configs, settings);
    onClose();
  };

