    <div className="fixed inset-0 z-[200] flex items-center justify-center bg-black/90 backdrop-blur-xl p-4">
      <div className="bg-[#0f172a] w-full h-full max-w-[1800px] max-h-[95vh] rounded-[3rem] shadow-[0_0_150px_rgba(34,197,94,0.2)] overflow-hidden flex flex-col border border-white/10">

