import React, { useState, useEffect, useMemo, useRef } from 'react';
import { SheetConfig, ColumnMapping, GlobalSettings } from '../types';
import { parseSheetUrl, getSheetDetails } from '../services/sheetService';

interface AdminPanelProps {
  onSave: (configs: SheetConfig[], settings: GlobalSettings) => void;
  onClose: () => void;
}

const AdminPanel: React.FC<AdminPanelProps> = ({ onSave, onClose }) => {
  const aircraftTypes = ["Bell-429", "AT-802", "T-70", "C-650", "B-360"];
  const DEFAULT_SCRIPT_URL = "https://script.google.com/macros/s/AKfycbz0yzWM9ZB9d6m7mpaPqDDCdcHsMQTA14tW_vVztMxxSAet2cO4PsCAxfnZNZFz_b6t/exec";
  const DEFAULT_BELL_URL = "https://docs.google.com/spreadsheets/d/1D83TF8K1QG30kBv2sCqnPCMYsdSbaJfcsw-E3S5A9VQ/edit?rm=minimal";

  const createDefaultConfig = (type: string): SheetConfig => ({
    aircraftType: type,
    sheetUrl: type === "Bell-429" ? DEFAULT_BELL_URL : '',
    sheetId: type === "Bell-429" ? parseSheetUrl(DEFAULT_BELL_URL).id : '',
    sheetName: '',
    mapping: {
      kuyrukNo: '',
      cagriKodu: '',
      durum: '',
      durumAyrintisi: '',
      konum: '',
      faydaliSaat: '',
      aciklama: ''
    }
  });

  const [configs, setConfigs] = useState<SheetConfig[]>(aircraftTypes.map(createDefaultConfig));
  const [settings, setSettings] = useState<GlobalSettings>({ appsScriptUrl: DEFAULT_SCRIPT_URL });
  const [activeType, setActiveType] = useState(aircraftTypes[0]);
  const [headers, setHeaders] = useState<string[]>([]);
  const [previewData, setPreviewData] = useState<any>(null);
  const [isLoading, setIsLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);

  // Context Menu State
  const [contextMenu, setContextMenu] = useState<{ x: number, y: number, header: string } | null>(null);

  const currentConfig = configs.find(c => c.aircraftType === activeType) || createDefaultConfig(activeType);

  useEffect(() => {
    const savedConfigs = localStorage.getItem('ogm_sheet_configs');
    if (savedConfigs) {
      try {
        const parsed = JSON.parse(savedConfigs);
        setConfigs(aircraftTypes.map(type => parsed.find((c: any) => c.aircraftType === type) || createDefaultConfig(type)));
      } catch (e) {}
    }
  }, []);

  const fetchDetails = async (id: string, name?: string) => {
    if (!settings?.appsScriptUrl) return;
    setIsLoading(true);
    try {
      const details = await getSheetDetails(settings.appsScriptUrl, id, name);
      setHeaders(details.headers || []);
      if (details.data?.length > 0) setPreviewData(details.data[0]);
      if (!name && details.sheetNames?.length > 0) {
        updateConfig({ sheetName: details.sheetNames[0] });
      }
    } catch (err: any) {
      setError(err.message);
    } finally {
      setIsLoading(false);
    }
  };

  useEffect(() => {
    if (currentConfig.sheetId) fetchDetails(currentConfig.sheetId, currentConfig.sheetName);
  }, [activeType]);

  const updateConfig = (updates: Partial<SheetConfig>) => {
    setConfigs(prev => prev.map(c => c.aircraftType === activeType ? { ...c, ...updates } : c));
  };

  const handleMappingChange = (key: keyof ColumnMapping, value: string) => {
    updateConfig({ mapping: { ...currentConfig.mapping, [key]: value } });
    setContextMenu(null);
  };

  const onHeaderContextMenu = (e: React.MouseEvent, header: string) => {
    e.preventDefault();
    setContextMenu({ x: e.clientX, y: e.clientY, header });
  };

  const MAPPING_FIELDS = [
    { label: 'TESCİL / KUYRUK NO', key: 'kuyrukNo' as keyof ColumnMapping },
    { label: 'ÇAĞRI KODU', key: 'cagriKodu' as keyof ColumnMapping },
    { label: 'DURUM', key: 'durum' as keyof ColumnMapping },
    { label: 'DURUM AYRINTISI', key: 'durumAyrintisi' as keyof ColumnMapping },
    { label: 'KONUM', key: 'konum' as keyof ColumnMapping },
    { label: 'FAYDALI SAAT', key: 'faydaliSaat' as keyof ColumnMapping },
    { label: 'AÇIKLAMA', key: 'aciklama' as keyof ColumnMapping },
  ];

  return (
    <div className="fixed inset-0 z-[200] flex items-center justify-center bg-black/95 backdrop-blur-2xl p-4" onClick={() => setContextMenu(null)}>
      <div className="bg-[#020617] w-full h-full max-w-[1900px] max-h-[96vh] rounded-[3.5rem] shadow-[0_0_150px_rgba(34,197,94,0.1)] overflow-hidden flex flex-col border border-white/5">

        {/* Header Area */}
        <div className="bg-slate-900/50 p-8 flex items-center justify-between border-b border-white/5">
          <div className="flex items-center space-x-8">
            <div className="w-14 h-14 bg-gradient-to-br from-green-400 to-green-600 rounded-[1.5rem] flex items-center justify-center shadow-[0_0_40px_rgba(34,197,94,0.3)]">
              <svg className="w-8 h-8 text-white" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={3} d="M15 15l-2 5L9 9l11 4-5 2zm0 0l5 5" /></svg>
            </div>
            <div>
              <h2 className="text-3xl font-black text-white uppercase tracking-tighter leading-none">INTERAKTİF HÜCRE HARİTALAMA</h2>
              <p className="text-[10px] text-green-500 font-bold uppercase tracking-[0.5em] mt-2">Başlık seçin ve sağ tıklayarak atama yapın</p>
            </div>
          </div>

          <div className="flex items-center space-x-3">
             {aircraftTypes.map(t => (
               <button key={t} onClick={() => setActiveType(t)} className={`px-6 py-3 rounded-2xl text-[10px] font-black uppercase tracking-widest transition-all ${activeType === t ? 'bg-green-600 text-white shadow-xl scale-105' : 'bg-white/5 text-gray-500 hover:text-white hover:bg-white/10'}`}>{t}</button>
             ))}
             <button onClick={onClose} className="ml-6 p-3 text-gray-500 hover:text-white transition-colors"><svg className="w-8 h-8" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path d="M6 18L18 6M6 6l12 12" strokeWidth={3} strokeLinecap="round" strokeLinejoin="round"/></svg></button>
          </div>
        </div>

        <div className="flex-1 flex overflow-hidden">
          {/* Left: Interactive Grid Context */}
          <div className="w-3/5 bg-black p-6 flex flex-col space-y-6">
             <div className="flex-1 rounded-[2.5rem] overflow-hidden border border-white/10 relative group">
                <iframe src={`${currentConfig.sheetUrl.split('/edit')[0]}/edit?rm=minimal`} className="w-full h-full grayscale opacity-40 group-hover:grayscale-0 group-hover:opacity-100 transition-all duration-700 pointer-events-none" />
                <div className="absolute inset-0 bg-gradient-to-t from-black via-transparent to-transparent pointer-events-none" />
                <div className="absolute top-8 left-8 bg-green-500 text-black px-4 py-2 rounded-xl font-black text-[10px] uppercase tracking-widest shadow-2xl">CANLI REFERANS GÖRÜNÜMÜ</div>
             </div>

             {/* Header Chips (Interactive Area) */}
             <div className="bg-slate-900/30 p-8 rounded-[2.5rem] border border-white/5 space-y-4">
                <div className="flex items-center justify-between mb-4">
                  <h4 className="text-[10px] font-black text-gray-400 uppercase tracking-widest">Tespit Edilen Sütun Başlıkları</h4>
                  <span className="text-[9px] text-green-500/50 font-mono">Fare ile üzerine gelip sağ tıklayın</span>
                </div>
                <div className="flex flex-wrap gap-3">
                   {headers.map((h, i) => (
                     <div 
                        key={i}
                        onContextMenu={(e) => onHeaderContextMenu(e, h)}
                        className={`px-5 py-3 rounded-xl border font-bold text-xs cursor-context-menu transition-all transform hover:scale-105 active:scale-95 flex items-center space-x-3 ${Object.values(currentConfig.mapping).includes(h) ? 'bg-green-500/20 border-green-500/50 text-green-400 shadow-[0_0_20px_rgba(34,197,94,0.2)]' : 'bg-white/5 border-white/10 text-gray-400 hover:border-white/30 hover:text-white'}`}
                     >
                       <span className="opacity-30">#{(i+1).toString().padStart(2, '0')}</span>
                       <span>{h}</span>
                       {previewData?.[h] && <span className="text-[9px] text-gray-600 font-mono">({previewData[h]})</span>}
                     </div>
                   ))}
                </div>
             </div>
          </div>

          {/* Right: Target Mapping slots */}
          <div className="w-2/5 p-10 bg-[#020617] overflow-y-auto">
             <div className="max-w-md mx-auto space-y-12">
                <div className="space-y-4">
                  <h3 className="text-[10px] font-black text-green-500 uppercase tracking-[0.4em] flex items-center">
                    <span className="w-12 h-[1px] bg-green-500/20 mr-4"></span>
                    HEDEF ATAMALARI
                  </h3>
                  <p className="text-xs text-gray-500 leading-relaxed font-medium">Sol taraftaki başlıklardan birine sağ tıklayarak aşağıdaki alanlara hızlıca atama yapabilirsiniz.</p>
                </div>

                <div className="space-y-6">
                   {MAPPING_FIELDS.map((field) => (
                     <div key={field.key} className="relative group">
                        <div className={`absolute -inset-2 bg-gradient-to-r from-green-500/10 to-transparent rounded-3xl opacity-0 group-hover:opacity-100 transition-opacity pointer-events-none ${currentConfig.mapping[field.key] ? 'opacity-100' : ''}`} />
                        <div className="relative p-5 bg-white/[0.02] border border-white/5 rounded-3xl flex items-center justify-between transition-all hover:border-white/20">
                           <div className="space-y-1">
                              <span className="text-[8px] font-black text-gray-500 uppercase tracking-widest">{field.label}</span>
                              <div className="font-bold text-sm text-white flex items-center">
                                 {currentConfig.mapping[field.key] ? (
                                   <span className="text-green-400 flex items-center animate-in slide-in-from-left-2">
                                     <svg className="w-4 h-4 mr-2" fill="currentColor" viewBox="0 0 20 20"><path fillRule="evenodd" d="M16.707 5.293a1 1 0 010 1.414l-8 8a1 1 0 01-1.414 0l-4-4a1 1 0 011.414-1.414L8 12.586l7.293-7.293a1 1 0 011.414 0z" clipRule="evenodd"/></svg>
                                     {currentConfig.mapping[field.key]}
                                   </span>
                                 ) : (
                                   <span className="text-gray-700 italic">Atanmadı...</span>
                                 )}
                              </div>
                           </div>
                           <button 
                             onClick={() => updateConfig({ mapping: { ...currentConfig.mapping, [field.key]: '' } })}
                             className={`p-2 text-gray-600 hover:text-red-400 transition-colors ${!currentConfig.mapping[field.key] && 'invisible'}`}
                           >
                             <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path d="M6 18L18 6M6 6l12 12" strokeWidth={2.5}/></svg>
                           </button>
                        </div>
                     </div>
                   ))}
                </div>

                <div className="pt-10">
                   <button 
                      onClick={() => { localStorage.setItem('ogm_sheet_configs', JSON.stringify(configs)); onSave(configs, settings); onClose(); }}
                      className="w-full bg-green-600 hover:bg-green-500 text-white py-6 rounded-[2rem] font-black text-xs uppercase tracking-[0.3em] shadow-[0_20px_50px_rgba(34,197,94,0.3)] transition-all active:scale-95 flex items-center justify-center space-x-4 border-b-4 border-green-800"
                   >
                      <span>KONFİGÜRASYONU TAMAMLA</span>
                      <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path d="M9 12l2 2 4-4m6 2a9 9 0 11-18 0 9 9 0 0118 0z" strokeWidth={3}/></svg>
                   </button>
                </div>
             </div>
          </div>
        </div>

        {/* Custom Context Menu */}
        {contextMenu && (
          <div 
            className="fixed z-[300] bg-[#1e293b] border border-white/10 rounded-2xl shadow-2xl py-2 w-64 animate-in fade-in zoom-in-95 duration-100"
            style={{ top: contextMenu.y, left: contextMenu.x }}
