import React, { useState, useMemo, useEffect } from 'react';
import Layout from './components/Layout';
import Dashboard from './components/Dashboard';
import AircraftDetailModal from './components/AircraftDetailModal';
import MaintenanceForm from './components/MaintenanceForm';
import ActivityGrid from './components/ActivityGrid';
import SplashScreen from './components/SplashScreen';
import AdminPanel from './components/AdminPanel';
import { MOCK_AIRCRAFT, MOCK_ACTIVITY_GRID } from './constants';
import { Aircraft, Status, SheetConfig, GlobalSettings } from './types';
import { fetchAircraftDataFromAppsScript } from './services/sheetService';

const App: React.FC = () => {
  const [isSplashVisible, setIsSplashVisible] = useState(true);
  const [isAdminOpen, setIsAdminOpen] = useState(false);
  const [isActivityVisible, setIsActivityVisible] = useState(false);
  const [fleet, setFleet] = useState<Aircraft[]>(MOCK_AIRCRAFT);
  const [selectedAircraft, setSelectedAircraft] = useState<Aircraft | null>(null);
  const [editingAircraft, setEditingAircraft] = useState<Aircraft | null>(null);
  const [searchTerm, setSearchTerm] = useState('');
  const [isSyncing, setIsSyncing] = useState(false);

  // Tarih Filtreleme State'leri
  const today = new Date();
  const firstDay = new Date(today.getFullYear(), today.getMonth(), 1);
  const lastDay = new Date(today.getFullYear(), today.getMonth() + 1, 0);

  const [filterType, setFilterType] = useState("Tümü");
  const [dateRange, setDateRange] = useState({
    start: firstDay.toISOString().split('T')[0],
    end: lastDay.toISOString().split('T')[0]
  });
  const [activeDateRange, setActiveDateRange] = useState({ start: firstDay, end: lastDay });
  const [activeFilterType, setActiveFilterType] = useState("Tümü");

  useEffect(() => {
    const savedConfigs = localStorage.getItem('ogm_sheet_configs');
    const savedSettings = localStorage.getItem('ogm_global_settings');
    if (savedConfigs && savedSettings) {
      try {
        const parsedConfigs = JSON.parse(savedConfigs);
        const parsedSettings = JSON.parse(savedSettings);
        if (Array.isArray(parsedConfigs) && parsedSettings) {
          handleSync(parsedConfigs, parsedSettings);
        }
      } catch (e) {
        console.error("Başlangıç senkronizasyon hatası:", e);
      }
    }
  }, []);

  const handleSync = async (configs: SheetConfig[], settings: GlobalSettings) => {
    if (!settings || !settings.appsScriptUrl) return;
    setIsSyncing(true);
    try {
      let newFleet: Aircraft[] = [];
      for (const config of configs) {
        if (config && config.sheetId && config.mapping && config.mapping.kuyrukNo) {
          const data = await fetchAircraftDataFromAppsScript(settings.appsScriptUrl, config);
          const enrichedData = data.map(a => ({
            ...a,
            platformTipi: config.aircraftType === "Bell-429" || config.aircraftType === "T-70" ? "H" : "SA",
            tip: config.aircraftType
          }));
          newFleet = [...newFleet, ...enrichedData];
        }
      }
      if (newFleet.length > 0) setFleet(newFleet);
    } catch (error) {
      console.error("Senkronizasyon hatası:", error);
    } finally {
      setIsSyncing(false);
    }
  };

  const handleFilterActivity = () => {
    setActiveDateRange({ start: new Date(dateRange.start), end: new Date(dateRange.end) });
    setActiveFilterType(filterType);
    setIsActivityVisible(true);
  };

  const filteredFleet = useMemo(() => {
    return fleet.filter(a => {
      const s = searchTerm.toLowerCase();
      return a.kuyrukNo.toLowerCase().includes(s) || a.cagriKodu.toLowerCase().includes(s) || a.konum.toLowerCase().includes(s);
    });
  }, [fleet, searchTerm]);

  const groupedActivities = useMemo(() => {
    const groups: { [type: string]: any[] } = {};
    MOCK_ACTIVITY_GRID.forEach(act => {
      if (activeFilterType !== "Tümü" && act.tip !== activeFilterType) return;
      if (!groups[act.tip]) groups[act.tip] = [];
      groups[act.tip].push(act);
    });
    return groups;
  }, [activeFilterType]);

  const exportSummaryExcel = () => {
    const table = document.getElementById('summary-table-content');
    if (!table) return;
    const clone = table.cloneNode(true) as HTMLElement;
    const html = `<html><head><meta charset="UTF-8"><style>table { border-collapse: collapse; } td, th { border: 1px solid black; padding: 5px; }</style></head><body>${clone.outerHTML}</body></html>`;
    const blob = new Blob([html], { type: 'application/vnd.ms-excel' });
    const url = URL.createObjectURL(blob);
    const link = document.createElement("a");
    link.href = url;
    link.download = `OGM_Hava_Araclari_Durum_Ozeti_${new Date().toISOString().split('T')[0]}.xls`;
    link.click();
  };

  if (isSplashVisible) return <SplashScreen onComplete={() => setIsSplashVisible(false)} />;

  return (
    <Layout>
      {/* Header Actions */}
      <div className="flex justify-between items-center mb-8">
         <div className="flex items-center space-x-3">
           {isSyncing && (
             <div className="flex items-center px-4 py-2 bg-emerald-500/10 text-emerald-400 rounded-xl font-black text-[10px] animate-pulse border border-emerald-500/20 shadow-lg shadow-emerald-500/5 uppercase tracking-[0.2em]">
               <div className="w-2.5 h-2.5 bg-emerald-500 rounded-full mr-3 shadow-[0_0_10px_rgba(16,185,129,0.5)]"></div>
               VERİ SENKRONİZASYONU
             </div>
           )}
         </div>
         <button 
           onClick={() => setIsAdminOpen(true)} 
           className="bg-white/5 hover:bg-white/10 text-white px-8 py-3.5 rounded-2xl font-black text-[10px] shadow-2xl transition-all border border-white/10 flex items-center uppercase tracking-[0.3em] active:scale-95"
         >
           <svg className="w-4 h-4 mr-3 text-green-400" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2.5} d="M10.325 4.317c.426-1.756 2.924-1.756 3.35 0a1.724 1.724 0 002.573 1.066c1.543-.94 3.31.826 2.37 2.37a1.724 1.724 0 001.065 2.572c1.756.426 1.756 2.924 0 3.35a1.724 1.724 0 00-1.066 2.573c.94 1.543-.826 3.31-2.37 2.37a1.724 1.724 0 00-2.572 1.065c-.426 1.756-2.924 1.756-3.35 0a1.724 1.724 0 00-2.573-1.066c-1.543.94-3.31-.826-2.37-2.37a1.724 1.724 0 00-1.065-2.572c-1.756-.426-1.756-2.924 0-3.35a1.724 1.724 0 001.066-2.573c-.94-1.543.826-3.31 2.37-2.37.996.608 2.296.07 2.572-1.065z" /><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2.5} d="M15 12a3 3 0 11-6 0 3 3 0 016 0z" /></svg>
           Yönetici Paneli (Hücre Okuyucu)
         </button>
      </div>

