import React from 'react';
import { AircraftActivity, DailyStatusCode } from '../types';

interface ActivityGridProps {
  activities: AircraftActivity[];
  startDate: Date;
  endDate: Date;
  title: string;
}

const ActivityGrid: React.FC<ActivityGridProps> = ({ activities, startDate, endDate, title }) => {
  const getDaysInRange = (start: Date, end: Date) => {
    const dates = [];
    let current = new Date(start);
    while (current <= end) {
      dates.push(new Date(current));
      current.setDate(current.getDate() + 1);
    }
    return dates;
  };

  const visibleDates = getDaysInRange(startDate, endDate);

  const getStatusClass = (code: DailyStatusCode) => {
    switch (code) {
      case 'B': 
      case 'BB': 
      case 'KM': return 'bg-[#ffff00] text-black font-bold excel-bg-yellow status-yellow'; 
      case 'A': 
      case 'PB': 
      case 'KK': return 'bg-[#ff0000] text-white font-bold excel-bg-red status-red'; 
      case 'X': return 'bg-[#7030a0] text-white font-bold excel-bg-purple status-purple'; 
      case 'F': return 'bg-white text-black';
      default: return 'bg-white text-black';
    }
  };

  const calculateRowStats = (activity: AircraftActivity) => {
    let bkm = 0, arz = 0, x = 0;

    visibleDates.forEach(date => {
      const day = date.getDate();
      const s = activity.dailyStatuses[day];
      if (['B', 'BB', 'KM'].includes(s)) bkm++;
      else if (['A', 'PB', 'KK'].includes(s)) arz++;
      else if (s === 'X') x++;
    });

    let countedGayriFaalForPercent = 0;
    let currentSequence = [];

    visibleDates.forEach(date => {
      const day = date.getDate();
      const status = activity.dailyStatuses[day] || '';
      const isGFaal = ['B', 'BB', 'KM', 'A', 'PB', 'KK', 'X'].includes(status);

      if (isGFaal) {
        currentSequence.push(day);
      } else {
        if (currentSequence.length >= 3) {
          countedGayriFaalForPercent += currentSequence.length;
        }
        currentSequence = [];
      }
    });
    if (currentSequence.length >= 3) {
      countedGayriFaalForPercent += currentSequence.length;
    }

    const totalDays = visibleDates.length;
    const operationalDaysForPercent = totalDays - countedGayriFaalForPercent;
    const percentage = ((operationalDaysForPercent / totalDays) * 100).toFixed(0);

    const totalGFaal = bkm + arz + x;
    const totalFaal = totalDays - totalGFaal;

    return { bkm, arz, x, totalGFaal, totalFaal, percentage };
  };

  const grandTotals = activities.reduce((acc, act) => {
    const s = calculateRowStats(act);
    return {
      bkm: acc.bkm + s.bkm,
      arz: acc.arz + s.arz,
      x: acc.x + s.x,
      totalGFaal: acc.totalGFaal + s.totalGFaal,
      totalFaal: acc.totalFaal + s.totalFaal
    };
  }, { bkm: 0, arz: 0, x: 0, totalGFaal: 0, totalFaal: 0 });

  if (activities.length === 0) return null;

  return (
    <div className="activity-grid-section mb-10 bg-white p-4">
      <div className="mb-4 flex items-center justify-between border-l-4 border-green-600 pl-4">
        <h4 className="text-sm font-black text-gray-800 uppercase tracking-widest">{title} ÜNİTELERİ</h4>
        <span className="text-[10px] font-bold text-gray-400 bg-gray-100 px-3 py-1 rounded-full">{activities.length} ADET</span>
      </div>
      <div className="overflow-x-auto">
        <table className="w-full border-collapse border-[2px] border-black text-[9px] font-sans bg-white excel-table">
          <thead>
            <tr className="bg-white">
              <th rowSpan={2} className="border border-black px-2 py-2 w-[100px] bg-slate-50 font-black">ÇAĞRI KODU</th>
              <th rowSpan={2} className="border border-black px-2 py-2 w-[100px] bg-slate-50 font-black">KUYRUK NO</th>
              <th rowSpan={2} className="border border-black px-2 py-2 w-[120px] bg-slate-50 font-black">TİP</th>
              {visibleDates.map((date, idx) => (
                <th key={idx} rowSpan={2} className="border border-black w-8 text-center font-bold h-24 relative min-w-[32px] excel-date-cell bg-slate-50">
                   <div className="absolute inset-0 flex items-center justify-center">
                     <span className="[writing-mode:vertical-lr] rotate-180 whitespace-nowrap text-[8px] font-black">
                        {date.toLocaleDateString('tr-TR', { day: '2-digit', month: '2-digit', year: 'numeric' })}
                     </span>
                   </div>
                </th>
              ))}
              <th colSpan={3} className="border border-black bg-[#0070c0] text-white py-2 text-[8px] font-black excel-bg-blue">GAYRI FAAL DAĞILIM</th>
              <th rowSpan={2} className="border border-black bg-[#00b0f0] text-white px-1 w-12 text-[8px] font-black excel-bg-blue">TOPLAM G.F.</th>
              <th rowSpan={2} className="border border-black bg-[#ffc000] text-black px-1 w-12 text-[8px] font-black excel-bg-orange">TOPLAM FAAL</th>
              <th rowSpan={2} className="border border-black bg-gray-900 text-white px-1 w-14 text-[8px] font-black excel-bg-gray900">VERİM %</th>
            </tr>
            <tr className="bg-white">
              <th className="border border-black bg-[#ffff00] text-black w-10 text-[7px] py-3 font-black uppercase excel-bg-yellow">Bakım</th>
              <th className="border border-black bg-[#ff0000] text-white w-10 text-[7px] py-3 font-black uppercase excel-bg-red">Arıza</th>
              <th className="border border-black bg-[#7030a0] text-white w-10 text-[7px] py-3 font-black uppercase excel-bg-purple">Olmadığı</th>
            </tr>
          </thead>
          <tbody>
            {activities.map((act, idx) => {
              const s = calculateRowStats(act);
              return (
                <tr key={idx} className="h-8 hover:bg-gray-50 group">
                  <td className="border border-black text-center font-black px-2 bg-slate-50/50">{act.cagriKodu}</td>
                  <td className="border border-black text-center font-bold px-2 text-green-700">{act.kuyrukNo}</td>
                  <td className="border border-black text-center px-2 uppercase font-medium">{act.tip}</td>
                  {visibleDates.map((date, dIdx) => {
                    const status = act.dailyStatuses[date.getDate()] || '';
                    return (
                      <td key={dIdx} className={`border border-black text-center text-[10px] ${getStatusClass(status)}`}>
                        {status}
                      </td>
                    );
                  })}
                  <td className="border border-black text-center font-black bg-[#ffffd0] text-sm tabular-nums">{s.bkm || '0'}</td>
                  <td className="border border-black text-center font-black bg-[#ffd0d0] text-sm tabular-nums">{s.arz || '0'}</td>
                  <td className="border border-black text-center font-black bg-[#f0f0f0] text-sm tabular-nums">{s.x || '0'}</td>
                  <td className="border border-black text-center font-black bg-[#c0e0ff] text-sm tabular-nums">{s.totalGFaal || '0'}</td>
                  <td className="border border-black text-center font-black bg-[#fff5d0] text-sm tabular-nums">{s.totalFaal || '0'}</td>
                  <td className="border border-black text-center font-black bg-slate-100 text-[11px] tabular-nums">%{s.percentage}</td>
                </tr>
              );
            })}
            <tr className="bg-white font-black h-9">
              <td colSpan={3} className="border border-black text-right px-4 uppercase text-[9px] bg-slate-200">GENEL TOPLAM</td>
              {visibleDates.map((_, idx) => <td key={idx} className="border border-black bg-slate-100"></td>)}
              <td className="border border-black text-center bg-[#ffff00] text-sm shadow-inner tabular-nums">{grandTotals.bkm}</td>
              <td className="border border-black text-center bg-[#ff0000] text-white text-sm shadow-inner tabular-nums">{grandTotals.arz}</td>
              <td className="border border-black text-center bg-[#7030a0] text-white text-sm shadow-inner tabular-nums">{grandTotals.x}</td>
              <td className="border border-black text-center bg-[#00b0f0] text-white text-sm shadow-inner tabular-nums">{grandTotals.totalGFaal}</td>
              <td className="border border-black text-center bg-[#ffc000] text-black text-sm shadow-inner tabular-nums">{grandTotals.totalFaal}</td>
              <td className="border border-black bg-gray-900"></td>
            </tr>
          </tbody>
        </table>
      </div>
    </div>
  );
};

export default ActivityGrid;

import React, { useState, useMemo, useEffect } from 'react';
import Layout from './components/Layout';
import Dashboard from './components/Dashboard';
import AircraftDetailModal from './components/AircraftDetailModal';
import MaintenanceForm from './components/MaintenanceForm';
import ActivityGrid from './components/ActivityGrid';
import SplashScreen from './components/SplashScreen';
import AdminPanel from './components/AdminPanel';
import { MOCK_AIRCRAFT, MOCK_ACTIVITY_GRID } from './constants';
import { Aircraft, Status, SheetConfig, GlobalSettings } from './types';
import { fetchAircraftDataFromAppsScript } from './services/sheetService';

const App: React.FC = () => {
  const [isSplashVisible, setIsSplashVisible] = useState(true);
  const [isAdminOpen, setIsAdminOpen] = useState(false);
  const [isActivityVisible, setIsActivityVisible] = useState(false);
  const [fleet, setFleet] = useState<Aircraft[]>(MOCK_AIRCRAFT);
  const [selectedAircraft, setSelectedAircraft] = useState<Aircraft | null>(null);
  const [editingAircraft, setEditingAircraft] = useState<Aircraft | null>(null);
  const [searchTerm, setSearchTerm] = useState('');
  const [isSyncing, setIsSyncing] = useState(false);

  const today = new Date();
  const firstDay = new Date(today.getFullYear(), today.getMonth(), 1);
  const lastDay = new Date(today.getFullYear(), today.getMonth() + 1, 0);

  const [filterType, setFilterType] = useState("Tümü");
  const [dateRange, setDateRange] = useState({
    start: firstDay.toISOString().split('T')[0],
    end: lastDay.toISOString().split('T')[0]
  });
  const [activeDateRange, setActiveDateRange] = useState({ start: firstDay, end: lastDay });
  const [activeFilterType, setActiveFilterType] = useState("Tümü");

  useEffect(() => {
    const savedConfigs = localStorage.getItem('ogm_sheet_configs');
    const savedSettings = localStorage.getItem('ogm_global_settings');
    if (savedConfigs && savedSettings) {
      try {
        const parsedConfigs = JSON.parse(savedConfigs);
        const parsedSettings = JSON.parse(savedSettings);
        if (Array.isArray(parsedConfigs) && parsedSettings) {
          handleSync(parsedConfigs, parsedSettings);
        }
      } catch (e) {
        console.error("Başlangıç senkronizasyon hatası:", e);
      }
    }
  }, []);

  const handleSync = async (configs: SheetConfig[], settings: GlobalSettings) => {
    if (!settings || !settings.appsScriptUrl) return;
    setIsSyncing(true);
    try {
      let newFleet: Aircraft[] = [];
      for (const config of configs) {
        if (config && config.sheetId && config.mapping && config.mapping.kuyrukNo) {
          const data = await fetchAircraftDataFromAppsScript(settings.appsScriptUrl, config);
          const enrichedData = data.map(a => ({
            ...a,
            platformTipi: config.aircraftType === "Bell-429" || config.aircraftType === "T-70" ? "H" : "SA",
            tip: config.aircraftType
          }));
          newFleet = [...newFleet, ...enrichedData];
        }
      }
      if (newFleet.length > 0) setFleet(newFleet);
    } catch (error) {
      console.error("Senkronizasyon hatası:", error);
    } finally {
      setIsSyncing(false);
    }
  };

  const handleFilterActivity = () => {
    setActiveDateRange({ start: new Date(dateRange.start), end: new Date(dateRange.end) });
    setActiveFilterType(filterType);
    setIsActivityVisible(true);
  };

  const filteredFleet = useMemo(() => {
    return fleet.filter(a => {
      const s = searchTerm.toLowerCase();
      return a.kuyrukNo.toLowerCase().includes(s) || a.cagriKodu.toLowerCase().includes(s) || a.konum.toLowerCase().includes(s);
    });
  }, [fleet, searchTerm]);

  const groupedActivities = useMemo(() => {
    const groups: { [type: string]: any[] } = {};
    MOCK_ACTIVITY_GRID.forEach(act => {
      if (activeFilterType !== "Tümü" && act.tip !== activeFilterType) return;
      if (!groups[act.tip]) groups[act.tip] = [];
      groups[act.tip].push(act);
    });
    return groups;
  }, [activeFilterType]);

  // Excel Stillerini Koruyan Fonksiyon
  const exportToExcelWithStyles = (elementId: string, fileName: string) => {
    const element = document.getElementById(elementId);
    if (!element) return;

    const header = `
      <html xmlns:o="urn:schemas-microsoft-com:office:office" xmlns:x="urn:schemas-microsoft-com:office:excel" xmlns="http://www.w3.org/TR/REC-html40">
      <head>
        <meta charset="UTF-8">
        <!--[if gte mso 9]><xml><x:ExcelWorkbook><x:ExcelWorksheets><x:ExcelWorksheet><x:Name>Sayfa1</x:Name><x:WorksheetOptions><x:DisplayGridlines/></x:WorksheetOptions></x:ExcelWorksheet></x:ExcelWorksheets></x:ExcelWorkbook></xml><![endif]-->
        <style>
          table { border-collapse: collapse; font-family: Arial, sans-serif; font-size: 10pt; }
          th, td { border: 1px solid #000000; padding: 5px; text-align: center; }
          .bg-slate-100 { background-color: #f1f5f9; }
          .bg-green-50 { background-color: #f0fdf4; }
          .bg-red-50 { background-color: #fef2f2; }
          .text-green-700 { color: #15803d; }
          .text-red-700 { color: #b91c1c; }
          .excel-bg-yellow { background-color: #ffff00 !important; }
