import React from 'react';
import { AircraftActivity, DailyStatusCode } from '../types';

interface ActivityGridProps {
  activities: AircraftActivity[];
  startDate: Date;
  endDate: Date;
  title: string;
}

const ActivityGrid: React.FC<ActivityGridProps> = ({ activities, startDate, endDate, title }) => {
  const getDaysInRange = (start: Date, end: Date) => {
    const dates = [];
    let current = new Date(start);
    while (current <= end) {
      dates.push(new Date(current));
      current.setDate(current.getDate() + 1);
    }
    return dates;
  };

  const visibleDates = getDaysInRange(startDate, endDate);

  const getStatusClass = (code: DailyStatusCode) => {
    switch (code) {
      case 'B': 
      case 'BB': 
      case 'KM': return 'bg-[#ffff00] text-black font-bold excel-bg-yellow status-yellow'; 
      case 'A': 
      case 'PB': 
      case 'KK': return 'bg-[#ff0000] text-white font-bold excel-bg-red status-red'; 
      case 'X': return 'bg-[#7030a0] text-white font-bold excel-bg-purple status-purple'; 
      case 'F': return 'bg-white text-black';
      default: return 'bg-white text-black';
    }
  };

  const calculateRowStats = (activity: AircraftActivity) => {
    let bkm = 0, arz = 0, x = 0;

    visibleDates.forEach(date => {
      const day = date.getDate();
      const s = activity.dailyStatuses[day];
      if (['B', 'BB', 'KM'].includes(s)) bkm++;
      else if (['A', 'PB', 'KK'].includes(s)) arz++;
      else if (s === 'X') x++;
    });

    let countedGayriFaalForPercent = 0;
    let currentSequence = [];

    visibleDates.forEach(date => {
      const day = date.getDate();
      const status = activity.dailyStatuses[day] || '';
      const isGFaal = ['B', 'BB', 'KM', 'A', 'PB', 'KK', 'X'].includes(status);

      if (isGFaal) {
        currentSequence.push(day);
      } else {
        if (currentSequence.length >= 3) {
          countedGayriFaalForPercent += currentSequence.length;
        }
        currentSequence = [];
      }
    });
    if (currentSequence.length >= 3) {
      countedGayriFaalForPercent += currentSequence.length;
    }

    const totalDays = visibleDates.length;
    const operationalDaysForPercent = totalDays - countedGayriFaalForPercent;
    const percentage = ((operationalDaysForPercent / totalDays) * 100).toFixed(0);

    const totalGFaal = bkm + arz + x;
    const totalFaal = totalDays - totalGFaal;

    return { bkm, arz, x, totalGFaal, totalFaal, percentage };
  };

  const grandTotals = activities.reduce((acc, act) => {
    const s = calculateRowStats(act);
    return {
      bkm: acc.bkm + s.bkm,
      arz: acc.arz + s.arz,
      x: acc.x + s.x,
      totalGFaal: acc.totalGFaal + s.totalGFaal,
      totalFaal: acc.totalFaal + s.totalFaal
    };
  }, { bkm: 0, arz: 0, x: 0, totalGFaal: 0, totalFaal: 0 });

  const abbreviations = [
    { code: 'B', label: 'BAKIM', color: 'bg-[#ffff00]' },
    { code: 'BB', label: 'BÜYÜK BAKIM', color: 'bg-[#ffff00]' },
    { code: 'KM', label: 'KONTROL/MUAYENE', color: 'bg-[#ffff00]' },
    { code: 'A', label: 'ARIZA', color: 'bg-[#ff0000]' },
    { code: 'PB', label: 'PARÇA BEKLER', color: 'bg-[#ff0000]' },
    { code: 'KK', label: 'KAZA KIRIM', color: 'bg-[#ff0000]' },
    { code: 'X', label: 'GÖREVDE DEĞİL', color: 'bg-[#7030a0]' },
    { code: 'F', label: 'FAAL', color: 'bg-white' },
  ];

  if (activities.length === 0) return null;

  return (
    <div className="activity-grid-section mb-10 bg-white p-4">
      <div className="mb-4 flex items-center justify-between border-l-4 border-green-600 pl-4">
        <h4 className="text-sm font-black text-gray-800 uppercase tracking-widest">{title} ÜNİTELERİ</h4>
        <span className="text-[10px] font-bold text-gray-400 bg-gray-100 px-3 py-1 rounded-full">{activities.length} ADET</span>
      </div>
      <div className="overflow-x-auto">
        <table className="w-full border-collapse border-[1pt] border-black text-[9px] font-sans bg-white excel-table">
          <thead>
            <tr className="bg-white">
              <th rowSpan={2} className="border border-black px-2 py-2 w-[100px] bg-slate-50 font-black excel-bg-slate">ÇAĞRI KODU</th>
              <th rowSpan={2} className="border border-black px-2 py-2 w-[100px] bg-slate-50 font-black excel-bg-slate">KUYRUK NO</th>
              <th rowSpan={2} className="border border-black px-2 py-2 w-[120px] bg-slate-50 font-black excel-bg-slate">TİP</th>
              {visibleDates.map((date, idx) => (
                <th key={idx} rowSpan={2} className="border border-black w-8 text-center font-bold h-24 relative min-w-[32px] excel-date-cell bg-slate-50 excel-bg-slate">
                   <div className="absolute inset-0 flex items-center justify-center">
                     <span className="[writing-mode:vertical-lr] rotate-180 whitespace-nowrap text-[8px] font-black">
                        {date.toLocaleDateString('tr-TR', { day: '2-digit', month: '2-digit', year: 'numeric' })}
                     </span>
                   </div>
                </th>
              ))}
              <th colSpan={3} className="border border-black bg-[#0070c0] text-white py-2 text-[8px] font-black excel-bg-blue">GAYRI FAAL DAĞILIM</th>
              <th rowSpan={2} className="border border-black bg-[#00b0f0] text-white px-1 w-12 text-[8px] font-black excel-bg-blue">TOPLAM G.F.</th>
              <th rowSpan={2} className="border border-black bg-[#ffc000] text-black px-1 w-12 text-[8px] font-black excel-bg-orange">TOPLAM FAAL</th>
              <th rowSpan={2} className="border border-black bg-gray-900 text-white px-1 w-14 text-[8px] font-black excel-bg-gray900">VERİM %</th>
            </tr>
            <tr className="bg-white">
              <th className="border border-black bg-[#ffff00] text-black w-10 text-[7px] py-3 font-black uppercase excel-bg-yellow">Bakım</th>
              <th className="border border-black bg-[#ff0000] text-white w-10 text-[7px] py-3 font-black uppercase excel-bg-red">Arıza</th>
              <th className="border border-black bg-[#7030a0] text-white w-10 text-[7px] py-3 font-black uppercase excel-bg-purple">Olmadığı</th>
            </tr>
          </thead>
          <tbody>
            {activities.map((act, idx) => {
              const s = calculateRowStats(act);
              return (
                <tr key={idx} className="h-8 hover:bg-gray-50 group">
                  <td className="border border-black text-center font-black px-2 bg-slate-50/50">{act.cagriKodu}</td>
                  <td className="border border-black text-center font-bold px-2 text-green-700">{act.kuyrukNo}</td>
                  <td className="border border-black text-center px-2 uppercase font-medium">{act.tip}</td>
                  {visibleDates.map((date, dIdx) => {
                    const status = act.dailyStatuses[date.getDate()] || '';
                    return (
                      <td key={dIdx} className={`border border-black text-center text-[10px] ${getStatusClass(status)}`}>
                        {status}
                      </td>
                    );
                  })}
                  <td className="border border-black text-center font-black bg-[#ffffd0] text-sm tabular-nums excel-bg-yellow">{s.bkm || '0'}</td>
                  <td className="border border-black text-center font-black bg-[#ffd0d0] text-sm tabular-nums excel-bg-red text-white">{s.arz || '0'}</td>
                  <td className="border border-black text-center font-black bg-[#f0f0f0] text-sm tabular-nums excel-bg-purple text-white">{s.x || '0'}</td>
                  <td className="border border-black text-center font-black bg-[#c0e0ff] text-sm tabular-nums excel-bg-blue text-white">{s.totalGFaal || '0'}</td>
                  <td className="border border-black text-center font-black bg-[#fff5d0] text-sm tabular-nums excel-bg-orange">{s.totalFaal || '0'}</td>
                  <td className="border border-black text-center font-black bg-slate-100 text-[11px] tabular-nums excel-bg-slate">%{s.percentage}</td>
                </tr>
              );
            })}
            <tr className="bg-white font-black h-9">
              <td colSpan={3} className="border border-black text-right px-4 uppercase text-[9px] bg-slate-200 excel-bg-slate">GENEL TOPLAM</td>
              {visibleDates.map((_, idx) => <td key={idx} className="border border-black bg-slate-100 excel-bg-slate"></td>)}
              <td className="border border-black text-center bg-[#ffff00] text-sm shadow-inner tabular-nums excel-bg-yellow">{grandTotals.bkm}</td>
              <td className="border border-black text-center bg-[#ff0000] text-white text-sm shadow-inner tabular-nums excel-bg-red">{grandTotals.arz}</td>
              <td className="border border-black text-center bg-[#7030a0] text-white text-sm shadow-inner tabular-nums excel-bg-purple">{grandTotals.x}</td>
              <td className="border border-black text-center bg-[#00b0f0] text-white text-sm shadow-inner tabular-nums excel-bg-blue">{grandTotals.totalGFaal}</td>
              <td className="border border-black text-center bg-[#ffc000] text-black text-sm shadow-inner tabular-nums excel-bg-orange">{grandTotals.totalFaal}</td>
              <td className="border border-black bg-gray-900 excel-bg-gray900"></td>
            </tr>
          </tbody>
        </table>
      </div>

      {/* Kisaltmalar (Legend) */}
      <div className="mt-6 flex flex-wrap gap-4 p-4 bg-slate-50 rounded-2xl border border-slate-200">
         <div className="w-full text-[10px] font-black text-slate-400 uppercase tracking-widest mb-1">KISALTMALAR VE RENK TANIMLARI</div>
         {abbreviations.map((abbr, i) => (
           <div key={i} className="flex items-center space-x-2">
              <div className={`w-8 h-6 border border-black flex items-center justify-center font-black text-[10px] ${abbr.color} ${abbr.code === 'A' || abbr.code === 'PB' || abbr.code === 'KK' || abbr.code === 'X' ? 'text-white' : 'text-black'}`}>
                {abbr.code}
              </div>
              <span className="text-[10px] font-bold text-slate-600 uppercase">{abbr.label}</span>
           </div>
         ))}
      </div>
    </div>
  );
};

