  const [activeFilterType, setActiveFilterType] = useState("Tümü");

  // Uygulama yüklendiğinde kayıtlı ayarları al ve senkronize et
  useEffect(() => {
    const savedConfigs = localStorage.getItem('ogm_sheet_configs');
    const savedSettings = localStorage.getItem('ogm_global_settings');
    if (savedConfigs && savedSettings) {
      try {
        const parsedConfigs = JSON.parse(savedConfigs);
        const parsedSettings = JSON.parse(savedSettings);
        if (Array.isArray(parsedConfigs) && parsedSettings) {
          handleSync(parsedConfigs, parsedSettings);
        }
      } catch (e) {
        console.error("Başlangıç senkronizasyon hatası:", e);
      }
    }
  }, []);

  const handleSync = async (configs: SheetConfig[], settings: GlobalSettings) => {
    if (!settings || !settings.appsScriptUrl) return;

    setIsSyncing(true);
    localStorage.setItem('ogm_sheet_configs', JSON.stringify(configs));
    localStorage.setItem('ogm_global_settings', JSON.stringify(settings));

    try {
      let newFleet = [...fleet];
      for (const config of configs) {
        if (config && config.sheetId && config.mapping && config.mapping.kuyrukNo) {
          const data = await fetchAircraftDataFromAppsScript(settings.appsScriptUrl, config);

          data.forEach(updatedAircraft => {
            const index = newFleet.findIndex(a => a.kuyrukNo === updatedAircraft.kuyrukNo);
            if (index !== -1) {
              newFleet[index] = { ...newFleet[index], ...updatedAircraft, tip: config.aircraftType } as Aircraft;
            } else {
              newFleet.push({ 
                ...updatedAircraft, 
                platformTipi: config.aircraftType === "Bell-429" || config.aircraftType === "T-70" ? "H" : "SA",
                tip: config.aircraftType 
