      processSnapshot(newFleet);

    } catch (error) {
      console.error("Senkronizasyon hatası:", error);
    } finally {
      setIsSyncing(false);
    }
  };

  const processSnapshot = (currentFleet: Aircraft[]) => {
    // Bu kısım normalde bir backend triggerı (00:00) ile çalışır.
    // Frontend tarafında sadece mevcut session'a veya localstorage'a snapshot bırakabiliriz.
    console.log("Snapshot processed for 00:00 activity log.");
  };

  const handleFilterActivity = () => {
    setActiveDateRange({ start: new Date(dateRange.start), end: new Date(dateRange.end) });
    setActiveFilterType(filterType);
    setIsActivityVisible(true);
  };

  const filteredFleet = useMemo(() => {
    return fleet.filter(a => {
      const matchesSearch = a.kuyrukNo.toLowerCase().includes(searchTerm.toLowerCase()) ||
                            a.cagriKodu.toLowerCase().includes(searchTerm.toLowerCase()) ||
                            a.konum.toLowerCase().includes(searchTerm.toLowerCase());
      return matchesSearch;
    });
  }, [fleet, searchTerm]);

  const groupedActivities = useMemo(() => {
    const groups: { [type: string]: any[] } = {};
    MOCK_ACTIVITY_GRID.forEach(act => {
      if (activeFilterType !== "Tümü" && act.tip !== activeFilterType) return;
      if (!groups[act.tip]) groups[act.tip] = [];
      groups[act.tip].push(act);
    });
    return groups;
  }, [activeFilterType]);

  const handleUpdateStatus = (updates: Partial<Aircraft>) => {
    if (!editingAircraft) return;
    setFleet(prev => prev.map(a => a.kuyrukNo === editingAircraft.kuyrukNo ? { ...a, ...updates } as Aircraft : a));
    setEditingAircraft(null);
  };

  if (isSplashVisible) return <SplashScreen onComplete={() => setIsSplashVisible(false)} />;

  return (
    <Layout>
      <div className="flex justify-between items-center mb-8">
         <div className="flex items-center space-x-3">
           {isSyncing && (
             <div className="flex items-center px-4 py-2 bg-emerald-500/10 text-emerald-400 rounded-xl font-black text-[10px] animate-pulse border border-emerald-500/20 shadow-lg shadow-emerald-500/5 uppercase tracking-[0.2em]">
               <div className="w-2.5 h-2.5 bg-emerald-500 rounded-full mr-3 shadow-[0_0_10px_rgba(16,185,129,0.5)]"></div>
               VERİ SENKRONİZASYONU
             </div>
           )}
         </div>
         <button 
           onClick={() => setIsAdminOpen(true)} 
           className="bg-white/5 hover:bg-white/10 text-white px-8 py-3.5 rounded-2xl font-black text-[10px] shadow-2xl transition-all border border-white/10 flex items-center uppercase tracking-[0.3em] active:scale-95"
         >
           <svg className="w-4 h-4 mr-3 text-green-400" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2.5} d="M10.325 4.317c.426-1.756 2.924-1.756 3.35 0a1.724 1.724 0 002.573 1.066c1.543-.94 3.31.826 2.37 2.37a1.724 1.724 0 001.065 2.572c1.756.426 1.756 2.924 0 3.35a1.724 1.724 0 00-1.066 2.573c.94 1.543-.826 3.31-2.37 2.37a1.724 1.724 0 00-2.572 1.065c-.426 1.756-2.924 1.756-3.35 0a1.724 1.724 0 00-2.573-1.066c-1.543.94-3.31-.826-2.37-2.37a1.724 1.724 0 00-1.065-2.572c-1.756-.426-1.756-2.924 0-3.35a1.724 1.724 0 001.066-2.573c-.94-1.543.826-3.31 2.37-2.37.996.608 2.296.07 2.572-1.065z" /><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2.5} d="M15 12a3 3 0 11-6 0 3 3 0 016 0z" /></svg>
           Yönetici Paneli (Hücre Okuyucu)
