  const [searchTerm, setSearchTerm] = useState('');

  // Bildirim ve Snapshot State'leri
  const [notifications, setNotifications] = useState<AppNotification[]>([]);
  const [snapshotPreviews, setSnapshotPreviews] = useState<SnapshotPreview[]>([]);
  const [isSnapshotModalOpen, setIsSnapshotModalOpen] = useState(false);

  const today = new Date();
  const firstDay = new Date(today.getFullYear(), today.getMonth(), 1);
  const lastDay = new Date(today.getFullYear(), today.getMonth() + 1, 0);

  const aircraftTypes = ["Tümü", "Bell-429", "AT-802", "T-70", "C-650", "B-360"];
  const [filterType, setFilterType] = useState("Tümü");
  const [dateRange, setDateRange] = useState({
    start: firstDay.toISOString().split('T')[0],
    end: lastDay.toISOString().split('T')[0]
  });

  const [activeDateRange, setActiveDateRange] = useState({ start: firstDay, end: lastDay });
  const [activeFilterType, setActiveFilterType] = useState("Tümü");

  // Otomatik Durum Kodu Belirleme Mantığı
  const determineStatusCode = (a: Partial<Aircraft>): { code: DailyStatusCode, gerekce: string } => {
    const text = `${a.durum} ${a.durumAyrintisi} ${a.aciklama}`.toLowerCase();

    if (text.includes('kaza') || text.includes('kırım')) return { code: 'KK', gerekce: 'Metin analizi: Kaza Kırım tespiti' };
    if (text.includes('parça bekler') || text.includes('yedek parça')) return { code: 'PB', gerekce: 'Metin analizi: Parça bekliyor tespiti' };
    if (text.includes('bakım') || text.includes('periyodik') || text.includes('200h') || text.includes('960h')) {
      if (text.includes('bekle')) return { code: 'BB', gerekce: 'Metin analizi: Bakım bekliyor tespiti' };
      return { code: 'B', gerekce: 'Metin analizi: Bakım tespiti' };
    }
    if (text.includes('arıza') || text.includes('fault') || text.includes('failure')) return { code: 'A', gerekce: 'Metin analizi: Arıza tespiti' };
    if (text.includes('kabul') || text.includes('muayene') || text.includes('test uçuşu')) return { code: 'KM', gerekce: 'Metin analizi: Kabul/Muayene tespiti' };

    return { code: 'X', gerekce: 'Analiz: Spesifik durum kodu bulunamadı, "Olmadığı Gün" atandı' };
  };

  const handleSyncFromExcel = (configs: SheetConfig[], data: Partial<Aircraft>[]) => {
    let newNotifications: AppNotification[] = [];
    let updatedFleet = [...fleet];

    data.forEach(incoming => {
      const existingIdx = updatedFleet.findIndex(a => a.kuyrukNo === incoming.kuyrukNo);
      if (existingIdx !== -1) {
        const existing = updatedFleet[existingIdx];
        // Değişiklik Kontrolü & Bildirim Üretimi
        if (existing.durum !== incoming.durum) {
          newNotifications.push({
            id: Math.random().toString(36).substr(2, 9),
            platform: 'Bell-429',
            kuyrukNo: existing.kuyrukNo,
            kolon: 'DURUM',
            oncekiDeger: existing.durum,
            yeniDeger: incoming.durum || '',
            mesaj: `DURUM verisi "${existing.durum}" -> "${incoming.durum}" olarak değiştirilmiştir.`,
            tarih: new Date().toLocaleString('tr-TR')
          });
        }
        updatedFleet[existingIdx] = { ...existing, ...incoming } as Aircraft;
      } else {
        updatedFleet.push({ 
          ...incoming, 
          cagriKodu: incoming.cagriKodu || `ORMAN-${incoming.kuyrukNo?.split('-')[1] || 'XX'}`,
          platformTipi: 'H', 
          tip: 'Bell-429' 
        } as Aircraft);
      }
    });

    setFleet(updatedFleet);
    setNotifications(prev => [...newNotifications, ...prev]);

    // 00:00 Snapshot Analizini Tetikle
    const previews = data.map(a => {
      const { code, gerekce } = determineStatusCode(a);
      return {
        kuyrukNo: a.kuyrukNo || '',
        tarih: new Date().toLocaleDateString('tr-TR'),
        kod: code,
        aciklamaOzeti: a.aciklama?.substring(0, 50) + '...' || '',
        gerekce: gerekce
      };
    });
    setSnapshotPreviews(previews);
    setIsSnapshotModalOpen(true);
  };

  const handleApproveSnapshot = () => {
    // Burada gerçek takvime kayıt işlemi yapılır (Mock olarak konsola yazıyoruz)
    console.log("Snapshot approved and saved to permanent activity log.");
    setIsSnapshotModalOpen(false);
  };

  const handleFilterActivity = () => {
    setActiveDateRange({ start: new Date(dateRange.start), end: new Date(dateRange.end) });
    setActiveFilterType(filterType);
    setIsActivityVisible(true);
  };

  const filteredFleet = useMemo(() => {
    return fleet.filter(a => {
      const s = searchTerm.toLowerCase();
      return a.kuyrukNo.toLowerCase().includes(s) || a.cagriKodu.toLowerCase().includes(s) || a.konum.toLowerCase().includes(s);
    });
  }, [fleet, searchTerm]);

  const groupedActivities = useMemo(() => {
    const groups: { [type: string]: any[] } = {};
    MOCK_ACTIVITY_GRID.forEach(act => {
      if (activeFilterType !== "Tümü" && act.tip !== activeFilterType) return;
      if (!groups[act.tip]) groups[act.tip] = [];
      groups[act.tip].push(act);
    });
    return groups;
  }, [activeFilterType]);

  if (isSplashVisible) return <SplashScreen onComplete={() => setIsSplashVisible(false)} />;

  return (
    <Layout>
      <div className="flex justify-between items-center mb-10">
         <div className="flex items-center space-x-6">
            {notifications.length > 0 && (
              <div className="bg-red-500/10 border border-red-500/20 px-4 py-2 rounded-xl flex items-center animate-pulse">
                <div className="w-2 h-2 bg-red-500 rounded-full mr-3"></div>
                <span className="text-red-400 font-black text-[9px] uppercase tracking-widest">{notifications.length} YENİ BİLDİRİM</span>
              </div>
            )}
         </div>
         <div className="flex space-x-4">
            <button 
              onClick={() => setIsAdminOpen(true)} 
              className="bg-white/5 hover:bg-white/10 text-white px-8 py-4 rounded-2xl font-black text-[10px] shadow-2xl transition-all border border-white/10 flex items-center uppercase tracking-[0.3em] active:scale-95"
            >
              Yönetici Paneli (Hücre Okuyucu)
            </button>
         </div>
      </div>

      <Dashboard fleet={fleet} />

      {/* BİLDİRİMLER PANELİ (SADECE VARSA GÖRÜNÜR) */}
      {notifications.length > 0 && (
        <div className="mb-12 bg-black/20 p-8 rounded-[2rem] border border-red-900/20">
           <h3 className="text-red-500 font-black text-xs uppercase tracking-[0.4em] mb-6 flex items-center">
             <svg className="w-5 h-5 mr-3" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path d="M15 17h5l-1.405-1.405A2.032 2.032 0 0118 14.158V11a6.002 6.002 0 00-4-5.659V5a2 2 0 10-4 0v.341C7.67 6.165 6 8.388 6 11v3.159c0 .538-.214 1.055-.595 1.436L4 17h5m6 0v1a3 3 0 11-6 0v-1m6 0H9" strokeWidth={2.5}/></svg>
             BELL-429 EXCEL DEĞİŞİKLİK BİLDİRİMLERİ
           </h3>
           <div className="space-y-4 max-h-60 overflow-y-auto pr-4 scrollbar-hide">
              {notifications.map(n => (
                <div key={n.id} className="bg-[#0a2f1a]/40 p-5 rounded-2xl border border-red-500/10 flex justify-between items-center group hover:bg-[#0a2f1a]/60 transition-all">
                   <div>
                      <div className="text-[10px] font-black text-white mb-1 uppercase tracking-widest">
                        {n.platform} | KUYRUK: <span className="text-red-400">{n.kuyrukNo}</span>
                      </div>
                      <p className="text-[11px] text-gray-400 font-bold">{n.mesaj}</p>
                   </div>
                   <div className="text-right">
                      <div className="text-[8px] font-black text-gray-600 mb-1">{n.tarih}</div>
                      <span className="text-[9px] font-black text-red-900 bg-red-500/10 px-3 py-1 rounded-full border border-red-500/20">LOGLANDI</span>
                   </div>
                </div>
              ))}
           </div>
        </div>
      )}

      {/* DURUM ÖZETLERİ */}
      <div className="mb-20">
        <div className="flex justify-between items-end mb-8">
           <div>
             <h3 className="text-2xl font-black text-white uppercase tracking-tighter">HAVA ARACI DURUM ÖZETLERİ</h3>
             <p className="text-green-500 text-[10px] font-bold uppercase tracking-[0.4em] mt-2">Güncel Operasyonel Veriler</p>
           </div>
           <div className="relative w-80">
              <input 
                type="text" 
                placeholder="Tabloda Ara..." 
                value={searchTerm} 
                onChange={(e) => setSearchTerm(e.target.value)} 
                className="w-full pl-12 pr-6 py-3.5 bg-black/30 text-white rounded-2xl border border-green-800/50 outline-none font-bold text-xs" 
              />
              <svg className="w-5 h-5 absolute left-4 top-1/2 -translate-y-1/2 text-green-700" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path d="M21 21l-6-6m2-5a7 7 0 11-14 0 7 7 0 0114 0z" strokeWidth={3}/></svg>
           </div>
        </div>

        <div className="bg-white p-1 rounded-[2.5rem] shadow-2xl overflow-hidden border-4 border-white">
          <table className="w-full border-collapse">
            <thead>
              <tr className="bg-slate-100 border-b-2 border-slate-200">
                <th className="px-6 py-4 text-left text-[10px] font-black text-slate-500 uppercase tracking-widest">ÇAĞRI KODU</th>
                <th className="px-6 py-4 text-left text-[10px] font-black text-slate-500 uppercase tracking-widest">KUYRUK NUMARASI</th>
                <th className="px-6 py-4 text-center text-[10px] font-black text-slate-500 uppercase tracking-widest">DURUM</th>
                <th className="px-6 py-4 text-left text-[10px] font-black text-slate-500 uppercase tracking-widest">AYRINTI</th>
                <th className="px-6 py-4 text-left text-[10px] font-black text-slate-500 uppercase tracking-widest">KONUM</th>
                <th className="px-6 py-4 text-center text-[10px] font-black text-slate-500 uppercase tracking-widest">FAYDALI SAAT</th>
                <th className="px-6 py-4 text-left text-[10px] font-black text-slate-500 uppercase tracking-widest">AÇIKLAMA</th>
              </tr>
            </thead>
            <tbody className="divide-y divide-slate-100">
              {filteredFleet.map((a, i) => (
                <tr key={i} className="hover:bg-slate-50 cursor-pointer transition-all" onClick={() => setSelectedAircraft(a)}>
                  <td className="px-6 py-4 text-sm font-black text-slate-900">{a.cagriKodu}</td>
                  <td className="px-6 py-4 text-sm font-bold text-green-700">{a.kuyrukNo} <span className="text-red-600 font-black">({a.platformTipi})</span></td>
                  <td className="px-6 py-4 text-center">
                    <span className={`px-4 py-1.5 rounded-xl font-black text-[9px] uppercase border-2 ${a.durum === Status.FAAL ? 'bg-green-50 text-green-700 border-green-200' : 'bg-red-50 text-red-700 border-red-200'}`}>
                      {a.durum}
                    </span>
                  </td>
                  <td className="px-6 py-4 text-[11px] font-bold text-slate-600">{a.durumAyrintisi}</td>
                  <td className="px-6 py-4 text-[11px] font-black text-slate-800 uppercase">{a.konum}</td>
                  <td className="px-6 py-4 text-center font-black text-base">{a.faydaliSaat}</td>
                  <td className="px-6 py-4 italic text-slate-400 text-[10px] max-w-xs truncate">{a.aciklama}</td>
                </tr>
              ))}
            </tbody>
          </table>
        </div>
      </div>

      {/* FAALİYET TAKVİMİ */}
      <div className="mb-20">
        <div className="flex justify-between items-center mb-10">
           <div className="flex items-center space-x-3">
             <div className="bg-white p-3 rounded-2xl shadow-xl border-b-4 border-orange-600">
               <svg className="w-6 h-6 text-orange-600" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path d="M8 7V3m8 4V3m-9 8h10M5 21h14a2 2 0 002-2V7a2 2 0 00-2-2H5a2 2 0 00-2 2v12a2 2 0 002 2z" strokeWidth={2.5}/></svg>
             </div>
             <h3 className="text-2xl font-black text-white uppercase tracking-tight">FAALİYET TAKVİM ÇİZELGELERİ</h3>
           </div>
           <div className="flex items-center space-x-3 bg-white/10 p-2 rounded-2xl border border-white/20">
              <select value={filterType} onChange={(e) => setFilterType(e.target.value)} className="bg-transparent text-white font-black text-xs outline-none px-4">
                {aircraftTypes.map(t => <option key={t} value={t} className="bg-green-950">{t}</option>)}
              </select>
              <input type="date" value={dateRange.start} onChange={(e) => setDateRange({...dateRange, start: e.target.value})} className="bg-transparent text-white font-black text-xs outline-none px-4 border-l border-white/10" />
              <button onClick={handleFilterActivity} className="bg-orange-500 text-white px-6 py-2.5 rounded-xl font-black text-[10px] hover:bg-orange-600 transition-all uppercase tracking-widest">SORGULA</button>
           </div>
        </div>

        {isActivityVisible && (
          <div className="bg-white p-8 rounded-[2.5rem] shadow-2xl overflow-hidden animate-in fade-in duration-700">
             {Object.entries(groupedActivities).map(([type, activities]) => (
               <ActivityGrid key={type} activities={activities} startDate={activeDateRange.start} endDate={activeDateRange.end} title={type} />
             ))}
             <div className="mt-12 grid grid-cols-4 gap-4 p-6 bg-slate-50 rounded-3xl border border-slate-200">
                <div className="text-[8px] font-black text-slate-400 uppercase tracking-widest col-span-4 mb-2">DURUM KODU TANIMLARI</div>
                <div className="flex items-center space-x-3"><div className="w-8 h-8 bg-[#ffff00] border border-black flex items-center justify-center font-black">B</div><span className="text-[10px] font-bold text-slate-600">BAKIM</span></div>
                <div className="flex items-center space-x-3"><div className="w-8 h-8 bg-[#ffff00] border border-black flex items-center justify-center font-black">BB</div><span className="text-[10px] font-bold text-slate-600">BAKIM BEKLER</span></div>
                <div className="flex items-center space-x-3"><div className="w-8 h-8 bg-[#ff0000] border border-black flex items-center justify-center font-black text-white">A</div><span className="text-[10px] font-bold text-slate-600">ARIZA</span></div>
                <div className="flex items-center space-x-3"><div className="w-8 h-8 bg-[#7030a0] border border-black flex items-center justify-center font-black text-white">X</div><span className="text-[10px] font-bold text-slate-600">OLMADIĞI GÜN</span></div>
             </div>
          </div>
        )}
      </div>

      {/* SNAPSHOT ONAY MODALI */}
      {isSnapshotModalOpen && (
        <div className="fixed inset-0 z-[300] bg-black/80 backdrop-blur-md flex items-center justify-center p-6">
           <div className="bg-white w-full max-w-4xl rounded-[2.5rem] shadow-2xl overflow-hidden animate-in zoom-in-95 duration-300">
              <div className="bg-orange-600 text-white p-8">
                 <h2 className="text-2xl font-black tracking-tighter uppercase">📊 TAKVİM KAYDI ÖN İZLEME & ONAY (00:00)</h2>
                 <p className="text-orange-100 text-[10px] font-bold uppercase tracking-widest mt-1">Sistem tarafından otomatik analiz edilen durum kodları</p>
              </div>
              <div className="p-8 max-h-[60vh] overflow-y-auto">
                 <table className="w-full text-left border-collapse">
                    <thead>
                       <tr className="border-b-2 border-slate-100">
                          <th className="px-4 py-4 text-[10px] font-black text-slate-400 uppercase">KUYRUK</th>
                          <th className="px-4 py-4 text-[10px] font-black text-slate-400 uppercase">TARİH</th>
                          <th className="px-4 py-4 text-[10px] font-black text-slate-400 uppercase text-center">KOD</th>
                          <th className="px-4 py-4 text-[10px] font-black text-slate-400 uppercase">ANALİZ GEREKÇESİ</th>
                       </tr>
                    </thead>
                    <tbody className="divide-y divide-slate-50">
                       {snapshotPreviews.map((p, idx) => (
                          <tr key={idx} className="hover:bg-slate-50">
                             <td className="px-4 py-4 font-black text-slate-900 text-sm">{p.kuyrukNo}</td>
                             <td className="px-4 py-4 text-xs font-bold text-slate-500">{p.tarih}</td>
                             <td className="px-4 py-4 text-center">
                                <span className={`w-10 h-10 inline-flex items-center justify-center rounded-lg font-black border border-black ${
                                  ['B','BB','KM'].includes(p.kod) ? 'bg-[#ffff00]' : 
                                  ['A','PB','KK'].includes(p.kod) ? 'bg-[#ff0000] text-white' : 
                                  p.kod === 'X' ? 'bg-[#7030a0] text-white' : 'bg-white'
                                }`}>
                                   {p.kod}
                                </span>
                             </td>
                             <td className="px-4 py-4">
                                <p className="text-[10px] font-black text-slate-800 uppercase leading-tight">{p.gerekce}</p>
                                <p className="text-[9px] text-slate-400 italic mt-1">{p.aciklamaOzeti}</p>
                             </td>
                          </tr>
                       ))}
                    </tbody>
                 </table>
              </div>
              <div className="bg-slate-50 p-8 border-t border-slate-200 flex justify-between items-center">
                 <p className="text-[10px] font-bold text-slate-400 uppercase max-w-sm italic">Sistem bu hava araçları için yukarıdaki kodları belirlemiştir. Onaylıyor musunuz?</p>
                 <div className="flex space-x-4">
                    <button onClick={() => setIsSnapshotModalOpen(false)} className="px-8 py-3.5 rounded-xl font-black text-[10px] uppercase text-slate-500 hover:text-slate-800 transition-all">REDDET & İNCELE</button>
                    <button onClick={handleApproveSnapshot} className="px-12 py-3.5 rounded-xl font-black text-[10px] uppercase bg-green-600 text-white shadow-xl hover:bg-green-700 transition-all">ONAYLA VE KAYDET</button>
                 </div>
              </div>
           </div>
        </div>
      )}

      {selectedAircraft && <AircraftDetailModal aircraft={selectedAircraft} onClose={() => setSelectedAircraft(null)} />}
      {editingAircraft && <MaintenanceForm aircraft={editingAircraft} onSave={() => setEditingAircraft(null)} onCancel={() => setEditingAircraft(null)} />}
      {isAdminOpen && <AdminPanel onSave={handleSyncFromExcel} onClose={() => setIsAdminOpen(false)} />}
    </Layout>
  );
};

export default App;

export enum PlatformType {
  H = 'H',
  SA = 'S-A',
  DA = 'D-A',
  SL = 'S-L',
  DL = 'D-L'
}

export enum Status {
  FAAL = 'FAAL',
  GAYRI_FAAL = 'GAYRI FAAL'
}

export enum StatusType {
  BAKIM = 'BAKIM',
  ARIZA = 'ARIZA',
  DIGER = 'DIGER',
  NONE = '-'
}

export interface MaintenanceHour {
  bakimTuru: string;
  kalanSaat: number;
}

export interface Aircraft {
  cagriKodu: string;
  kuyrukNo: string;
  platformTipi: string;
  durum: Status;
  durumTipi: StatusType;
  durumAyrintisi: string;
  konum: string;
  faydaliSaat: number;
  durumBaslangic: string;
  durumBitis?: string;
  aciklama: string;
  guncellemeTarihi: string;
  seriNo: string;
  motor: string;
  uretimYili: number;
  base: string;
  maintenanceHours: MaintenanceHour[];
  photos: string[];
  tip?: string;
}

export type DailyStatusCode = 'B' | 'BB' | 'KM' | 'A' | 'PB' | 'KK' | 'X' | 'F' | '';

export interface AircraftActivity {
  kuyrukNo: string;
  cagriKodu: string;
  tip: string;
  dailyStatuses: { [day: number]: DailyStatusCode };
}

export interface SheetMapping {
  kuyrukNo: string;
  durum: string;
  durumAyrintisi: string;
  konum: string;
  faydaliSaat: string;
  aciklama: string;
}

export interface SheetConfig {
  aircraftType: string;
  sheetId: string;
  appsScriptUrl: string;
  mapping: SheetMapping;
}

export interface GlobalSettings {
  appsScriptUrl: string;
}

export interface AppNotification {
  id: string;
  platform: string;
  kuyrukNo: string;
  mesaj: string;
  tarih: string;
  oncekiDeger: string;
  yeniDeger: string;
  kolon: string;
}

export interface SnapshotPreview {
  kuyrukNo: string;
  tarih: string;
  kod: DailyStatusCode;
  aciklamaOzeti: string;
  gerekce: string;
  originalData: Partial<Aircraft>;
}

import React, { useState, useMemo, useEffect } from 'react';
import Layout from './components/Layout';
import Dashboard from './components/Dashboard';
import AircraftDetailModal from './components/AircraftDetailModal';
import MaintenanceForm from './components/MaintenanceForm';
import ActivityGrid from './components/ActivityGrid';
import SplashScreen from './components/SplashScreen';
import AdminPanel from './components/AdminPanel';
import { MOCK_AIRCRAFT, MOCK_ACTIVITY_GRID } from './constants';
import { Aircraft, Status, SheetConfig, AppNotification, SnapshotPreview, DailyStatusCode } from './types';

const App: React.FC = () => {
  const [isSplashVisible, setIsSplashVisible] = useState(true);
  const [isAdminOpen, setIsAdminOpen] = useState(false);
  const [isActivityVisible, setIsActivityVisible] = useState(false);
  const [fleet, setFleet] = useState<Aircraft[]>(MOCK_AIRCRAFT);
  const [selectedAircraft, setSelectedAircraft] = useState<Aircraft | null>(null);
  const [editingAircraft, setEditingAircraft] = useState<Aircraft | null>(null);
  const [searchTerm, setSearchTerm] = useState('');

  // Bildirim ve Snapshot State'leri
  const [notifications, setNotifications] = useState<AppNotification[]>([]);
  const [snapshotPreviews, setSnapshotPreviews] = useState<SnapshotPreview[]>([]);
  const [isSnapshotModalOpen, setIsSnapshotModalOpen] = useState(false);

  const today = new Date();
  const firstDay = new Date(today.getFullYear(), today.getMonth(), 1);
  const lastDay = new Date(today.getFullYear(), today.getMonth() + 1, 0);

  const aircraftTypes = ["Tümü", "Bell-429", "AT-802", "T-70", "C-650", "B-360"];
  const [filterType, setFilterType] = useState("Tümü");
  const [dateRange, setDateRange] = useState({
    start: firstDay.toISOString().split('T')[0],
    end: lastDay.toISOString().split('T')[0]
  });

  const [activeDateRange, setActiveDateRange] = useState({ start: firstDay, end: lastDay });
  const [activeFilterType, setActiveFilterType] = useState("Tümü");

  // OTOMATİK KARAR VERME MANTIĞI (Metin Analizi - Keyword Bazlı)
  const determineStatusCode = (a: Partial<Aircraft>): { code: DailyStatusCode, gerekce: string } => {
    const durum = (a.durum || '').toLowerCase();
    const ayrinti = (a.durumAyrintisi || '').toLowerCase();
    const aciklama = (a.aciklama || '').toLowerCase();
    const fullText = `${durum} ${ayrinti} ${aciklama}`;

    // 1. KAZA KIRIM (KK) - En yüksek öncelik
    if (fullText.includes('kaza') || fullText.includes('kırım')) {
      return { code: 'KK', gerekce: 'Anahtar Kelime: "Kaza" veya "Kırım" tespit edildi.' };
    }

    // 2. PARÇA BEKLER (PB)
    if (fullText.includes('parça bekler') || fullText.includes('yedek parça') || fullText.includes('parça bekleniyor')) {
      return { code: 'PB', gerekce: 'Anahtar Kelime: "Parça Bekler" ifadeleri tespit edildi.' };
    }

    // 3. BAKIM / BAKIM BEKLER (B/BB)
    if (fullText.includes('bakım') || fullText.includes('periyodik') || fullText.includes('200h') || fullText.includes('960h')) {
      if (fullText.includes('bekle')) {
        return { code: 'BB', gerekce: 'Anahtar Kelime: "Bakım" ve "Bekleme" ifadeleri tespit edildi.' };
      }
      return { code: 'B', gerekce: 'Anahtar Kelime: "Bakım" tespiti yapıldı.' };
    }

    // 4. ARIZA (A)
    if (fullText.includes('arıza') || fullText.includes('arızalı') || fullText.includes('fault') || fullText.includes('failure')) {
      return { code: 'A', gerekce: 'Anahtar Kelime: "Arıza" varyasyonları tespit edildi.' };
    }

    // 5. KABUL MUAYENESİ (KM)
    if (fullText.includes('kabul') || fullText.includes('muayene') || fullText.includes('test uçuşu')) {
      return { code: 'KM', gerekce: 'Anahtar Kelime: "Kabul" veya "Muayene" tespit edildi.' };
    }

    // 6. HİÇBİRİ YOKSA -> X
    return { code: 'X', gerekce: 'Metin Analizi: Belirlenen anahtar kelimelerden hiçbiri bulunamadı.' };
  };

  const handleSyncFromExcel = (configs: SheetConfig[], incomingData: Partial<Aircraft>[]) => {
    let newNotifications: AppNotification[] = [];
    let updatedFleet = [...fleet];

    incomingData.forEach(incoming => {
      const existingIdx = updatedFleet.findIndex(a => a.kuyrukNo === incoming.kuyrukNo);

      if (existingIdx !== -1) {
        const existing = updatedFleet[existingIdx];

        // EXCEL VERİ DEĞİŞİKLİĞİ BİLDİRİM SİSTEMİ
        const columnsToCheck: (keyof Aircraft)[] = ['durum', 'durumAyrintisi', 'konum', 'faydaliSaat', 'aciklama'];
        columnsToCheck.forEach(col => {
          const oldVal = String(existing[col] || '');
          const newVal = String(incoming[col] || '');

          if (oldVal !== newVal) {
            newNotifications.push({
              id: Math.random().toString(36).substr(2, 9),
              platform: 'Bell-429',
              kuyrukNo: existing.kuyrukNo,
              kolon: col.toUpperCase(),
              oncekiDeger: oldVal,
              yeniDeger: newVal,
              mesaj: `Bell-429 | KUYRUK: ${existing.kuyrukNo} | ${col.toUpperCase()} kolonu verisi "${oldVal}" -> "${newVal}" olarak değiştirilmiştir.`,
              tarih: new Date().toLocaleString('tr-TR', { day: '2-digit', month: '2-digit', year: 'numeric', hour: '2-digit', minute: '2-digit' })
            });
          }
        });

        updatedFleet[existingIdx] = { ...existing, ...incoming } as Aircraft;
      } else {
        // Yeni Kayıt
        updatedFleet.push({ 
          ...incoming, 
          cagriKodu: incoming.cagriKodu || `ORMAN-${incoming.kuyrukNo?.split('-')[1] || 'XX'}`,
          platformTipi: 'H', 
          tip: 'Bell-429' 
        } as Aircraft);
      }
    });

    setFleet(updatedFleet);
    setNotifications(prev => [...newNotifications, ...prev]);

    // GÜNLÜK TAKVİME AKTARIM ÖNCESİ ANALİZ (Snapshot Hazırlığı)
    const previews: SnapshotPreview[] = incomingData.map(a => {
      const { code, gerekce } = determineStatusCode(a);
      return {
        kuyrukNo: a.kuyrukNo || 'BİLİNMİYOR',
        tarih: new Date().toLocaleDateString('tr-TR'),
        kod: code,
        aciklamaOzeti: `${a.durumAyrintisi || ''} - ${a.konum || ''}`.substring(0, 50),
        gerekce: gerekce,
        originalData: a
      };
    });

    setSnapshotPreviews(previews);
    setIsSnapshotModalOpen(true);
  };

  const handleApproveSnapshot = () => {
    // Burada onaylanan veriler kalıcı günlük takvim (Activity Log) tablosuna işlenir.
    console.log("Onaylandı: Günlük takvime snapshot olarak kaydedildi.");
    setIsSnapshotModalOpen(false);
  };

  const handleFilterActivity = () => {
    setActiveDateRange({ start: new Date(dateRange.start), end: new Date(dateRange.end) });
    setActiveFilterType(filterType);
    setIsActivityVisible(true);
  };

  const filteredFleet = useMemo(() => {
    return fleet.filter(a => {
      const s = searchTerm.toLowerCase();
      return a.kuyrukNo.toLowerCase().includes(s) || a.cagriKodu.toLowerCase().includes(s) || a.konum.toLowerCase().includes(s);
    });
  }, [fleet, searchTerm]);

  const groupedActivities = useMemo(() => {
    const groups: { [type: string]: any[] } = {};
    MOCK_ACTIVITY_GRID.forEach(act => {
      if (activeFilterType !== "Tümü" && act.tip !== activeFilterType) return;
      if (!groups[act.tip]) groups[act.tip] = [];
      groups[act.tip].push(act);
    });
    return groups;
  }, [activeFilterType]);

  if (isSplashVisible) return <SplashScreen onComplete={() => setIsSplashVisible(false)} />;

  return (
    <Layout>
      <div className="flex justify-between items-center mb-10">
         <div className="flex items-center space-x-6">
            {notifications.length > 0 && (
              <div className="bg-red-500/10 border border-red-500/20 px-4 py-2 rounded-xl flex items-center animate-pulse">
                <div className="w-2 h-2 bg-red-500 rounded-full mr-3 shadow-[0_0_10px_rgba(239,68,68,0.5)]"></div>
                <span className="text-red-400 font-black text-[9px] uppercase tracking-[0.3em]">{notifications.length} EXCEL VERİ DEĞİŞİKLİĞİ</span>
              </div>
            )}
         </div>
         <button 
           onClick={() => setIsAdminOpen(true)} 
           className="bg-white/5 hover:bg-white/10 text-white px-8 py-4 rounded-2xl font-black text-[10px] shadow-2xl transition-all border border-white/10 flex items-center uppercase tracking-[0.3em] active:scale-95"
         >
