              <h3 className="text-red-500 font-black text-xs uppercase tracking-[0.4em] flex items-center">
                <svg className="w-5 h-5 mr-3" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path d="M15 17h5l-1.405-1.405A2.032 2.032 0 0118 14.158V11a6.002 6.002 0 00-4-5.659V5a2 2 0 10-4 0v.341C7.67 6.165 6 8.388 6 11v3.159c0 .538-.214 1.055-.595 1.436L4 17h5m6 0v1a3 3 0 11-6 0v-1m6 0H9" strokeWidth={2.5}/></svg>
                BELL-429 | VERİ DEĞİŞİKLİK BİLDİRİMLERİ
              </h3>
              <button onClick={() => setNotifications([])} className="text-gray-600 text-[9px] font-black uppercase hover:text-white transition-colors">TÜMÜNÜ TEMİZLE</button>
           </div>
           <div className="space-y-4 max-h-[350px] overflow-y-auto pr-4 scrollbar-hide">
              {notifications.map(n => (
                <div key={n.id} className="bg-black/40 p-5 rounded-2xl border border-white/5 flex justify-between items-center group hover:border-red-900/30 transition-all">
                   <div className="flex-grow">
                      <div className="text-[10px] font-black text-white mb-2 uppercase tracking-widest flex items-center">
                        <span className="text-red-500 mr-2">●</span> BELL-429 | KUYRUK: <span className="text-emerald-400 ml-1">{n.kuyrukNo}</span>
