                      <p className="text-[11px] text-gray-400 font-bold leading-relaxed">
                        <span className="text-gray-500 font-black">{n.kolon}</span> hücresi: 
                        <span className="mx-2 text-red-900 line-through decoration-2">"{n.oncekiDeger}"</span>
                        <svg className="w-3 h-3 inline mx-2 text-green-500" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path d="M13 7l5 5m0 0l-5 5m5-5H6" strokeWidth={3}/></svg>
                        <span className="text-emerald-500 font-black">"{n.yeniDeger}"</span> olarak güncellendi.
                      </p>
                   </div>
                   <div className="text-right flex flex-col items-end">
                      <span className="text-[8px] font-black text-gray-600 mb-2 uppercase tracking-widest">{n.tarih}</span>
                      <span className="text-[9px] font-black text-emerald-900 bg-emerald-500/10 px-3 py-1 rounded-full border border-emerald-500/20">LOG KAYDI</span>
                   </div>
                </div>
              ))}
           </div>
        </div>
      )}

      {/* DURUM ÖZETLERİ TABLOSU */}
      <div className="mb-20">
        <div className="flex justify-between items-end mb-8">
           <div>
             <h3 className="text-2xl font-black text-white uppercase tracking-tighter">HAVA ARACI DURUM ÖZETLERİ</h3>
