              />
              <svg className="w-5 h-5 absolute left-4 top-1/2 -translate-y-1/2 text-green-700" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path d="M21 21l-6-6m2-5a7 7 0 11-14 0 7 7 0 0114 0z" strokeWidth={3}/></svg>
