        <div className="bg-white p-1 rounded-[2.5rem] shadow-2xl overflow-hidden border-4 border-white">
          <table className="w-full border-collapse">
            <thead>
              <tr className="bg-slate-50 border-b-2 border-slate-100">
                <th className="px-6 py-5 text-left text-[10px] font-black text-slate-400 uppercase tracking-widest">ÇAĞRI KODU</th>
