                <th className="px-6 py-5 text-left text-[10px] font-black text-slate-400 uppercase tracking-widest">AYRINTI</th>
                <th className="px-6 py-5 text-left text-[10px] font-black text-slate-400 uppercase tracking-widest">KONUM</th>
                <th className="px-6 py-5 text-center text-[10px] font-black text-slate-400 uppercase tracking-widest">SAAT</th>
                <th className="px-6 py-5 text-left text-[10px] font-black text-slate-400 uppercase tracking-widest">AÇIKLAMA</th>
              </tr>
            </thead>
            <tbody className="divide-y divide-slate-100">
              {filteredFleet.map((a, i) => (
                <tr key={i} className="hover:bg-slate-50 cursor-pointer transition-all group" onClick={() => setSelectedAircraft(a)}>
                  <td className="px-6 py-5 text-sm font-black text-slate-900">{a.cagriKodu}</td>
