                  <td className="px-6 py-5 text-center">
                    <span className={`px-4 py-2 rounded-xl font-black text-[9px] uppercase border-2 shadow-sm ${a.durum === Status.FAAL ? 'bg-emerald-50 text-emerald-700 border-emerald-200' : 'bg-red-50 text-red-700 border-red-200'}`}>
                      {a.durum}
                    </span>
                  </td>
                  <td className="px-6 py-5 text-[11px] font-bold text-slate-600">{a.durumAyrintisi}</td>
                  <td className="px-6 py-5 text-[11px] font-black text-slate-800 uppercase">{a.konum}</td>
                  <td className="px-6 py-5 text-center font-black text-lg tabular-nums text-blue-600">{a.faydaliSaat}</td>
                  <td className="px-6 py-5 italic text-slate-400 text-[10px] max-w-xs truncate leading-relaxed">{a.aciklama}</td>
