              ))}
            </tbody>
          </table>
        </div>
      </div>

      {/* FAALİYET TAKVİMİ */}
      <div className="mb-20">
        <div className="flex justify-between items-center mb-10">
           <div className="flex items-center space-x-4">
             <div className="bg-white p-3 rounded-2xl shadow-xl border-b-4 border-orange-600">
               <svg className="w-6 h-6 text-orange-600" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path d="M8 7V3m8 4V3m-9 8h10M5 21h14a2 2 0 002-2V7a2 2 0 00-2-2H5a2 2 0 00-2 2v12a2 2 0 002 2z" strokeWidth={2.5}/></svg>
             </div>
             <div>
               <h3 className="text-2xl font-black text-white uppercase tracking-tight">FAALİYET TAKVİM ÇİZELGELERİ</h3>
               <p className="text-orange-500 text-[10px] font-bold uppercase tracking-widest mt-1">Snapshot Bazlı Geçmiş Kayıtları</p>
             </div>
           </div>
           <div className="flex items-center space-x-3 bg-white/5 p-2 rounded-2xl border border-white/10 backdrop-blur-md">
              <select value={filterType} onChange={(e) => setFilterType(e.target.value)} className="bg-transparent text-white font-black text-xs outline-none px-4 appearance-none cursor-pointer">
