        {isActivityVisible && (
          <div className="bg-white p-8 rounded-[2.5rem] shadow-2xl overflow-hidden animate-in fade-in duration-700 border-4 border-white">
             {Object.entries(groupedActivities).map(([type, activities]) => (
               <ActivityGrid key={type} activities={activities} startDate={activeDateRange.start} endDate={activeDateRange.end} title={type} />
             ))}
             <div className="mt-12 grid grid-cols-2 md:grid-cols-4 gap-4 p-8 bg-slate-50 rounded-[2rem] border border-slate-200">
