              </div>

              <div className="p-10 max-h-[55vh] overflow-y-auto scrollbar-hide">
                 <table className="w-full text-left border-collapse">
                    <thead>
                       <tr className="border-b-2 border-slate-100">
                          <th className="px-4 py-4 text-[11px] font-black text-slate-400 uppercase tracking-widest">KUYRUK</th>
                          <th className="px-4 py-4 text-[11px] font-black text-slate-400 uppercase tracking-widest text-center">BELİRLENEN KOD</th>
