                          <th className="px-4 py-4 text-[11px] font-black text-slate-400 uppercase tracking-widest">DETAY ÖZETİ</th>
                       </tr>
                    </thead>
                    <tbody className="divide-y divide-slate-50">
                       {snapshotPreviews.map((p, idx) => (
                          <tr key={idx} className="hover:bg-slate-50 transition-colors group">
                             <td className="px-4 py-6 font-black text-slate-900 text-sm group-hover:translate-x-1 transition-transform">{p.kuyrukNo}</td>
