                                  ['B','BB','KM'].includes(p.kod) ? 'bg-[#ffff00]' : 
                                  ['A','PB','KK'].includes(p.kod) ? 'bg-[#ff0000] text-white' : 
                                  p.kod === 'X' ? 'bg-[#7030a0] text-white' : 'bg-white'
                                }`}>
                                   {p.kod}
                                </span>
                             </td>
                             <td className="px-4 py-6">
                                <div className="text-[11px] font-black text-slate-800 uppercase leading-snug">{p.gerekce}</div>
                                <div className="text-[9px] text-emerald-600 font-bold mt-1 uppercase tracking-tighter">İlgili Alan: {p.originalData.durum} | {p.originalData.durumAyrintisi}</div>
                             </td>
                             <td className="px-4 py-6">
