                          </tr>
                       ))}
                    </tbody>
                 </table>
              </div>

              <div className="bg-slate-100 p-10 border-t border-slate-200 flex flex-col md:flex-row justify-between items-center gap-6">
                 <div className="flex items-start space-x-4 max-w-xl">
                    <div className="bg-orange-100 p-3 rounded-2xl border border-orange-200">
                       <svg className="w-6 h-6 text-orange-600" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path d="M12 9v2m0 4h.01m-6.938 4h13.856c1.54 0 2.502-1.667 1.732-3L13.732 4c-.77-1.333-2.694-1.333-3.464 0L3.34 16c-.77 1.333.192 3 1.732 3z" strokeWidth={2.5}/></svg>
                    </div>
                    <p className="text-[11px] font-bold text-slate-500 uppercase tracking-wide leading-relaxed">
                       <span className="text-slate-800 font-black">ONAY SORUSU:</span> Sistem bu hava araçları için yukarıdaki durum kodlarını belirlemiştir. Bu veriler kalıcı günlük takvime snapshot olarak işlenecektir. Onaylıyor musunuz?
                    </p>
                 </div>
                 <div className="flex space-x-4 w-full md:w-auto">
                    <button 
                      onClick={() => {
                        console.log("Snapshot reddedildi - Admin inceleme modu aktif.");
                        setIsSnapshotModalOpen(false);
                      }} 
                      className="flex-1 md:flex-none px-10 py-5 rounded-2xl font-black text-[10px] uppercase tracking-widest text-slate-500 hover:bg-slate-200 border border-slate-300 transition-all"
                    >
                      REDDET & İNCELE
                    </button>
                    <button 
                      onClick={handleApproveSnapshot} 
                      className="flex-1 md:flex-none px-14 py-5 rounded-2xl font-black text-[10px] uppercase tracking-[0.3em] bg-emerald-600 text-white shadow-2xl hover:bg-emerald-700 transition-all active:scale-95"
                    >
                      ONAYLA VE KAYDET
                    </button>
                 </div>
              </div>
           </div>
        </div>
      )}

      {selectedAircraft && <AircraftDetailModal aircraft={selectedAircraft} onClose={() => setSelectedAircraft(null)} />}
      {editingAircraft && <MaintenanceForm aircraft={editingAircraft} onSave={() => setEditingAircraft(null)} onCancel={() => setEditingAircraft(null)} />}
      {isAdminOpen && <AdminPanel onSave={handleSyncFromExcel} onClose={() => setIsAdminOpen(false)} />}
    </Layout>
  );
};

