import React, { useState } from 'react';
import { SheetConfig, SheetMapping, Aircraft, Status, StatusType } from '../types';
import { fetchAircraftDataFromAppsScript } from '../services/sheetService';

interface AdminPanelProps {
  onSave: (configs: SheetConfig[], data: Partial<Aircraft>[]) => void;
  onClose: () => void;
}

const AdminPanel: React.FC<AdminPanelProps> = ({ onSave, onClose }) => {
  const [activeTab, setActiveTab] = useState('Bell-429');
  const [previewData, setPreviewData] = useState<Partial<Aircraft>[]>([]);
  const [isLoading, setIsLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);

  // Sabit Tanımlı Bell-429 Kaynakları
  const BELL_429_URL = "https://docs.google.com/spreadsheets/d/1D83TF8K1QG30kBv2sCqnPCMYsdSbaJfcsw-E3S5A9VQ/edit?gid=84538314";
  const APPS_SCRIPT_URL = "https://script.google.com/macros/s/AKfycbz0yzWM9ZB9d6m7mpaPqDDCdcHsMQTA14tW_vVztMxxSAet2cO4PsCAxfnZNZFz_b6t/exec";
  const SHEET_ID = "1D83TF8K1QG30kBv2sCqnPCMYsdSbaJfcsw-E3S5A9VQ";

  // Kullanıcı tarafından belirtilen yeni hücre aralıkları
  const [mapping, setMapping] = useState<SheetMapping>({
    kuyrukNo: 'A2:A8',
    durum: 'M2:M8',
    durumAyrintisi: 'N2:N8',
    konum: 'L2:L8',
    faydaliSaat: 'I2:I8',
    aciklama: 'O2:O8'
  });

  const handleRead = async () => {
    if (Object.values(mapping).some(v => !v)) {
      setError("Hücre aralıkları boş olamaz");
      return;
    }

    setIsLoading(true);
    setError(null);

    try {
      const results = await fetchAircraftDataFromAppsScript(APPS_SCRIPT_URL, {
        aircraftType: 'Bell-429',
        sheetId: SHEET_ID,
        appsScriptUrl: APPS_SCRIPT_URL,
        mapping
      });

      if (results.length === 0) {
        setError("Satır sayıları eşleşmiyor veya veri okunamadı");
      } else {
        setPreviewData(results);
      }
    } catch (e) {
      setError("Bağlantı hatası: Veriler alınamadı");
    } finally {
      setIsLoading(false);
    }
  };

  const handleTransfer = () => {
    if (previewData.length === 0) {
      setError("Ön izleme olmadan aktarım yapılamaz");
      return;
    }

    onSave([{ 
      aircraftType: 'Bell-429', 
      sheetId: SHEET_ID, 
      appsScriptUrl: APPS_SCRIPT_URL, 
      mapping 
    }], previewData);
    onClose();
  };

  const platforms = [
    { id: 'Bell-429', label: 'Bell-429', active: true },
    { id: 'AT-802', label: 'AT-802', active: false },
    { id: 'T-70', label: 'T-70', active: false },
    { id: 'B-360', label: 'B-360', active: false },
    { id: 'C-650', label: 'C-650', active: false },
  ];

  return (
    <div className="fixed inset-0 z-[200] bg-black/90 backdrop-blur-xl flex items-center justify-center p-4">
      <div className="bg-[#052e16] w-full max-w-[1700px] h-[95vh] rounded-[2.5rem] border border-green-800/50 flex overflow-hidden shadow-2xl animate-in zoom-in-95 duration-300">

        {/* SOL MENÜ */}
        <div className="w-64 bg-[#021a0c] border-r border-green-900/50 p-6 flex flex-col">
          <h2 className="text-white font-black text-lg mb-8 tracking-tighter uppercase">PLATFORMLAR</h2>
          <nav className="space-y-2 flex-grow">
            {platforms.map(p => (
              <button
                key={p.id}
                onClick={() => p.active && setActiveTab(p.id)}
                className={`w-full text-left px-5 py-3.5 rounded-xl font-black text-[9px] uppercase tracking-widest transition-all flex items-center justify-between group ${
                  activeTab === p.id 
                    ? 'bg-green-600 text-white shadow-lg' 
                    : p.active 
                      ? 'text-green-500 hover:bg-green-950 border border-transparent hover:border-green-800' 
                      : 'text-gray-800 opacity-20 cursor-not-allowed'
                }`}
              >
                {p.label}
                {p.active && <div className="w-1.5 h-1.5 bg-current rounded-full animate-pulse"></div>}
              </button>
            ))}
          </nav>
          <button onClick={onClose} className="py-3.5 rounded-xl border border-red-900/30 text-red-500 font-black text-[9px] uppercase tracking-widest hover:bg-red-950 transition-all">PANELİ KAPAT</button>
        </div>

        {/* SAĞ PANEL */}
        <div className="flex-1 flex flex-col overflow-hidden">

          <div className="p-8 border-b border-green-900/50 bg-[#052e16]/50 flex justify-between items-center">
            <div>
              <h1 className="text-white text-2xl font-black tracking-tighter uppercase">EXCEL VERİ OKUMA (ÇİFT ÖN İZLEMELİ)</h1>
              <p className="text-green-500 text-[9px] font-bold uppercase tracking-[0.4em] mt-1">SİSTEM: {activeTab} PORTALI</p>
            </div>
            <div className="flex items-center space-x-4">
               <div className="bg-[#0a2f1a] px-5 py-2.5 rounded-2xl border border-green-800/50">
                  <span className="text-[8px] font-black text-gray-500 uppercase tracking-widest block mb-1">SCRIPT DURUMU</span>
                  <span className="text-emerald-400 font-black text-xs uppercase flex items-center">AKTİF</span>
               </div>
            </div>
          </div>

          <div className="flex-1 p-8 overflow-y-auto space-y-8 scrollbar-hide">

            {/* 1. ÖN İZLEME - EXCEL TABLO GÖRÜNÜMÜ */}
            <div className="space-y-4">
               <div className="flex items-center justify-between">
                  <h3 className="text-white font-black text-xs uppercase tracking-widest flex items-center">
                    <span className="bg-blue-500 w-5 h-5 rounded-full flex items-center justify-center text-[10px] mr-2">1</span>
                    EXCEL TABLO GÖRÜNÜMÜ (ÖN İZLEME)
                  </h3>
                  <a href={BELL_429_URL} target="_blank" className="text-blue-400 text-[10px] font-black underline">YENİ SEKMEDE AÇ</a>
               </div>
               <div className="bg-[#021a0c] rounded-3xl border border-green-900/50 h-[400px] overflow-hidden shadow-2xl">
                  <iframe 
                    src={BELL_429_URL.replace("/edit", "/htmlembed") + "&widget=false&chrome=false&headers=false"} 
                    className="w-full h-full opacity-90 grayscale-[0.3] contrast-[1.1]"
                  ></iframe>
               </div>
            </div>

            {/* HÜCRE OKUMA TANIMI */}
            <div className="grid grid-cols-1 lg:grid-cols-4 gap-6 items-end bg-[#0a2f1a]/30 p-8 rounded-3xl border border-green-800/20">
               <div className="lg:col-span-4 border-b border-green-900/30 pb-4 mb-2">
                  <h3 className="text-green-400 text-[10px] font-black uppercase tracking-widest">HÜCRE OKUMA TANIMI</h3>
               </div>
               {Object.entries(mapping).map(([key, value]) => (
                 <div key={key} className="flex flex-col">
                   <label className="text-[8px] font-black text-gray-500 uppercase tracking-widest mb-2 ml-1">
                     {key.replace(/([A-Z])/g, ' $1').toUpperCase()}
                   </label>
                   <input 
                     type="text" 
                     value={value}
                     onChange={(e) => setMapping({...mapping, [key]: e.target.value.toUpperCase()})}
                     placeholder="Örn: A2:A10"
                     className="bg-[#021a0c] text-white px-5 py-3 rounded-xl border border-green-900/50 focus:border-green-400 outline-none font-bold text-xs uppercase transition-all"
                   />
                 </div>
               ))}
               <button 
                onClick={handleRead}
                disabled={isLoading}
                className="bg-blue-600 hover:bg-blue-500 text-white h-[46px] rounded-xl font-black text-xs uppercase tracking-[0.2em] shadow-xl transition-all disabled:opacity-50"
              >
                {isLoading ? "OKUNUYOR..." : "OKU"}
              </button>
            </div>

            {/* 2. ÖN İZLEME - DURUM ÖZETİ */}
            {previewData.length > 0 && (
              <div className="space-y-4 animate-in slide-in-from-top-4">
                 <h3 className="text-white font-black text-xs uppercase tracking-widest flex items-center">
                    <span className="bg-blue-500 w-5 h-5 rounded-full flex items-center justify-center text-[10px] mr-2">2</span>
                    DURUM ÖZETİ ÖN İZLEME (AKTARIM ÖNCESİ)
                 </h3>
                 <div className="bg-[#021a0c] rounded-3xl border border-green-900/50 overflow-hidden shadow-2xl">
                    <table className="w-full text-left border-collapse">
                       <thead>
                          <tr className="border-b border-green-900/30 bg-[#0a2f1a]/50">
                             <th className="px-6 py-4 text-[9px] font-black text-gray-500 uppercase tracking-widest">KUYRUK</th>
                             <th className="px-6 py-4 text-[9px] font-black text-gray-500 uppercase tracking-widest">DURUM</th>
                             <th className="px-6 py-4 text-[9px] font-black text-gray-500 uppercase tracking-widest">AYRINTI</th>
                             <th className="px-6 py-4 text-[9px] font-black text-gray-500 uppercase tracking-widest">KONUM</th>
                             <th className="px-6 py-4 text-[9px] font-black text-gray-500 uppercase tracking-widest text-center">SAAT</th>
                             <th className="px-6 py-4 text-[9px] font-black text-gray-500 uppercase tracking-widest">AÇIKLAMA</th>
                          </tr>
                       </thead>
                       <tbody className="divide-y divide-green-900/10">
                          {previewData.map((row, i) => (
                             <tr key={i} className={`hover:bg-white/5 transition-colors ${!row.kuyrukNo ? 'bg-red-950/20' : ''}`}>
                                <td className="px-6 py-4 text-xs font-black text-white">{row.kuyrukNo || 'EKSİK'}</td>
                                <td className="px-6 py-4">
                                   <span className={`px-3 py-1 rounded-lg font-black text-[8px] uppercase border ${
                                     row.durum === Status.FAAL 
                                      ? 'bg-emerald-500/10 text-emerald-400 border-emerald-500/20' 
                                      : row.durumAyrintisi?.includes('PARÇA BEKLER')
                                        ? 'bg-orange-500/10 text-orange-400 border-orange-500/20'
                                        : 'bg-red-500/10 text-red-400 border-red-500/20'
                                   }`}>
                                      {row.durum}
                                   </span>
                                </td>
                                <td className="px-6 py-4 text-[10px] font-bold text-gray-400 uppercase">{row.durumAyrintisi}</td>
                                <td className="px-6 py-4 text-xs font-bold text-gray-300 uppercase">{row.konum}</td>
                                <td className="px-6 py-4 text-xs font-black text-center text-blue-400">{row.faydaliSaat}</td>
                                <td className="px-6 py-4 text-[10px] text-gray-500 italic max-w-[200px] truncate">{row.aciklama}</td>
                             </tr>
                          ))}
                       </tbody>
                    </table>
                 </div>

                 {error && <p className="text-red-500 text-[10px] font-bold uppercase tracking-widest ml-4">{error}</p>}

                 <div className="flex justify-end pt-4 pb-12">
                    <button 
                      onClick={handleTransfer}
                      className="bg-emerald-600 hover:bg-emerald-500 text-white px-12 py-4 rounded-2xl font-black text-xs uppercase tracking-[0.2em] shadow-2xl transition-all"
                    >
                      KAYDET VE AKTAR
                    </button>
                 </div>
              </div>
            )}

            {previewData.length === 0 && !isLoading && (
              <div className="py-24 text-center">
                 <svg className="w-16 h-16 text-green-900 mx-auto mb-6" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path d="M9 5H7a2 2 0 00-2 2v12a2 2 0 002 2h10a2 2 0 002-2V7a2 2 0 00-2-2h-2M9 5a2 2 0 002 2h2a2 2 0 002-2M9 5a2 2 0 012-2h2a2 2 0 012 2" strokeWidth={1}/></svg>
                 <p className="text-green-900 font-black text-[10px] uppercase tracking-[0.5em]">Verileri görmek için OKU butonuna basın</p>
              </div>
            )}

          </div>
        </div>
      </div>
    </div>
  );
};

export default AdminPanel;

import React, { useState, useMemo, useEffect } from 'react';
import Layout from './components/Layout';
import Dashboard from './components/Dashboard';
import AircraftDetailModal from './components/AircraftDetailModal';
import MaintenanceForm from './components/MaintenanceForm';
import ActivityGrid from './components/ActivityGrid';
import SplashScreen from './components/SplashScreen';
import AdminPanel from './components/AdminPanel';
import { MOCK_AIRCRAFT, MOCK_ACTIVITY_GRID } from './constants';
import { Aircraft, Status, SheetConfig, AppNotification, SnapshotPreview, DailyStatusCode } from './types';
import { fetchAircraftDataFromAppsScript } from './services/sheetService';

const App: React.FC = () => {
  const [isSplashVisible, setIsSplashVisible] = useState(true);
  const [isAdminOpen, setIsAdminOpen] = useState(false);
  const [isActivityVisible, setIsActivityVisible] = useState(false);
  const [fleet, setFleet] = useState<Aircraft[]>(MOCK_AIRCRAFT);
  const [selectedAircraft, setSelectedAircraft] = useState<Aircraft | null>(null);
  const [editingAircraft, setEditingAircraft] = useState<Aircraft | null>(null);
  const [searchTerm, setSearchTerm] = useState('');

  // Bildirim ve Snapshot State'leri
  const [notifications, setNotifications] = useState<AppNotification[]>([]);
  const [snapshotPreviews, setSnapshotPreviews] = useState<SnapshotPreview[]>([]);
  const [isSnapshotModalOpen, setIsSnapshotModalOpen] = useState(false);

  const today = new Date();
  const firstDay = new Date(today.getFullYear(), today.getMonth(), 1);
  const lastDay = new Date(today.getFullYear(), today.getMonth() + 1, 0);

  const aircraftTypes = ["Tümü", "Bell-429", "AT-802", "T-70", "C-650", "B-360"];
  const [filterType, setFilterType] = useState("Tümü");
  const [dateRange, setDateRange] = useState({
    start: firstDay.toISOString().split('T')[0],
    end: lastDay.toISOString().split('T')[0]
  });

  const [activeDateRange, setActiveDateRange] = useState({ start: firstDay, end: lastDay });
  const [activeFilterType, setActiveFilterType] = useState("Tümü");

  // AÇILIŞTA OTOMATİK SENKRONİZASYON
  useEffect(() => {
    const autoSync = async () => {
      const APPS_SCRIPT_URL = "https://script.google.com/macros/s/AKfycbz0yzWM9ZB9d6m7mpaPqDDCdcHsMQTA14tW_vVztMxxSAet2cO4PsCAxfnZNZFz_b6t/exec";
      const defaultMapping = {
        kuyrukNo: 'A2:A8',
        durum: 'M2:M8',
        durumAyrintisi: 'N2:N8',
        konum: 'L2:L8',
        faydaliSaat: 'I2:I8',
        aciklama: 'O2:O8'
      };

      const defaultConfig: SheetConfig = {
        aircraftType: 'Bell-429',
        sheetId: '1D83TF8K1QG30kBv2sCqnPCMYsdSbaJfcsw-E3S5A9VQ',
        appsScriptUrl: APPS_SCRIPT_URL,
        mapping: defaultMapping
      };

      try {
        const data = await fetchAircraftDataFromAppsScript(APPS_SCRIPT_URL, defaultConfig);
        if (data && data.length > 0) {
          handleSyncFromExcel([defaultConfig], data, true); // true = sessiz (onay modalsız) başlangıç sync'i
        }
      } catch (e) {
        console.error("Otomatik açılış senkronizasyonu başarısız:", e);
      }
    };

    const timer = setTimeout(() => {
      autoSync();
    }, 1000); // Splash sonrası kısa bir gecikme ile tetikle

    return () => clearTimeout(timer);
  }, []);

  // OTOMATİK KARAR VERME MANTIĞI (Metin Analizi - Keyword Bazlı)
  const determineStatusCode = (a: Partial<Aircraft>): { code: DailyStatusCode, gerekce: string } => {
    const durum = (a.durum || '').toLowerCase();
    const ayrinti = (a.durumAyrintisi || '').toLowerCase();
    const aciklama = (a.aciklama || '').toLowerCase();
    const fullText = `${durum} ${ayrinti} ${aciklama}`;

    // 1. KAZA KIRIM (KK) - En yüksek öncelik
    if (fullText.includes('kaza') || fullText.includes('kırım')) {
      return { code: 'KK', gerekce: 'Anahtar Kelime: "Kaza" veya "Kırım" tespit edildi.' };
    }

    // 2. PARÇA BEKLER (PB)
    if (fullText.includes('parça bekler') || fullText.includes('yedek parça') || fullText.includes('parça bekleniyor')) {
      return { code: 'PB', gerekce: 'Anahtar Kelime: "Parça Bekler" ifadeleri tespit edildi.' };
    }

    // 3. BAKIM / BAKIM BEKLER (B/BB)
    if (fullText.includes('bakım') || fullText.includes('periyodik') || fullText.includes('200h') || fullText.includes('960h')) {
      if (fullText.includes('bekle')) {
        return { code: 'BB', gerekce: 'Anahtar Kelime: "Bakım" ve "Bekleme" ifadeleri tespit edildi.' };
      }
      return { code: 'B', gerekce: 'Anahtar Kelime: "Bakım" tespiti yapıldı.' };
    }

    // 4. ARIZA (A)
    if (fullText.includes('arıza') || fullText.includes('arızalı') || fullText.includes('fault') || fullText.includes('failure')) {
      return { code: 'A', gerekce: 'Anahtar Kelime: "Arıza" varyasyonları tespit edildi.' };
    }

    // 5. KABUL MUAYENESİ (KM)
    if (fullText.includes('kabul') || fullText.includes('muayene') || fullText.includes('test uçuşu')) {
      return { code: 'KM', gerekce: 'Anahtar Kelime: "Kabul" veya "Muayene" tespit edildi.' };
    }

    // 6. HİÇBİRİ YOKSA -> X
    return { code: 'X', gerekce: 'Metin Analizi: Belirlenen anahtar kelimelerden hiçbiri bulunamadı.' };
  };

  const handleSyncFromExcel = (configs: SheetConfig[], incomingData: Partial<Aircraft>[], silent: boolean = false) => {
    let newNotifications: AppNotification[] = [];
    let updatedFleet = [...fleet];

    incomingData.forEach(incoming => {
      const existingIdx = updatedFleet.findIndex(a => a.kuyrukNo === incoming.kuyrukNo);

      if (existingIdx !== -1) {
        const existing = updatedFleet[existingIdx];

        // EXCEL VERİ DEĞİŞİKLİĞİ BİLDİRİM SİSTEMİ
        const columnsToCheck: (keyof Aircraft)[] = ['durum', 'durumAyrintisi', 'konum', 'faydaliSaat', 'aciklama'];
        columnsToCheck.forEach(col => {
          const oldVal = String(existing[col] || '');
          const newVal = String(incoming[col] || '');

          if (oldVal !== newVal) {
            newNotifications.push({
              id: Math.random().toString(36).substr(2, 9),
              platform: 'Bell-429',
              kuyrukNo: existing.kuyrukNo,
              kolon: col.toUpperCase(),
              oncekiDeger: oldVal,
              yeniDeger: newVal,
              mesaj: `Bell-429 | KUYRUK: ${existing.kuyrukNo} | ${col.toUpperCase()} kolonu verisi "${oldVal}" -> "${newVal}" olarak değiştirilmiştir.`,
              tarih: new Date().toLocaleString('tr-TR', { day: '2-digit', month: '2-digit', year: 'numeric', hour: '2-digit', minute: '2-digit' })
            });
          }
        });

        updatedFleet[existingIdx] = { ...existing, ...incoming } as Aircraft;
      } else {
        // Yeni Kayıt
        updatedFleet.push({ 
          ...incoming, 
          cagriKodu: incoming.cagriKodu || `ORMAN-${incoming.kuyrukNo?.split('-')[1] || 'XX'}`,
          platformTipi: 'H', 
          tip: 'Bell-429' 
        } as Aircraft);
      }
    });

    setFleet(updatedFleet);
    if (!silent) setNotifications(prev => [...newNotifications, ...prev]);

    if (!silent) {
      // GÜNLÜK TAKVİME AKTARIM ÖNCESİ ANALİZ (Snapshot Hazırlığı)
      const previews: SnapshotPreview[] = incomingData.map(a => {
        const { code, gerekce } = determineStatusCode(a);
        return {
          kuyrukNo: a.kuyrukNo || 'BİLİNMİYOR',
          tarih: new Date().toLocaleDateString('tr-TR'),
          kod: code,
          aciklamaOzeti: `${a.durumAyrintisi || ''} - ${a.konum || ''}`.substring(0, 50),
          gerekce: gerekce,
          originalData: a
        };
      });

      setSnapshotPreviews(previews);
      setIsSnapshotModalOpen(true);
    }
  };

  const handleApproveSnapshot = () => {
    // Burada onaylanan veriler kalıcı günlük takvim (Activity Log) tablosuna işlenir.
    console.log("Onaylandı: Günlük takvime snapshot olarak kaydedildi.");
    setIsSnapshotModalOpen(false);
  };

  const handleFilterActivity = () => {
    setActiveDateRange({ start: new Date(dateRange.start), end: new Date(dateRange.end) });
    setActiveFilterType(filterType);
    setIsActivityVisible(true);
  };

  const filteredFleet = useMemo(() => {
    return fleet.filter(a => {
      const s = searchTerm.toLowerCase();
      return a.kuyrukNo.toLowerCase().includes(s) || a.cagriKodu.toLowerCase().includes(s) || a.konum.toLowerCase().includes(s);
    });
  }, [fleet, searchTerm]);

  const groupedActivities = useMemo(() => {
    const groups: { [type: string]: any[] } = {};
    MOCK_ACTIVITY_GRID.forEach(act => {
      if (activeFilterType !== "Tümü" && act.tip !== activeFilterType) return;
      if (!groups[act.tip]) groups[act.tip] = [];
      groups[act.tip].push(act);
    });
    return groups;
  }, [activeFilterType]);

  if (isSplashVisible) return <SplashScreen onComplete={() => setIsSplashVisible(false)} />;

  return (
    <Layout>
      <div className="flex justify-between items-center mb-10">
         <div className="flex items-center space-x-6">
            {notifications.length > 0 && (
              <div className="bg-red-500/10 border border-red-500/20 px-4 py-2 rounded-xl flex items-center animate-pulse">
                <div className="w-2 h-2 bg-red-500 rounded-full mr-3 shadow-[0_0_10px_rgba(239,68,68,0.5)]"></div>
                <span className="text-red-400 font-black text-[9px] uppercase tracking-[0.3em]">{notifications.length} EXCEL VERİ DEĞİŞİKLİĞİ</span>
              </div>
            )}
         </div>
         <button 
           onClick={() => setIsAdminOpen(true)} 
           className="bg-white/5 hover:bg-white/10 text-white px-8 py-4 rounded-2xl font-black text-[10px] shadow-2xl transition-all border border-white/10 flex items-center uppercase tracking-[0.3em] active:scale-95"
         >
           Yönetici Paneli (Excel Okuyucu)
         </button>
      </div>

      <Dashboard fleet={fleet} />

      {/* 7. BELL-429 -> BİLDİRİMLER PANELİ */}
      {notifications.length > 0 && (
        <div className="mb-12 bg-[#021a0c] p-8 rounded-[2.5rem] border border-red-900/30 shadow-2xl animate-in fade-in duration-500">
           <div className="flex items-center justify-between mb-8 border-b border-red-900/20 pb-4">
              <h3 className="text-red-500 font-black text-xs uppercase tracking-[0.4em] flex items-center">
