/**
 * Apps Script üzerinden tanımlı hücre aralıklarını okur.
 * Google Apps Script Web App CORS sorunlarını aşmak için POST isteği 
 * 'text/plain' content-type ile gönderilir.
 */
export const fetchAircraftDataFromAppsScript = async (url: string, config: SheetConfig): Promise<Partial<Aircraft>[]> => {
  try {
    const response = await fetch(url, {
      method: 'POST',
      mode: 'cors',
      headers: {
        'Content-Type': 'text/plain;charset=utf-8',
      },
      body: JSON.stringify({
        sheetId: config.sheetId,
        mapping: config.mapping
      })
    });

    if (!response.ok) throw new Error(`HTTP Hata: ${response.status}`);

    const data = await response.json();

    if (!Array.isArray(data)) {
      console.warn("Apps Script'ten geçersiz veri formatı geldi:", data);
      return [];
    }

    // Apps Script'ten gelen veriyi Aircraft tipine mapleyelim
    return data.map((item: any) => ({
      kuyrukNo: item.kuyrukNo,
      cagriKodu: item.cagriKodu || `ORMAN-${item.kuyrukNo?.split('-')[1] || 'XX'}`,
      durum: item.durum === 'FAAL' ? Status.FAAL : Status.GAYRI_FAAL,
      durumTipi: item.durumAyrintisi ? StatusType.BAKIM : StatusType.NONE,
      durumAyrintisi: item.durumAyrintisi || '-',
      konum: item.konum || 'ANKARA',
      faydaliSaat: parseInt(item.faydaliSaat) || 0,
      aciklama: item.aciklama || '',
      guncellemeTarihi: new Date().toLocaleString('tr-TR', { day: '2-digit', month: '2-digit', year: 'numeric', hour: '2-digit', minute: '2-digit' }),
      durumBaslangic: new Date().toISOString().split('T')[0],
      maintenanceHours: [{ bakimTuru: 'PERİYODİK', kalanSaat: parseInt(item.faydaliSaat) || 0 }],
      photos: [`https://picsum.photos/seed/${item.kuyrukNo || 'aircraft'}/800/600`]
    }));
  } catch (error) {
    console.error("Sheet read error (Failed to fetch):", error);
    // Hata durumunda boş dizi dönerek uygulamanın çökmesini önle
    return [];
  }
};

