"Sayfa okuma hatası (Veri alma başarısız oldu):" "Veri alma başarısız oldu" bunu çöz birde açılrıken direk otomatik olarak çözüsn eğer ki komut.js de eklenmesi greken bir şey varsa tekrar yaz function doGet(e) {
  // Hata Ayıklama Yardımı: Eğer editörden çalıştırılırsa e tanımsızdır
  if (!e || !e.parameter) {
    return ContentService.createTextOutput(JSON.stringify({
      error: "Hata: Script doğrudan çalıştırılamaz. Lütfen 'Web Uygulaması' olarak dağıtın ve URL'yi uygulamaya yapıştırın."
    })).setMimeType(ContentService.MimeType.JSON);
  }

  const id = e.parameter.id;
  const sheetName = e.parameter.sheet;

  if (!id) return ContentService.createTextOutput(JSON.stringify({error: "Spreadsheet ID bulunamadı."})).setMimeType(ContentService.MimeType.JSON);

  try {
    const ss = SpreadsheetApp.openById(id);
    const sheet = sheetName ? ss.getSheetByName(sheetName) : ss.getSheets()[0];
    if (!sheet) throw new Error("Sayfa bulunamadı: " + sheetName);

    const data = sheet.getDataRange().getValues();
    if (data.length === 0) throw new Error("Sayfa boş.");

    const headers = data[0].map(h => h.toString().trim());
    const rows = data.slice(1).map(row => {
      let obj = {};
      headers.forEach((h, i) => { if (h) obj[h] = row[i]; });
      return obj;
    });

    return ContentService.createTextOutput(JSON.stringify({
      sheetNames: ss.getSheets().map(s => s.getName()),
      headers: headers,
      data: rows
    })).setMimeType(ContentService.MimeType.JSON);
  } catch (err) {
    return ContentService.createTextOutput(JSON.stringify({error: err.toString()})).setMimeType(ContentService.MimeType.JSON);
  }
}

Bu hatanın temel sebebi, paylaştığınız Google Apps Script kodunun sadece `doGet` (sadece tarayıcıdan URL ile çağrılabilen) fonksiyonunu içermesi, ancak uygulamanın veri göndermek için `POST` yöntemini kullanmasıdır. Ayrıca CORS (erişim engeli) sorunlarını aşmak için Apps Script tarafında özel bir yapılandırma gereklidir.

Aşağıdaki güncellemeler ile hem bağlantı hatasını çözüyoruz hem de açılışta verilerin otomatik olarak yüklenmesini garanti altına alıyoruz.

### Önemli: Google Apps Script Kodunuzu Güncelleyin
Lütfen Google Apps Script düzenleyicinizi açın ve mevcut kodunuzun tamamını silip **aşağıdaki kodu yapıştırın**, ardından **Yeni Dağıtım (New Deployment)** diyerek "Herkes (Anyone)" seçeneğiyle tekrar yayınlayın:

```javascript
function doPost(e) {
  try {
    var contents = JSON.parse(e.postData.contents);
    var ss = SpreadsheetApp.openById(contents.sheetId);
    var sheet = ss.getSheets()[0];
    var mapping = contents.mapping;

    function getRangeValues(rangeStr) {
      if (!rangeStr) return [];
      return sheet.getRange(rangeStr).getValues().map(function(row) { return row[0]; });
    }

    var kuyrukNos = getRangeValues(mapping.kuyrukNo);
    var durumlar = getRangeValues(mapping.durum);
    var durumAyrintilari = getRangeValues(mapping.durumAyrintisi);
    var konumlar = getRangeValues(mapping.konum);
    var faydaliSaatler = getRangeValues(mapping.faydaliSaat);
    var aciklamalar = getRangeValues(mapping.aciklama);

    var results = [];
    for (var i = 0; i < kuyrukNos.length; i++) {
      if (kuyrukNos[i]) {
        results.push({
          kuyrukNo: String(kuyrukNos[i]),
          durum: String(durumlar[i] || ""),
          durumAyrintisi: String(durumAyrintilari[i] || ""),
          konum: String(konumlar[i] || ""),
          faydaliSaat: String(faydaliSaatler[i] || "0"),
          aciklama: String(aciklamalar[i] || "")
        });
      }
    }

    return ContentService.createTextOutput(JSON.stringify(results))
      .setMimeType(ContentService.MimeType.JSON);
  } catch (err) {
    return ContentService.createTextOutput(JSON.stringify({ error: err.toString() }))
      .setMimeType(ContentService.MimeType.JSON);
  }
}

