import { SheetConfig, Aircraft, Status, StatusType } from '../types';

/**
 * Apps Script üzerinden tanımlı hücre aralıklarını okur.
 * Google Apps Script Web App CORS sorunlarını (Failed to fetch) aşmak için 
 * POST isteği 'text/plain' content-type ile gönderilir.
 */
export const fetchAircraftDataFromAppsScript = async (url: string, config: SheetConfig): Promise<Partial<Aircraft>[]> => {
  try {
    const response = await fetch(url, {
      method: 'POST',
      mode: 'no-cors', // Apps Script redirect'leri için bazen gereklidir ancak 'cors' + 'text/plain' daha stabildir
      headers: {
        'Content-Type': 'text/plain;charset=utf-8',
      },
      body: JSON.stringify({
        sheetId: config.sheetId,
        mapping: config.mapping
      })
    });

    // Not: mode 'no-cors' kullanıldığında response.json() okunamayabilir. 
    // Bu yüzden standart cors modunda text/plain gönderiyoruz.
    const standardResponse = await fetch(url, {
      method: 'POST',
      headers: { 'Content-Type': 'text/plain;charset=utf-8' },
      body: JSON.stringify({
        sheetId: config.sheetId,
        mapping: config.mapping
      })
    });

    const data = await standardResponse.json();

    if (data.error) {
      console.error("Apps Script Hatası:", data.error);
      return [];
    }

    if (!Array.isArray(data)) return [];

    return data.map((item: any) => ({
      kuyrukNo: String(item.kuyrukNo || '').trim(),
      cagriKodu: `ORMAN-${String(item.kuyrukNo || '').split('-')[1] || 'XX'}`,
      durum: String(item.durum).toUpperCase().includes('FAAL') && !String(item.durum).toUpperCase().includes('GAYRI') ? Status.FAAL : Status.GAYRI_FAAL,
      durumTipi: item.durumAyrintisi ? StatusType.BAKIM : StatusType.NONE,
      durumAyrintisi: String(item.durumAyrintisi || '-'),
      konum: String(item.konum || 'BİLİNMİYOR'),
      faydaliSaat: parseInt(item.faydaliSaat) || 0,
      aciklama: String(item.aciklama || ''),
      guncellemeTarihi: new Date().toLocaleString('tr-TR'),
      durumBaslangic: new Date().toISOString().split('T')[0],
      maintenanceHours: [{ bakimTuru: 'PERİYODİK', kalanSaat: parseInt(item.faydaliSaat) || 0 }],
      photos: [`https://picsum.photos/seed/${item.kuyrukNo}/800/600`],
      platformTipi: 'H',
      tip: 'Bell-429'
    }));
  } catch (error) {
    console.error("Sheet read error:", error);
    return [];
  }
};

