  const autoAssignCode = (item: any): DailyStatusCode => {
    const text = `${item.durum} ${item.durumAyrintisi} ${item.aciklama}`.toLowerCase();
    if (text.includes('kaza') || text.includes('kırım')) return 'KK';
    if (text.includes('parça bekler')) return 'PB';
    if (text.includes('bakım') || text.includes('periyodik')) return text.includes('bekle') ? 'BB' : 'B';
    if (text.includes('arıza')) return 'A';
