import React, { useState, useMemo, useEffect } from 'react';
import Layout from './components/Layout';
import Dashboard from './components/Dashboard';
import AircraftDetailModal from './components/AircraftDetailModal';
import MaintenanceForm from './components/MaintenanceForm';
import ActivityGrid from './components/ActivityGrid';
import SplashScreen from './components/SplashScreen';
import AdminPanel from './components/AdminPanel';
import { MOCK_ACTIVITY_GRID } from './constants';
import { Aircraft, Status, SheetConfig, AppNotification, SnapshotPreview, DailyStatusCode } from './types';
import { fetchAircraftDataFromAppsScript } from './services/sheetService';

const App: React.FC = () => {
  const [isSplashVisible, setIsSplashVisible] = useState(true);
  const [isAdminOpen, setIsAdminOpen] = useState(false);
  const [isActivityVisible, setIsActivityVisible] = useState(false);

  // Filo verisi başlangıçta boştur, sadece Excel'den gelenle dolar.
  const [fleet, setFleet] = useState<Aircraft[]>([]);

  const [selectedAircraft, setSelectedAircraft] = useState<Aircraft | null>(null);
  const [editingAircraft, setEditingAircraft] = useState<Aircraft | null>(null);
  const [searchTerm, setSearchTerm] = useState('');

  const [notifications, setNotifications] = useState<AppNotification[]>([]);
  const [snapshotPreviews, setSnapshotPreviews] = useState<SnapshotPreview[]>([]);
  const [isSnapshotModalOpen, setIsSnapshotModalOpen] = useState(false);

  // GÜNCEL APPS SCRIPT URL
  const APPS_SCRIPT_URL = "https://script.google.com/macros/s/AKfycbzt9ukLiMIWNIQKzHJvw74HaEM28zBHfYao9kbv-g5zb5QxaMUS1UaH45jONA0BeMZr/exec";

  // AÇILIŞTA OTOMATİK SENKRONİZASYON
  useEffect(() => {
    const autoSync = async () => {
      // Talep edilen row 3 mapping
      const defaultMapping = {
        kuyrukNo: 'A3:A8',
        durum: 'M3:M8',
        durumAyrintisi: 'N3:N8',
        konum: 'L3:L8',
        faydaliSaat: 'I3:I8',
        aciklama: 'O3:O8'
      };

      const defaultConfig: SheetConfig = {
        aircraftType: 'Bell-429',
        sheetId: '1D83TF8K1QG30kBv2sCqnPCMYsdSbaJfcsw-E3S5A9VQ',
        appsScriptUrl: APPS_SCRIPT_URL,
        mapping: defaultMapping
      };

      try {
        const data = await fetchAircraftDataFromAppsScript(APPS_SCRIPT_URL, defaultConfig);
        if (data && data.length > 0) {
          handleSyncFromExcel([defaultConfig], data, true);
        }
      } catch (e) {
        console.error("Otomatik başlangıç senkronizasyonu başarısız:", e);
      }
    };

    if (!isSplashVisible) {
      autoSync();
    }
  }, [isSplashVisible]);

  const determineStatusCode = (a: any): { code: DailyStatusCode, gerekce: string } => {
    // Eğer veride zaten atanmış bir kod varsa onu kullan (AdminPanel'den gelmişse)
    if (a.assignedCode) return { code: a.assignedCode, gerekce: 'Manuel/Otomatik Kod Ataması' };

    const fullText = `${a.durum || ''} ${a.durumAyrintisi || ''} ${a.aciklama || ''}`.toLowerCase();
    if (fullText.includes('kaza') || fullText.includes('kırım')) return { code: 'KK', gerekce: 'Kaza/Kırım tespiti' };
    if (fullText.includes('parça bekler') || fullText.includes('yedek parça')) return { code: 'PB', gerekce: 'Parça Bekler tespiti' };
    if (fullText.includes('bakım') || fullText.includes('periyodik') || fullText.includes('200h')) {
      return fullText.includes('bekle') ? { code: 'BB', gerekce: 'Bakım Bekler' } : { code: 'B', gerekce: 'Bakım' };
    }
    if (fullText.includes('arıza') || fullText.includes('fault')) return { code: 'A', gerekce: 'Arıza tespiti' };
    if (fullText.includes('kabul') || fullText.includes('muayene')) return { code: 'KM', gerekce: 'Kabul Muayenesi' };
    return { code: 'X', gerekce: 'Belirlenemedi' };
  };

  const handleSyncFromExcel = (configs: SheetConfig[], incomingData: Partial<Aircraft>[], silent: boolean = false) => {
    let newNotifications: AppNotification[] = [];
    const currentFleet = [...fleet];

    const updatedFleet = incomingData.map(incoming => {
      const existing = currentFleet.find(a => a.kuyrukNo === incoming.kuyrukNo);

      if (existing && !silent) {
        const columns: (keyof Aircraft)[] = ['durum', 'durumAyrintisi', 'konum', 'faydaliSaat', 'aciklama'];
        columns.forEach(col => {
          if (String(existing[col]) !== String(incoming[col])) {
            newNotifications.push({
              id: Math.random().toString(36).substr(2, 9),
              platform: 'Bell-429',
              kuyrukNo: existing.kuyrukNo,
              kolon: col.toUpperCase(),
              oncekiDeger: String(existing[col]),
              yeniDeger: String(incoming[col]),
              mesaj: `${existing.kuyrukNo} güncellendi.`,
              tarih: new Date().toLocaleString('tr-TR')
            });
          }
        });
      }
      return { ...(existing || {}), ...incoming } as Aircraft;
    });

    setFleet(updatedFleet);
    if (!silent) {
      setNotifications(prev => [...newNotifications, ...prev]);
      // Artık Snapshot modalları AdminPanel içinde halledildiği için burada 
      // isterseniz ek bildirim verebilirsiniz, şimdilik sessizce güncelliyoruz.
    }
  };

  const filteredFleet = useMemo(() => {
    return fleet.filter(a => {
      const s = searchTerm.toLowerCase();
      return a.kuyrukNo.toLowerCase().includes(s) || a.konum.toLowerCase().includes(s);
    });
  }, [fleet, searchTerm]);

  if (isSplashVisible) return <SplashScreen onComplete={() => setIsSplashVisible(false)} />;

  return (
    <Layout>
      <div className="flex justify-between items-center mb-10">
         <div className="flex items-center space-x-6">
            {notifications.length > 0 && (
              <div className="bg-red-500/10 border border-red-500/20 px-4 py-2 rounded-xl flex items-center animate-pulse">
                <div className="w-2 h-2 bg-red-500 rounded-full mr-3"></div>
                <span className="text-red-400 font-black text-[9px] uppercase tracking-[0.3em]">{notifications.length} VERİ GÜNCELLEMESİ</span>
              </div>
            )}
         </div>
         <button onClick={() => setIsAdminOpen(true)} className="bg-white/5 hover:bg-white/10 text-white px-8 py-4 rounded-2xl font-black text-[10px] border border-white/10 uppercase tracking-[0.3em] transition-all shadow-2xl">Yönetici Paneli</button>
      </div>

      <Dashboard fleet={fleet} />

      {notifications.length > 0 && (
        <div className="mb-12 bg-[#021a0c] p-8 rounded-[2.5rem] border border-red-900/30 shadow-2xl">
           <div className="flex items-center justify-between mb-8 border-b border-red-900/20 pb-4">
              <h3 className="text-red-500 font-black text-xs uppercase tracking-[0.4em]">DEĞİŞİKLİK BİLDİRİMLERİ</h3>
              <button onClick={() => setNotifications([])} className="text-gray-600 text-[9px] font-black uppercase hover:text-white">TEMİZLE</button>
           </div>
           <div className="space-y-4 max-h-[300px] overflow-y-auto scrollbar-hide">
              {notifications.map(n => (
                <div key={n.id} className="bg-black/40 p-4 rounded-xl border border-white/5 flex justify-between items-center">
                   <div>
                      <div className="text-[10px] font-black text-white uppercase tracking-widest">KUYRUK: <span className="text-emerald-400">{n.kuyrukNo}</span></div>
                      <p className="text-[11px] text-gray-400 mt-1">
                        <span className="text-gray-500 font-black">{n.kolon}:</span> "{n.oncekiDeger}" → <span className="text-emerald-500 font-black">"{n.yeniDeger}"</span>
                      </p>
                   </div>
                   <span className="text-[8px] font-black text-gray-600 uppercase">{n.tarih}</span>
                </div>
              ))}
           </div>
        </div>
      )}

      <div className="mb-20">
        <div className="flex justify-between items-end mb-8 px-2">
           <div>
              <h3 className="text-2xl font-black text-white uppercase tracking-tighter">HAVA ARACI DURUM ÖZETLERİ</h3>
              <p className="text-emerald-500 text-[10px] font-bold uppercase tracking-[0.4em] mt-1">Sistem Genel Çizelge Görünümü</p>
           </div>
           <input 
             type="text" placeholder="Ara..." value={searchTerm} onChange={(e) => setSearchTerm(e.target.value)} 
             className="w-80 px-6 py-4 bg-black/40 text-white rounded-2xl border border-green-800/50 outline-none font-bold text-xs focus:border-emerald-400 shadow-2xl transition-all" 
           />
        </div>

        <div className="bg-white p-1 rounded-[2.5rem] shadow-2xl overflow-hidden border-4 border-white">
          <table className="w-full border-collapse">
            <thead>
              <tr className="bg-slate-50 border-b-2 border-slate-100">
                <th className="px-6 py-5 text-left text-[10px] font-black text-slate-400 uppercase tracking-widest">KUYRUK NO</th>
                <th className="px-6 py-5 text-center text-[10px] font-black text-slate-400 uppercase tracking-widest">DURUM</th>
                <th className="px-6 py-5 text-left text-[10px] font-black text-slate-400 uppercase tracking-widest">AYRINTI</th>
                <th className="px-6 py-5 text-left text-[10px] font-black text-slate-400 uppercase tracking-widest">KONUM</th>
                <th className="px-6 py-5 text-center text-[10px] font-black text-slate-400 uppercase tracking-widest">SAAT</th>
                <th className="px-6 py-5 text-left text-[10px] font-black text-slate-400 uppercase tracking-widest">AÇIKLAMA</th>
              </tr>
            </thead>
            <tbody className="divide-y divide-slate-100">
              {filteredFleet.map((a, i) => (
                <tr key={i} className="hover:bg-slate-50 cursor-pointer transition-colors" onClick={() => setSelectedAircraft(a)}>
                  <td className="px-6 py-5 text-sm font-bold text-emerald-700">{a.kuyrukNo}</td>
                  <td className="px-6 py-5 text-center">
                    <span className={`px-4 py-2 rounded-xl font-black text-[9px] uppercase border-2 ${a.durum === Status.FAAL ? 'bg-emerald-50 text-emerald-700 border-emerald-200' : 'bg-red-50 text-red-700 border-red-200'}`}>
                      {a.durum}
                    </span>
                  </td>
                  <td className="px-6 py-5 text-[11px] font-bold text-slate-600">{a.durumAyrintisi}</td>
                  <td className="px-6 py-5 text-[11px] font-black text-slate-800 uppercase">{a.konum}</td>
                  <td className="px-6 py-5 text-center font-black text-lg text-blue-600 tabular-nums">{a.faydaliSaat}</td>
                  <td className="px-6 py-5 italic text-slate-400 text-[10px] truncate max-w-xs">{a.aciklama}</td>
                </tr>
              ))}
              {filteredFleet.length === 0 && (
                <tr><td colSpan={6} className="py-20 text-center text-slate-300 font-black uppercase text-[10px] tracking-[0.5em]">Veri Yükleniyor veya Bulunamadı...</td></tr>
              )}
            </tbody>
          </table>
        </div>
      </div>

      {selectedAircraft && <AircraftDetailModal aircraft={selectedAircraft} onClose={() => setSelectedAircraft(null)} />}
      {isAdminOpen && <AdminPanel onSave={handleSyncFromExcel} onClose={() => setIsAdminOpen(false)} />}
    </Layout>
  );
};

