import React, { useState, useEffect } from 'react';
import { SheetConfig, SheetMapping, Aircraft, Status, StatusType, DailyStatusCode } from '../types';
import { fetchAircraftDataFromAppsScript } from '../services/sheetService';

interface AdminPanelProps {
  onSave: (configs: SheetConfig[], data: Partial<Aircraft>[]) => void;
  onClose: () => void;
}

const AdminPanel: React.FC<AdminPanelProps> = ({ onSave, onClose }) => {
  const [activeSubTab, setActiveSubTab] = useState('excel'); // 'excel' | 'calendar'
  const [previewData, setPreviewData] = useState<any[]>([]);
  const [isLoading, setIsLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [isConfirmingTransfer, setIsConfirmingTransfer] = useState(false);

  const BELL_429_URL = "https://docs.google.com/spreadsheets/d/1D83TF8K1QG30kBv2sCqnPCMYsdSbaJfcsw-E3S5A9VQ/edit?gid=84538314";
  const APPS_SCRIPT_URL = "https://script.google.com/macros/s/AKfycbzt9ukLiMIWNIQKzHJvw74HaEM28zBHfYao9kbv-g5zb5QxaMUS1UaH45jONA0BeMZr/exec";
  const SHEET_ID = "1D83TF8K1QG30kBv2sCqnPCMYsdSbaJfcsw-E3S5A9VQ";

  // Talep edilen Row 3 mapping
  const [mapping, setMapping] = useState<SheetMapping>({
    kuyrukNo: 'A3:A8',
    durum: 'M3:M8',
    durumAyrintisi: 'N3:N8',
    konum: 'L3:L8',
    faydaliSaat: 'I3:I8',
    aciklama: 'O3:O8'
  });

  const analyzeStatusText = (item: any): { code: DailyStatusCode, interpretation: string } => {
    const detail = String(item.durumAyrintisi || '').toLowerCase();
    const desc = String(item.aciklama || '').toLowerCase();
    const fullText = `${detail} ${desc}`;
    const isGayriFaal = String(item.durum).toUpperCase().includes('GAYRİ') || String(item.durum).toUpperCase().includes('G.FAAL');

    if (!isGayriFaal) return { code: 'F', interpretation: 'Hava aracı operasyonel (FAAL) olarak tespit edildi.' };

    if (fullText.includes('kaza') || fullText.includes('kırım')) 
      return { code: 'KK', interpretation: 'Ciddi hasar/kaza raporu tespit edildi.' };

    if (fullText.includes('parça bekler') || fullText.includes('yedek parça'))
      return { code: 'PB', interpretation: 'Lojistik/Parça tedarik sürecinde.' };

    if (fullText.includes('kabul muayene'))
      return { code: 'KM', interpretation: 'Envanter giriş/kabul muayenesi aşamasında.' };

    if (fullText.includes('bakım bekler'))
      return { code: 'BB', interpretation: 'Bakım planlaması yapılmış, sıra bekliyor.' };

    if (fullText.includes('yıllık') || fullText.includes('periyodik') || fullText.includes('bakım') || fullText.includes('200h'))
      return { code: 'B', interpretation: 'Aktif olarak periyodik bakım/yıllık kontrol sürecinde.' };

    if (fullText.includes('arıza') || fullText.includes('fault'))
      return { code: 'A', interpretation: 'Teknik arıza/faal olmayan durum tespit edildi.' };

    return { code: 'X', interpretation: 'Belirli bir durum kodu eşleşmedi, manuel kontrol önerilir.' };
  };

  const handleRead = async () => {
    setIsLoading(true);
