                 <h3 className="text-3xl font-black text-white uppercase tracking-tighter">GÜNLÜK FAALİYET ÇİZELGESİ</h3>
                 <p className="text-emerald-500 text-[10px] font-black uppercase tracking-[0.5em] mt-2">HAVA ARAÇLARI DURUM TAKİP ÇİZELGESİ</p>
              </div>
