          <div className="mb-12">
            <h2 className="text-white font-black text-xl tracking-tighter uppercase">ADMİN PANELİ</h2>
            <p className="text-green-600 text-[8px] font-black tracking-[0.5em] mt-2">HAVA ARACI YÖNETİMİ</p>
          </div>

          <nav className="space-y-8 flex-grow">
            <div>
              <span className="text-[9px] font-black text-gray-700 uppercase tracking-[0.3em] block mb-4 ml-2">ENVANTER</span>
              <button className="w-full text-left px-5 py-4 rounded-2xl font-black text-[10px] uppercase tracking-widest bg-green-600 text-white shadow-lg transition-all active:scale-95">Bell-429 Filosu</button>
            </div>

            <div className="pl-4 border-l-2 border-green-900/30 space-y-4">
              <button 
                onClick={() => setActiveSubTab('excel')}
                className={`w-full text-left px-4 py-2 font-black text-[9px] uppercase tracking-widest transition-all ${activeSubTab === 'excel' ? 'text-emerald-400 bg-emerald-500/10 rounded-lg translate-x-1' : 'text-gray-500 hover:text-white'}`}
              >
                ● EXCEL VERİ OKUMA
              </button>
              <button 
                onClick={() => setActiveSubTab('calendar')}
                className={`w-full text-left px-4 py-2 font-black text-[9px] uppercase tracking-widest transition-all ${activeSubTab === 'calendar' ? 'text-emerald-400 bg-emerald-500/10 rounded-lg translate-x-1' : 'text-gray-500 hover:text-white'}`}
              >
                ○ TAKVİM ÇİZELGESİ DURUMU
              </button>
            </div>
          </nav>

          <button onClick={onClose} className="py-5 rounded-2xl border border-red-900/30 text-red-500 font-black text-[9px] uppercase tracking-widest hover:bg-red-950 transition-all">PANELİ KAPAT</button>
        </div>

        {/* ANA İÇERİK */}
        <div className="flex-1 flex flex-col overflow-hidden bg-[#052e16]">
          {activeSubTab === 'excel' ? (
            <div className="flex-1 flex flex-col overflow-hidden">
                <div className="p-8 border-b border-green-900/50 bg-[#052e16]/50 flex justify-between items-center">
                  <div className="flex items-center space-x-6">
                    <div className="bg-emerald-500 w-12 h-12 rounded-2xl flex items-center justify-center shadow-lg">
                       <svg className="w-6 h-6 text-white" fill="currentColor" viewBox="0 0 24 24"><path d="M21.17 3.25c.32.1.58.33.73.63.15.3.15.65.15 1.34v13.56c0 .69 0 1.04-.15 1.34-.15.3-.41.53-.73.63-.3.09-.65.09-1.34.09H7.17c-.69 0-1.04 0-1.34-.09-.32-.1-.58-.33-.73-.63-.15-.3-.15-.65-.15-1.34V5.22c0-.69 0-1.04.15-1.34.15-.3.41-.53.73-.63.3-.09.65-.09 1.34-.09h12.66c.69 0 1.04 0 1.34.09ZM8.25 7a.75.75 0 0 0 0 1.5h7.5a.75.75 0 0 0 0-1.5h-7.5Zm0 3.5a.75.75 0 0 0 0 1.5h7.5a.75.75 0 0 0 0-1.5h-7.5Zm0 3.5a.75.75 0 0 0 0 1.5h4.5a.75.75 0 0 0 0-1.5h-4.5Z"/></svg>
                    </div>
                    <div>
                      <h1 className="text-white text-3xl font-black uppercase tracking-tighter">Akıllı Veri Aktarımı</h1>
