import React, { useState, useEffect } from 'react';
import { SheetConfig, SheetMapping, Aircraft, Status, StatusType, DailyStatusCode } from '../types';
import { fetchAircraftDataFromAppsScript } from '../services/sheetService';

interface AdminPanelProps {
  onSave: (configs: SheetConfig[], data: Partial<Aircraft>[]) => void;
  onClose: () => void;
}

const AdminPanel: React.FC<AdminPanelProps> = ({ onSave, onClose }) => {
  const [activeSubTab, setActiveSubTab] = useState('excel'); // 'excel' | 'calendar'
  const [previewData, setPreviewData] = useState<any[]>([]);
  const [isLoading, setIsLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [isConfirmingTransfer, setIsConfirmingTransfer] = useState(false);

  const BELL_429_URL = "https://docs.google.com/spreadsheets/d/1D83TF8K1QG30kBv2sCqnPCMYsdSbaJfcsw-E3S5A9VQ/edit?gid=84538314";
  const APPS_SCRIPT_URL = "https://script.google.com/macros/s/AKfycbzt9ukLiMIWNIQKzHJvw74HaEM28zBHfYao9kbv-g5zb5QxaMUS1UaH45jONA0BeMZr/exec";
  const SHEET_ID = "1D83TF8K1QG30kBv2sCqnPCMYsdSbaJfcsw-E3S5A9VQ";

  const [mapping, setMapping] = useState<SheetMapping>({
    kuyrukNo: 'A3:A8',
    durum: 'M3:M8',
    durumAyrintisi: 'N3:N8',
    konum: 'L3:L8',
    faydaliSaat: 'I3:I8',
    aciklama: 'O3:O8'
  });

  const analyzeStatusText = (item: any): { code: DailyStatusCode, interpretation: string } => {
    const detail = String(item.durumAyrintisi || '').toLocaleLowerCase('tr-TR');
    const desc = String(item.aciklama || '').toLocaleLowerCase('tr-TR');
    const durumStr = String(item.durum || '').toLocaleUpperCase('tr-TR');
    const fullText = `${detail} ${desc}`;

    // KRİTİK DÜZELTME: "GAYRI" ve "GAYRİ" (noktalı/noktasız) varyasyonlarının tamamını kontrol et
    // Eğer durum hücresi (M) içinde "GAYR" veya "G." geçiyorsa gayrı faal kabul et.
    // Ayrıca hücrede "BAKIM" veya "ARIZA" kelimesi geçiyorsa ama "FAAL" yazıyorsa çelişkiyi yakala.
    const isGayriFaalExplicit = durumStr.includes('GAYRİ') || 
                                durumStr.includes('GAYRI') || 
                                durumStr.includes('G.FAAL') || 
                                durumStr.includes('G. FAAL') ||
                                durumStr.includes('GAYRIFAAL') ||
                                (durumStr.includes('FAAL') && durumStr.includes('DEĞİL'));

    // Eğer açıklama kısmında aktif bir süreç varsa ama durum "FAAL" işaretlenmişse sistem şüphelenmeli
    const contextSuggestsGayriFaal = fullText.includes('bakım başladı') || 
                                     fullText.includes('arıza devam') || 
                                     fullText.includes('kaza kırım');

    if (!isGayriFaalExplicit && !contextSuggestsGayriFaal) {
      return { 
        code: 'F', 
        interpretation: 'Sistem Durumu "FAAL" olarak okundu. Hava aracı operasyonel kabul edildi.' 
      };
    }

    // Gayrı Faal ise Detay Analizi
    if (fullText.includes('kaza') || fullText.includes('kırım')) {
      return { code: 'KK', interpretation: 'Analiz: "Kaza/Kırım" anahtar kelimesi tespit edildi. Çizelgeye KK kodu atandı.' };
    }

    if (fullText.includes('bakım bekler')) {
      return { code: 'BB', interpretation: 'Analiz: "Bakım Bekler" ifadesi tespit edildi. Henüz bakıma girmediği anlaşıldı.' };
    }

    if (fullText.includes('yıllık') || fullText.includes('bakım') || fullText.includes('periyodik') || fullText.includes('200h')) {
      return { code: 'B', interpretation: 'Analiz: "Yıllık/Bakım" süreci tespit edildi. Aktif bakım kodu (B) atandı.' };
    }

    if (fullText.includes('kabul muayene')) {
      return { code: 'KM', interpretation: 'Analiz: "Kabul Muayenesi" terimi tespit edildi. Envanter kontrol süreci (KM).' };
    }

    if (fullText.includes('parça bekler') || fullText.includes('yedek parça')) {
      return { code: 'PB', interpretation: 'Analiz: Lojistik bekleme (Parça Bekler) durumu tespit edildi.' };
    }

    if (fullText.includes('arıza') || fullText.includes('fault')) {
      return { code: 'A', interpretation: 'Analiz: "Arıza" anahtar kelimesi tespit edildi. Teknik müdahale gerekiyor.' };
    }

    return { 
      code: 'X', 
      interpretation: 'Analiz: "Gayrı Faal" tespiti yapıldı ancak net bir alt neden bulunamadı. Varsayılan X atandı.' 
    };
  };

  const handleRead = async () => {
    setIsLoading(true);
    setError(null);
    try {
      const results = await fetchAircraftDataFromAppsScript(APPS_SCRIPT_URL, {
        aircraftType: 'Bell-429',
        sheetId: SHEET_ID,
        appsScriptUrl: APPS_SCRIPT_URL,
        mapping
      });

      if (results.length === 0) {
        setError("Excel'den veri çekilemedi. Lütfen bağlantınızı veya Apps Script URL'sini kontrol edin.");
      } else {
        const enriched = results.map(r => {
          const analysis = analyzeStatusText(r);
          return { ...r, assignedCode: analysis.code, aiInterpretation: analysis.interpretation };
        });
        setPreviewData(enriched);
      }
    } catch (e) {
      setError("Bağlantı hatası: Google Apps Script yanıt vermiyor.");
    } finally {
      setIsLoading(false);
    }
  };

  const handleTransfer = () => {
    onSave([{ aircraftType: 'Bell-429', sheetId: SHEET_ID, appsScriptUrl: APPS_SCRIPT_URL, mapping }], previewData);
    onClose();
  };

  const statusCodes: {code: DailyStatusCode, label: string, color: string}[] = [
    { code: 'B', label: 'BAKIM', color: 'bg-[#ffff00]' },
    { code: 'BB', label: 'BAKIM BEKLER', color: 'bg-[#ffff00]' },
    { code: 'KM', label: 'KABUL MUAYENE', color: 'bg-[#ffff00]' },
    { code: 'A', label: 'ARIZA', color: 'bg-[#ff0000] text-white' },
    { code: 'PB', label: 'PARÇA BEKLER', color: 'bg-[#ff0000] text-white' },
    { code: 'KK', label: 'KAZA KIRIM', color: 'bg-[#ff0000] text-white' },
    { code: 'X', label: 'OLMADIĞI GÜN', color: 'bg-[#7030a0] text-white' },
