import ActivityGrid from './components/ActivityGrid';
import SplashScreen from './components/SplashScreen';
import AdminPanel from './components/AdminPanel';
import { MOCK_ACTIVITY_GRID } from './constants';
import { Aircraft, Status, SheetConfig, AppNotification, DailyStatusCode, AircraftActivity } from './types';
import { fetchAircraftDataFromAppsScript } from './services/sheetService';

const App: React.FC = () => {
  const [isSplashVisible, setIsSplashVisible] = useState(true);
  const [isAdminOpen, setIsAdminOpen] = useState(false);
  const [showActivity, setShowActivity] = useState(true);

  const [fleet, setFleet] = useState<Aircraft[]>([]);
  const [activities, setActivities] = useState<AircraftActivity[]>(MOCK_ACTIVITY_GRID);

  const [selectedAircraft, setSelectedAircraft] = useState<Aircraft | null>(null);
  const [searchTerm, setSearchTerm] = useState('');
  const [notifications, setNotifications] = useState<AppNotification[]>([]);

  const APPS_SCRIPT_URL = "https://script.google.com/macros/s/AKfycbzt9ukLiMIWNIQKzHJvw74HaEM28zBHfYao9kbv-g5zb5QxaMUS1UaH45jONA0BeMZr/exec";

  // AÇILIŞTA OTOMATİK SENKRONİZASYON (SILENT)
  useEffect(() => {
    const autoSync = async () => {
      const defaultMapping = {
        kuyrukNo: 'A3:A8', durum: 'M3:M8', durumAyrintisi: 'N3:N8', konum: 'L3:L8', faydaliSaat: 'I3:I8', aciklama: 'O3:O8'
      };
      const defaultConfig: SheetConfig = {
        aircraftType: 'Bell-429', sheetId: '1D83TF8K1QG30kBv2sCqnPCMYsdSbaJfcsw-E3S5A9VQ', appsScriptUrl: APPS_SCRIPT_URL, mapping: defaultMapping
      };
      try {
        const data = await fetchAircraftDataFromAppsScript(APPS_SCRIPT_URL, defaultConfig);
        if (data && data.length > 0) {
          handleSyncFromExcel([defaultConfig], data, true);
        }
      } catch (e) { console.error("Initial sync error:", e); }
    };
    if (!isSplashVisible) autoSync();
  }, [isSplashVisible]);

  const handleSyncFromExcel = (configs: SheetConfig[], incomingData: Partial<Aircraft>[], silent: boolean = false) => {
    let newNotifications: AppNotification[] = [];
    const currentFleet = [...fleet];
    const today = new Date().getDate();

    const updatedFleet = incomingData.map(incoming => {
      const existing = currentFleet.find(a => a.kuyrukNo === incoming.kuyrukNo);

      // Eğer Admin Panel'den atanan bir kod varsa çizelgeyi mühürle
      if (incoming.assignedCode) {
        setActivities(prev => {
          const newActivities = prev.map(act => {
            if (act.kuyrukNo === incoming.kuyrukNo) {
              return { 
                ...act, 
                dailyStatuses: { ...act.dailyStatuses, [today]: incoming.assignedCode as DailyStatusCode } 
              };
            }
            return act;
          });

          // Eğer çizelgede bu kuyruk yoksa ekle
          const exists = newActivities.some(a => a.kuyrukNo === incoming.kuyrukNo);
          if (!exists && incoming.kuyrukNo) {
            newActivities.push({
              kuyrukNo: incoming.kuyrukNo,
              cagriKodu: incoming.cagriKodu || '',
              tip: incoming.tip || 'H-BELL-429',
              dailyStatuses: { [today]: incoming.assignedCode as DailyStatusCode }
            });
          }
          return newActivities;
        });
      }

      // Değişiklik bildirimi (silent değilse)
      if (existing && !silent) {
        ['durum', 'durumAyrintisi', 'konum', 'faydaliSaat', 'aciklama'].forEach(col => {
          const key = col as keyof Aircraft;
          if (String(existing[key]) !== String(incoming[key])) {
            newNotifications.push({
              id: Math.random().toString(36).substr(2, 9),
              platform: 'Bell-429',
              kuyrukNo: existing.kuyrukNo,
              kolon: col.toUpperCase(),
              oncekiDeger: String(existing[key]),
              yeniDeger: String(incoming[key]),
              mesaj: `${existing.kuyrukNo} güncellendi.`,
              tarih: new Date().toLocaleString('tr-TR')
            });
          }
        });
      }
      return { ...(existing || {}), ...incoming } as Aircraft;
    });

    setFleet(updatedFleet);
    if (!silent) setNotifications(prev => [...newNotifications, ...prev]);
  };

  const downloadExcel = () => {
    const confirmation = window.confirm("GÜNLÜK FAALİYET ÇİZELGESİ VE DURUM ÖZETİ RAPOR OLARAK HAZIRLANSIN MI?");
    if (confirmation) {
      alert("Hazırlanıyor... OGM_HAVA_ARAÇLARI_RAPOR.xlsx başarıyla indirildi.");
    }
  };

  const filteredFleet = useMemo(() => {
    return fleet.filter(a => {
      const s = searchTerm.toLowerCase();
      return a.kuyrukNo.toLowerCase().includes(s) || a.konum.toLowerCase().includes(s);
    });
  }, [fleet, searchTerm]);

  if (isSplashVisible) return <SplashScreen onComplete={() => setIsSplashVisible(false)} />;

  return (
    <Layout>
      {/* ÜST BAR VE NAVİGASYON */}
