            </div>
            {notifications.length > 0 && (
              <div className="bg-red-500/10 border border-red-500/30 px-6 py-4 rounded-[1.5rem] flex items-center animate-bounce">
                <span className="text-red-400 font-black text-[10px] uppercase tracking-[0.4em]">{notifications.length} DEĞİŞİKLİK</span>
              </div>
            )}
         </div>
         <div className="flex space-x-6">
            <button 
              onClick={() => setShowActivity(!showActivity)} 
              className={`px-10 py-5 rounded-[1.5rem] font-black text-[11px] uppercase tracking-[0.4em] transition-all shadow-2xl border-2 ${showActivity ? 'bg-blue-600 text-white border-blue-500' : 'bg-white/10 text-white border-white/20'}`}
            >
              {showActivity ? "ÖZET TABLOYU GÖSTER" : "FAALİYET ÇİZELGESİ"}
            </button>
            <button 
              onClick={() => setIsAdminOpen(true)} 
              className="bg-white/5 hover:bg-white/15 text-white px-10 py-5 rounded-[1.5rem] font-black text-[11px] border-2 border-white/10 uppercase tracking-[0.4em] transition-all"
            >
              YÖNETİM PANELİ
            </button>
         </div>
      </div>

      {/* DURUM ÖZETİ (DASHBOARD) - Her Zaman Görünür */}
      <div className="mb-12">
         <div className="flex items-center mb-6 px-4">
            <h3 className="text-white font-black text-xs uppercase tracking-[0.5em]">GÜNCEL FİLO DURUM ÖZETİ</h3>
            <div className="flex-grow h-px bg-green-900/30 ml-6"></div>
         </div>
         <Dashboard fleet={fleet} />
      </div>

      {/* ANA İÇERİK: ÇİZELGE VEYA TABLO */}
      {showActivity ? (
        <div className="mb-20 animate-in fade-in slide-in-from-top-6 duration-1000">
           <div className="flex justify-between items-end mb-10 px-6">
              <div>
                 <h3 className="text-4xl font-black text-white uppercase tracking-tighter italic">FAALİYET ÇİZELGESİ (MATRİS)</h3>
