                <svg className="w-5 h-5 mr-4" fill="currentColor" viewBox="0 0 24 24"><path d="M12 16l-5-5h3V4h4v7h3l-5 5zm9 4H3v-2h18v2z"/></svg>
                TAM RAPOR İNDİR
              </button>
           </div>
           <div className="bg-white rounded-[4rem] p-3 shadow-[0_40px_100px_rgba(0,0,0,0.6)] border-[6px] border-white overflow-hidden">
             <ActivityGrid 
