import React, { useState, useMemo, useEffect } from 'react';
import Layout from './components/Layout';
import Dashboard from './components/Dashboard';
import AircraftDetailModal from './components/AircraftDetailModal';
import ActivityGrid from './components/ActivityGrid';
import SplashScreen from './components/SplashScreen';
import AdminPanel from './components/AdminPanel';
import { MOCK_ACTIVITY_GRID } from './constants';
import { Aircraft, Status, SheetConfig, AppNotification, DailyStatusCode, AircraftActivity } from './types';
import { fetchAircraftDataFromAppsScript } from './services/sheetService';

const App: React.FC = () => {
  const [isSplashVisible, setIsSplashVisible] = useState(true);
  const [isAdminOpen, setIsAdminOpen] = useState(false);
  const [showActivity, setShowActivity] = useState(true);

  // Fleet (Durum Bankası) ve Activities (Faaliyet Çizelgesi) eyaletleri
  const [fleet, setFleet] = useState<Aircraft[]>([]);
  const [activities, setActivities] = useState<AircraftActivity[]>(MOCK_ACTIVITY_GRID);

  const [selectedAircraft, setSelectedAircraft] = useState<Aircraft | null>(null);
  const [searchTerm, setSearchTerm] = useState('');
  const [notifications, setNotifications] = useState<AppNotification[]>([]);

  const APPS_SCRIPT_URL = "https://script.google.com/macros/s/AKfycbzt9ukLiMIWNIQKzHJvw74HaEM28zBHfYao9kbv-g5zb5QxaMUS1UaH45jONA0BeMZr/exec";

  // Uygulama açıldığında Excel'den son verileri çek (Sessiz Senkronizasyon)
  useEffect(() => {
    const autoSync = async () => {
      const defaultMapping = {
        kuyrukNo: 'A3:A8', durum: 'M3:M8', durumAyrintisi: 'N3:N8', konum: 'L3:L8', faydaliSaat: 'I3:I8', aciklama: 'O3:O8'
      };
      const defaultConfig: SheetConfig = {
        aircraftType: 'Bell-429', sheetId: '1D83TF8K1QG30kBv2sCqnPCMYsdSbaJfcsw-E3S5A9VQ', appsScriptUrl: APPS_SCRIPT_URL, mapping: defaultMapping
      };
      try {
        const data = await fetchAircraftDataFromAppsScript(APPS_SCRIPT_URL, defaultConfig);
        if (data && data.length > 0) {
          handleSyncFromExcel([defaultConfig], data, true);
        }
