      // Admin panelinde analiz edilip onaylanan 'assignedCode' (B, A, F vb.) bugün için matrise işlenir.
      if (incoming.assignedCode) {
        setActivities(prev => {
          let updated = prev.map(act => {
            if (act.kuyrukNo === incoming.kuyrukNo) {
              return { 
                ...act, 
                dailyStatuses: { ...act.dailyStatuses, [today]: incoming.assignedCode as DailyStatusCode } 
              };
            }
            return act;
          });

          // Eğer bu uçak matriste henüz yoksa yeni bir satır olarak ekle
          if (!updated.some(a => a.kuyrukNo === incoming.kuyrukNo)) {
            updated.push({
              kuyrukNo: incoming.kuyrukNo || '',
              cagriKodu: incoming.cagriKodu || `ORMAN-${incoming.kuyrukNo?.split('-')[1] || 'XX'}`,
              tip: incoming.tip || 'Bell-429',
              dailyStatuses: { [today]: incoming.assignedCode as DailyStatusCode }
            });
          }
          return updated;
        });
      }

      // Değişiklik bildirimlerini yakala
      if (existing && !silent) {
        ['durum', 'konum', 'aciklama'].forEach(col => {
          const key = col as keyof Aircraft;
          if (String(existing[key]) !== String(incoming[key])) {
            newNotifications.push({
              id: Math.random().toString(36).substr(2, 9),
              platform: 'Bell-429',
              kuyrukNo: existing.kuyrukNo,
              kolon: col.toUpperCase(),
              oncekiDeger: String(existing[key]),
              yeniDeger: String(incoming[key]),
              mesaj: `${existing.kuyrukNo} verisi değişti.`,
              tarih: new Date().toLocaleString('tr-TR')
            });
          }
        });
      }
      return { ...(existing || {}), ...incoming } as Aircraft;
    });

    setFleet(updatedFleet);
    if (!silent) setNotifications(prev => [...newNotifications, ...prev]);
  };

  const downloadExcel = () => {
    alert("Excel raporu hazırlanıyor... Tüm analizler ve çizelge verileri dışa aktarılıyor.");
  };

  const filteredFleet = useMemo(() => {
    return fleet.filter(a => {
      const s = searchTerm.toLowerCase();
      return a.kuyrukNo.toLowerCase().includes(s) || a.konum.toLowerCase().includes(s);
    });
  }, [fleet, searchTerm]);

  if (isSplashVisible) return <SplashScreen onComplete={() => setIsSplashVisible(false)} />;

  return (
    <Layout>
      {/* ÜST KONTROL PANELİ */}
      <div className="flex justify-between items-center mb-12">
         <div className="flex items-center space-x-6">
            <div className="bg-emerald-500/10 border border-emerald-500/30 px-6 py-4 rounded-[1.8rem] flex items-center shadow-2xl backdrop-blur-md">
               <div className="w-3 h-3 bg-emerald-500 rounded-full mr-4 animate-pulse"></div>
               <span className="text-emerald-400 font-black text-[11px] uppercase tracking-[0.5em]">AKILLI ANALİZ SİSTEMİ AKTİF</span>
            </div>
            {notifications.length > 0 && (
              <div className="bg-orange-500/10 border border-orange-500/30 px-6 py-4 rounded-[1.8rem] flex items-center shadow-lg">
                <span className="text-orange-400 font-black text-[10px] uppercase tracking-[0.3em]">{notifications.length} VERİ GÜNCELLEMESİ</span>
              </div>
            )}
         </div>
         <div className="flex space-x-5">
            <button 
              onClick={() => setShowActivity(!showActivity)} 
              className={`px-10 py-5 rounded-[1.8rem] font-black text-[11px] uppercase tracking-[0.4em] transition-all shadow-2xl border-2 ${showActivity ? 'bg-blue-600 text-white border-blue-500' : 'bg-white/10 text-white border-white/20'}`}
            >
              {showActivity ? "DURUM BANKASINA GEÇ" : "FAALİYET ÇİZELGESİNE GEÇ"}
            </button>
            <button 
              onClick={() => setIsAdminOpen(true)} 
              className="bg-white/5 hover:bg-white/15 text-white px-10 py-5 rounded-[1.8rem] font-black text-[11px] border-2 border-white/10 uppercase tracking-[0.4em] transition-all"
            >
              YÖNETİM PANELİ
            </button>
         </div>
      </div>

      {/* DASHBOARD (DURUM ÖZETİ) */}
      <div className="mb-14">
         <div className="flex items-center mb-8 px-4">
            <h3 className="text-white font-black text-xs uppercase tracking-[0.6em]">GENEL FİLO İSTATİSTİKLERİ</h3>
            <div className="flex-grow h-px bg-white/10 ml-8"></div>
         </div>
         <Dashboard fleet={fleet} />
      </div>

      {/* ANA GÖRÜNÜM: FAALİYET ÇİZELGESİ (MATRİS) */}
      {showActivity ? (
        <div className="mb-24 animate-in fade-in slide-in-from-top-10 duration-1000">
           <div className="flex justify-between items-end mb-12 px-6">
              <div>
                 <h2 className="text-5xl font-black text-white uppercase tracking-tighter italic">FAALİYET ÇİZELGESİ</h2>
                 <p className="text-emerald-500 text-xs font-black uppercase tracking-[0.7em] mt-4">Analiz Edilmiş ve Mühürlenmiş Günlük Durumlar</p>
              </div>
              <button onClick={downloadExcel} className="bg-emerald-600 hover:bg-emerald-500 text-white px-14 py-6 rounded-[2rem] font-black text-[11px] uppercase tracking-[0.4em] flex items-center transition-all shadow-[0_20px_40px_rgba(16,185,129,0.3)] active:scale-95">
                <svg className="w-5 h-5 mr-4" fill="currentColor" viewBox="0 0 24 24"><path d="M12 16l-5-5h3V4h4v7h3l-5 5zm9 4H3v-2h18v2z"/></svg>
                XLSX RAPORU AL
              </button>
           </div>

           <div className="bg-white rounded-[4.5rem] p-4 shadow-[0_50px_120px_rgba(0,0,0,0.7)] border-[10px] border-white/5 overflow-hidden transition-all hover:border-emerald-500/20">
             <ActivityGrid 
               activities={activities} 
               startDate={new Date(2025, 0, 1)} 
               endDate={new Date(2025, 0, 31)} 
               title="OCAK 2025" 
             />
           </div>

           <div className="mt-12 px-12 flex flex-wrap gap-12 justify-center">
              <div className="flex items-center"><div className="w-7 h-7 bg-[#ffff00] border-2 border-black rounded-xl shadow-lg mr-4"></div><span className="text-white text-[11px] font-black uppercase tracking-[0.2em]">BAKIM (B/BB/KM)</span></div>
              <div className="flex items-center"><div className="w-7 h-7 bg-[#ff0000] border-2 border-black rounded-xl shadow-lg mr-4"></div><span className="text-white text-[11px] font-black uppercase tracking-[0.2em]">ARIZA (A/PB/KK)</span></div>
              <div className="flex items-center"><div className="w-7 h-7 bg-[#7030a0] border-2 border-black rounded-xl shadow-lg mr-4"></div><span className="text-white text-[11px] font-black uppercase tracking-[0.2em]">GÖREV YOK (X)</span></div>
              <div className="flex items-center"><div className="w-7 h-7 bg-white border-2 border-black rounded-xl shadow-lg mr-4"></div><span className="text-white text-[11px] font-black uppercase tracking-[0.2em]">FAAL (F)</span></div>
           </div>
        </div>
      ) : (
        <div className="mb-24 animate-in fade-in slide-in-from-bottom-10 duration-1000">
          <div className="flex justify-between items-end mb-12 px-6">
             <div>
                <h2 className="text-5xl font-black text-white uppercase tracking-tighter italic">DURUM BANKASI</h2>
                <p className="text-emerald-500 text-xs font-black uppercase tracking-[0.7em] mt-4">Detaylı Teknik Envanter Listesi</p>
             </div>
             <div className="relative">
               <input 
                 type="text" placeholder="Hızlı Arama..." value={searchTerm} onChange={(e) => setSearchTerm(e.target.value)} 
                 className="w-[500px] px-12 py-7 bg-black/50 text-white rounded-[2.5rem] border-2 border-white/10 outline-none font-bold text-base focus:border-emerald-500 shadow-2xl transition-all placeholder:text-gray-700" 
               />
               <svg className="w-7 h-7 text-gray-700 absolute right-10 top-7" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path d="M21 21l-6-6m2-5a7 7 0 11-14 0 7 7 0 0114 0z" strokeWidth={3}/></svg>
             </div>
          </div>

          <div className="bg-white p-3 rounded-[4.5rem] shadow-[0_50px_120px_rgba(0,0,0,0.7)] overflow-hidden border-[10px] border-white/5">
            <table className="w-full border-collapse">
              <thead>
                <tr className="bg-slate-50 border-b-2 border-slate-100">
