            >
              {showActivity ? "DURUM BANKASINA GEÇ" : "FAALİYET ÇİZELGESİNE GEÇ"}
            </button>
            <button 
              onClick={() => setIsAdminOpen(true)} 
              className="bg-white/5 hover:bg-white/15 text-white px-10 py-5 rounded-[1.8rem] font-black text-[11px] border-2 border-white/10 uppercase tracking-[0.4em] transition-all"
