         <Dashboard fleet={fleet} />
      </div>

      {/* ANA GÖRÜNÜM: FAALİYET ÇİZELGESİ (SADECE ANALİZ EDİLENLER) */}
      {showActivity ? (
        <div className="mb-24 animate-in fade-in slide-in-from-top-10 duration-1000">
           <div className="flex justify-between items-end mb-12 px-6">
              <div>
                 <h2 className="text-5xl font-black text-white uppercase tracking-tighter italic">FAALİYET ÇİZELGESİ (MATRİS)</h2>
                 <p className="text-emerald-500 text-xs font-black uppercase tracking-[0.7em] mt-4">Durum Bankası Analizlerine Göre Otomatik Oluşturulur</p>
