import React from 'react';
import { AircraftActivity, DailyStatusCode } from '../types';

interface ActivityGridProps {
  activities: AircraftActivity[];
  startDate: Date;
  endDate: Date;
  title: string;
}

const ActivityGrid: React.FC<ActivityGridProps> = ({ activities, startDate, endDate, title }) => {
  const getDaysInRange = (start: Date) => {
    const dates = [];
    const year = start.getFullYear();
    const month = start.getMonth();
    const daysInMonth = new Date(year, month + 1, 0).getDate();

    for (let i = 1; i <= daysInMonth; i++) {
      dates.push(new Date(year, month, i));
    }
    return dates;
  };

  const visibleDates = getDaysInRange(startDate);

  const getStatusClass = (code: DailyStatusCode) => {
    switch (code) {
      case 'B': 
      case 'BB': 
      case 'KM': 
        return 'bg-[#FFFF00] text-black font-black border-black'; // Sarı Grup
      case 'A': 
      case 'PB': 
      case 'KK': 
        return 'bg-[#FF0000] text-white font-black border-black'; // Kırmızı Grup
      case 'X': 
        return 'bg-[#7030A0] text-white font-black border-black'; // Mor Grup
      case 'F': 
        return 'bg-white text-transparent'; // Faal: Boş gözükmeli
      default: 
        return 'bg-white';
    }
  };

  const calculateRowStats = (activity: AircraftActivity) => {
    let bkm = 0, arz = 0, x = 0;
    const days = visibleDates.map(d => d.getDate());

    visibleDates.forEach(date => {
      const day = date.getDate();
      const s = activity.dailyStatuses[day];
      if (['B', 'BB', 'KM'].includes(s)) bkm++;
      else if (['A', 'PB', 'KK'].includes(s)) arz++;
      else if (s === 'X') x++;
    });

    let countedGayriFaalForPercent = 0;
    let currentSequence = [];

    days.forEach(day => {
      const status = activity.dailyStatuses[day] || '';
      const isGFaal = ['B', 'BB', 'KM', 'A', 'PB', 'KK', 'X'].includes(status);

      if (isGFaal) {
        currentSequence.push(day);
      } else {
        if (currentSequence.length >= 3) {
          countedGayriFaalForPercent += currentSequence.length;
        }
        currentSequence = [];
      }
    });

    if (currentSequence.length >= 3) {
      countedGayriFaalForPercent += currentSequence.length;
    }

    const totalDays = visibleDates.length;
    const operationalDaysForPercent = totalDays - countedGayriFaalForPercent;
    const percentage = ((operationalDaysForPercent / totalDays) * 100).toFixed(0);

    const totalGFaal = bkm + arz + x;
    const totalFaal = totalDays - totalGFaal;

    return { bkm, arz, x, totalGFaal, totalFaal, percentage };
  };

  const grandTotals = activities.reduce((acc, act) => {
    const s = calculateRowStats(act);
    return {
      bkm: acc.bkm + s.bkm,
      arz: acc.arz + s.arz,
      x: acc.x + s.x,
      totalGFaal: acc.totalGFaal + s.totalGFaal,
      totalFaal: acc.totalFaal + s.totalFaal
    };
  }, { bkm: 0, arz: 0, x: 0, totalGFaal: 0, totalFaal: 0 });

  if (activities.length === 0) return null;

  return (
    <div className="activity-grid-section mb-6 bg-white p-1">
      <div className="overflow-x-auto">
        <table className="w-full border-collapse border-[2px] border-black text-[10px] font-sans bg-white">
          <thead>
            <tr className="bg-white">
              <th rowSpan={2} className="border border-black px-1 py-1 w-[100px] uppercase font-black">ÇAĞRI KODU</th>
              <th rowSpan={2} className="border border-black px-1 py-1 w-[100px] uppercase font-black">KUYRUK NO</th>
              <th rowSpan={2} className="border border-black px-1 py-1 w-[120px] uppercase font-black">TİP</th>
              {visibleDates.map((date, idx) => (
                <th key={idx} rowSpan={2} className="border border-black w-8 text-center font-bold h-24 relative min-w-[32px]">
                   <div className="absolute inset-0 flex items-center justify-center bg-gray-50/50">
                     <span className="[writing-mode:vertical-lr] rotate-180 whitespace-nowrap text-[9px] font-black tracking-tighter">
                        {date.toLocaleDateString('tr-TR', { day: '2-digit', month: '2-digit', year: 'numeric' })}
                     </span>
                   </div>
                </th>
              ))}
              <th colSpan={3} className="border border-black bg-[#00b0f0] text-white py-1 text-[9px] font-black">TOPLAM G.FAAL</th>
              <th rowSpan={2} className="border border-black bg-[#00b0f0] text-white px-0.5 w-12 text-[9px] font-black">TOPLAM G.FAAL</th>
              <th rowSpan={2} className="border border-black bg-[#ffc000] text-black px-0.5 w-12 text-[9px] font-black">TOPLAM FAAL</th>
              <th rowSpan={2} className="border border-black bg-gray-900 text-white px-0.5 w-14 text-[9px] font-black">VERİM %</th>
            </tr>
            <tr className="bg-white">
              <th className="border border-black bg-[#ffff00] text-black w-10 text-[8px] py-2 font-black uppercase">B/BB/KM</th>
              <th className="border border-black bg-[#ff0000] text-white w-10 text-[8px] py-2 font-black uppercase">A/PB/KK</th>
              <th className="border border-black bg-[#7030a0] text-white w-10 text-[8px] py-2 font-black uppercase">X</th>
            </tr>
          </thead>
          <tbody>
            {activities.map((act, idx) => {
              const s = calculateRowStats(act);
              return (
                <tr key={idx} className="h-8 hover:bg-gray-50 transition-colors">
                  <td className="border border-black text-center font-black px-1 text-emerald-900">{act.cagriKodu}</td>
                  <td className="border border-black text-center font-black px-1">{act.kuyrukNo}</td>
                  <td className="border border-black text-center px-1 uppercase font-bold text-gray-500">{act.tip}</td>
                  {visibleDates.map((date, dIdx) => {
                    const status = act.dailyStatuses[date.getDate()] || '';
                    return (
                      <td key={dIdx} className={`border border-black text-center text-[11px] ${getStatusClass(status)}`}>
                        {status === 'F' ? '' : status}
                      </td>
                    );
                  })}
                  <td className="border border-black text-center font-black bg-[#ffff99]">{s.bkm || '0'}</td>
                  <td className="border border-black text-center font-black bg-[#ff9999]">{s.arz || '0'}</td>
                  <td className="border border-black text-center font-black bg-[#d8d8d8]">{s.x || '0'}</td>
                  <td className="border border-black text-center font-black bg-[#99ccff]">{s.totalGFaal || '0'}</td>
                  <td className="border border-black text-center font-black bg-[#ffffcc]">{s.totalFaal || '0'}</td>
                  <td className="border border-black text-center font-black bg-gray-100 text-[11px]">%{s.percentage}</td>
                </tr>
              );
            })}
            <tr className="bg-white font-black h-8">
              <td colSpan={3} className="border border-black text-right px-4 uppercase text-[10px] bg-slate-50">GENEL TOPLAM</td>
              {visibleDates.map((_, idx) => <td key={idx} className="border border-black bg-slate-50/20"></td>)}
              <td className="border border-black text-center bg-[#ffff00]">{grandTotals.bkm}</td>
              <td className="border border-black text-center bg-[#ff0000] text-white">{grandTotals.arz}</td>
              <td className="border border-black text-center bg-[#7030a0] text-white">{grandTotals.x}</td>
              <td className="border border-black text-center bg-[#00b0f0] text-white">{grandTotals.totalGFaal}</td>
              <td className="border border-black text-center bg-[#ffc000] text-black">{grandTotals.totalFaal}</td>
              <td className="border border-black bg-gray-800"></td>
            </tr>
          </tbody>
        </table>
      </div>
    </div>
  );
};

