import React, { useState, useEffect } from 'react';
import { SheetConfig, SheetMapping, Aircraft, Status, StatusType, DailyStatusCode, AppNotification } from '../types';
import { fetchAircraftDataFromAppsScript } from '../services/sheetService';

interface AdminPanelProps {
  onSave: (configs: SheetConfig[], data: Partial<Aircraft>[]) => void;
  onClose: () => void;
  notifications: AppNotification[];
}

const AdminPanel: React.FC<AdminPanelProps> = ({ onSave, onClose, notifications }) => {
  const [activeSubTab, setActiveSubTab] = useState('excel'); // 'excel' | 'calendar' | 'notifications'
  const [previewData, setPreviewData] = useState<any[]>([]);
  const [isLoading, setIsLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);

  const BELL_429_URL = "https://docs.google.com/spreadsheets/d/1D83TF8K1QG30kBv2sCqnPCMYsdSbaJfcsw-E3S5A9VQ/edit?gid=84538314";
  const APPS_SCRIPT_URL = "https://script.google.com/macros/s/AKfycbzt9ukLiMIWNIQKzHJvw74HaEM28zBHfYao9kbv-g5zb5QxaMUS1UaH45jONA0BeMZr/exec";
  const SHEET_ID = "1D83TF8K1QG30kBv2sCqnPCMYsdSbaJfcsw-E3S5A9VQ";

  const [mapping, setMapping] = useState<SheetMapping>({
    kuyrukNo: 'A3:A8',
    durum: 'M3:M8',
    durumAyrintisi: 'N3:N8',
    konum: 'L3:L8',
    faydaliSaat: 'I3:I8',
    aciklama: 'O3:O8'
  });

  const analyzeStatusText = (item: any): { code: DailyStatusCode, interpretation: string } => {
    const detail = String(item.durumAyrintisi || '').toLocaleLowerCase('tr-TR');
    const desc = String(item.aciklama || '').toLocaleLowerCase('tr-TR');
    const durumStr = String(item.durum || '').toLocaleUpperCase('tr-TR');
    const fullText = `${detail} ${desc}`;

    const isGayriFaalExplicit = durumStr.includes('GAYRİ') || 
                                durumStr.includes('GAYRI') || 
                                durumStr.includes('G.FAAL') || 
                                durumStr.includes('G. FAAL') ||
                                durumStr.includes('GAYRIFAAL') ||
                                (durumStr.includes('FAAL') && durumStr.includes('DEĞİL'));

    const contextSuggestsGayriFaal = fullText.includes('bakım başladı') || 
                                     fullText.includes('arıza devam') || 
                                     fullText.includes('kaza kırım');

    if (!isGayriFaalExplicit && !contextSuggestsGayriFaal) {
      return { code: 'F', interpretation: 'Sistem Durumu "FAAL" olarak okundu.' };
    }

    if (fullText.includes('kaza') || fullText.includes('kırım')) return { code: 'KK', interpretation: 'Analiz: Kaza/Kırım tespit edildi.' };
    if (fullText.includes('bakım bekler')) return { code: 'BB', interpretation: 'Analiz: Bakım Bekler tespiti.' };
    if (fullText.includes('yıllık') || fullText.includes('bakım') || fullText.includes('periyodik') || fullText.includes('200h')) return { code: 'B', interpretation: 'Analiz: Bakım süreci tespiti.' };
    if (fullText.includes('kabul muayene')) return { code: 'KM', interpretation: 'Analiz: Kabul Muayenesi tespiti.' };
    if (fullText.includes('parça bekler')) return { code: 'PB', interpretation: 'Analiz: Parça Bekleme tespiti.' };
    if (fullText.includes('arıza')) return { code: 'A', interpretation: 'Analiz: Arıza tespiti.' };

    return { code: 'X', interpretation: 'Analiz: Gayrı Faal (Belirsiz Neden).' };
  };

  const handleReadAndSync = async () => {
    setIsLoading(true);
    setError(null);
    try {
      const results = await fetchAircraftDataFromAppsScript(APPS_SCRIPT_URL, {
        aircraftType: 'Bell-429',
        sheetId: SHEET_ID,
        appsScriptUrl: APPS_SCRIPT_URL,
        mapping
      });

      if (results.length === 0) {
        setError("Excel'den veri çekilemedi.");
      } else {
        const enriched = results.map(r => {
          const analysis = analyzeStatusText(r);
          return { ...r, assignedCode: analysis.code, aiInterpretation: analysis.interpretation };
        });
        setPreviewData(enriched);
        // Otomatik Aktarım: Onay penceresi olmadan doğrudan App state'ine gönder
        onSave([{ aircraftType: 'Bell-429', sheetId: SHEET_ID, appsScriptUrl: APPS_SCRIPT_URL, mapping }], enriched);
      }
    } catch (e) {
      setError("Bağlantı hatası.");
    } finally {
      setIsLoading(false);
    }
  };

  const statusCodes = [
    { code: 'B', color: 'bg-[#ffff00]' },
    { code: 'BB', color: 'bg-[#ffff00]' },
    { code: 'KM', color: 'bg-[#ffff00]' },
    { code: 'A', color: 'bg-[#ff0000] text-white' },
    { code: 'PB', color: 'bg-[#ff0000] text-white' },
    { code: 'KK', color: 'bg-[#ff0000] text-white' },
    { code: 'X', color: 'bg-[#7030a0] text-white' },
    { code: 'F', color: 'bg-emerald-500 text-white' },
  ];

  return (
    <div className="fixed inset-0 z-[200] bg-black/90 backdrop-blur-xl flex items-center justify-center p-4">
      <div className="bg-[#052e16] w-full max-w-[1700px] h-[95vh] rounded-[3rem] border border-green-800/50 flex overflow-hidden shadow-2xl">

        {/* SOL MENÜ */}
        <div className="w-80 bg-[#021a0c] border-r border-green-900/50 p-8 flex flex-col">
          <div className="mb-12">
            <h2 className="text-white font-black text-xl tracking-tighter uppercase">ADMİN PANELİ</h2>
            <p className="text-green-600 text-[8px] font-black tracking-[0.5em] mt-2">AKILLI ANALİZ SİSTEMİ</p>
          </div>

          <nav className="space-y-8 flex-grow">
            <div>
              <span className="text-[9px] font-black text-gray-700 uppercase tracking-[0.3em] block mb-4 ml-2">İŞLEMLER</span>
              <button 
                onClick={() => setActiveSubTab('excel')} 
                className={`w-full flex items-center justify-between px-5 py-4 rounded-2xl font-black text-[10px] uppercase tracking-widest transition-all ${activeSubTab === 'excel' ? 'bg-green-600 text-white shadow-lg' : 'text-gray-400 hover:text-white'}`}
              >
                <span>EXCEL VERİ OKUMA</span>
                {notifications.length > 0 && (
                  <span className="bg-red-500 text-white text-[8px] px-2 py-1 rounded-full animate-pulse">{notifications.length}</span>
                )}
              </button>
            </div>

            <div className="pl-4 border-l-2 border-green-900/30 space-y-4">
              <button onClick={() => setActiveSubTab('notifications')} className={`w-full text-left px-4 py-2 font-black text-[9px] uppercase tracking-widest transition-all ${activeSubTab === 'notifications' ? 'text-emerald-400 bg-emerald-500/10 rounded-lg' : 'text-gray-500 hover:text-white'}`}>
                ● GELEN KUTUSU (TAKİP)
              </button>
              <button onClick={() => setActiveSubTab('calendar')} className={`w-full text-left px-4 py-2 font-black text-[9px] uppercase tracking-widest transition-all ${activeSubTab === 'calendar' ? 'text-emerald-400 bg-emerald-500/10 rounded-lg' : 'text-gray-500 hover:text-white'}`}>
                ○ ÇİZELGE DURUMU
              </button>
            </div>
          </nav>

          <button onClick={onClose} className="py-5 rounded-2xl border border-red-900/30 text-red-500 font-black text-[9px] uppercase tracking-widest hover:bg-red-950 transition-all">PANELİ KAPAT</button>
        </div>

        {/* ANA İÇERİK */}
        <div className="flex-1 flex flex-col overflow-hidden bg-[#052e16]">
          {activeSubTab === 'excel' ? (
            <div className="flex-1 flex flex-col overflow-hidden">
                <div className="p-8 border-b border-green-900/50 flex justify-between items-center">
                  <h1 className="text-white text-3xl font-black uppercase tracking-tighter italic">Excel Canlı Entegrasyon</h1>
                  <button 
                    onClick={handleReadAndSync} 
                    disabled={isLoading}
                    className="bg-blue-600 hover:bg-blue-500 text-white px-10 py-5 rounded-2xl font-black text-xs uppercase tracking-[0.3em] shadow-xl disabled:opacity-50 transition-all active:scale-95"
                  >
                    {isLoading ? "SENKRONİZE EDİLİYOR..." : "VERİLERİ ÇEK VE ANALİZ ET"}
                  </button>
                </div>

                <div className="flex-1 p-8 overflow-y-auto space-y-10">
                   <div className="bg-[#021a0c] rounded-[2.5rem] border border-green-900/50 h-[300px] overflow-hidden relative shadow-inner">
                      <iframe src={BELL_429_URL.replace("/edit", "/htmlembed") + "&widget=false&chrome=false&headers=false"} className="w-full h-full opacity-40 grayscale"></iframe>
                      <div className="absolute inset-0 flex items-center justify-center pointer-events-none">
                         <div className="text-green-500/30 font-black text-6xl uppercase tracking-[0.2em] rotate-12">CANLI EXCEL</div>
                      </div>
                   </div>

                   {previewData.length > 0 && (
                     <div className="bg-[#021a0c] rounded-[2.5rem] border border-green-900/30 overflow-hidden shadow-2xl">
                        <div className="bg-emerald-900/20 px-8 py-4 border-b border-green-900/30 flex justify-between items-center">
                           <span className="text-emerald-400 font-black text-[10px] uppercase tracking-widest">SON ANALİZ SONUÇLARI (OTOMATİK AKTARILDI)</span>
                           <span className="text-gray-500 text-[9px] font-bold italic">{new Date().toLocaleTimeString()}</span>
                        </div>
                        <table className="w-full text-left">
                           <thead>
                              <tr className="border-b border-green-900/20 bg-black/20">
                                 <th className="px-8 py-6 text-[9px] font-black text-gray-500 uppercase">KUYRUK</th>
                                 <th className="px-8 py-6 text-center text-[9px] font-black text-gray-500 uppercase">KOD</th>
                                 <th className="px-8 py-6 text-[9px] font-black text-gray-500 uppercase">ANALİZ DETAYI</th>
                                 <th className="px-8 py-6 text-[9px] font-black text-gray-500 uppercase">EXCEL VERİSİ</th>
                              </tr>
                           </thead>
                           <tbody className="divide-y divide-green-900/10">
                              {previewData.map((row, i) => (
                                 <tr key={i} className="hover:bg-white/5 transition-all">
                                    <td className="px-8 py-6 font-black text-white text-xs">{row.kuyrukNo}</td>
                                    <td className="px-8 py-6 text-center">
                                       <div className={`inline-flex w-10 h-10 rounded-xl items-center justify-center font-black text-sm border border-black/40 ${statusCodes.find(c => c.code === row.assignedCode)?.color}`}>
                                          {row.assignedCode}
                                       </div>
                                    </td>
                                    <td className="px-8 py-6 text-[11px] font-bold text-emerald-400">{row.aiInterpretation}</td>
                                    <td className="px-8 py-6 text-[9px] text-gray-500 italic">"{row.durumAyrintisi}"</td>
                                 </tr>
                              ))}
                           </tbody>
                        </table>
                     </div>
                   )}
                </div>
            </div>
          ) : activeSubTab === 'notifications' ? (
            <div className="flex-1 flex flex-col overflow-hidden">
                <div className="p-8 border-b border-green-900/50">
                   <h1 className="text-white text-3xl font-black uppercase tracking-tighter italic">Gelen Kutusu & Değişiklik Takibi</h1>
                   <p className="text-emerald-500 text-[10px] font-bold uppercase tracking-[0.4em] mt-2">Excel'deki her hücre değişikliği burada listelenir</p>
                </div>
                <div className="flex-1 p-8 overflow-y-auto space-y-4">
                   {notifications.length === 0 ? (
                     <div className="h-full flex flex-col items-center justify-center text-gray-600 uppercase font-black tracking-widest italic opacity-20">
                        Henüz bir değişiklik tespit edilmedi
                     </div>
                   ) : (
                     notifications.map((n) => (
                       <div key={n.id} className="bg-[#021a0c] p-6 rounded-3xl border border-green-900/30 flex items-center space-x-8 hover:border-emerald-500/50 transition-all group">
