                    <td className="px-12 py-10 text-center">
                      <span className={`px-8 py-4 rounded-[1.2rem] font-black text-xs uppercase border-2 ${a.durum === Status.FAAL ? 'bg-emerald-50 text-emerald-700 border-emerald-200' : 'bg-red-50 text-red-700 border-red-200'}`}>{a.durum}</span>
                    </td>
                    <td className="px-12 py-10 text-sm font-black text-slate-800 uppercase">{a.konum}</td>
