      {selectedAircraft && <AircraftDetailModal aircraft={selectedAircraft} onClose={() => setSelectedAircraft(null)} />}
      {isAdminOpen && <AdminPanel notifications={notifications} onSave={handleSyncFromExcel} onClose={() => setIsAdminOpen(false)} />}
    </Layout>
  );
};

