import React, { useState, useEffect, useCallback } from 'react';
import { SheetConfig, SheetMapping, Aircraft, Status, StatusType, DailyStatusCode, AppNotification } from '../types';
import { fetchAircraftDataFromAppsScript } from '../services/sheetService';

interface AdminPanelProps {
  onSave: (configs: SheetConfig[], data: Partial<Aircraft>[]) => void;
  onClose: () => void;
  notifications: AppNotification[];
  initialData?: any[]; // App.tsx'den gelen halihazırdaki veriler
}

const AdminPanel: React.FC<AdminPanelProps> = ({ onSave, onClose, notifications, initialData = [] }) => {
  const [activeSubTab, setActiveSubTab] = useState('excel'); 
  const [previewData, setPreviewData] = useState<any[]>(initialData);
  const [isLoading, setIsLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);

  const BELL_429_URL = "https://docs.google.com/spreadsheets/d/1D83TF8K1QG30kBv2sCqnPCMYsdSbaJfcsw-E3S5A9VQ/edit?gid=84538314";
  const APPS_SCRIPT_URL = "https://script.google.com/macros/s/AKfycbzt9ukLiMIWNIQKzHJvw74HaEM28zBHfYao9kbv-g5zb5QxaMUS1UaH45jONA0BeMZr/exec";
  const SHEET_ID = "1D83TF8K1QG30kBv2sCqnPCMYsdSbaJfcsw-E3S5A9VQ";

  const [mapping] = useState<SheetMapping>({
    kuyrukNo: 'A3:A8',
    durum: 'M3:M8',
    durumAyrintisi: 'N3:N8',
    konum: 'L3:L8',
    faydaliSaat: 'I3:I8',
    aciklama: 'O3:O8'
  });

  const analyzeStatusText = (item: any): { code: DailyStatusCode, interpretation: string } => {
    const detail = String(item.durumAyrintisi || '').toLocaleLowerCase('tr-TR');
    const desc = String(item.aciklama || '').toLocaleLowerCase('tr-TR');
    const durumStr = String(item.durum || '').toLocaleUpperCase('tr-TR');
    const fullText = `${detail} ${desc}`;

    const isGayriFaalExplicit = durumStr.includes('GAYRİ') || 
                                durumStr.includes('GAYRI') || 
                                durumStr.includes('G.FAAL') || 
                                durumStr.includes('G. FAAL') ||
                                durumStr.includes('GAYRIFAAL') ||
                                (durumStr.includes('FAAL') && durumStr.includes('DEĞİL'));

    const contextSuggestsGayriFaal = fullText.includes('bakım başladı') || 
                                     fullText.includes('arıza devam') || 
                                     fullText.includes('kaza kırım');

    if (!isGayriFaalExplicit && !contextSuggestsGayriFaal) {
      return { code: 'F', interpretation: 'Sistem Durumu "FAAL" olarak okundu.' };
    }

    if (fullText.includes('kaza') || fullText.includes('kırım')) return { code: 'KK', interpretation: 'Analiz: Kaza/Kırım tespit edildi.' };
    if (fullText.includes('bakım bekler')) return { code: 'BB', interpretation: 'Analiz: Bakım Bekler tespiti.' };
    if (fullText.includes('yıllık') || fullText.includes('bakım') || fullText.includes('periyodik') || fullText.includes('200h')) return { code: 'B', interpretation: 'Analiz: Bakım süreci tespiti.' };
    if (fullText.includes('kabul muayene')) return { code: 'KM', interpretation: 'Analiz: Kabul Muayenesi tespiti.' };
    if (fullText.includes('parça bekler')) return { code: 'PB', interpretation: 'Analiz: Parça Bekleme tespiti.' };
    if (fullText.includes('arıza')) return { code: 'A', interpretation: 'Analiz: Arıza tespiti.' };

    return { code: 'X', interpretation: 'Analiz: Gayrı Faal (Belirsiz Neden).' };
  };

  const handleReadAndSync = useCallback(async (isAuto = false) => {
    setIsLoading(true);
    setError(null);
    try {
      const results = await fetchAircraftDataFromAppsScript(APPS_SCRIPT_URL, {
        aircraftType: 'Bell-429',
        sheetId: SHEET_ID,
        appsScriptUrl: APPS_SCRIPT_URL,
        mapping
      });

      if (results.length > 0) {
        const enriched = results.map(r => {
          const analysis = analyzeStatusText(r);
          return { ...r, assignedCode: analysis.code, aiInterpretation: analysis.interpretation };
        });
        setPreviewData(enriched);
        onSave([{ aircraftType: 'Bell-429', sheetId: SHEET_ID, appsScriptUrl: APPS_SCRIPT_URL, mapping }], enriched);
      } else if (!isAuto) {
        setError("Excel'den veri çekilemedi.");
      }
    } catch (e) {
      if (!isAuto) setError("Bağlantı hatası.");
    } finally {
      setIsLoading(false);
    }
  }, [onSave, mapping]);

  // Admin Panel açıldığında otomatik tetikle
  useEffect(() => {
    handleReadAndSync(true);
  }, [handleReadAndSync]);

  const statusCodes = [
    { code: 'B', color: 'bg-[#ffff00]' },
    { code: 'BB', color: 'bg-[#ffff00]' },
    { code: 'KM', color: 'bg-[#ffff00]' },
    { code: 'A', color: 'bg-[#ff0000] text-white' },
    { code: 'PB', color: 'bg-[#ff0000] text-white' },
    { code: 'KK', color: 'bg-[#ff0000] text-white' },
    { code: 'X', color: 'bg-[#7030a0] text-white' },
    { code: 'F', color: 'bg-emerald-500 text-white' },
  ];

  return (
