        {/* SOL MENÜ */}
        <div className="w-80 bg-[#021a0c] border-r border-green-900/50 p-8 flex flex-col">
          <div className="mb-12">
            <h2 className="text-white font-black text-xl tracking-tighter uppercase">ADMİN PANELİ</h2>
            <p className="text-green-600 text-[8px] font-black tracking-[0.5em] mt-2 italic">ARKA PLAN OTOMASYONU AKTİF</p>
          </div>

          <nav className="space-y-8 flex-grow">
            <div>
              <span className="text-[9px] font-black text-gray-700 uppercase tracking-[0.3em] block mb-4 ml-2">VERİ YÖNETİMİ</span>
              <button 
                onClick={() => setActiveSubTab('excel')} 
                className={`w-full flex items-center justify-between px-5 py-4 rounded-2xl font-black text-[10px] uppercase tracking-widest transition-all ${activeSubTab === 'excel' ? 'bg-green-600 text-white shadow-lg' : 'text-gray-400 hover:text-white'}`}
              >
                <span>EXCEL VERİ OKUMA</span>
                {notifications.length > 0 && (
                  <span className="bg-red-500 text-white text-[8px] px-2 py-1 rounded-full animate-bounce">{notifications.length}</span>
                )}
              </button>
            </div>

            <div className="pl-4 border-l-2 border-green-900/30 space-y-4">
              <button onClick={() => setActiveSubTab('notifications')} className={`w-full text-left px-4 py-2 font-black text-[9px] uppercase tracking-widest transition-all ${activeSubTab === 'notifications' ? 'text-emerald-400 bg-emerald-500/10 rounded-lg' : 'text-gray-500 hover:text-white'}`}>
                ● GELEN KUTUSU ({notifications.length})
              </button>
              <button onClick={() => setActiveSubTab('calendar')} className={`w-full text-left px-4 py-2 font-black text-[9px] uppercase tracking-widest transition-all ${activeSubTab === 'calendar' ? 'text-emerald-400 bg-emerald-500/10 rounded-lg' : 'text-gray-500 hover:text-white'}`}>
                ○ ÇİZELGE DURUMU
              </button>
            </div>
          </nav>

          <button onClick={onClose} className="py-5 rounded-2xl border border-red-900/30 text-red-500 font-black text-[9px] uppercase tracking-widest hover:bg-red-950 transition-all">PANELİ KAPAT</button>
        </div>

        {/* ANA İÇERİK */}
        <div className="flex-1 flex flex-col overflow-hidden bg-[#052e16]">
          {activeSubTab === 'excel' ? (
            <div className="flex-1 flex flex-col overflow-hidden">
                <div className="p-8 border-b border-green-900/50 flex justify-between items-center bg-black/10">
                  <div>
                    <h1 className="text-white text-3xl font-black uppercase tracking-tighter italic">Excel Canlı Entegrasyon</h1>
                    <div className="flex items-center mt-2">
                       <div className="w-2 h-2 bg-emerald-500 rounded-full animate-pulse mr-2"></div>
                       <span className="text-emerald-400 text-[10px] font-bold uppercase tracking-widest">Veriler Otomatik Olarak Analiz Ediliyor</span>
                    </div>
                  </div>
                  <div className="flex items-center space-x-4">
                    {isLoading && (
                      <span className="text-blue-400 text-[10px] font-black uppercase tracking-widest animate-pulse">SENKRONİZE EDİLİYOR...</span>
                    )}
                    <button 
                      onClick={() => handleReadAndSync()} 
                      className="bg-white/5 hover:bg-white/10 text-white px-8 py-4 rounded-xl font-black text-[10px] uppercase tracking-widest border border-white/10 transition-all active:scale-95"
                    >
                      MANUEL YENİLE
                    </button>
                  </div>
                </div>

                <div className="flex-1 p-8 overflow-y-auto space-y-10 custom-scrollbar">
                   {error && (
                     <div className="bg-red-500/10 border border-red-500/50 p-6 rounded-2xl text-red-500 font-bold text-sm flex items-center">
                        <svg className="w-6 h-6 mr-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path d="M12 9v2m0 4h.01m-6.938 4h13.856c1.54 0 2.502-1.667 1.732-3L13.732 4c-.77-1.333-2.694-1.333-3.464 0L3.34 16c-.77 1.333.192 3 1.732 3z" strokeWidth={2}/></svg>
