import { SheetConfig, Aircraft, Status, StatusType, DailyStatusCode } from '../types';

/**
 * Durum metinlerini analiz ederek faaliyet kodlarını atar.
 */
export const analyzeStatus = (item: any): { code: DailyStatusCode, interpretation: string } => {
  const detail = String(item.durumAyrintisi || '').toLocaleLowerCase('tr-TR');
  const desc = String(item.aciklama || '').toLocaleLowerCase('tr-TR');
  const durumStr = String(item.durum || '').toLocaleUpperCase('tr-TR');
  const fullText = `${detail} ${desc}`;

  const isGayriFaalExplicit = durumStr.includes('GAYRİ') || 
                              durumStr.includes('GAYRI') || 
                              durumStr.includes('G.FAAL') || 
                              durumStr.includes('G. FAAL') ||
                              durumStr.includes('GAYRIFAAL') ||
                              (durumStr.includes('FAAL') && durumStr.includes('DEĞİL'));

  const contextSuggestsGayriFaal = fullText.includes('bakım başladı') || 
                                   fullText.includes('arıza devam') || 
                                   fullText.includes('kaza kırım');

  if (!isGayriFaalExplicit && !contextSuggestsGayriFaal) {
    return { code: 'F', interpretation: 'Sistem Durumu "FAAL" olarak okundu.' };
  }

  if (fullText.includes('kaza') || fullText.includes('kırım')) return { code: 'KK', interpretation: 'Analiz: Kaza/Kırım tespit edildi.' };
  if (fullText.includes('bakım bekler')) return { code: 'BB', interpretation: 'Analiz: Bakım Bekler tespiti.' };
  if (fullText.includes('yıllık') || fullText.includes('bakım') || fullText.includes('periyodik') || fullText.includes('200h')) return { code: 'B', interpretation: 'Analiz: Bakım süreci tespiti.' };
  if (fullText.includes('kabul muayene')) return { code: 'KM', interpretation: 'Analiz: Kabul Muayenesi tespiti.' };
  if (fullText.includes('parça bekler')) return { code: 'PB', interpretation: 'Analiz: Parça Bekleme tespiti.' };
  if (fullText.includes('arıza')) return { code: 'A', interpretation: 'Analiz: Arıza tespiti.' };

  return { code: 'X', interpretation: 'Analiz: Gayrı Faal (Belirsiz Neden).' };
};

/**
 * Google Apps Script üzerinden veri çeker ve otomatik analiz eder.
 */
export const fetchAircraftDataFromAppsScript = async (url: string, config: SheetConfig): Promise<Partial<Aircraft>[]> => {
  try {
    const response = await fetch(url, {
      method: 'POST',
      headers: {
        'Content-Type': 'text/plain;charset=utf-8',
      },
      body: JSON.stringify({
        sheetId: config.sheetId,
        mapping: config.mapping
      })
    });

    if (!response.ok) throw new Error(`HTTP Error: ${response.status}`);

    const data = await response.json();
    if (data.error || !Array.isArray(data)) return [];

    return data.map((item: any) => {
      const analysis = analyzeStatus(item);
      return {
        kuyrukNo: String(item.kuyrukNo || '').trim(),
        cagriKodu: `ORMAN-${String(item.kuyrukNo || '').split('-')[1] || 'XX'}`,
        durum: (String(item.durum).toUpperCase().includes('FAAL') && !String(item.durum).toUpperCase().includes('GAYRI')) ? Status.FAAL : Status.GAYRI_FAAL,
        durumTipi: item.durumAyrintisi ? StatusType.BAKIM : StatusType.NONE,
        durumAyrintisi: String(item.durumAyrintisi || '-'),
        konum: String(item.konum || 'ANKARA'),
        faydaliSaat: parseInt(item.faydaliSaat) || 0,
        aciklama: String(item.aciklama || ''),
        guncellemeTarihi: new Date().toLocaleString('tr-TR'),
        durumBaslangic: new Date().toISOString().split('T')[0],
        maintenanceHours: [{ bakimTuru: 'PERİYODİK', kalanSaat: parseInt(item.faydaliSaat) || 0 }],
        photos: [`https://picsum.photos/seed/${item.kuyrukNo}/800/600`],
        platformTipi: 'H',
        tip: 'Bell-429',
        assignedCode: analysis.code,
        aiInterpretation: analysis.interpretation
      };
    });
  } catch (error) {
    console.error("Veri alma başarısız oldu:", error);
    return [];
  }
};

