               <span className="text-emerald-400 font-black text-[11px] uppercase tracking-[0.5em]">CANLI VERİ AKIŞI AKTİF</span>
            </div>
            {notifications.length > 0 && (
              <div 
                onClick={() => { setIsAdminOpen(true); }}
                className="bg-red-500/10 border border-red-500/30 px-6 py-4 rounded-[1.8rem] flex items-center shadow-lg cursor-pointer hover:bg-red-500/20 transition-all animate-bounce"
              >
                <span className="text-red-400 font-black text-[10px] uppercase tracking-[0.4em]">{notifications.length} YENİ ANALİZ BİLDİRİMİ</span>
              </div>
            )}
