const App: React.FC = () => {
  const [isSplashVisible, setIsSplashVisible] = useState(true);
  const [isAdminOpen, setIsAdminOpen] = useState(false);
  const [showActivity, setShowActivity] = useState(true);

  const [fleet, setFleet] = useState<Aircraft[]>([]);
  const [activities, setActivities] = useState<AircraftActivity[]>([]);

  const [selectedAircraft, setSelectedAircraft] = useState<Aircraft | null>(null);
  const [searchTerm, setSearchTerm] = useState('');
  const [notifications, setNotifications] = useState<AppNotification[]>([]);

  const APPS_SCRIPT_URL = "https://script.google.com/macros/s/AKfycbzt9ukLiMIWNIQKzHJvw74HaEM28zBHfYao9kbv-g5zb5QxaMUS1UaH45jONA0BeMZr/exec";
  const initialSyncDone = useRef(false);

  const handleSyncFromExcel = useCallback((configs: SheetConfig[], incomingData: Partial<Aircraft>[], silent: boolean = false) => {
    if (!incomingData || incomingData.length === 0) return;

    let discoveredChanges: AppNotification[] = [];
    const today = new Date().getDate();

    setFleet(prevFleet => {
      const updatedFleet = incomingData.map(incoming => {
        const existing = prevFleet.find(a => a.kuyrukNo === incoming.kuyrukNo);

        // DEĞİŞİKLİK TAKİBİ
        if (existing && !silent) {
          ['durum', 'konum', 'durumAyrintisi'].forEach(col => {
            const key = col as keyof Aircraft;
            if (String(existing[key] || '').trim() !== String(incoming[key] || '').trim()) {
              discoveredChanges.push({
                id: Math.random().toString(36).substr(2, 9),
                platform: 'Bell-429',
                kuyrukNo: existing.kuyrukNo,
                kolon: col.toUpperCase(),
                oncekiDeger: String(existing[key] || '-'),
                yeniDeger: String(incoming[key] || '-'),
                mesaj: `${existing.kuyrukNo} hücresinde değişiklik tespit edildi.`,
                tarih: new Date().toLocaleTimeString('tr-TR')
              });
            }
          });
        }
        return { ...(existing || {}), ...incoming } as Aircraft;
      });

      // ÇİZELGE GÜNCELLEME (FAALİYET MATRİSİ)
      setActivities(prevActivities => {
        let newActivities = [...prevActivities];
        incomingData.forEach(incoming => {
          if (incoming.kuyrukNo) {
            const existsIdx = newActivities.findIndex(act => act.kuyrukNo === incoming.kuyrukNo);
            const newCode = (incoming.assignedCode || 'F') as DailyStatusCode;

            if (existsIdx !== -1) {
              newActivities[existsIdx] = {
                ...newActivities[existsIdx],
                dailyStatuses: { ...newActivities[existsIdx].dailyStatuses, [today]: newCode }
              };
            } else {
              newActivities.push({
                kuyrukNo: incoming.kuyrukNo || '',
                cagriKodu: incoming.cagriKodu || `ORMAN-${incoming.kuyrukNo?.split('-')[1] || 'XX'}`,
                tip: incoming.tip || 'Bell-429',
                dailyStatuses: { [today]: newCode }
              });
            }
          }
        });
        return newActivities;
      });

      return updatedFleet;
    });

    if (discoveredChanges.length > 0) {
      setNotifications(prev => [...discoveredChanges, ...prev].slice(0, 50));
    }
  }, []);

  const runSync = useCallback(async () => {
    const defaultMapping = {
      kuyrukNo: 'A3:A8', durum: 'M3:M8', durumAyrintisi: 'N3:N8', konum: 'L3:L8', faydaliSaat: 'I3:I8', aciklama: 'O3:O8'
    };
    const defaultConfig: SheetConfig = {
      aircraftType: 'Bell-429', sheetId: '1D83TF8K1QG30kBv2sCqnPCMYsdSbaJfcsw-E3S5A9VQ', appsScriptUrl: APPS_SCRIPT_URL, mapping: defaultMapping
    };
    try {
      const data = await fetchAircraftDataFromAppsScript(APPS_SCRIPT_URL, defaultConfig);
      if (data && data.length > 0) {
        handleSyncFromExcel([defaultConfig], data, initialSyncDone.current);
        initialSyncDone.current = true;
      }
    } catch (e) { console.error("Sync error:", e); }
  }, [handleSyncFromExcel]);

  // UYGULAMA AÇILIR AÇILMAZ ÇALIŞTIR (Splash bitsin bitmesin)
  useEffect(() => {
    runSync(); 
    const interval = setInterval(runSync, 60000); 
    return () => clearInterval(interval);
  }, [runSync]);

  const filteredFleet = useMemo(() => {
    return fleet.filter(a => {
      const s = searchTerm.toLowerCase();
      return a.kuyrukNo.toLowerCase().includes(s) || a.konum.toLowerCase().includes(s);
    });
  }, [fleet, searchTerm]);

  if (isSplashVisible) return <SplashScreen onComplete={() => setIsSplashVisible(false)} />;

  return (
    <Layout>
      <div className="flex justify-between items-center mb-12">
         <div className="flex items-center space-x-6">
            <div className="bg-emerald-500/10 border border-emerald-500/30 px-6 py-4 rounded-[1.8rem] flex items-center shadow-2xl backdrop-blur-md">
               <div className="w-3 h-3 bg-emerald-500 rounded-full mr-4 animate-pulse"></div>
               <span className="text-emerald-400 font-black text-[11px] uppercase tracking-[0.5em]">CANLI VERİ AKIŞI AKTİF</span>
            </div>
            {notifications.length > 0 && (
              <div 
                onClick={() => { setIsAdminOpen(true); }}
                className="bg-red-500/10 border border-red-500/30 px-6 py-4 rounded-[1.8rem] flex items-center shadow-lg cursor-pointer hover:bg-red-500/20 transition-all animate-bounce"
              >
                <span className="text-red-400 font-black text-[10px] uppercase tracking-[0.4em]">{notifications.length} YENİ ANALİZ BİLDİRİMİ</span>
              </div>
            )}
         </div>
         <div className="flex space-x-5">
            <button onClick={() => setShowActivity(!showActivity)} className={`px-10 py-5 rounded-[1.8rem] font-black text-[11px] uppercase tracking-[0.4em] transition-all shadow-2xl border-2 ${showActivity ? 'bg-blue-600 text-white border-blue-500' : 'bg-white/10 text-white border-white/20'}`}>
              {showActivity ? "DURUM BANKASI" : "FAALİYET ÇİZELGESİ"}
            </button>
            <button onClick={() => setIsAdminOpen(true)} className="bg-white/5 hover:bg-white/15 text-white px-10 py-5 rounded-[1.8rem] font-black text-[11px] border-2 border-white/10 uppercase tracking-[0.4em] transition-all shadow-lg">
              YÖNETİM PANELİ
            </button>
         </div>
      </div>

      <div className="mb-14">
         <Dashboard fleet={fleet} />
      </div>

      {showActivity ? (
        <div className="mb-24 animate-in fade-in slide-in-from-top-10 duration-1000">
           <div className="flex justify-between items-end mb-12 px-6">
              <div>
                 <h2 className="text-5xl font-black text-white uppercase tracking-tighter italic">FAALİYET ÇİZELGESİ</h2>
                 <p className="text-emerald-500 text-xs font-black uppercase tracking-[0.7em] mt-4">Analiz Edilen Durum Kodları (F: Faal Hücresi Boş Gözükür)</p>
              </div>
           </div>

           <div className="bg-white rounded-[4rem] p-4 shadow-[0_50px_120px_rgba(0,0,0,0.7)] border-[10px] border-white/5 overflow-hidden min-h-[450px]">
             {activities.length > 0 ? (
               <ActivityGrid activities={activities} startDate={new Date(2025, 0, 1)} endDate={new Date(2025, 0, 31)} title="OCAK 2025" />
             ) : (
               <div className="h-[400px] flex flex-col items-center justify-center text-center">
                  <div className="w-12 h-12 border-4 border-emerald-500 border-t-transparent rounded-full animate-spin mb-6"></div>
                  <h3 className="text-slate-400 font-black text-xl uppercase tracking-tighter italic">Veriler Analiz Edilip Yükleniyor...</h3>
               </div>
             )}
           </div>

           <div className="mt-12 px-12 grid grid-cols-1 md:grid-cols-3 gap-6">
              <div className="space-y-2">
                <div className="bg-[#FFFF00] text-black font-black p-3 border-2 border-black flex justify-between items-center rounded shadow-md"><span>B: BAKIM</span></div>
                <div className="bg-[#FFFF00] text-black font-black p-3 border-2 border-black flex justify-between items-center rounded shadow-md"><span>BB: BAKIM BEKLER</span></div>
                <div className="bg-[#FFFF00] text-black font-black p-3 border-2 border-black flex justify-between items-center rounded shadow-md"><span>KM: KABUL MUAYENESİ</span></div>
              </div>
              <div className="space-y-2">
                <div className="bg-[#FF0000] text-white font-black p-3 border-2 border-black flex justify-between items-center rounded shadow-md"><span>A: ARIZA</span></div>
                <div className="bg-[#FF0000] text-white font-black p-3 border-2 border-black flex justify-between items-center rounded shadow-md"><span>PB: PARÇA BEKLER</span></div>
                <div className="bg-[#FF0000] text-white font-black p-3 border-2 border-black flex justify-between items-center rounded shadow-md"><span>KK: KAZA KIRIM</span></div>
              </div>
              <div className="space-y-2">
                <div className="bg-[#7030A0] text-white font-black p-3 border-2 border-black flex items-center justify-center rounded shadow-md h-full">
                   <span className="text-lg">X: OLMADIĞI GÜNLER</span>
                </div>
              </div>
           </div>
        </div>
      ) : (
        <div className="mb-24 animate-in fade-in slide-in-from-bottom-10 duration-1000">
          <div className="flex justify-between items-end mb-12 px-6">
             <div>
                <h2 className="text-5xl font-black text-white uppercase tracking-tighter italic">DURUM BANKASI</h2>
                <p className="text-emerald-500 text-xs font-black uppercase tracking-[0.7em] mt-4">Teknik Envanter Veri Havuzu</p>
             </div>
             <input type="text" placeholder="Hızlı Arama..." value={searchTerm} onChange={(e) => setSearchTerm(e.target.value)} className="w-[500px] px-12 py-7 bg-black/50 text-white rounded-[2.5rem] border-2 border-white/10 outline-none font-bold text-base focus:border-emerald-500 transition-all shadow-2xl" />
          </div>

          <div className="bg-white p-3 rounded-[4.5rem] shadow-[0_50px_120px_rgba(0,0,0,0.7)] overflow-hidden border-[10px] border-white/5 min-h-[400px]">
            <table className="w-full border-collapse">
              <thead>
                <tr className="bg-slate-50 border-b-2 border-slate-100">
                  <th className="px-12 py-10 text-left text-xs font-black text-slate-400 uppercase tracking-[0.3em]">HAVA ARACI</th>
                  <th className="px-12 py-10 text-center text-xs font-black text-slate-400 uppercase tracking-[0.3em]">DURUM</th>
                  <th className="px-12 py-10 text-left text-xs font-black text-slate-400 uppercase tracking-[0.3em]">KONUM</th>
                  <th className="px-12 py-10 text-center text-xs font-black text-slate-400 uppercase tracking-[0.3em]">SAAT</th>
                  <th className="px-12 py-10 text-left text-xs font-black text-slate-400 uppercase tracking-[0.3em]">DETAY</th>
                </tr>
              </thead>
              <tbody className="divide-y divide-slate-100">
                {filteredFleet.map((a, i) => (
                  <tr key={i} className="hover:bg-slate-50 cursor-pointer transition-all active:scale-[0.98]" onClick={() => setSelectedAircraft(a)}>
                    <td className="px-12 py-10 font-black text-emerald-950 text-lg">{a.kuyrukNo}</td>
                    <td className="px-12 py-10 text-center">
                      <span className={`px-8 py-4 rounded-[1.2rem] font-black text-xs uppercase border-2 ${a.durum === Status.FAAL ? 'bg-emerald-50 text-emerald-700 border-emerald-200' : 'bg-red-50 text-red-700 border-red-200'}`}>{a.durum}</span>
                    </td>
                    <td className="px-12 py-10 text-sm font-black text-slate-800 uppercase">{a.konum}</td>
                    <td className="px-12 py-10 text-center font-black text-3xl text-blue-600">{a.faydaliSaat}</td>
                    <td className="px-12 py-10 italic text-slate-500 text-xs truncate max-w-xs">{a.durumAyrintisi}</td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
        </div>
      )}

      {selectedAircraft && <AircraftDetailModal aircraft={selectedAircraft} onClose={() => setSelectedAircraft(null)} />}
      {isAdminOpen && <AdminPanel notifications={notifications} initialData={fleet} onSave={handleSyncFromExcel} onClose={() => setIsAdminOpen(false)} />}
    </Layout>
  );
};

export default App;

export enum PlatformType {
  H = 'H',
  SA = 'S-A',
  DA = 'D-A',
  SL = 'S-L',
  DL = 'D-L'
}

export enum Status {
  FAAL = 'FAAL',
  GAYRI_FAAL = 'GAYRI FAAL'
}

export enum StatusType {
  BAKIM = 'BAKIM',
  ARIZA = 'ARIZA',
  DIGER = 'DIGER',
  NONE = '-'
}

export interface MaintenanceHour {
  bakimTuru: string;
  kalanSaat: number;
}

export interface Aircraft {
  cagriKodu: string;
  kuyrukNo: string;
  platformTipi: string;
  durum: Status;
  durumTipi: StatusType;
  durumAyrintisi: string;
  konum: string;
  faydaliSaat: number;
  durumBaslangic: string;
  durumBitis?: string;
  aciklama: string;
  guncellemeTarihi: string;
  seriNo: string;
  motor: string;
  uretimYili: number;
  base: string;
  maintenanceHours: MaintenanceHour[];
  photos: string[];
  tip?: string;
  assignedCode?: DailyStatusCode;
  aiInterpretation?: string;
}

export type DailyStatusCode = 'B' | 'BB' | 'KM' | 'A' | 'PB' | 'KK' | 'X' | 'F' | '';

export interface AircraftActivity {
  kuyrukNo: string;
  cagriKodu: string;
  tip: string;
  dailyStatuses: { [day: number]: DailyStatusCode };
}

export interface SheetMapping {
  kuyrukNo: string;
  durum: string;
  durumAyrintisi: string;
  konum: string;
  faydaliSaat: string;
  aciklama: string;
}

export interface SheetConfig {
  aircraftType: string;
  sheetId: string;
  appsScriptUrl: string;
  mapping: SheetMapping;
}

export interface AppNotification {
  id: string;
  platform: string; // Hangi platform (Bell-429, T-70 vb.)
  kuyrukNo: string;
  mesaj: string;
  tarih: string; // Tam tarih ve saat (DD.MM.YYYY HH:mm:ss)
  oncekiDeger: string;
  yeniDeger: string;
  kolon: string; // Değişen alan adı
}

export interface SnapshotPreview {
  kuyrukNo: string;
  tarih: string;
  kod: DailyStatusCode;
  aciklamaOzeti: string;
  gerekce: string;
  originalData: Partial<Aircraft>;
}

import React, { useState, useMemo, useEffect, useCallback, useRef } from 'react';
import Layout from './components/Layout';
import Dashboard from './components/Dashboard';
import AircraftDetailModal from './components/AircraftDetailModal';
import ActivityGrid from './components/ActivityGrid';
import SplashScreen from './components/SplashScreen';
import AdminPanel from './components/AdminPanel';
import { Aircraft, Status, SheetConfig, AppNotification, DailyStatusCode, AircraftActivity } from './types';
import { fetchAircraftDataFromAppsScript } from './services/sheetService';

const App: React.FC = () => {
  const [isSplashVisible, setIsSplashVisible] = useState(true);
  const [isAdminOpen, setIsAdminOpen] = useState(false);
  const [showActivity, setShowActivity] = useState(true);

  const [fleet, setFleet] = useState<Aircraft[]>([]);
  const [activities, setActivities] = useState<AircraftActivity[]>([]);

  const [selectedAircraft, setSelectedAircraft] = useState<Aircraft | null>(null);
  const [searchTerm, setSearchTerm] = useState('');
  const [notifications, setNotifications] = useState<AppNotification[]>([]);

  const APPS_SCRIPT_URL = "https://script.google.com/macros/s/AKfycbzt9ukLiMIWNIQKzHJvw74HaEM28zBHfYao9kbv-g5zb5QxaMUS1UaH45jONA0BeMZr/exec";
  const initialSyncDone = useRef(false);

  const handleSyncFromExcel = useCallback((incomingData: Partial<Aircraft>[], platform: string) => {
    if (!incomingData || incomingData.length === 0) return;

    const now = new Date();
    const timestamp = now.toLocaleDateString('tr-TR') + ' ' + now.toLocaleTimeString('tr-TR');
    const today = now.getDate();
    let discoveredChanges: AppNotification[] = [];

    setFleet(prevFleet => {
      const updatedFleet = [...prevFleet];

      incomingData.forEach(incoming => {
        const existingIdx = updatedFleet.findIndex(a => a.kuyrukNo === incoming.kuyrukNo);
        const existing = existingIdx !== -1 ? updatedFleet[existingIdx] : null;

        // DEĞİŞİKLİK TESPİTİ VE BİLDİRİM OLUŞTURMA
        if (existing && initialSyncDone.current) {
          ['durum', 'konum', 'durumAyrintisi', 'faydaliSaat'].forEach(col => {
            const key = col as keyof Aircraft;
            const oldVal = String(existing[key] || '').trim();
            const newVal = String(incoming[key] || '').trim();

            if (oldVal !== newVal) {
              discoveredChanges.push({
                id: Math.random().toString(36).substr(2, 9),
                platform: platform,
                kuyrukNo: existing.kuyrukNo,
                kolon: col.toUpperCase(),
                oncekiDeger: oldVal || 'BOŞ',
                yeniDeger: newVal || 'BOŞ',
                mesaj: `${platform} - ${existing.kuyrukNo} verisi güncellendi.`,
                tarih: timestamp
              });
            }
          });
        }

        // Fleet State Güncelleme
        if (existingIdx !== -1) {
          updatedFleet[existingIdx] = { ...updatedFleet[existingIdx], ...incoming } as Aircraft;
        } else {
          updatedFleet.push(incoming as Aircraft);
        }

        // FAALİYET ÇİZELGESİ (MATRIX) GÜNCELLEME
        setActivities(prevActivities => {
          let newActivities = [...prevActivities];
          const existsIdx = newActivities.findIndex(act => act.kuyrukNo === incoming.kuyrukNo);
          const newCode = (incoming.assignedCode || 'F') as DailyStatusCode;

          if (existsIdx !== -1) {
            newActivities[existsIdx] = {
              ...newActivities[existsIdx],
              dailyStatuses: { ...newActivities[existsIdx].dailyStatuses, [today]: newCode }
            };
          } else {
            newActivities.push({
              kuyrukNo: incoming.kuyrukNo || '',
              cagriKodu: incoming.cagriKodu || `ORMAN-${incoming.kuyrukNo?.split('-')[1] || 'XX'}`,
              tip: incoming.tip || platform,
              dailyStatuses: { [today]: newCode }
            });
          }
          return newActivities;
        });
      });

      return updatedFleet;
    });

    if (discoveredChanges.length > 0) {
      setNotifications(prev => [...discoveredChanges, ...prev].slice(0, 100)); // Son 100 değişikliği tut
    }

    if (!initialSyncDone.current) initialSyncDone.current = true;
  }, []);

  const runGlobalSync = useCallback(async () => {
    // Gelecekte buraya farklı platformlar (T-70, AT-802 vb.) için yeni fetch'ler eklenebilir.
    const bellConfig: SheetConfig = {
      aircraftType: 'Bell-429',
      sheetId: '1D83TF8K1QG30kBv2sCqnPCMYsdSbaJfcsw-E3S5A9VQ',
      appsScriptUrl: APPS_SCRIPT_URL,
      mapping: { kuyrukNo: 'A3:A8', durum: 'M3:M8', durumAyrintisi: 'N3:N8', konum: 'L3:L8', faydaliSaat: 'I3:I8', aciklama: 'O3:O8' }
    };

    try {
      const data = await fetchAircraftDataFromAppsScript(APPS_SCRIPT_URL, bellConfig);
      if (data && data.length > 0) {
        handleSyncFromExcel(data, 'Bell-429');
      }
    } catch (e) { console.error("Sync Error:", e); }
  }, [handleSyncFromExcel]);

  // Arka Plan Motoru: Uygulama yüklenir yüklenmez başlar
  useEffect(() => {
    runGlobalSync(); 
    const interval = setInterval(runGlobalSync, 60000); // Her dakika kontrol
    return () => clearInterval(interval);
  }, [runGlobalSync]);

  const filteredFleet = useMemo(() => {
    return fleet.filter(a => {
      const s = searchTerm.toLowerCase();
      return a.kuyrukNo.toLowerCase().includes(s) || a.konum.toLowerCase().includes(s);
    });
  }, [fleet, searchTerm]);

  if (isSplashVisible) return <SplashScreen onComplete={() => setIsSplashVisible(false)} />;

  return (
    <Layout>
      <div className="flex justify-between items-center mb-12">
         <div className="flex items-center space-x-6">
            <div className="bg-emerald-500/10 border border-emerald-500/30 px-6 py-4 rounded-[1.8rem] flex items-center shadow-2xl backdrop-blur-md relative overflow-hidden group">
               <div className="absolute inset-0 bg-emerald-500/5 translate-x-[-100%] group-hover:translate-x-[100%] transition-transform duration-1000"></div>
               <div className="w-3 h-3 bg-emerald-500 rounded-full mr-4 animate-pulse shadow-[0_0_10px_#10b981]"></div>
               <span className="text-emerald-400 font-black text-[11px] uppercase tracking-[0.5em]">OTOMATİK VERİ TAKİBİ AKTİF</span>
            </div>
            {notifications.length > 0 && (
              <div 
                onClick={() => setIsAdminOpen(true)}
                className="bg-red-500/10 border border-red-500/30 px-6 py-4 rounded-[1.8rem] flex items-center shadow-lg cursor-pointer hover:bg-red-500/20 transition-all animate-bounce"
              >
                <div className="bg-red-500 text-white text-[9px] font-black w-6 h-6 rounded-full flex items-center justify-center mr-3 shadow-lg">{notifications.length}</div>
                <span className="text-red-400 font-black text-[10px] uppercase tracking-[0.4em]">YENİ EXCEL BİLDİRİMİ</span>
              </div>
            )}
         </div>
         <div className="flex space-x-5">
            <button onClick={() => setShowActivity(!showActivity)} className={`px-10 py-5 rounded-[2rem] font-black text-[11px] uppercase tracking-[0.4em] transition-all shadow-2xl border-2 ${showActivity ? 'bg-blue-600 text-white border-blue-500' : 'bg-white/10 text-white border-white/20'}`}>
              {showActivity ? "ENVANTER LİSTESİ" : "FAALİYET ÇİZELGESİ"}
            </button>
            <button onClick={() => setIsAdminOpen(true)} className="bg-[#021a0c] hover:bg-emerald-900 text-white px-10 py-5 rounded-[2rem] font-black text-[11px] border-2 border-emerald-800/50 uppercase tracking-[0.4em] transition-all shadow-lg flex items-center">
              <svg className="w-4 h-4 mr-3" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path d="M10.325 4.317c.426-1.756 2.924-1.756 3.35 0a1.724 1.724 0 002.573 1.066c1.543-.94 3.31.826 2.37 2.37a1.724 1.724 0 001.065 2.572c1.756.426 1.756 2.924 0 3.35a1.724 1.724 0 00-1.066 2.573c.94 1.543-.826 3.31-2.37 2.37a1.724 1.724 0 00-2.572 1.065c-.426 1.756-2.924 1.756-3.35 0a1.724 1.724 0 00-2.573-1.066c-1.543.94-3.31-.826-2.37-2.37a1.724 1.724 0 00-1.065-2.572c-1.756-.426-1.756-2.924 0-3.35a1.724 1.724 0 001.066-2.573c-.94-1.543.826-3.31 2.37-2.37.996.608 2.296.07 2.572-1.065z" strokeWidth={2}/><path d="M15 12a3 3 0 11-6 0 3 3 0 016 0z" strokeWidth={2}/></svg>
              YÖNETİM & GELEN KUTUSU
            </button>
         </div>
      </div>

      <div className="mb-14">
         <Dashboard fleet={fleet} />
      </div>

      {showActivity ? (
        <div className="mb-24 animate-in fade-in slide-in-from-top-10 duration-1000">
           <div className="flex justify-between items-end mb-12 px-6">
              <div>
                 <h2 className="text-6xl font-black text-white uppercase tracking-tighter italic">FAALİYET ÇİZELGESİ</h2>
                 <p className="text-emerald-500 text-[10px] font-black uppercase tracking-[0.8em] mt-4 border-l-4 border-emerald-500 pl-4">Canlı Excel Verisiyle Otomatik Eşleşen Matris</p>
              </div>
           </div>

           <div className="bg-white rounded-[4rem] p-4 shadow-[0_50px_120px_rgba(0,0,0,0.8)] border-[12px] border-white/5 overflow-hidden min-h-[500px]">
             {activities.length > 0 ? (
               <ActivityGrid activities={activities} startDate={new Date(2025, 0, 1)} endDate={new Date(2025, 0, 31)} title="OCAK 2025" />
             ) : (
               <div className="h-[450px] flex flex-col items-center justify-center text-center">
                  <div className="w-16 h-16 border-4 border-emerald-500 border-t-transparent rounded-full animate-spin mb-8"></div>
                  <h3 className="text-slate-400 font-black text-2xl uppercase tracking-widest italic">Veriler Çekiliyor ve Analiz Ediliyor...</h3>
               </div>
             )}
           </div>

           <div className="mt-12 px-12 grid grid-cols-1 md:grid-cols-3 gap-8">
              <div className="bg-black/20 p-6 rounded-3xl border border-white/5 space-y-3">
                <div className="text-[10px] font-black text-gray-500 uppercase tracking-widest mb-2">BAKIM GRUBU</div>
                <div className="bg-[#FFFF00] text-black font-black p-4 border-2 border-black/10 flex justify-between items-center rounded-xl shadow-lg"><span>B: PERİYODİK BAKIM</span></div>
                <div className="bg-[#FFFF00] text-black font-black p-4 border-2 border-black/10 flex justify-between items-center rounded-xl shadow-lg"><span>BB: BAKIM BEKLER</span></div>
                <div className="bg-[#FFFF00] text-black font-black p-4 border-2 border-black/10 flex justify-between items-center rounded-xl shadow-lg"><span>KM: KABUL MUAYENE</span></div>
              </div>
              <div className="bg-black/20 p-6 rounded-3xl border border-white/5 space-y-3">
                <div className="text-[10px] font-black text-gray-500 uppercase tracking-widest mb-2">ARIZA & KRİTİK</div>
                <div className="bg-[#FF0000] text-white font-black p-4 border-2 border-black/10 flex justify-between items-center rounded-xl shadow-lg"><span>A: TEKNİK ARIZA</span></div>
                <div className="bg-[#FF0000] text-white font-black p-4 border-2 border-black/10 flex justify-between items-center rounded-xl shadow-lg"><span>PB: PARÇA BEKLER</span></div>
                <div className="bg-[#FF0000] text-white font-black p-4 border-2 border-black/10 flex justify-between items-center rounded-xl shadow-lg"><span>KK: KAZA KIRIM</span></div>
              </div>
              <div className="bg-black/20 p-6 rounded-3xl border border-white/5 flex flex-col justify-center">
                <div className="text-[10px] font-black text-gray-500 uppercase tracking-widest mb-4">DİĞER</div>
