                <span className="text-red-400 font-black text-[10px] uppercase tracking-[0.4em]">YENİ EXCEL BİLDİRİMİ</span>
              </div>
            )}
         </div>
         <div className="flex space-x-5">
            <button onClick={() => setShowActivity(!showActivity)} className={`px-10 py-5 rounded-[2rem] font-black text-[11px] uppercase tracking-[0.4em] transition-all shadow-2xl border-2 ${showActivity ? 'bg-blue-600 text-white border-blue-500' : 'bg-white/10 text-white border-white/20'}`}>
              {showActivity ? "ENVANTER LİSTESİ" : "FAALİYET ÇİZELGESİ"}
            </button>
            <button onClick={() => setIsAdminOpen(true)} className="bg-[#021a0c] hover:bg-emerald-900 text-white px-10 py-5 rounded-[2rem] font-black text-[11px] border-2 border-emerald-800/50 uppercase tracking-[0.4em] transition-all shadow-lg flex items-center">
              <svg className="w-4 h-4 mr-3" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path d="M10.325 4.317c.426-1.756 2.924-1.756 3.35 0a1.724 1.724 0 002.573 1.066c1.543-.94 3.31.826 2.37 2.37a1.724 1.724 0 001.065 2.572c1.756.426 1.756 2.924 0 3.35a1.724 1.724 0 00-1.066 2.573c.94 1.543-.826 3.31-2.37 2.37a1.724 1.724 0 00-2.572 1.065c-.426 1.756-2.924 1.756-3.35 0a1.724 1.724 0 00-2.573-1.066c-1.543.94-3.31-.826-2.37-2.37a1.724 1.724 0 00-1.065-2.572c-1.756-.426-1.756-2.924 0-3.35a1.724 1.724 0 001.066-2.573c-.94-1.543.826-3.31 2.37-2.37.996.608 2.296.07 2.572-1.065z" strokeWidth={2}/><path d="M15 12a3 3 0 11-6 0 3 3 0 016 0z" strokeWidth={2}/></svg>
              YÖNETİM & GELEN KUTUSU
            </button>
         </div>
      </div>

      <div className="mb-14">
         <Dashboard fleet={fleet} />
      </div>

      {showActivity ? (
        <div className="mb-24 animate-in fade-in slide-in-from-top-10 duration-1000">
           <div className="flex justify-between items-end mb-12 px-6">
              <div>
                 <h2 className="text-6xl font-black text-white uppercase tracking-tighter italic">FAALİYET ÇİZELGESİ</h2>
                 <p className="text-emerald-500 text-[10px] font-black uppercase tracking-[0.8em] mt-4 border-l-4 border-emerald-500 pl-4">Canlı Excel Verisiyle Otomatik Eşleşen Matris</p>
              </div>
           </div>

           <div className="bg-white rounded-[4rem] p-4 shadow-[0_50px_120px_rgba(0,0,0,0.8)] border-[12px] border-white/5 overflow-hidden min-h-[500px]">
             {activities.length > 0 ? (
               <ActivityGrid activities={activities} startDate={new Date(2025, 0, 1)} endDate={new Date(2025, 0, 31)} title="OCAK 2025" />
             ) : (
               <div className="h-[450px] flex flex-col items-center justify-center text-center">
                  <div className="w-16 h-16 border-4 border-emerald-500 border-t-transparent rounded-full animate-spin mb-8"></div>
