             </div>
          </div>

          <div className="bg-white p-4 rounded-[5rem] shadow-[0_50px_120px_rgba(0,0,0,0.8)] overflow-hidden border-[12px] border-white/5 min-h-[450px]">
            <table className="w-full border-collapse">
              <thead>
                <tr className="bg-slate-50 border-b-2 border-slate-100">
