                </tr>
              </thead>
              <tbody className="divide-y divide-slate-100">
                {filteredFleet.map((a, i) => (
                  <tr key={i} className="hover:bg-slate-50 cursor-pointer transition-all active:scale-[0.99] group" onClick={() => setSelectedAircraft(a)}>
                    <td className="px-14 py-12">
                       <div className="font-black text-emerald-950 text-2xl tracking-tighter group-hover:text-emerald-600 transition-colors">{a.kuyrukNo}</div>
                       <div className="text-[10px] font-black text-slate-400 uppercase mt-1">{a.tip}</div>
                    </td>
                    <td className="px-14 py-12 text-center">
                      <span className={`px-10 py-5 rounded-[1.5rem] font-black text-xs uppercase border-2 shadow-lg ${a.durum === Status.FAAL ? 'bg-emerald-50 text-emerald-700 border-emerald-200' : 'bg-red-50 text-red-700 border-red-200'}`}>{a.durum}</span>
                    </td>
                    <td className="px-14 py-12 text-sm font-black text-slate-800 uppercase tracking-widest">{a.konum}</td>
                    <td className="px-14 py-12 text-center">
                       <div className="font-black text-4xl text-blue-600 tracking-tighter">{a.faydaliSaat}</div>
                       <div className="text-[8px] font-black text-slate-400 mt-1 uppercase">KALAN SAAT</div>
                    </td>
                    <td className="px-14 py-12">
                       <div className="italic text-slate-500 text-xs font-bold leading-relaxed max-w-sm">"{a.durumAyrintisi}"</div>
                       <div className="text-[9px] text-emerald-600 font-black mt-2 uppercase tracking-tighter italic">{a.aiInterpretation}</div>
                    </td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
        </div>
      )}

      {selectedAircraft && <AircraftDetailModal aircraft={selectedAircraft} onClose={() => setSelectedAircraft(null)} />}
      {isAdminOpen && <AdminPanel notifications={notifications} initialData={fleet} onSave={(configs, data) => handleSyncFromExcel(data, configs[0].aircraftType)} onClose={() => setIsAdminOpen(false)} />}
    </Layout>
  );
};

