const App: React.FC = () => {
  const [isSplashVisible, setIsSplashVisible] = useState(true);
  const [isAdminOpen, setIsAdminOpen] = useState(false);
  const [showActivity, setShowActivity] = useState(true);
  const [isSyncing, setIsSyncing] = useState(false);

  const [fleet, setFleet] = useState<Aircraft[]>([]);
  const [activities, setActivities] = useState<AircraftActivity[]>([]);

  const [selectedAircraft, setSelectedAircraft] = useState<Aircraft | null>(null);
  const [searchTerm, setSearchTerm] = useState('');
  const [notifications, setNotifications] = useState<AppNotification[]>([]);

  const APPS_SCRIPT_URL = "https://script.google.com/macros/s/AKfycbzt9ukLiMIWNIQKzHJvw74HaEM28zBHfYao9kbv-g5zb5QxaMUS1UaH45jONA0BeMZr/exec";
  const initialSyncDone = useRef(false);

  const exportTableToExcel = (tableId: string, filename: string) => {
    const table = document.getElementById(tableId);
    if (!table) return;
    const html = table.outerHTML;
    const url = 'data:application/vnd.ms-excel,' + encodeURIComponent(html);
    const link = document.createElement('a');
    link.download = filename + '.xls';
    link.href = url;
    link.click();
  };

  const handleSyncFromExcel = useCallback((incomingData: Partial<Aircraft>[], platform: string) => {
    if (!incomingData || incomingData.length === 0) return;

    const now = new Date();
    const timestamp = now.toLocaleDateString('tr-TR') + ' ' + now.toLocaleTimeString('tr-TR');
    const today = now.getDate();
    let discoveredChanges: AppNotification[] = [];

    setFleet(prevFleet => {
      const updatedFleet = [...prevFleet];

      incomingData.forEach(incoming => {
        const existingIdx = updatedFleet.findIndex(a => a.kuyrukNo === incoming.kuyrukNo);
        const existing = existingIdx !== -1 ? updatedFleet[existingIdx] : null;

        if (existing && initialSyncDone.current) {
          let fieldChanges: string[] = [];
          let columnsChanged: string[] = [];

          ['durum', 'konum', 'durumAyrintisi', 'faydaliSaat'].forEach(col => {
            const key = col as keyof Aircraft;
            const oldVal = String(existing[key] || '').trim();
            const newVal = String(incoming[key] || '').trim();

            if (oldVal !== newVal) {
              columnsChanged.push(col.toUpperCase());
              fieldChanges.push(`${col.toUpperCase()}: "${oldVal}" -> "${newVal}"`);
            }
          });

          if (fieldChanges.length > 0) {
            discoveredChanges.push({
              id: Math.random().toString(36).substr(2, 9),
              platform: platform,
              kuyrukNo: existing.kuyrukNo,
              kolon: columnsChanged.join(', '),
              oncekiDeger: '-', // Konsolide edildiği için mesaj içinde veriliyor
              yeniDeger: '-',
              mesaj: `${existing.kuyrukNo} (${platform}) Güncellemesi: ${fieldChanges.join(' | ')}`,
              tarih: timestamp
            });
          }
        }

        if (existingIdx !== -1) {
          updatedFleet[existingIdx] = { ...updatedFleet[existingIdx], ...incoming } as Aircraft;
        } else {
          updatedFleet.push(incoming as Aircraft);
        }

        setActivities(prevActivities => {
          let newActivities = [...prevActivities];
          const existsIdx = newActivities.findIndex(act => act.kuyrukNo === incoming.kuyrukNo);
          const newCode = (incoming.assignedCode || 'F') as DailyStatusCode;

          if (existsIdx !== -1) {
            newActivities[existsIdx] = {
              ...newActivities[existsIdx],
              dailyStatuses: { ...newActivities[existsIdx].dailyStatuses, [today]: newCode }
            };
          } else {
            newActivities.push({
              kuyrukNo: incoming.kuyrukNo || '',
              cagriKodu: incoming.cagriKodu || `ORMAN-${incoming.kuyrukNo?.split('-')[1] || 'XX'}`,
              tip: incoming.tip || platform,
              dailyStatuses: { [today]: newCode }
            });
          }
          return newActivities;
        });
      });

      return updatedFleet;
    });

    if (discoveredChanges.length > 0) {
      setNotifications(prev => [...discoveredChanges, ...prev].slice(0, 100));
    }

    if (!initialSyncDone.current) initialSyncDone.current = true;
  }, []);

  const runGlobalSync = useCallback(async () => {
    setIsSyncing(true);
    const bellConfig: SheetConfig = {
      aircraftType: 'Bell-429',
      sheetId: '1D83TF8K1QG30kBv2sCqnPCMYsdSbaJfcsw-E3S5A9VQ',
      appsScriptUrl: APPS_SCRIPT_URL,
      // Fix: corrected typo 'fydaliSaat' to 'faydaliSaat' to match SheetMapping interface
      mapping: { kuyrukNo: 'A3:A8', durum: 'M3:M8', durumAyrintisi: 'N3:N8', konum: 'L3:L8', faydaliSaat: 'I3:I8', aciklama: 'O3:O8' }
    };
    try {
      const data = await fetchAircraftDataFromAppsScript(APPS_SCRIPT_URL, bellConfig);
      if (data && data.length > 0) handleSyncFromExcel(data, 'Bell-429');
    } catch (e) { console.error(e); } finally { setTimeout(() => setIsSyncing(false), 2000); }
  }, [handleSyncFromExcel]);

  useEffect(() => {
    runGlobalSync(); 
    const interval = setInterval(runGlobalSync, 20000); 
    return () => clearInterval(interval);
  }, [runGlobalSync]);

  const filteredFleet = useMemo(() => {
    return fleet.filter(a => {
      const s = searchTerm.toLowerCase();
      return a.kuyrukNo.toLowerCase().includes(s) || a.konum.toLowerCase().includes(s);
    });
  }, [fleet, searchTerm]);

  if (isSplashVisible) return <SplashScreen onComplete={() => setIsSplashVisible(false)} />;

  return (
    <Layout>
      <div className="flex justify-between items-center mb-12">
         <div className="flex items-center space-x-6">
            <div className="bg-emerald-500/10 border border-emerald-500/30 px-6 py-4 rounded-[1.8rem] flex items-center shadow-2xl backdrop-blur-md">
               <div className={`w-3 h-3 rounded-full mr-4 shadow-[0_0_10px_#10b981] ${isSyncing ? 'bg-blue-400 animate-spin' : 'bg-emerald-500 animate-pulse'}`}></div>
               <span className="text-emerald-400 font-black text-[11px] uppercase tracking-[0.5em]">
                  {isSyncing ? 'VERİLER ÇEKİLİYOR...' : 'OTOMATİK VERİ TAKİBİ AKTİF'}
               </span>
            </div>
            {notifications.length > 0 && (
              <div onClick={() => setIsAdminOpen(true)} className="bg-red-500/10 border border-red-500/30 px-6 py-4 rounded-[1.8rem] flex items-center shadow-lg cursor-pointer hover:bg-red-500/20 transition-all animate-bounce">
                <div className="bg-red-500 text-white text-[9px] font-black w-6 h-6 rounded-full flex items-center justify-center mr-3 shadow-lg">{notifications.length}</div>
                <span className="text-red-400 font-black text-[10px] uppercase tracking-[0.4em]">YENİ EXCEL BİLDİRİMİ</span>
              </div>
            )}
         </div>
         <div className="flex space-x-5">
            <button onClick={() => setShowActivity(!showActivity)} className={`px-10 py-5 rounded-[2rem] font-black text-[11px] uppercase tracking-[0.4em] transition-all shadow-2xl border-2 ${showActivity ? 'bg-blue-600 text-white border-blue-500' : 'bg-white/10 text-white border-white/20'}`}>
              {showActivity ? "ENVANTER LİSTESİ" : "FAALİYET ÇİZELGESİ"}
            </button>
            <button onClick={() => setIsAdminOpen(true)} className="bg-[#021a0c] hover:bg-emerald-900 text-white px-10 py-5 rounded-[2rem] font-black text-[11px] border-2 border-emerald-800/50 uppercase tracking-[0.4em] transition-all shadow-lg flex items-center">
              YÖNETİM & GELEN KUTUSU
            </button>
         </div>
      </div>

      <div className="mb-14"><Dashboard fleet={fleet} /></div>

      {showActivity ? (
        <div className="mb-24 animate-in fade-in slide-in-from-top-10 duration-1000">
           <div className="flex justify-between items-end mb-12 px-6">
              <div>
                 <h2 className="text-6xl font-black text-white uppercase tracking-tighter italic">FAALİYET ÇİZELGESİ</h2>
                 <p className="text-emerald-500 text-[10px] font-black uppercase tracking-[0.8em] mt-4 border-l-4 border-emerald-500 pl-4">Canlı Excel Verisiyle Otomatik Eşleşen Matris</p>
              </div>
           </div>
           <div className="bg-white rounded-[4rem] p-4 shadow-[0_50px_120px_rgba(0,0,0,0.8)] border-[12px] border-white/5 overflow-hidden">
             <ActivityGrid activities={activities} startDate={new Date(2025, 0, 1)} endDate={new Date(2025, 0, 31)} title="OCAK 2025" onExport={() => exportTableToExcel('activity-table', 'Faaliyet_Cizelgesi_Ocak_2025')} />
           </div>
        </div>
      ) : (
        <div className="mb-24 animate-in fade-in slide-in-from-bottom-10 duration-1000">
          <div className="flex justify-between items-end mb-12 px-6">
             <div>
                <h2 className="text-6xl font-black text-white uppercase tracking-tighter italic">ENVANTER LİSTESİ</h2>
                <p className="text-emerald-500 text-[10px] font-black uppercase tracking-[0.8em] mt-4 border-l-4 border-emerald-500 pl-4">Aktif Filo ve Teknik Durum Özeti</p>
             </div>
             <div className="flex items-center space-x-6">
                <button onClick={() => exportTableToExcel('inventory-table', 'Envanter_Listesi')} className="bg-emerald-600 hover:bg-emerald-500 text-white px-8 py-5 rounded-[2rem] font-black text-[10px] uppercase tracking-widest transition-all shadow-xl flex items-center">
                   <svg className="w-4 h-4 mr-2" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path d="M4 16v1a3 3 0 003 3h10a3 3 0 003-3v-1m-4-4l-4 4m0 0l-4-4m4 4V4" strokeWidth={3}/></svg>
                   EXCEL İNDİR
                </button>
                <div className="relative">
                  <input type="text" placeholder="Kuyruk No veya Konum Ara..." value={searchTerm} onChange={(e) => setSearchTerm(e.target.value)} className="w-[400px] px-12 py-5 bg-black/60 text-white rounded-[3rem] border-2 border-white/10 outline-none font-bold focus:border-emerald-500 transition-all shadow-2xl backdrop-blur-xl" />
                  <svg className="absolute left-4 top-1/2 -translate-y-1/2 w-5 h-5 text-gray-500" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path d="M21 21l-6-6m2-5a7 7 0 11-14 0 7 7 0 0114 0z" strokeWidth={3}/></svg>
                </div>
             </div>
          </div>

          <div className="bg-white p-4 rounded-[5rem] shadow-[0_50px_120px_rgba(0,0,0,0.8)] overflow-hidden border-[12px] border-white/5">
            <table id="inventory-table" className="w-full border-collapse">
              <thead>
                <tr className="bg-emerald-800 text-white">
                  <th className="px-10 py-8 text-left text-xs font-black uppercase tracking-[0.4em]">HAVA ARACI</th>
                  <th className="px-10 py-8 text-center text-xs font-black uppercase tracking-[0.4em]">DURUM</th>
                  <th className="px-10 py-8 text-left text-xs font-black uppercase tracking-[0.4em]">KONUM</th>
                  <th className="px-10 py-8 text-center text-xs font-black uppercase tracking-[0.4em]">FAYDALI SAAT</th>
                  <th className="px-10 py-8 text-left text-xs font-black uppercase tracking-[0.4em]">EXCEL AÇIKLAMA METNİ</th>
                </tr>
              </thead>
              <tbody className="divide-y divide-slate-100">
                {filteredFleet.map((a, i) => (
                  <tr key={i} className="hover:bg-slate-50 cursor-pointer transition-all active:scale-[0.99] group" onClick={() => setSelectedAircraft(a)}>
                    <td className="px-10 py-8">
                       <div className="font-black text-emerald-950 text-xl tracking-tighter group-hover:text-emerald-600 transition-colors">{a.kuyrukNo}</div>
                       <div className="text-[9px] font-black text-slate-400 uppercase mt-1">{a.tip}</div>
