                    <td className="px-10 py-8 text-center">
                      <span className={`px-8 py-4 rounded-[1.5rem] font-black text-[10px] uppercase border-2 shadow-sm ${a.durum === Status.FAAL ? 'bg-emerald-50 text-emerald-700 border-emerald-200' : 'bg-red-50 text-red-700 border-red-200'}`}>{a.durum}</span>
