                       <div className="italic text-slate-500 text-xs font-bold leading-relaxed max-w-md">
                          {a.aciklama && a.aciklama !== '-' ? `"${a.aciklama}"` : "-"}
                       </div>
                    </td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
        </div>
      )}

      {selectedAircraft && <AircraftDetailModal aircraft={selectedAircraft} onClose={() => setSelectedAircraft(null)} />}
      {isAdminOpen && <AdminPanel notifications={notifications} initialData={fleet} onSave={(configs, data) => handleSyncFromExcel(data, configs[0].aircraftType)} onClose={() => setIsAdminOpen(false)} />}
    </Layout>
  );
};

