import { SheetConfig, Aircraft, Status, StatusType, DailyStatusCode } from '../types';

/**
 * Durum metinlerini analiz ederek faaliyet kodlarını atar.
 * Daha geniş bir anahtar kelime havuzu ve esnek eşleşme sağlar.
 */
export const analyzeStatus = (item: any): { code: DailyStatusCode, interpretation: string } => {
  const detail = String(item.durumAyrintisi || '').toLocaleLowerCase('tr-TR').trim();
  const desc = String(item.aciklama || '').toLocaleLowerCase('tr-TR').trim();
  const durumStr = String(item.durum || '').toLocaleUpperCase('tr-TR').trim();
  const fullText = `${detail} ${desc}`;

  // 1. ADIM: KRİTİK ANAHTAR KELİME ANALİZİ
  if (fullText.includes('kaza') || fullText.includes('kırım') || fullText.includes('hasar')) 
    return { code: 'KK', interpretation: 'Sistem metinlerde "Kaza/Kırım" ifadesi tespit etti.' };

  if (fullText.includes('bakım bekler') || fullText.includes('sıra bekliyor') || fullText.includes('bakıma alınacak')) 
    return { code: 'BB', interpretation: 'Sistem metinlerde "Bakım Bekler" tespiti yaptı.' };

  if (fullText.includes('yıllık') || fullText.includes('bakım') || fullText.includes('periyodik') || 
      /\b\d+h\b/.test(fullText) || fullText.includes('bakımı yapılıyor')) 
    return { code: 'B', interpretation: 'Sistem metinlerde aktif "Bakım" süreci tespit etti.' };

  if (fullText.includes('kabul muayene') || fullText.includes('test uçuşu') || fullText.includes('teslimat')) 
    return { code: 'KM', interpretation: 'Sistem metinlerde "Kabul Muayenesi" tespiti yaptı.' };

  if (fullText.includes('parça bekler') || fullText.includes('parça bekleme') || fullText.includes('yedek parça') || fullText.includes('p/n') || fullText.includes('sipariş edildi')) 
    return { code: 'PB', interpretation: 'Sistem metinlerde "Parça Bekleme" tespiti yaptı.' };

  if (fullText.includes('arıza') || fullText.includes('teknik sorun') || fullText.includes('gayri faal') || fullText.includes('arızalı')) 
    return { code: 'A', interpretation: 'Sistem metinlerde "Arıza" tespiti yaptı.' };

  // 2. ADIM: ANA DURUM KOLONU KONTROLÜ (GAYRI FAAL tespiti)
  const isGayriFaalExplicit = durumStr.includes('GAYRİ') || 
                              durumStr.includes('GAYRI') || 
                              durumStr.includes('G.FAAL') || 
                              durumStr.includes('G. FAAL') ||
                              durumStr.includes('GAYRIFAAL') ||
                              (durumStr.includes('FAAL') && (durumStr.includes('DEĞİL') || durumStr.includes('NO')));

  if (isGayriFaalExplicit) {
    return { code: 'X', interpretation: 'Hava aracı "GAYRI FAAL" işaretlenmiş fakat detay metni analiz edilemedi.' };
  }

  // Hiçbir kısıt yoksa Faal kabul et
  return { code: 'F', interpretation: 'Hava aracı "FAAL" olarak okundu.' };
};

/**
 * Google Apps Script üzerinden veri çeker ve otomatik analiz eder.
 */
export const fetchAircraftDataFromAppsScript = async (url: string, config: SheetConfig): Promise<Partial<Aircraft>[]> => {
  try {
    const response = await fetch(url, {
      method: 'POST',
      headers: {
        'Content-Type': 'text/plain;charset=utf-8',
      },
      body: JSON.stringify({
        sheetId: config.sheetId,
        mapping: config.mapping
      })
    });

    if (!response.ok) throw new Error(`HTTP Error: ${response.status}`);

    const data = await response.json();
    if (data.error || !Array.isArray(data)) return [];

    return data.map((item: any) => {
      const analysis = analyzeStatus(item);
      const kuyrukNo = String(item.kuyrukNo || '').trim();

      return {
        kuyrukNo: kuyrukNo,
        cagriKodu: `ORMAN-${kuyrukNo.split('-')[1] || 'XX'}`,
        durum: (analysis.code !== 'F') ? Status.GAYRI_FAAL : Status.FAAL,
        durumTipi: analysis.code === 'B' || analysis.code === 'BB' ? StatusType.BAKIM : 
                   analysis.code === 'A' || analysis.code === 'PB' ? StatusType.ARIZA : StatusType.NONE,
        durumAyrintisi: String(item.durumAyrintisi || '-'),
        konum: String(item.konum || 'ANKARA'),
        faydaliSaat: parseInt(item.faydaliSaat) || 0,
        aciklama: String(item.aciklama || ''),
        guncellemeTarihi: new Date().toLocaleString('tr-TR'),
        durumBaslangic: new Date().toISOString().split('T')[0],
        maintenanceHours: [{ bakimTuru: 'PERİYODİK', kalanSaat: parseInt(item.faydaliSaat) || 0 }],
        photos: [`https://picsum.photos/seed/${kuyrukNo}/800/600`],
        platformTipi: 'H',
        tip: 'Bell-429',
        assignedCode: analysis.code,
        aiInterpretation: analysis.interpretation
      };
    });
  } catch (error) {
    console.error("Veri alma başarısız oldu:", error);
    return [];
  }
};

import React, { useState, useMemo, useEffect, useCallback, useRef } from 'react';
import Layout from './components/Layout';
import Dashboard from './components/Dashboard';
