                                  onDoubleClick={() => isAssignment && setSelectedNotifyForEdit(n)}
                                  className={`group border-b border-white/5 transition-all ${isAssignment ? 'bg-orange-600/20 hover:bg-orange-600/30 cursor-pointer' : 'hover:bg-white/5'}`}
                                >
                                  <td className="px-8 py-6 text-emerald-400 font-black text-xs">{n.tarih}</td>
                                  <td className="px-8 py-6 text-white font-black text-lg italic tracking-tighter">
                                     {n.kuyrukNo}
                                     <div className={`text-[8px] uppercase mt-1 ${isAssignment ? 'text-orange-400 font-black' : 'text-gray-500'}`}>
                                        {isAssignment ? '● OTOMATİK ANALİZ ATAMASI' : n.platform}
                                     </div>
                                  </td>
                                  <td className="px-8 py-6">
                                    <div className={`p-4 rounded-2xl text-white text-sm font-medium italic border transition-all ${isAssignment ? 'bg-orange-500/10 border-orange-500/20' : 'bg-black/20 border-white/5'}`}>
                                       {n.mesaj}
                                    </div>
                                  </td>
                                </tr>
                              );
                            })}
                          </tbody>
                        </table>
                      </div>
                    </div>
                   )}
                </div>
            </div>
          ) : (
            <div className="flex-1 flex flex-col p-10">
                <div className="p-10 border-b border-green-900/40 flex justify-between items-center bg-black/10 rounded-t-[3rem]">
                  <h1 className="text-white text-3xl font-black uppercase italic">Excel Entegrasyonu</h1>
                  <button onClick={handleManualSync} disabled={isLoading} className="bg-emerald-600 hover:bg-emerald-500 text-white px-10 py-5 rounded-[2rem] font-black text-xs uppercase shadow-xl disabled:opacity-50 transition-all">
                    {isLoading ? "VERİLER ÇEKİLİYOR..." : "MANUEL YENİLE VE ANALİZ ET"}
                  </button>
                </div>
                <div className="bg-[#021a0c] p-10 flex-1 overflow-y-auto custom-scrollbar rounded-b-[3rem]">
                   <table className="w-full text-left bg-white/5 rounded-3xl overflow-hidden">
                      <thead className="bg-emerald-800/40 text-emerald-400">
                         <tr>
                            <th className="px-8 py-5 text-[10px] font-black uppercase">Hava Aracı</th>
                            <th className="px-8 py-5 text-[10px] font-black uppercase">Konum</th>
                            <th className="px-8 py-5 text-[10px] font-black uppercase">Analiz Kodu</th>
                            <th className="px-8 py-5 text-[10px] font-black uppercase">Detay / Açıklama</th>
                         </tr>
                      </thead>
                      <tbody>
                        {previewData.map((row, i) => (
                          <tr key={i} className="border-b border-white/5 text-white text-sm font-medium">
                            <td className="px-8 py-4 font-bold">{row.kuyrukNo}</td>
                            <td className="px-8 py-4">{row.konum}</td>
                            <td className="px-8 py-4">
                               <span className="bg-blue-500/20 text-blue-400 px-3 py-1 rounded-lg text-xs font-black">{row.assignedCode}</span>
                            </td>
                            <td className="px-8 py-4 italic text-gray-400">
                               <div className="text-[10px] text-emerald-500 mb-1">{row.durumAyrintisi}</div>
                               <div className="text-xs">"{row.aciklama}"</div>
                            </td>
                          </tr>
                        ))}
                      </tbody>
                   </table>
                </div>
            </div>
          )}

          {/* ATAMA DEĞİŞTİRME MODALI */}
          {selectedNotifyForEdit && (
            <div className="absolute inset-0 z-50 bg-black/80 backdrop-blur-md flex items-center justify-center p-10">
              <div className="bg-emerald-950 border-2 border-emerald-500/50 p-12 rounded-[3rem] max-w-lg w-full shadow-[0_0_100px_rgba(249,115,22,0.4)]">
                <h3 className="text-white text-2xl font-black uppercase italic mb-8 border-b border-emerald-500/20 pb-4">Analiz Kodunu Düzelt</h3>
                <p className="text-emerald-400 text-xs font-bold uppercase mb-4">Hava Aracı: {selectedNotifyForEdit.kuyrukNo}</p>
                <div className="bg-orange-500/10 border border-orange-500/20 p-4 rounded-xl mb-8">
                   <p className="text-orange-400 text-[10px] font-black uppercase mb-1">Tespit Edilen Mesaj:</p>
                   <p className="text-white text-xs italic">"{selectedNotifyForEdit.mesaj}"</p>
                </div>

                <div className="grid grid-cols-4 gap-4 mb-12">
                   {codeOptions.map(code => (
                     <button 
                       key={code}
                       onClick={() => {
                          if (onOverride) onOverride(selectedNotifyForEdit.kuyrukNo, code);
                          setSelectedNotifyForEdit(null);
                       }}
                       className="aspect-square bg-emerald-900 border border-emerald-800 hover:bg-orange-500 hover:text-white transition-all rounded-2xl flex items-center justify-center font-black text-lg text-emerald-400"
                     >
                       {code || 'F'}
                     </button>
                   ))}
                </div>

                <button 
                  onClick={() => setSelectedNotifyForEdit(null)}
                  className="w-full py-5 rounded-[1.5rem] bg-red-500/10 text-red-500 font-black text-xs uppercase hover:bg-red-500/20 transition-all"
                >
                  İPTAL
                </button>
              </div>
            </div>
          )}
        </div>
      </div>
    </div>
  );
};

