/**
 * Durum metinlerini kelime kelime ve cümle bazlı analiz ederek en doğru faaliyet kodunu atar.
 */
export const analyzeStatus = (item: any): { code: DailyStatusCode, interpretation: string } => {
  const detail = String(item.durumAyrintisi || '').toLocaleLowerCase('tr-TR').trim();
  const desc = String(item.aciklama || '').toLocaleLowerCase('tr-TR').trim();
  const durumStr = String(item.durum || '').toLocaleUpperCase('tr-TR').trim();
  const fullText = `${detail} ${desc}`;

  // 1. KAZA / KIRIM ANALİZİ
  if (fullText.includes('kaza') || fullText.includes('kırım') || fullText.includes('hasar') || fullText.includes('enkaz')) 
    return { code: 'KK', interpretation: 'Metin analizi sonucunda "Kaza/Kırım/Hasar" tespiti yapıldı.' };

  // 2. PARÇA BEKLEME ANALİZİ
  if (fullText.includes('parça') && (fullText.includes('bekleniyor') || fullText.includes('sipariş') || fullText.includes('temin') || fullText.includes('haber') || fullText.includes('bekle'))) {
    return { code: 'PB', interpretation: 'Sistem metinlerdeki bağlamdan dolayı "Parça Bekler" ataması yaptı.' };
  }
  if (fullText.includes('p/n') || fullText.includes('pn ') || fullText.includes('part number')) {
    return { code: 'PB', interpretation: 'Metinde parça numarası (P/N) tespit edildiği için "Parça Bekler" olarak atandı.' };
  }

  // 3. BAKIM ANALİZİ
  if (fullText.includes('yıllık') || fullText.includes('bakım') || fullText.includes('periyodik') || 
      /\b\d+h\b/.test(fullText) || fullText.includes('bakımı yapılıyor') || fullText.includes('revizyon')) {

    if (fullText.includes('bekliyor') || fullText.includes('sıra') || fullText.includes('alınacak')) {
      return { code: 'BB', interpretation: 'Hava aracının "Bakım Beklediği" tespit edildi.' };
    }
    return { code: 'B', interpretation: 'Hava aracının aktif "Bakım" sürecinde olduğu tespit edildi.' };
  }

  // 4. KABUL MUAYENE ANALİZİ
  if (fullText.includes('kabul') || fullText.includes('muayene') || fullText.includes('test uçuşu') || fullText.includes('teslimat')) 
    return { code: 'KM', interpretation: 'Metin analizi sonucunda "Kabul Muayene" süreci tespit edildi.' };

  // 5. ARIZA ANALİZİ
  if (fullText.includes('arıza') || fullText.includes('teknik sorun') || fullText.includes('problem') || fullText.includes('çalışmıyor') || fullText.includes('faal değil')) 
    return { code: 'A', interpretation: 'Metin analizi sonucunda aktif bir "Arıza/Teknik Sorun" tespit edildi.' };

  // 6. ANA DURUM KOLONU KONTROLÜ
  const isGayriFaalExplicit = durumStr.includes('GAYRİ') || 
                              durumStr.includes('GAYRI') || 
                              durumStr.includes('G.FAAL') || 
                              durumStr.includes('G. FAAL') ||
                              durumStr.includes('GAYRIFAAL') ||
                              (durumStr.includes('FAAL') && (durumStr.includes('DEĞİL') || durumStr.includes('YOK')));

  if (isGayriFaalExplicit) {
    return { code: 'X', interpretation: 'Detaylı analiz yapılamadı ancak durum "GAYRI FAAL" olduğu için X atandı.' };
  }

  return { code: 'F', interpretation: 'Herhangi bir kısıt tespit edilmedi, "FAAL" kabul edildi.' };
};

/**
 * Google Apps Script üzerinden veri çeker ve cümle cümle analiz eder.
 */
export const fetchAircraftDataFromAppsScript = async (url: string, config: SheetConfig): Promise<Partial<Aircraft>[]> => {
  try {
    const response = await fetch(url, {
      method: 'POST',
      headers: {
        'Content-Type': 'text/plain;charset=utf-8',
      },
      body: JSON.stringify({
        sheetId: config.sheetId,
        mapping: config.mapping
      })
    });

    if (!response.ok) throw new Error(`HTTP Error: ${response.status}`);

    const data = await response.json();
    if (data.error || !Array.isArray(data)) return [];

    return data.map((item: any) => {
      const analysis = analyzeStatus(item);
      const kuyrukNo = String(item.kuyrukNo || '').trim();

      return {
        kuyrukNo: kuyrukNo,
        cagriKodu: `ORMAN-${kuyrukNo.split('-')[1] || 'XX'}`,
        durum: (analysis.code !== 'F') ? Status.GAYRI_FAAL : Status.FAAL,
        durumTipi: analysis.code === 'B' || analysis.code === 'BB' ? StatusType.BAKIM : 
                   analysis.code === 'A' || analysis.code === 'PB' ? StatusType.ARIZA : StatusType.NONE,
        durumAyrintisi: String(item.durumAyrintisi || '-'),
        konum: String(item.konum || 'ANKARA'),
        faydaliSaat: parseInt(item.faydaliSaat) || 0,
        govdeUcusSaati: String(item.govdeUcusSaati || '-'),
        aciklama: String(item.aciklama || ''),
        guncellemeTarihi: new Date().toLocaleString('tr-TR'),
        durumBaslangic: new Date().toISOString().split('T')[0],
        maintenanceHours: [{ bakimTuru: 'PERİYODİK', kalanSaat: parseInt(item.faydaliSaat) || 0 }],
        photos: [`https://picsum.photos/seed/${kuyrukNo}/800/600`],
        platformTipi: 'H',
        tip: config.aircraftType,
        assignedCode: analysis.code,
        aiInterpretation: analysis.interpretation
      };
    });
  } catch (error) {
    console.error("Veri alma başarısız oldu:", error);
    return [];
  }
};

