Bu talebinize göre hem **Google Apps Script** kodunu (komut.js) en esnek ve güçlü hale getiriyoruz hem de **Frontend** tarafındaki mapping ve veri işleme mantığını son verdiğiniz sütun bilgilerine göre mühürlüyoruz.

### 1. Google Apps Script (komut.js) - Yeni Nesil
Bu script artık sadece tek bir sütunu değil, belirttiğiniz `V3:AI14` gibi çoklu sütun aralıklarını da dizi olarak döndürebilecek kapasitededir. Ayrıca sayfa ismini (`GÜNLÜK DURUM`) dinamik olarak seçer.

```javascript
/**
 * OGM HAVACILIK - GENEL VERİ ÇEKME SCRİPTİ (V4)
 * Bu script hem Bell-429 hem de AT-802 için ortaktır.
 * Mapping ve Sayfa ismi frontend'den gönderilir.
 */
function doPost(e) {
  try {
    var contents = JSON.parse(e.postData.contents);
    var ss = SpreadsheetApp.openById(contents.sheetId);

    // Sayfa ismi gönderilmişse ona git, yoksa ilk sayfayı al
    var sheet = contents.sheetName ? ss.getSheetByName(contents.sheetName) : ss.getSheets()[0];

    if (!sheet) {
      throw new Error("Hata: '" + (contents.sheetName || "İlk Sayfa") + "' isimli sayfa bulunamadı.");
    }

    var mapping = contents.mapping;
    var rawData = {};

    // Her bir mapping anahtarı için ilgili hücre aralığını oku
    Object.keys(mapping).forEach(function(key) {
      if (mapping[key]) {
        rawData[key] = sheet.getRange(mapping[key]).getValues();
      }
    });

    // Kuyruk No sütununu referans alarak satırları döngüye sok
    var numRows = rawData.kuyrukNo.length;
    var results = [];

    for (var i = 0; i < numRows; i++) {
      var item = {};
      Object.keys(rawData).forEach(function(key) {
        var rowValues = rawData[key][i];
        // Eğer aralık tek bir sütunsa değeri direkt al, çoklu sütunsa (V:AI gibi) dizi olarak al
        item[key] = rowValues.length === 1 ? rowValues[0] : rowValues;
      });

      // Sadece Kuyruk No dolu olan satırları ekle
      if (item.kuyrukNo && String(item.kuyrukNo).trim() !== "") {
        results.push(item);
      }
    }

    return ContentService.createTextOutput(JSON.stringify(results))
      .setMimeType(ContentService.MimeType.JSON);

  } catch (err) {
    return ContentService.createTextOutput(JSON.stringify({ 
      error: true, 
      message: err.toString(),
      details: "Lütfen Spreadsheet ID ve Sayfa İsmini kontrol edin."
    })).setMimeType(ContentService.MimeType.JSON);
  }
}

function doGet(e) {
  return ContentService.createTextOutput("OGM Apps Script Aktif. Lütfen POST isteği gönderin.");
}
```

