Talebiniz doğrultusunda **AT-802** için yeni sağladığınız Apps Script URL'sini sisteme entegre ettim. Ayrıca hem **AT-802** hem de **Bell-429** için belirttiğiniz hücre aralıklarını (B3:B14, F3:F14, V3:AI14 vb.) ve sayfa isimlerini mühürledim.

### Güncellenmiş Google Apps Script (komut.js)
Bu kodu Google Sheets üzerindeki her iki projenize de yapıştırıp **"Yeni Dağıtım (New Deployment)"** olarak yayınlayabilirsiniz. Her iki platform için de tek bir script yeterlidir; çünkü mapping bilgileri frontend tarafından dinamik olarak gönderilmektedir.

```javascript
function doPost(e) {
  try {
    var contents = JSON.parse(e.postData.contents);
    var ss = SpreadsheetApp.openById(contents.sheetId);
    var sheet = contents.sheetName ? ss.getSheetByName(contents.sheetName) : ss.getSheets()[0];
    var mapping = contents.mapping;
    var rawData = {};

    Object.keys(mapping).forEach(function(key) {
      if (mapping[key]) {
        rawData[key] = sheet.getRange(mapping[key]).getValues();
      }
    });

    var numRows = rawData.kuyrukNo.length;
    var results = [];
    for (var i = 0; i < numRows; i++) {
      var item = {};
      Object.keys(rawData).forEach(function(key) {
        var rowValues = rawData[key][i];
        item[key] = rowValues.length === 1 ? rowValues[0] : rowValues;
      });
      if (item.kuyrukNo && String(item.kuyrukNo).trim() !== "") {
        results.push(item);
      }
    }
    return ContentService.createTextOutput(JSON.stringify(results)).setMimeType(ContentService.MimeType.JSON);
  } catch (err) {
    return ContentService.createTextOutput(JSON.stringify({ error: err.toString() })).setMimeType(ContentService.MimeType.JSON);
  }
}
