import React, { useState } from 'react';
import { SheetConfig, Aircraft, AppNotification, DailyStatusCode } from '../types';
import { fetchAircraftDataFromAppsScript } from '../services/sheetService';

interface AdminPanelProps {
  onSave: (configs: SheetConfig[], data: Partial<Aircraft>[]) => void;
  onOverride?: (kuyrukNo: string, code: DailyStatusCode) => void;
  onClose: () => void;
  notifications: AppNotification[];
  initialData?: any[]; 
}

const AdminPanel: React.FC<AdminPanelProps> = ({ onSave, onOverride, onClose, notifications, initialData = [] }) => {
  const [activeSubTab, setActiveSubTab] = useState('notifications'); 
  const [previewData, setPreviewData] = useState<any[]>(initialData);
  const [isLoading, setIsLoading] = useState(false);
  const [selectedNotifyForEdit, setSelectedNotifyForEdit] = useState<AppNotification | null>(null);

  const BELL_SCRIPT_URL = "https://script.google.com/macros/s/AKfycbzt9ukLiMIWNIQKzHJvw74HaEM28zBHfYao9kbv-g5zb5QxaMUS1UaH45jONA0BeMZr/exec";
  const AT802_SCRIPT_URL = "https://script.google.com/macros/s/AKfycby0-QuoC0Do_W_7Oxkz8T7sDAlv_AO585eJ33_nIR93DVj4CoY1-MHOfixH3ZHiHiCx/exec";

  const BELL_SHEET_ID = "1D83TF8K1QG30kBv2sCqnPCMYsdSbaJfcsw-E3S5A9VQ";
  const AT802_SHEET_ID = "1vyGHaD5k1H11Fokl5wUKB0fadJGmOugjbd42zLdtDz4";

  const exportTableToExcel = (tableId: string, filename: string) => {
    const table = document.getElementById(tableId);
    if (!table) return;
    const html = `
      <html xmlns:o="urn:schemas-microsoft-com:office:office" xmlns:x="urn:schemas-microsoft-com:office:excel" xmlns="http://www.w3.org/TR/REC-html40">
      <head><meta charset="UTF-8"></head>
      <body>${table.outerHTML}</body>
      </html>
    `;
    const url = 'data:application/vnd.ms-excel;base64,' + btoa(unescape(encodeURIComponent(html)));
    const link = document.createElement('a');
    link.download = filename + '.xls';
    link.href = url;
    link.click();
  };

  const handleManualSync = async (type: 'Bell-429' | 'AT-802') => {
    setIsLoading(true);
    let mapping;
    let sheetId;
    let sheetName;
    let scriptUrl;

    if (type === 'Bell-429') {
      mapping = { 
        kuyrukNo: 'A3:A8', 
        durum: 'M3:M8', 
        durumAyrintisi: 'N3:N8', 
        konum: 'L3:L8', 
        faydaliSaat: 'I3:I8', 
        aciklama: 'O3:O8',
        govdeUcusSaati: 'E3:E8'
      };
      sheetId = BELL_SHEET_ID;
      scriptUrl = BELL_SCRIPT_URL;
    } else {
      mapping = { 
        kuyrukNo: 'B3:B14', 
        durum: 'C3:C14', 
        durumAyrintisi: 'D3:D14', 
        konum: 'E3:E14', 
        faydaliSaat: 'V3:AI14', 
        aciklama: 'AL3:AL14',
        govdeUcusSaati: 'F3:F14'
      };
      sheetId = AT802_SHEET_ID;
      sheetName = 'GÜNLÜK DURUM';
      scriptUrl = AT802_SCRIPT_URL;
    }

    const config: SheetConfig = {
      aircraftType: type,
      sheetId: sheetId,
      sheetName: sheetName,
      appsScriptUrl: scriptUrl,
      mapping: mapping
    };
    try {
      const results = await fetchAircraftDataFromAppsScript(scriptUrl, config);
      if (results.length > 0) {
        setPreviewData(results);
        onSave([config], results);
      }
    } catch (e) { console.error(e); }
    setIsLoading(false);
  };

  const codeOptions: DailyStatusCode[] = ['B', 'BB', 'KM', 'A', 'PB', 'KK', 'X', 'F'];

  return (
    <div className="fixed inset-0 z-[200] bg-black/95 backdrop-blur-2xl flex items-center justify-center p-4">
      <div className="bg-[#052e16] w-full max-w-[1700px] h-[95vh] rounded-[4rem] border border-green-800/40 flex overflow-hidden shadow-[0_0_100px_rgba(0,0,0,1)]">

        <div className="w-80 bg-[#021a0c] border-r border-green-900/40 p-10 flex flex-col">
          <div className="mb-14">
            <h2 className="text-white font-black text-2xl tracking-tighter uppercase">ADMİN PANELİ</h2>
            <p className="text-green-600 text-[8px] font-black tracking-[0.6em] mt-3 italic uppercase opacity-50">Sistem Denetim Merkezi</p>
          </div>

          <nav className="space-y-10 flex-grow">
            <div>
              <span className="text-[10px] font-black text-gray-700 uppercase tracking-[0.4em] block mb-6 ml-2">CANLI DENETİM</span>
              <button onClick={() => setActiveSubTab('notifications')} className={`w-full flex items-center justify-between px-6 py-5 rounded-[2rem] font-black text-[11px] uppercase tracking-widest transition-all ${activeSubTab === 'notifications' ? 'bg-emerald-600 text-white shadow-xl' : 'text-gray-500 hover:text-white'}`}>
                <span>GELEN KUTUSU</span>
                {notifications.length > 0 && <span className="bg-red-500 text-white text-[9px] w-6 h-6 rounded-full flex items-center justify-center">{notifications.length}</span>}
              </button>
            </div>

            <div className="pl-6 border-l-2 border-green-900/30 space-y-6">
              <span className="text-[10px] font-black text-gray-700 uppercase tracking-[0.4em] block mb-2 ml-2">ENTEGRASYON</span>
              <button onClick={() => setActiveSubTab('excel')} className={`w-full text-left px-5 py-3 font-black text-[10px] uppercase tracking-widest ${activeSubTab === 'excel' ? 'text-emerald-400 bg-emerald-500/10 rounded-xl' : 'text-gray-600 hover:text-white'}`}>○ EXCEL MODÜLLERİ</button>
            </div>
          </nav>
          <button onClick={onClose} className="py-6 rounded-[2rem] border-2 border-red-900/30 text-red-500 font-black text-[10px] uppercase tracking-[0.3em] hover:bg-red-950/30 transition-all">PANELİ KAPAT</button>
        </div>

        <div className="flex-1 flex flex-col overflow-hidden bg-[#052e16] relative">
          {activeSubTab === 'notifications' ? (
            <div className="flex-1 flex flex-col overflow-hidden">
                <div className="p-10 border-b border-green-900/40 bg-black/10 flex justify-between items-center">
                   <div>
                      <h1 className="text-white text-4xl font-black uppercase tracking-tighter italic">Gelen Kutusu</h1>
                      <p className="text-emerald-500 text-[10px] font-bold uppercase tracking-[0.5em] mt-3">NOT: TURUNCU SATIRLAR CÜMLE ANALİZİ SONUCU ATANAN KODLARDIR</p>
                   </div>
                   <button onClick={() => exportTableToExcel('inbox-table', 'Gelen_Kutusu_Loglari')} className="bg-emerald-600 hover:bg-emerald-500 text-white px-10 py-5 rounded-[2rem] font-black text-[10px] uppercase tracking-[0.3em] shadow-xl flex items-center">
                      <svg className="w-4 h-4 mr-3" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path d="M4 16v1a3 3 0 003 3h10a3 3 0 003-3v-1m-4-4l-4 4m0 0l-4-4m4 4V4" strokeWidth={3}/></svg>
                      GELEN KUTUSU EXCEL İNDİR
                   </button>
                </div>

                <div className="flex-1 p-10 overflow-hidden">
                   {notifications.length === 0 ? (
                     <div className="h-full flex flex-col items-center justify-center text-gray-700 uppercase font-black tracking-[0.5em] italic opacity-30">Henüz bir değişiklik tespit edilmedi</div>
                   ) : (
                    <div className="bg-white/5 rounded-[2.5rem] border border-green-900/30 overflow-hidden flex flex-col shadow-2xl h-full">
                      <div className="overflow-y-auto custom-scrollbar">
                        <table id="inbox-table" className="w-full text-left border-collapse">
                          <thead className="sticky top-0 z-10">
                            <tr className="bg-emerald-700 text-white">
                              <th className="px-8 py-6 font-black text-[11px] uppercase tracking-widest border-r border-emerald-800">TARİH / SAAT</th>
                              <th className="px-8 py-6 font-black text-[11px] uppercase tracking-widest border-r border-emerald-800">KUYRUK NO</th>
                              <th className="px-8 py-6 font-black text-[11px] uppercase tracking-widest">GÜNCELLEME VE ANALİZ DETAYI (DÜZENLEMEK İÇİN ÇİFT TIKLA)</th>
                            </tr>
                          </thead>
                          <tbody className="divide-y divide-white/10">
                            {notifications.map((n) => {
                              const isAssignment = n.kolon === 'ANALİZ / ÇİZELGE' || n.kolon === 'ATAMA KODU';
                              return (
                                <tr 
                                  key={n.id} 
                                  onDoubleClick={() => isAssignment && setSelectedNotifyForEdit(n)}
                                  className={`group border-b border-white/5 transition-all ${isAssignment ? 'bg-orange-600/20 hover:bg-orange-600/30 cursor-pointer' : 'hover:bg-white/5'}`}
                                >
                                  <td className="px-8 py-6 text-emerald-400 font-black text-xs">{n.tarih}</td>
                                  <td className="px-8 py-6 text-white font-black text-lg italic tracking-tighter">
                                     {n.kuyrukNo}
                                     <div className={`text-[8px] uppercase mt-1 ${isAssignment ? 'text-orange-400 font-black' : 'text-gray-500'}`}>
                                        {isAssignment ? `● ${n.platform} ANALİZ ATAMASI` : n.platform}
                                     </div>
                                  </td>
                                  <td className="px-8 py-6">
                                    <div className={`p-4 rounded-2xl text-white text-sm font-medium italic border transition-all ${isAssignment ? 'bg-orange-500/10 border-orange-500/20' : 'bg-black/20 border-white/5'}`}>
                                       {n.mesaj}
                                    </div>
                                  </td>
                                </tr>
                              );
                            })}
                          </tbody>
                        </table>
                      </div>
                    </div>
                   )}
                </div>
            </div>
          ) : (
            <div className="flex-1 flex flex-col p-10">
                <div className="p-10 border-b border-green-900/40 flex justify-between items-center bg-black/10 rounded-t-[3rem]">
                  <div>
                    <h1 className="text-white text-3xl font-black uppercase italic">Excel Entegrasyon Modülleri</h1>
                    <p className="text-emerald-500 text-[10px] font-black uppercase tracking-widest mt-2">Aktif Platformlar: Bell-429, AT-802 (Sayfa: GÜNLÜK DURUM)</p>
                  </div>
                  <div className="flex space-x-4">
                    <button onClick={() => handleManualSync('Bell-429')} disabled={isLoading} className="bg-emerald-600 hover:bg-emerald-500 text-white px-8 py-4 rounded-xl font-black text-[10px] uppercase shadow-xl disabled:opacity-50 transition-all">
                      BELL-429 YENİLE
                    </button>
                    <button onClick={() => handleManualSync('AT-802')} disabled={isLoading} className="bg-blue-600 hover:bg-blue-500 text-white px-8 py-4 rounded-xl font-black text-[10px] uppercase shadow-xl disabled:opacity-50 transition-all">
                      AT-802 YENİLE
                    </button>
                  </div>
                </div>
                <div className="bg-[#021a0c] p-10 flex-1 overflow-y-auto custom-scrollbar rounded-b-[3rem]">
                   <table className="w-full text-left bg-white/5 rounded-3xl overflow-hidden border-collapse">
                      <thead className="bg-emerald-800/40 text-emerald-400">
                         <tr>
                            <th className="px-8 py-5 text-[10px] font-black uppercase border-b border-green-900/40">Platform</th>
                            <th className="px-8 py-5 text-[10px] font-black uppercase border-b border-green-900/40">Kuyruk</th>
                            <th className="px-8 py-5 text-[10px] font-black uppercase border-b border-green-900/40">Gövde Saati</th>
                            <th className="px-8 py-5 text-[10px] font-black uppercase border-b border-green-900/40">Faydalı Saat</th>
                            <th className="px-8 py-5 text-[10px] font-black uppercase border-b border-green-900/40">Analiz Kodu</th>
                            <th className="px-8 py-5 text-[10px] font-black uppercase border-b border-green-900/40">Detay Analizi</th>
                         </tr>
                      </thead>
                      <tbody>
                        {previewData.map((row, i) => (
                          <tr key={i} className="border-b border-white/5 text-white text-sm font-medium hover:bg-white/5 transition-colors">
                            <td className="px-8 py-4"><span className="text-[10px] font-black bg-emerald-900/50 px-2 py-1 rounded text-emerald-400">{row.tip || "BELİRSİZ"}</span></td>
                            <td className="px-8 py-4 font-bold">{row.kuyrukNo}</td>
                            <td className="px-8 py-4 text-blue-400 font-black">{row.govdeUcusSaati || '-'}</td>
                            <td className="px-8 py-4 text-emerald-400 font-black">{row.faydaliSaat}</td>
                            <td className="px-8 py-4">
                               <span className={`px-3 py-1 rounded-lg text-xs font-black ${row.assignedCode === 'F' ? 'bg-emerald-500/20 text-emerald-400' : 'bg-orange-500/20 text-orange-400'}`}>{row.assignedCode}</span>
                            </td>
                            <td className="px-8 py-4 italic text-gray-400">
                               <div className="text-[10px] text-emerald-500 mb-1 font-black">{row.durumAyrintisi}</div>
                               <div className="text-xs truncate max-w-xs">"{row.aciklama}"</div>
                            </td>
                          </tr>
                        ))}
                      </tbody>
                   </table>
                </div>
            </div>
          )}
        </div>
      </div>
    </div>
  );
};

export default AdminPanel;

import React, { useState, useMemo, useEffect, useCallback, useRef } from 'react';
import Layout from './components/Layout';
import Dashboard from './components/Dashboard';
import AircraftDetailModal from './components/AircraftDetailModal';
import ActivityGrid from './components/ActivityGrid';
import SplashScreen from './components/SplashScreen';
import AdminPanel from './components/AdminPanel';
import { Aircraft, Status, SheetConfig, AppNotification, DailyStatusCode, AircraftActivity } from './types';
import { fetchAircraftDataFromAppsScript } from './services/sheetService';

const App: React.FC = () => {
  const [isSplashVisible, setIsSplashVisible] = useState(true);
  const [isAdminOpen, setIsAdminOpen] = useState(false);
  const [showActivity, setShowActivity] = useState(true);
  const [isSyncing, setIsSyncing] = useState(false);

  const [fleet, setFleet] = useState<Aircraft[]>([]);
  const [activities, setActivities] = useState<AircraftActivity[]>([]);

  const [selectedAircraft, setSelectedAircraft] = useState<Aircraft | null>(null);
  const [searchTerm, setSearchTerm] = useState('');
  const [notifications, setNotifications] = useState<AppNotification[]>([]);
  const [toggledHours, setToggledHours] = useState<Record<string, boolean>>({});

  const BELL_SCRIPT_URL = "https://script.google.com/macros/s/AKfycbzt9ukLiMIWNIQKzHJvw74HaEM28zBHfYao9kbv-g5zb5QxaMUS1UaH45jONA0BeMZr/exec";
  const AT802_SCRIPT_URL = "https://script.google.com/macros/s/AKfycby0-QuoC0Do_W_7Oxkz8T7sDAlv_AO585eJ33_nIR93DVj4CoY1-MHOfixH3ZHiHiCx/exec";

  const initialSyncDone = useRef(false);

  const SHEET_CONFIGS: SheetConfig[] = [
    {
      aircraftType: 'Bell-429',
      sheetId: '1D83TF8K1QG30kBv2sCqnPCMYsdSbaJfcsw-E3S5A9VQ',
      appsScriptUrl: BELL_SCRIPT_URL,
      mapping: { 
        kuyrukNo: 'A3:A8', 
        durum: 'M3:M8', 
        durumAyrintisi: 'N3:N8', 
        konum: 'L3:L8', 
        faydaliSaat: 'I3:I8', 
        aciklama: 'O3:O8',
        govdeUcusSaati: 'E3:E8'
      }
    },
    {
      aircraftType: 'AT-802',
      sheetId: '1vyGHaD5k1H11Fokl5wUKB0fadJGmOugjbd42zLdtDz4',
      sheetName: 'GÜNLÜK DURUM',
      appsScriptUrl: AT802_SCRIPT_URL,
      mapping: { 
        kuyrukNo: 'B3:B14', 
        durum: 'C3:C14', 
        durumAyrintisi: 'D3:D14', 
        konum: 'E3:E14', 
        faydaliSaat: 'V3:AL14', // V'den AL'ye kadar her satırı tara
        aciklama: 'AL3:AL14',
        govdeUcusSaati: 'F3:F14'
      }
    }
  ];

  const exportTableToExcel = (tableId: string, filename: string) => {
    const table = document.getElementById(tableId);
    if (!table) return;
    const html = `
      <html xmlns:o="urn:schemas-microsoft-com:office:office" xmlns:x="urn:schemas-microsoft-com:office:excel" xmlns="http://www.w3.org/TR/REC-html40">
      <head><meta charset="UTF-8"></head>
      <body>${table.outerHTML}</body>
      </html>
    `;
    const url = 'data:application/vnd.ms-excel;base64,' + btoa(unescape(encodeURIComponent(html)));
    const link = document.createElement('a');
    link.download = filename + '.xls';
    link.href = url;
    link.click();
  };

  const handleManualOverride = (kuyrukNo: string, newCode: DailyStatusCode) => {
    setFleet(prev => prev.map(a => a.kuyrukNo === kuyrukNo ? { ...a, assignedCode: newCode } : a));
    setActivities(prev => prev.map(act => act.kuyrukNo === kuyrukNo ? {
      ...act,
      dailyStatuses: { ...act.dailyStatuses, [new Date().getDate()]: newCode }
    } : act));

    setNotifications(prev => [{
      id: Math.random().toString(36).substr(2, 9),
      platform: 'MANUEL',
      kuyrukNo: kuyrukNo,
      kolon: 'ATAMA KODU',
      oncekiDeger: '-',
      yeniDeger: newCode,
      mesaj: `${kuyrukNo} atama kodu manuel olarak "${newCode}" olarak güncellendi.`,
      tarih: new Date().toLocaleTimeString('tr-TR')
    }, ...prev]);
  };

  const handleSyncFromExcel = useCallback((incomingData: Partial<Aircraft>[], platform: string) => {
    if (!incomingData || incomingData.length === 0) return;

    const now = new Date();
    const timestamp = now.toLocaleDateString('tr-TR') + ' ' + now.toLocaleTimeString('tr-TR');
    const today = now.getDate();
    let discoveredChanges: AppNotification[] = [];

    setFleet(prevFleet => {
      const updatedFleet = [...prevFleet];

      incomingData.forEach(incoming => {
        const existingIdx = updatedFleet.findIndex(a => a.kuyrukNo === incoming.kuyrukNo);
        const existing = existingIdx !== -1 ? updatedFleet[existingIdx] : null;

        if (existing && initialSyncDone.current) {
          let fieldChanges: string[] = [];
          let columnsChanged: string[] = [];

          if (existing.assignedCode !== incoming.assignedCode) {
             const codeMsg = incoming.assignedCode === 'F' ? 'FAAL (Atama Kaldırıldı)' : `GAYRI FAAL [${incoming.assignedCode}]`;
             discoveredChanges.push({
               id: Math.random().toString(36).substr(2, 9),
               platform: platform,
               kuyrukNo: existing.kuyrukNo,
               kolon: 'ANALİZ / ÇİZELGE',
               oncekiDeger: existing.assignedCode || 'F',
               yeniDeger: incoming.assignedCode || 'F',
               mesaj: `${existing.kuyrukNo} (${platform}) metinleri analiz edildi: Çizelgeye "${codeMsg}" olarak atandı.`,
               tarih: timestamp
             });
          }

          ['durum', 'konum', 'durumAyrintisi', 'faydaliSaat'].forEach(col => {
            const key = col as keyof Aircraft;
            const oldVal = String(existing[key] || '').trim();
            const newVal = String(incoming[key] || '').trim();

            if (oldVal !== newVal) {
              const labelMap: Record<string, string> = {
                'durum': 'DURUM',
                'konum': 'KONUM',
                'durumAyrintisi': 'DURUM AYRINTISI',
                'faydaliSaat': 'FAYDALI SAAT'
              };
              const colLabel = labelMap[col] || col.toUpperCase();
              columnsChanged.push(colLabel);

              const action = (newVal && newVal !== '-') ? `"${newVal}" yazıldı` : 'boş bırakıldı';
              fieldChanges.push(`${colLabel} alanına ${action}`);
            }
          });

          if (fieldChanges.length > 0) {
            discoveredChanges.push({
              id: Math.random().toString(36).substr(2, 9),
              platform: platform,
              kuyrukNo: existing.kuyrukNo,
              kolon: columnsChanged.join(', '),
              oncekiDeger: '-', 
              yeniDeger: '-',
              mesaj: `${existing.kuyrukNo} (${platform}) Veri Güncellemesi: ${fieldChanges.join(' | ')}`,
              tarih: timestamp
            });
          }
        }

        if (existingIdx !== -1) {
          updatedFleet[existingIdx] = { ...updatedFleet[existingIdx], ...incoming } as Aircraft;
        } else {
          updatedFleet.push(incoming as Aircraft);
        }

        setActivities(prevActivities => {
          let newActivities = [...prevActivities];
          const existsIdx = newActivities.findIndex(act => act.kuyrukNo === incoming.kuyrukNo);
          const newCode = (incoming.assignedCode || 'F') as DailyStatusCode;

          if (existsIdx !== -1) {
            newActivities[existsIdx] = {
              ...newActivities[existsIdx],
              dailyStatuses: { ...newActivities[existsIdx].dailyStatuses, [today]: newCode }
            };
          } else {
            newActivities.push({
              kuyrukNo: incoming.kuyrukNo || '',
              cagriKodu: incoming.cagriKodu || `ORMAN-${incoming.kuyrukNo?.split('-')[1] || 'XX'}`,
              tip: incoming.tip || platform,
              dailyStatuses: { [today]: newCode }
            });
          }
          return newActivities;
        });
      });

      return updatedFleet;
    });

    if (discoveredChanges.length > 0) {
      setNotifications(prev => [...discoveredChanges, ...prev].slice(0, 100));
    }
  }, []);

  const runGlobalSync = useCallback(async () => {
    setIsSyncing(true);
    for (const config of SHEET_CONFIGS) {
      try {
        const data = await fetchAircraftDataFromAppsScript(config.appsScriptUrl, config);
        if (data && data.length > 0) handleSyncFromExcel(data, config.aircraftType);
      } catch (e) { console.error(`Sync error for ${config.aircraftType}:`, e); }
    }
    initialSyncDone.current = true;
    setTimeout(() => setIsSyncing(false), 2000);
  }, [handleSyncFromExcel]);

  useEffect(() => {
    runGlobalSync(); 
    const interval = setInterval(runGlobalSync, 60000); 
    return () => clearInterval(interval);
  }, [runGlobalSync]);

  const filteredFleet = useMemo(() => {
    return fleet.filter(a => {
      const s = searchTerm.toLowerCase();
      return a.kuyrukNo.toLowerCase().includes(s) || a.konum.toLowerCase().includes(s) || (a.tip && a.tip.toLowerCase().includes(s));
    });
  }, [fleet, searchTerm]);

  const toggleHours = (kuyrukNo: string) => {
    setToggledHours(prev => ({ ...prev, [kuyrukNo]: !prev[kuyrukNo] }));
  };

  if (isSplashVisible) return <SplashScreen onComplete={() => setIsSplashVisible(false)} />;

  return (
    <Layout>
      <div className="flex justify-between items-center mb-12">
         <div className="flex items-center space-x-6">
            <div className="bg-emerald-500/10 border border-emerald-500/30 px-6 py-4 rounded-[1.8rem] flex items-center shadow-2xl backdrop-blur-md">
               <div className={`w-3 h-3 rounded-full mr-4 shadow-[0_0_10px_#10b981] ${isSyncing ? 'bg-blue-400 animate-spin' : 'bg-emerald-500 animate-pulse'}`}></div>
               <span className="text-emerald-400 font-black text-[11px] uppercase tracking-[0.5em]">
                  {isSyncing ? 'FİLO VERİLERİ ÇEKİLİYOR...' : 'OTOMATİK VERİ TAKİBİ AKTİF'}
               </span>
