import { SheetConfig, Aircraft, Status, StatusType, DailyStatusCode } from '../types';

/**
 * Durum metinlerini kelime kelime ve cümle bazlı analiz ederek en doğru faaliyet kodunu atar.
 */
export const analyzeStatus = (item: any): { code: DailyStatusCode, interpretation: string } => {
  const detail = String(item.durumAyrintisi || '').toLocaleLowerCase('tr-TR').trim();
  const desc = String(item.aciklama || '').toLocaleLowerCase('tr-TR').trim();
  const durumStr = String(item.durum || '').toLocaleUpperCase('tr-TR').trim();
  const fullText = `${detail} ${desc}`;

  if (fullText.includes('kaza') || fullText.includes('kırım') || fullText.includes('hasar') || fullText.includes('enkaz')) 
    return { code: 'KK', interpretation: 'Metin analizi sonucunda "Kaza/Kırım/Hasar" tespiti yapıldı.' };

  if (fullText.includes('parça') && (fullText.includes('bekleniyor') || fullText.includes('sipariş') || fullText.includes('temin') || fullText.includes('haber') || fullText.includes('bekle'))) {
    return { code: 'PB', interpretation: 'Sistem metinlerdeki bağlamdan dolayı "Parça Bekler" ataması yaptı.' };
  }
  if (fullText.includes('p/n') || fullText.includes('pn ') || fullText.includes('part number')) {
    return { code: 'PB', interpretation: 'Metinde parça numarası (P/N) tespit edildiği için "Parça Bekler" olarak atandı.' };
  }

  if (fullText.includes('yıllık') || fullText.includes('bakım') || fullText.includes('periyodik') || 
      /\b\d+h\b/.test(fullText) || fullText.includes('bakımı yapılıyor') || fullText.includes('revizyon')) {

    if (fullText.includes('bekliyor') || fullText.includes('sıra') || fullText.includes('alınacak')) {
      return { code: 'BB', interpretation: 'Hava aracının "Bakım Beklediği" tespit edildi.' };
    }
    return { code: 'B', interpretation: 'Hava aracının aktif "Bakım" sürecinde olduğu tespit edildi.' };
  }

  if (fullText.includes('kabul') || fullText.includes('muayene') || fullText.includes('test uçuşu') || fullText.includes('teslimat')) 
    return { code: 'KM', interpretation: 'Metin analizi sonucunda "Kabul Muayene" süreci tespit edildi.' };

  if (fullText.includes('arıza') || fullText.includes('teknik sorun') || fullText.includes('problem') || fullText.includes('çalışmıyor') || fullText.includes('faal değil')) 
    return { code: 'A', interpretation: 'Metin analizi sonucunda aktif bir "Arıza/Teknik Sorun" tespit edildi.' };

  const isGayriFaalExplicit = durumStr.includes('GAYRİ') || 
                              durumStr.includes('GAYRI') || 
                              durumStr.includes('G.FAAL') || 
                              durumStr.includes('G. FAAL') ||
                              durumStr.includes('GAYRIFAAL') ||
                              (durumStr.includes('FAAL') && (durumStr.includes('DEĞİL') || durumStr.includes('YOK')));

  if (isGayriFaalExplicit) {
    return { code: 'X', interpretation: 'Detaylı analiz yapılamadı ancak durum "GAYRI FAAL" olduğu için X atandı.' };
  }

  return { code: 'F', interpretation: 'Herhangi bir kısıt tespit edilmedi, "FAAL" kabul edildi.' };
};

/**
 * Değeri sayısal saate dönüştürür. 
 * HH:MM (Örn: 59:00) veya doğrudan sayıları destekler.
 * Tarih Seri Numaralarını (40000+) göz ardı eder.
 */
const parseToNumericHour = (v: any): number | null => {
  if (v === null || v === undefined || v === '') return null;

  // 1. Durum: Apps Script Duration (Date objesi olarak dönerse)
  if (v instanceof Date || (typeof v === 'object' && typeof v.getTime === 'function')) {
    const d = new Date(v);
    if (d.getFullYear() < 1910) { // 1899 base duration
      const base = new Date(1899, 11, 30, 0, 0, 0);
      const diff = d.getTime() - base.getTime();
      return diff / (1000 * 60 * 60);
    }
    return null; // Gerçek bir takvim tarihidir, saat değildir.
  }

  const s = String(v).trim().replace(',', '.');

  // 2. Durum: HH:MM formatı
  if (s.includes(':')) {
    const parts = s.split(':');
    const h = parseFloat(parts[0]);
    const m = parts.length > 1 ? parseFloat(parts[1]) : 0;
    if (!isNaN(h)) return h + (m / 60);
    return null;
  }

  // 3. Durum: Düz Rakam
  const n = parseFloat(s);
  if (isNaN(n)) return null;

  // 30.000'den büyük rakamlar muhtemelen tarih seri numarasıdır (Bakım saati değildir)
  if (n > 30000) return null;

  return n;
};

/**
 * Google Apps Script üzerinden veri çeker ve her satır için V:AI aralığındaki MİNİMUM değeri bulur.
 */
export const fetchAircraftDataFromAppsScript = async (url: string, config: SheetConfig): Promise<Partial<Aircraft>[]> => {
  try {
    const response = await fetch(url, {
      method: 'POST',
      headers: { 'Content-Type': 'text/plain;charset=utf-8' },
      body: JSON.stringify({
        sheetId: config.sheetId,
        sheetName: config.sheetName,
        mapping: config.mapping
      })
    });

    if (!response.ok) throw new Error(`HTTP Error: ${response.status}`);

    const data = await response.json();
    if (data.error || !Array.isArray(data)) return [];

    return data.map((item: any) => {
      const analysis = analyzeStatus(item);
      const kuyrukNo = String(item.kuyrukNo || '').trim();

      let minFaydali = 0;

      // SATIR SEVİYESİNDE TARAMA (V'den AI'ya kadar olan hücreler dizi olarak gelmiş olmalı)
      if (Array.isArray(item.faydaliSaat)) {
        // Bu satıra ait V:AI hücrelerini listele (flat ile tek boyutlu diziye indir)
        const rowValues = item.faydaliSaat.flat();

        // Sadece geçerli, 0'dan büyük bakım saatlerini ayıkla
        const numericValues = rowValues
          .map(v => parseToNumericHour(v))
          .filter((v): v is number => v !== null && v > 0);

        // Satırdaki en küçük değeri bul (Excel MIN mantığı)
        if (numericValues.length > 0) {
          minFaydali = Math.min(...numericValues);
        }
      } else {
        // Tek bir hücre gelirse doğrudan işle
        minFaydali = parseToNumericHour(item.faydaliSaat) || 0;
      }

      return {
        kuyrukNo: kuyrukNo,
        cagriKodu: `ORMAN-${kuyrukNo.split('-')[1] || 'XX'}`,
        durum: (analysis.code !== 'F') ? Status.GAYRI_FAAL : Status.FAAL,
        durumTipi: analysis.code === 'B' || analysis.code === 'BB' ? StatusType.BAKIM : 
                   analysis.code === 'A' || analysis.code === 'PB' ? StatusType.ARIZA : StatusType.NONE,
        durumAyrintisi: String(item.durumAyrintisi || '-'),
        konum: String(item.konum || 'ANKARA'),
        faydaliSaat: Math.floor(minFaydali), // En küçük tam sayı saat
        govdeUcusSaati: String(item.govdeUcusSaati || '-'),
        aciklama: String(item.aciklama || ''),
        guncellemeTarihi: new Date().toLocaleString('tr-TR'),
        durumBaslangic: new Date().toISOString().split('T')[0],
        maintenanceHours: [{ bakimTuru: 'PERİYODİK', kalanSaat: Math.floor(minFaydali) }],
        photos: [`https://picsum.photos/seed/${kuyrukNo}/800/600`],
        platformTipi: 'H',
        tip: config.aircraftType,
        assignedCode: analysis.code,
        aiInterpretation: analysis.interpretation
      };
    });
  } catch (error) {
    console.error("Satır bazlı veri işleme hatası:", error);
    return [];
  }
};

import React, { useState, useMemo, useEffect, useCallback, useRef } from 'react';
import Layout from './components/Layout';
import Dashboard from './components/Dashboard';
import AircraftDetailModal from './components/AircraftDetailModal';
import ActivityGrid from './components/ActivityGrid';
import SplashScreen from './components/SplashScreen';
import AdminPanel from './components/AdminPanel';
import { Aircraft, Status, SheetConfig, AppNotification, DailyStatusCode, AircraftActivity } from './types';
import { fetchAircraftDataFromAppsScript } from './services/sheetService';

const App: React.FC = () => {
  const [isSplashVisible, setIsSplashVisible] = useState(true);
  const [isAdminOpen, setIsAdminOpen] = useState(false);
  const [showActivity, setShowActivity] = useState(true);
  const [isSyncing, setIsSyncing] = useState(false);

  const [fleet, setFleet] = useState<Aircraft[]>([]);
  const [activities, setActivities] = useState<AircraftActivity[]>([]);

  const [selectedAircraft, setSelectedAircraft] = useState<Aircraft | null>(null);
  const [searchTerm, setSearchTerm] = useState('');
  const [notifications, setNotifications] = useState<AppNotification[]>([]);
  const [toggledHours, setToggledHours] = useState<Record<string, boolean>>({});

  const BELL_SCRIPT_URL = "https://script.google.com/macros/s/AKfycbzt9ukLiMIWNIQKzHJvw74HaEM28zBHfYao9kbv-g5zb5QxaMUS1UaH45jONA0BeMZr/exec";
  const AT802_SCRIPT_URL = "https://script.google.com/macros/s/AKfycbw_PhzaenZ7JMLCMLk5ayuXT8d0zuTgcE7y17-CoPYPG2Gaso5I4N3mu-piDdi_i8lTgw/exec";

  const initialSyncDone = useRef(false);

  const SHEET_CONFIGS: SheetConfig[] = [
    {
      aircraftType: 'Bell-429',
      sheetId: '1D83TF8K1QG30kBv2sCqnPCMYsdSbaJfcsw-E3S5A9VQ',
      appsScriptUrl: BELL_SCRIPT_URL,
      mapping: { 
        kuyrukNo: 'A3:A8', 
        durum: 'M3:M8', 
        durumAyrintisi: 'N3:N8', 
        konum: 'L3:L8', 
        faydaliSaat: 'I3:I8', 
        aciklama: 'O3:O8',
        govdeUcusSaati: 'E3:E8'
      }
    },
    {
      aircraftType: 'AT-802',
      sheetId: '1vyGHaD5k1H11Fokl5wUKB0fadJGmOugjbd42zLdtDz4',
      sheetName: 'GÜNLÜK DURUM',
      appsScriptUrl: AT802_SCRIPT_URL,
      mapping: { 
        kuyrukNo: 'B3:B14', 
        durum: 'C3:C14', 
        durumAyrintisi: 'D3:D14', 
        konum: 'E3:E14', 
        faydaliSaat: 'V3:AI14', // V:AI aralığı taranıp MIN değeri alınacak
        aciklama: 'AL3:AL14',   // Açıklama AL sütunu
        govdeUcusSaati: 'F3:F14'
      }
    }
  ];

  const exportTableToExcel = (tableId: string, filename: string) => {
    const table = document.getElementById(tableId);
    if (!table) return;
    const html = `
      <html xmlns:o="urn:schemas-microsoft-com:office:office" xmlns:x="urn:schemas-microsoft-com:office:excel" xmlns="http://www.w3.org/TR/REC-html40">
      <head><meta charset="UTF-8"></head>
      <body>${table.outerHTML}</body>
      </html>
    `;
    const url = 'data:application/vnd.ms-excel;base64,' + btoa(unescape(encodeURIComponent(html)));
    const link = document.createElement('a');
    link.download = filename + '.xls';
    link.href = url;
    link.click();
  };

  const handleManualOverride = (kuyrukNo: string, newCode: DailyStatusCode) => {
    setFleet(prev => prev.map(a => a.kuyrukNo === kuyrukNo ? { ...a, assignedCode: newCode } : a));
    setActivities(prev => prev.map(act => act.kuyrukNo === kuyrukNo ? {
      ...act,
      dailyStatuses: { ...act.dailyStatuses, [new Date().getDate()]: newCode }
    } : act));

    setNotifications(prev => [{
      id: Math.random().toString(36).substr(2, 9),
      platform: 'MANUEL',
      kuyrukNo: kuyrukNo,
      kolon: 'ATAMA KODU',
      oncekiDeger: '-',
      yeniDeger: newCode,
      mesaj: `${kuyrukNo} uçağı için ATAMA KODU verisi manuel olarak "${newCode}" olarak güncellendi.`,
      tarih: new Date().toLocaleTimeString('tr-TR')
    }, ...prev]);
  };

  const handleSyncFromExcel = useCallback((incomingData: Partial<Aircraft>[], platform: string) => {
    if (!incomingData || incomingData.length === 0) return;

    const now = new Date();
    const timestamp = now.toLocaleDateString('tr-TR') + ' ' + now.toLocaleTimeString('tr-TR');
    let discoveredChanges: AppNotification[] = [];

    setFleet(prevFleet => {
      const updatedFleet = [...prevFleet];

      incomingData.forEach(incoming => {
        const existingIdx = updatedFleet.findIndex(a => a.kuyrukNo === incoming.kuyrukNo);
        const existing = existingIdx !== -1 ? updatedFleet[existingIdx] : null;

        if (existing && initialSyncDone.current) {
          // ANALİZ KODU DEĞİŞİMİ
          if (existing.assignedCode !== incoming.assignedCode) {
             discoveredChanges.push({
               id: Math.random().toString(36).substr(2, 9),
               platform: platform,
               kuyrukNo: existing.kuyrukNo,
               kolon: 'ANALİZ / ÇİZELGE',
               oncekiDeger: existing.assignedCode || 'F',
               yeniDeger: incoming.assignedCode || 'F',
               mesaj: `${existing.kuyrukNo} uçağı için ANALİZ verisi ${existing.assignedCode || 'F'} → ${incoming.assignedCode || 'F'} olarak değiştirilmiştir.`,
               tarih: timestamp
             });
          }

          // DİĞER ALAN DEĞİŞİMLERİ
          ['durum', 'konum', 'durumAyrintisi', 'faydaliSaat'].forEach(col => {
            const key = col as keyof Aircraft;
            const oldVal = String(existing[key] || '').trim();
            const newVal = String(incoming[key] || '').trim();

            if (oldVal !== newVal) {
              const labelMap: Record<string, string> = {
                'durum': 'DURUM',
                'konum': 'KONUM',
                'durumAyrintisi': 'DURUM AYRINTISI',
                'faydaliSaat': 'FAYDALI SAAT'
              };
              const colLabel = labelMap[col] || col.toUpperCase();

              discoveredChanges.push({
                id: Math.random().toString(36).substr(2, 9),
                platform: platform,
                kuyrukNo: existing.kuyrukNo,
                kolon: colLabel,
                oncekiDeger: oldVal, 
                yeniDeger: newVal,
                mesaj: `${existing.kuyrukNo} uçağı için ${colLabel} verisi ${oldVal} → ${newVal} olarak değiştirilmiştir.`,
                tarih: timestamp
              });
            }
          });
        }

        if (existingIdx !== -1) {
          updatedFleet[existingIdx] = { ...updatedFleet[existingIdx], ...incoming } as Aircraft;
        } else {
          updatedFleet.push(incoming as Aircraft);
        }

        setActivities(prevActivities => {
          let newActivities = [...prevActivities];
          const existsIdx = newActivities.findIndex(act => act.kuyrukNo === incoming.kuyrukNo);
          const currentDayNum = new Date().getDate();
          const newCode = (incoming.assignedCode || 'F') as DailyStatusCode;

          if (existsIdx !== -1) {
            newActivities[existsIdx] = {
              ...newActivities[existsIdx],
              dailyStatuses: { ...newActivities[existsIdx].dailyStatuses, [currentDayNum]: newCode }
            };
          } else {
            newActivities.push({
              kuyrukNo: incoming.kuyrukNo || '',
              cagriKodu: incoming.cagriKodu || `ORMAN-${incoming.kuyrukNo?.split('-')[1] || 'XX'}`,
              tip: incoming.tip || platform,
              dailyStatuses: { [currentDayNum]: newCode }
            });
          }
          return newActivities;
        });
      });

      return updatedFleet;
    });

    if (discoveredChanges.length > 0) {
      setNotifications(prev => [...discoveredChanges, ...prev].slice(0, 100));
    }
  }, []);

  const runGlobalSync = useCallback(async () => {
    setIsSyncing(true);
    for (const config of SHEET_CONFIGS) {
      try {
        const data = await fetchAircraftDataFromAppsScript(config.appsScriptUrl, config);
        if (data && data.length > 0) handleSyncFromExcel(data, config.aircraftType);
      } catch (e) { console.error(`Sync error for ${config.aircraftType}:`, e); }
    }
    initialSyncDone.current = true;
    setTimeout(() => setIsSyncing(false), 2000);
  }, [handleSyncFromExcel]);

  useEffect(() => {
    runGlobalSync(); 
    const interval = setInterval(runGlobalSync, 60000); 
    return () => clearInterval(interval);
  }, [runGlobalSync]);

  const filteredFleet = useMemo(() => {
    return fleet.filter(a => {
      const s = searchTerm.toLowerCase();
      return a.kuyrukNo.toLowerCase().includes(s) || a.konum.toLowerCase().includes(s) || (a.tip && a.tip.toLowerCase().includes(s));
    });
  }, [fleet, searchTerm]);

  const toggleHours = (kuyrukNo: string) => {
    setToggledHours(prev => ({ ...prev, [kuyrukNo]: !prev[kuyrukNo] }));
  };

  if (isSplashVisible) return <SplashScreen onComplete={() => setIsSplashVisible(false)} />;

  return (
    <Layout>
      <div className="flex justify-between items-center mb-12">
         <div className="flex items-center space-x-6">
            <div className="bg-emerald-500/10 border border-emerald-500/30 px-6 py-4 rounded-[1.8rem] flex items-center shadow-2xl backdrop-blur-md">
               <div className={`w-3 h-3 rounded-full mr-4 shadow-[0_0_10px_#10b981] ${isSyncing ? 'bg-blue-400 animate-spin' : 'bg-emerald-500 animate-pulse'}`}></div>
               <span className="text-emerald-400 font-black text-[11px] uppercase tracking-[0.5em]">
                  {isSyncing ? 'FİLO VERİLERİ ÇEKİLİYOR...' : 'OTOMATİK VERİ TAKİBİ AKTİF'}
               </span>
            </div>
            {notifications.length > 0 && (
              <div onClick={() => setIsAdminOpen(true)} className="bg-red-500/10 border border-red-500/30 px-6 py-4 rounded-[1.8rem] flex items-center shadow-lg cursor-pointer hover:bg-red-500/20 transition-all animate-bounce">
                <div className="bg-red-500 text-white text-[9px] font-black w-6 h-6 rounded-full flex items-center justify-center mr-3 shadow-lg">{notifications.length}</div>
                <span className="text-red-400 font-black text-[10px] uppercase tracking-[0.4em]">YENİ ANALİZ BİLDİRİMİ</span>
              </div>
            )}
         </div>
         <div className="flex space-x-5">
            <button onClick={() => setShowActivity(!showActivity)} className={`px-10 py-5 rounded-[2rem] font-black text-[11px] uppercase tracking-[0.4em] transition-all shadow-2xl border-2 ${showActivity ? 'bg-blue-600 text-white border-blue-500' : 'bg-white/10 text-white border-white/20'}`}>
              {showActivity ? "ENVANTER LİSTESİ" : "FAALİYET ÇİZELGESİ"}
            </button>
            <button onClick={() => setIsAdminOpen(true)} className="bg-[#021a0c] hover:bg-emerald-900 text-white px-10 py-5 rounded-[2rem] font-black text-[11px] border-2 border-emerald-800/50 uppercase tracking-[0.4em] transition-all shadow-lg flex items-center">
              YÖNETİM & GELEN KUTUSU
            </button>
         </div>
      </div>

      <div className="mb-14"><Dashboard fleet={fleet} /></div>

      {showActivity ? (
        <div className="mb-24 animate-in fade-in duration-1000">
           <div className="bg-white rounded-[2rem] p-4 shadow-2xl border-4 border-emerald-800/20 overflow-hidden">
             <ActivityGrid activities={activities} startDate={new Date(2025, 0, 1)} endDate={new Date(2025, 0, 31)} title="OCAK 2025" onExport={() => exportTableToExcel('activity-table', 'OGM_Faaliyet_Raporu_Ocak_2025')} />
           </div>
        </div>
      ) : (
        <div className="mb-24 animate-in fade-in duration-1000">
          <div className="flex justify-between items-end mb-12 px-6">
             <div>
                <h2 className="text-6xl font-black text-white uppercase tracking-tighter italic">ENVANTER LİSTESİ</h2>
                <p className="text-emerald-500 text-[10px] font-black uppercase tracking-[0.8em] mt-4 border-l-4 border-emerald-500 pl-4">Platform Bazlı Durum ve Gövde Uçuş Saati</p>
             </div>
             <div className="flex items-center space-x-6">
                <button onClick={() => exportTableToExcel('inventory-table', 'Envanter_Listesi')} className="bg-emerald-700 hover:bg-emerald-600 text-white px-8 py-4 rounded-xl font-black text-[10px] uppercase tracking-widest transition-all shadow-xl flex items-center">
                   <svg className="w-4 h-4 mr-2" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path d="M4 16v1a3 3 0 003 3h10a3 3 0 003-3v-1m-4-4l-4 4m0 0l-4-4m4 4V4" strokeWidth={3}/></svg>
                   ENVANTER EXCEL İNDİR
                </button>
                <div className="relative">
                  <input type="text" placeholder="Kuyruk, Tip veya Konum Ara..." value={searchTerm} onChange={(e) => setSearchTerm(e.target.value)} className="w-[400px] px-12 py-4 bg-black/60 text-white rounded-[2rem] border-2 border-white/10 outline-none font-bold focus:border-emerald-500 transition-all shadow-2xl backdrop-blur-xl" />
                  <svg className="absolute left-4 top-1/2 -translate-y-1/2 w-5 h-5 text-gray-500" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path d="M21 21l-6-6m2-5a7 7 0 11-14 0 7 7 0 0114 0z" strokeWidth={3}/></svg>
                </div>
             </div>
          </div>

          <div className="bg-white p-2 rounded-[2rem] shadow-2xl overflow-hidden border-4 border-emerald-800/10">
            <table id="inventory-table" className="w-full border-collapse">
              <thead>
                <tr className="bg-emerald-900 text-white">
                  <th className="px-8 py-6 text-left text-xs font-black uppercase tracking-widest border-r border-emerald-800">HAVA ARACI / TİP</th>
                  <th className="px-8 py-6 text-center text-xs font-black uppercase tracking-widest border-r border-emerald-800">DURUM (ÇİFT TIKLA SAAT GÖR)</th>
                  <th className="px-8 py-6 text-left text-xs font-black uppercase tracking-widest border-r border-emerald-800">KONUM</th>
                  <th className="px-8 py-6 text-center text-xs font-black uppercase tracking-widest border-r border-emerald-800">FAYDALI SAAT (MİN)</th>
                  <th className="px-8 py-6 text-left text-xs font-black uppercase tracking-widest">AÇIKLAMA METNİ ANALİZİ</th>
                </tr>
              </thead>
              <tbody className="divide-y divide-slate-100">
                {filteredFleet.map((a, i) => (
                  <tr key={i} className="hover:bg-slate-50 cursor-pointer transition-all active:scale-[0.99] group">
                    <td className="px-8 py-6" onClick={() => setSelectedAircraft(a)}>
                       <div className="font-black text-emerald-950 text-xl tracking-tighter group-hover:text-emerald-600 transition-colors">{a.kuyrukNo}</div>
                       <div className="text-[9px] font-black text-emerald-600 bg-emerald-100 px-2 py-0.5 rounded-full w-fit uppercase mt-1">{a.tip}</div>
                    </td>
                    <td className="px-8 py-6 text-center select-none" onDoubleClick={() => toggleHours(a.kuyrukNo)}>
                      {toggledHours[a.kuyrukNo] ? (
                        <div className="bg-blue-600 text-white px-6 py-3 rounded-xl font-black text-[12px] shadow-lg animate-in zoom-in duration-300">
                           {a.govdeUcusSaati || '0'} <span className="text-[8px] opacity-70 ml-1">SAAT</span>
                        </div>
                      ) : (
                        <span className={`px-6 py-3 rounded-xl font-black text-[10px] uppercase border-2 shadow-sm ${a.durum === Status.FAAL ? 'bg-emerald-50 text-emerald-700 border-emerald-200' : 'bg-red-50 text-red-700 border-red-200'}`}>
                          {a.durum}
                        </span>
                      )}
                    </td>
                    <td className="px-8 py-6 text-sm font-black text-slate-800 uppercase tracking-widest">{a.konum}</td>
                    <td className="px-8 py-6 text-center">
                       <div className="font-black text-3xl text-blue-600 tracking-tighter">{a.faydaliSaat}</div>
                    </td>
                    <td className="px-8 py-6">
                       <div className="text-slate-500 text-xs font-bold leading-relaxed max-w-md">
                          <div className="text-emerald-700 font-black text-[9px] uppercase mb-1">{a.durumAyrintisi}</div>
                          <div className="italic truncate">"{a.aciklama && a.aciklama !== '-' ? a.aciklama : "Metin Yok"}"</div>
                       </div>
                    </td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
        </div>
      )}

      {selectedAircraft && <AircraftDetailModal aircraft={selectedAircraft} onClose={() => setSelectedAircraft(null)} />}
      {isAdminOpen && <AdminPanel notifications={notifications} initialData={fleet} onSave={(configs, data) => handleSyncFromExcel(data, configs[0].aircraftType)} onOverride={handleManualOverride} onClose={() => setIsAdminOpen(false)} />}
    </Layout>
  );
};

export default App;

import React, { useState } from 'react';
import { SheetConfig, Aircraft, AppNotification, DailyStatusCode } from '../types';
import { fetchAircraftDataFromAppsScript } from '../services/sheetService';

interface AdminPanelProps {
  onSave: (configs: SheetConfig[], data: Partial<Aircraft>[]) => void;
  onOverride?: (kuyrukNo: string, code: DailyStatusCode) => void;
  onClose: () => void;
  notifications: AppNotification[];
  initialData?: any[]; 
}

const AdminPanel: React.FC<AdminPanelProps> = ({ onSave, onOverride, onClose, notifications, initialData = [] }) => {
  const [activeSubTab, setActiveSubTab] = useState('notifications'); 
  const [previewData, setPreviewData] = useState<any[]>(initialData);
  const [isLoading, setIsLoading] = useState(false);
  const [selectedNotifyForEdit, setSelectedNotifyForEdit] = useState<AppNotification | null>(null);

  const BELL_SCRIPT_URL = "https://script.google.com/macros/s/AKfycbzt9ukLiMIWNIQKzHJvw74HaEM28zBHfYao9kbv-g5zb5QxaMUS1UaH45jONA0BeMZr/exec";
  const AT802_SCRIPT_URL = "https://script.google.com/macros/s/AKfycbw_PhzaenZ7JMLCMLk5ayuXT8d0zuTgcE7y17-CoPYPG2Gaso5I4N3mu-piDdi_i8lTgw/exec";

  const BELL_SHEET_ID = "1D83TF8K1QG30kBv2sCqnPCMYsdSbaJfcsw-E3S5A9VQ";
  const AT802_SHEET_ID = "1vyGHaD5k1H11Fokl5wUKB0fadJGmOugjbd42zLdtDz4";

  const exportTableToExcel = (tableId: string, filename: string) => {
    const table = document.getElementById(tableId);
    if (!table) return;
    const html = `
      <html xmlns:o="urn:schemas-microsoft-com:office:office" xmlns:x="urn:schemas-microsoft-com:office:excel" xmlns="http://www.w3.org/TR/REC-html40">
      <head><meta charset="UTF-8"></head>
      <body>${table.outerHTML}</body>
      </html>
    `;
    const url = 'data:application/vnd.ms-excel;base64,' + btoa(unescape(encodeURIComponent(html)));
    const link = document.createElement('a');
    link.download = filename + '.xls';
    link.href = url;
    link.click();
  };

  const handleManualSync = async (type: 'Bell-429' | 'AT-802') => {
    setIsLoading(true);
    let mapping;
    let sheetId;
    let sheetName;
    let scriptUrl;

    if (type === 'Bell-429') {
      mapping = { 
        kuyrukNo: 'A3:A8', 
        durum: 'M3:M8', 
        durumAyrintisi: 'N3:N8', 
        konum: 'L3:L8', 
        faydaliSaat: 'I3:I8', 
        aciklama: 'O3:O8',
        govdeUcusSaati: 'E3:E8'
      };
      sheetId = BELL_SHEET_ID;
      scriptUrl = BELL_SCRIPT_URL;
    } else {
      mapping = { 
        kuyrukNo: 'B3:B14', 
        durum: 'C3:C14', 
        durumAyrintisi: 'D3:D14', 
        konum: 'E3:E14', 
        faydaliSaat: 'V3:AI14', // V:AI aralığı
        aciklama: 'AL3:AL14',   // Açıklama AL sütunu
        govdeUcusSaati: 'F3:F14'
      };
      sheetId = AT802_SHEET_ID;
      sheetName = 'GÜNLÜK DURUM';
      scriptUrl = AT802_SCRIPT_URL;
    }

    const config: SheetConfig = {
      aircraftType: type,
      sheetId: sheetId,
      sheetName: sheetName,
      appsScriptUrl: scriptUrl,
      mapping: mapping
    };
    try {
      const results = await fetchAircraftDataFromAppsScript(scriptUrl, config);
      if (results.length > 0) {
        setPreviewData(results);
        onSave([config], results);
      }
    } catch (e) { console.error(e); }
    setIsLoading(false);
  };

  return (
    <div className="fixed inset-0 z-[200] bg-black/95 backdrop-blur-2xl flex items-center justify-center p-4">
      <div className="bg-[#052e16] w-full max-w-[1700px] h-[95vh] rounded-[4rem] border border-green-800/40 flex overflow-hidden shadow-[0_0_100px_rgba(0,0,0,1)]">

        <div className="w-80 bg-[#021a0c] border-r border-green-900/40 p-10 flex flex-col">
          <div className="mb-14">
            <h2 className="text-white font-black text-2xl tracking-tighter uppercase">ADMİN PANELİ</h2>
            <p className="text-green-600 text-[8px] font-black tracking-[0.6em] mt-3 italic uppercase opacity-50">Sistem Denetim Merkezi</p>
          </div>

          <nav className="space-y-10 flex-grow">
            <div>
              <span className="text-[10px] font-black text-gray-700 uppercase tracking-[0.4em] block mb-6 ml-2">CANLI DENETİM</span>
              <button onClick={() => setActiveSubTab('notifications')} className={`w-full flex items-center justify-between px-6 py-5 rounded-[2rem] font-black text-[11px] uppercase tracking-widest transition-all ${activeSubTab === 'notifications' ? 'bg-emerald-600 text-white shadow-xl' : 'text-gray-500 hover:text-white'}`}>
                <span>GELEN KUTUSU</span>
                {notifications.length > 0 && <span className="bg-red-500 text-white text-[9px] w-6 h-6 rounded-full flex items-center justify-center">{notifications.length}</span>}
              </button>
            </div>

            <div className="pl-6 border-l-2 border-green-900/30 space-y-6">
              <span className="text-[10px] font-black text-gray-700 uppercase tracking-[0.4em] block mb-2 ml-2">ENTEGRASYON</span>
              <button onClick={() => setActiveSubTab('excel')} className={`w-full text-left px-5 py-3 font-black text-[10px] uppercase tracking-widest ${activeSubTab === 'excel' ? 'text-emerald-400 bg-emerald-500/10 rounded-xl' : 'text-gray-600 hover:text-white'}`}>○ EXCEL MODÜLLERİ</button>
            </div>
          </nav>
          <button onClick={onClose} className="py-6 rounded-[2rem] border-2 border-red-900/30 text-red-500 font-black text-[10px] uppercase tracking-[0.3em] hover:bg-red-950/30 transition-all">PANELİ KAPAT</button>
        </div>

        <div className="flex-1 flex flex-col overflow-hidden bg-[#052e16] relative">
          {activeSubTab === 'notifications' ? (
