/**
 * Hücre değerini sayısal bir saate dönüştürür.
 * HH:MM:SS formatını tam sayıya çevirir. 
 * 1900-2100 arası YIL değerlerini ve TARİH seri numaralarını kesinlikle eler.
 */
const parseToNumericHour = (v: any): number | null => {
  if (v === null || v === undefined || v === '') return null;

  // Apps Script Duration (Date objesi) durumu
  if (v instanceof Date || (typeof v === 'object' && typeof v.getTime === 'function')) {
    const d = new Date(v);
    const year = d.getFullYear();
    // Eğer yıl 1910'dan küçükse bu bir "Süre/Duration"dır (Excel mantığı)
    if (year < 1910) { 
      const base = new Date(1899, 11, 30, 0, 0, 0);
      const diff = d.getTime() - base.getTime();
      const hours = diff / (1000 * 60 * 60);
      return hours > 0 ? hours : null;
    }
    return null; // Gerçek takvim tarihi (2026 vb.) ise eliyoruz
  }

  const s = String(v).trim().replace(',', '.');

  // Tarih içeren metinleri (8/1/2026 vb.) kesinlikle ele
  if ((s.includes('/') || (s.includes('-') && s.indexOf('-') > 0)) && !s.includes(':')) {
    return null;
  }

  // HH:MM:SS veya HH:MM formatı
  if (s.includes(':')) {
    const parts = s.split(':');
    const h = parseFloat(parts[0]);
    const m = parts.length > 1 ? parseFloat(parts[1]) : 0;
    const sec = parts.length > 2 ? parseFloat(parts[2]) : 0;
    if (!isNaN(h)) {
      const totalHours = h + (m / 60) + (sec / 3600);
      // Eğer bu değer bir yıl gibi görünüyorsa (1900-2100) hata payı için eliyoruz
      if (totalHours >= 1890 && totalHours <= 2100) return null;
      return totalHours;
    }
    return null;
  }

  // Saf sayı durumu
  const n = parseFloat(s);
  if (isNaN(n)) return null;

  // KRİTİK FİLTRE: Eğer sayı 1890 ile 2100 arasındaysa bu muhtemelen bir yıldır, saat değildir.
  if (n >= 1890 && n <= 2100) return null;

  // Excel tarih seri numaralarını (40000+) ele
  if (n > 30000) return null;

  return n > 0 ? n : null;
};

