const parseToNumericHour = (v: any): number | null => {
  if (v === null || v === undefined || v === '') return null;

  // Google Sheets Süre (Date/Duration) Objesi
  if (v instanceof Date || (v && typeof v.getTime === 'function')) {
    const d = new Date(v);
    // Yıl 1910'dan küçükse bu bir "Süre" verisidir
    if (d.getFullYear() < 1910) {
      const base = new Date(1899, 11, 30, 0, 0, 0);
      const hours = (d.getTime() - base.getTime()) / (1000 * 60 * 60);
      // Sadece anlamlı saatleri al (0 veya hatalı tarih olmasın)
