/**
 * HH:MM:SS veya düz sayıları sayısal saate çevirir.
 */
const parseToNumericHour = (v: any): number | null => {
  if (v === null || v === undefined || v === '') return null;

  // Google Sheets Duration (Tarih objesi olarak gelirse)
  if (v instanceof Date || (v && typeof v.getTime === 'function')) {
    const d = new Date(v);
    // Eğer yıl 1910'dan küçükse bu bir süredir (duration)
    if (d.getFullYear() < 1910) {
      const base = new Date(1899, 11, 30, 0, 0, 0);
      const hours = (d.getTime() - base.getTime()) / (1000 * 60 * 60);
      return hours > 0.001 ? hours : null;
    }
    return null; // Gerçek takvim tarihi ise saat değildir
  }

  const s = String(v).trim().replace(',', '.');

  // Saat formatı kontrolü (Örn: 218:50)
  if (s.includes(':')) {
    const parts = s.split(':');
    const h = parseFloat(parts[0]) || 0;
    const m = parseFloat(parts[1]) || 0;
    const sec = parts.length > 2 ? parseFloat(parts[2]) || 0 : 0;
    const total = h + (m / 60) + (sec / 3600);
    return total > 0 ? total : null;
  }

  // Düz sayı ise
  const n = parseFloat(s);
  if (isNaN(n) || n <= 0) return null;

  // Çok büyük Excel tarih seri numaralarını ele (Örn: 45000+)
  if (n > 40000) return null;

  return n;
};

