  if (v === null || v === undefined || v === '' || v === 0 || v === "0") return null;

  // 1. Durum: Google Sheets'ten "Süre" objesi (Date) olarak gelirse
  if (v instanceof Date || (v && typeof v.getTime === 'function')) {
    const d = new Date(v);
    const year = d.getFullYear();

    // Eğer yıl 1910'dan küçükse (1899-1900), bu aslında bir "Süre"dir.
    if (year < 1910) {
      const base = new Date(1899, 11, 30, 0, 0, 0);
      const diffMs = d.getTime() - base.getTime();
      const hours = diffMs / (1000 * 60 * 60);
      return hours > 0.01 ? hours : null;
    }
    // Eğer yıl 2020+, bu gerçek bir tarihtir (8/28/2025 gibi), bunu saat olarak alma.
    return null; 
  }

  // 2. Durum: Metin formatında gelirse (Örn: "218:50")
  const s = String(v).trim().replace(',', '.');
  if (s.includes(':')) {
    const parts = s.split(':');
    const h = parseFloat(parts[0]) || 0;
    const m = parseFloat(parts[1]) || 0;
    const sec = parts.length > 2 ? parseFloat(parts[2]) || 0 : 0;
    const totalHours = h + (m / 60) + (sec / 3600);
    return totalHours > 0 ? totalHours : null;
  }

  // 3. Durum: Direkt sayı formatında ise
  const n = parseFloat(s);
  if (isNaN(n) || n <= 0) return null;

  // Eğer sayı 40000'den büyükse, bu muhtemelen bir Excel tarih seri numarasıdır (Örn: 45000 = 2023 yılı).
  // Bakım saatleri genellikle 100-5000 arasındadır.
  if (n > 20000) return null; 

  return n;
};

