/**
 * Hücre değerini sayısal saate çevirir.
 * HH:MM (218:50) ve Google Sheets Süre (Date) verilerini işler.
 * 1899/1900 gibi hatalı artifact değerlerini eledikten sonra sonucu döndürür.
 */
const parseToNumericHour = (v: any): number | null => {
  if (v === null || v === undefined || v === '' || v === 0 || v === "0" || v === "N/A") return null;

  let totalHours: number | null = null;

  // 1. Google Sheets Süre (Date Objeleri)
  if (v instanceof Date || (v && typeof v.getTime === 'function')) {
    const d = new Date(v);
    const year = d.getFullYear();

    // Yıl 1910'dan küçükse bu bir süredir (1899/1900 yılları Sheets'te 0 noktasıdır)
    if (year < 1910) {
      const base = new Date(1899, 11, 30, 0, 0, 0);
      const diffMs = d.getTime() - base.getTime();
      totalHours = diffMs / (1000 * 60 * 60);
    }
  } 
  // 2. Metin veya Sayı Formatı
  else {
    const s = String(v).trim().replace(',', '.');

    // HH:MM:SS veya HH:MM formatı
    if (s.includes(':')) {
      const parts = s.split(':');
      const h = parseFloat(parts[0]) || 0;
      const m = parseFloat(parts[1]) || 0;
      const sec = parts.length > 2 ? parseFloat(parts[2]) || 0 : 0;
      totalHours = h + (m / 60) + (sec / 3600);
    } 
    // Düz Sayı
    else {
      const n = parseFloat(s);
      if (!isNaN(n)) totalHours = n;
    }
  }

  // VALIDASYON VE ARTIFACT TEMİZLİĞİ
  if (totalHours === null || isNaN(totalHours) || totalHours <= 0) return null;

  // ÇOK ÖNEMLİ: Eğer hesaplanan saat 1899 veya 1900 ise bu bir veritabanı artifactidir.
  // Uçak bakımında tam olarak 1899.00 veya 1900.00 saat kalması ihtimali hata payından düşüktür.
  const rounded = Math.round(totalHours);
  if (rounded === 1899 || rounded === 1900) return null;

  // 40000'den büyükse muhtemelen 2024+ yılına ait bir tarih seri numarasıdır.
  if (totalHours > 40000) return null;

  return totalHours;
};

