    return { code: 'B', interpretation: 'Bakımda.' };
  }

  if (fullText.includes('arıza') || fullText.includes('problem')) 
    return { code: 'A', interpretation: 'Arıza.' };

  const isGayriFaalExplicit = durumStr.includes('GAYRİ') || durumStr.includes('GAYRI') || durumStr.includes('G.FAAL');
  if (isGayriFaalExplicit) return { code: 'X', interpretation: 'Gayrı Faal.' };

  return { code: 'F', interpretation: 'Faal.' };
};

/**
 * Hücre değerini sayısal saate çevirir.
 * 1899 ve 1900 artifactlarını (boş süre hücrelerini) KESİN olarak reddeder.
 */
const parseToNumericHour = (v: any): number | null => {
  // Temel boş kontrolleri
  if (v === null || v === undefined || v === '' || v === 0 || v === "0" || v === "N/A" || v === "00:00") return null;

  let val: number | null = null;

  // 1. Google Sheets Tarih/Süre Objeleri (Date)
  if (v instanceof Date || (v && typeof v.getTime === 'function')) {
    const d = new Date(v);
    const year = d.getFullYear();

    // Google Sheets '0' süresini 1899-12-30 olarak saklar.
    // Eğer yıl 1899 veya 1900 ise bu çöp veridir.
    if (year === 1899 || year === 1900) return null;

    // Eğer yıl 2020 ve üzeriyse bu gerçek bir takvim tarihidir (Örn: 8/28/2025), saat değildir.
    if (year > 2020) return null;

    // Küçük yıl değerleri (1899-1910 arası) Sheets süre temsilidir.
    if (year >= 1899 && year < 1910) {
      const base = new Date(1899, 11, 30, 0, 0, 0);
      val = (d.getTime() - base.getTime()) / (1000 * 60 * 60);
    }
  } 
  // 2. Metin veya Sayı Formatı
  else {
    const s = String(v).trim().replace(',', '.');

    // HH:MM formatı (218:50)
    if (s.includes(':')) {
      const parts = s.split(':');
      const h = parseFloat(parts[0]) || 0;
      const m = parseFloat(parts[1]) || 0;
      const sec = parts.length > 2 ? parseFloat(parts[2]) || 0 : 0;
      val = h + (m / 60) + (sec / 3600);
    } 
    // Düz Sayı
    else {
      const n = parseFloat(s);
      if (!isNaN(n)) val = n;
    }
  }

  // VALIDASYON VE KATI ARTIFACT FİLTRESİ
  if (val === null || isNaN(val) || val <= 0.001) return null;

  // ÇOK ÖNEMLİ: Eğer hesaplanan saat tam olarak 1899 veya 1900 ise bu bir 'Yıl' artifactidir.
  // Sheets'teki boş hücreler bazen 1899.0 olarak sayıya döner.
  const rounded = Math.round(val);
  if (rounded === 1899 || rounded === 1900 || rounded === 1) return null;

  // 20.000'den büyük sayılar muhtemelen Excel tarih seri numaralarıdır (Tarih verisidir, saat değil).
  if (val > 20000) return null;

  return val;
};

/**
 * V:AI aralığını tarar, artifactları eler ve EN KÜÇÜK (MIN) değeri bulur.
 */
export const fetchAircraftDataFromAppsScript = async (url: string, config: SheetConfig): Promise<Partial<Aircraft>[]> => {
  try {
    const response = await fetch(url, {
      method: 'POST',
      headers: { 'Content-Type': 'text/plain;charset=utf-8' },
      body: JSON.stringify({
        sheetId: config.sheetId,
        sheetName: config.sheetName,
        mapping: config.mapping
      })
    });

    if (!response.ok) throw new Error(`HTTP Error: ${response.status}`);

    const data = await response.json();
    if (data.error || !Array.isArray(data)) return [];

    return data.map((item: any) => {
      const analysis = analyzeStatus(item);
      const kuyrukNo = String(item.kuyrukNo || '').trim();

      let finalFaydaliValue = 0;

      // V:AI ARALIĞINI TARAMA (Dizi olarak bekliyoruz)
      if (Array.isArray(item.faydaliSaat)) {
        const flatCells = item.faydaliSaat.flat();

        // Sadece geçerli saatleri filtrele (1899, 1900, 0 ve Tarihler elendi)
        const validHours = flatCells
          .map(cell => parseToNumericHour(cell))
          .filter((v): v is number => v !== null && v > 0);

        // Geçerli saatlerin en küçüğünü seç
        if (validHours.length > 0) {
          finalFaydaliValue = Math.min(...validHours);
        }
      } else {
        // Tek hücre gelirse
        finalFaydaliValue = parseToNumericHour(item.faydaliSaat) || 0;
      }

      // 1900 sonucunun hala çıkma ihtimaline karşı son bir baraj:
      if (finalFaydaliValue === 1900 || finalFaydaliValue === 1899) {
        finalFaydaliValue = 0;
      }

      const finalHour = Math.floor(finalFaydaliValue);

      return {
        kuyrukNo: kuyrukNo,
        cagriKodu: `ORMAN-${kuyrukNo.split('-')[1] || 'XX'}`,
        durum: (analysis.code !== 'F') ? Status.GAYRI_FAAL : Status.FAAL,
        durumTipi: analysis.code === 'B' || analysis.code === 'BB' ? StatusType.BAKIM : 
                   analysis.code === 'A' || analysis.code === 'PB' ? StatusType.ARIZA : StatusType.NONE,
        durumAyrintisi: String(item.durumAyrintisi || '-'),
        konum: String(item.konum || 'ANKARA'),
        faydaliSaat: finalHour, 
        govdeUcusSaati: String(item.govdeUcusSaati || '-'),
        aciklama: String(item.aciklama || ''),
        guncellemeTarihi: new Date().toLocaleString('tr-TR'),
        durumBaslangic: new Date().toISOString().split('T')[0],
        maintenanceHours: [{ bakimTuru: 'PERİYODİK', kalanSaat: finalHour }],
        photos: [`https://picsum.photos/seed/${kuyrukNo}/800/600`],
        platformTipi: 'H',
        tip: config.aircraftType,
        assignedCode: analysis.code,
        aiInterpretation: analysis.interpretation
      };
    });
  } catch (error) {
    console.error("Faydalı saat işleme kritik hatası:", error);
    return [];
  }
};

import { SheetConfig, Aircraft, Status, StatusType, DailyStatusCode } from '../types';

/**
 * Durum metinlerini analiz ederek faaliyet kodunu belirler.
 */
export const analyzeStatus = (item: any): { code: DailyStatusCode, interpretation: string } => {
  const detail = String(item.durumAyrintisi || '').toLocaleLowerCase('tr-TR').trim();
  const desc = String(item.aciklama || '').toLocaleLowerCase('tr-TR').trim();
  const durumStr = String(item.durum || '').toLocaleUpperCase('tr-TR').trim();
  const fullText = `${detail} ${desc}`;

  if (fullText.includes('kaza') || fullText.includes('kırım') || fullText.includes('hasar')) 
    return { code: 'KK', interpretation: 'Kaza/Kırım tespiti.' };

  if (fullText.includes('parça') && (fullText.includes('bekle') || fullText.includes('sipariş'))) {
    return { code: 'PB', interpretation: 'Parça Bekler.' };
  }

  if (fullText.includes('bakım') || fullText.includes('yıllık') || fullText.includes('periyodik') || /\b\d+h\b/.test(fullText)) {
    if (fullText.includes('bekliyor') || fullText.includes('sıra')) {
      return { code: 'BB', interpretation: 'Bakım Bekler.' };
    }
    return { code: 'B', interpretation: 'Bakımda.' };
  }

  if (fullText.includes('arıza') || fullText.includes('problem')) 
    return { code: 'A', interpretation: 'Arıza.' };

  const isGayriFaalExplicit = durumStr.includes('GAYRİ') || durumStr.includes('GAYRI') || durumStr.includes('G.FAAL');
  if (isGayriFaalExplicit) return { code: 'X', interpretation: 'Gayrı Faal.' };

  return { code: 'F', interpretation: 'Faal.' };
};

/**
 * Hücre değerini sayısal saate çevirir.
 * 1899, 1900 ve 1000+ gibi çöp verileri KESİN olarak reddeder.
 */
const parseToNumericHour = (v: any): number | null => {
  // Temel boş ve sıfır kontrolleri (Taviz yok)
  if (v === null || v === undefined || v === '' || v === 0 || v === "0" || v === "N/A" || v === "00:00") return null;

  let calculatedVal: number | null = null;

  // 1. Google Sheets Tarih/Süre Objeleri (Date)
  if (v instanceof Date || (v && typeof v.getTime === 'function')) {
    const d = new Date(v);
    const year = d.getFullYear();

    // Yıl 1899 veya 1900 ise bu Google Sheets'in boş süre artifact'idir.
    if (year === 1899 || year === 1900) return null;

    // Modern bir tarih ise (8/28/2025 gibi), bu bir saat verisi değildir.
    if (year > 2020) return null;

    // Süre temsili olan yılları (1899-1910) saate çevir
    const base = new Date(1899, 11, 30, 0, 0, 0);
    calculatedVal = (d.getTime() - base.getTime()) / (1000 * 60 * 60);
  } 
  // 2. Metin veya Sayı Formatı
  else {
    const s = String(v).trim().replace(',', '.');

    // HH:MM:SS veya HH:MM formatı (218:50)
    if (s.includes(':')) {
      const parts = s.split(':');
      const h = parseFloat(parts[0]) || 0;
      const m = parseFloat(parts[1]) || 0;
      const sec = parts.length > 2 ? parseFloat(parts[2]) || 0 : 0;
      calculatedVal = h + (m / 60) + (sec / 3600);
    } 
    // Düz Sayı
    else {
      const n = parseFloat(s);
      if (!isNaN(n)) calculatedVal = n;
    }
  }

  // VALIDASYON VE KATI ARTIFACT FİLTRELEME (1000+ Kuralı Dahil)
  if (calculatedVal === null || isNaN(calculatedVal)) return null;

  // Kural: 0 veya negatif olamaz
  if (calculatedVal <= 0.0001) return null;

  // Kural: 1899 / 1900 sayısal değer olarak geldiyse çöp veridir
  const rounded = Math.round(calculatedVal);
  if (rounded === 1899 || rounded === 1900) return null;

  // KRİTİK SINIR KURALI: Faydalı saat 1000 veya üzeri OLAMAZ.
  // Bu değerler genellikle hatalı tarih eşleşmeleridir.
  if (calculatedVal >= 1000) return null;

  return calculatedVal;
};

/**
 * Apps Script'ten verileri çeker ve V:AI aralığındaki EN KÜÇÜK TEMİZ saati hesaplar.
 */
export const fetchAircraftDataFromAppsScript = async (url: string, config: SheetConfig): Promise<Partial<Aircraft>[]> => {
  try {
    const response = await fetch(url, {
      method: 'POST',
      headers: { 'Content-Type': 'text/plain;charset=utf-8' },
      body: JSON.stringify({
        sheetId: config.sheetId,
        sheetName: config.sheetName,
        mapping: config.mapping
      })
    });

    if (!response.ok) throw new Error(`HTTP Error: ${response.status}`);

    const data = await response.json();
    if (data.error || !Array.isArray(data)) return [];

    return data.map((item: any) => {
      const analysis = analyzeStatus(item);
      const kuyrukNo = String(item.kuyrukNo || '').trim();

      let finalMinHour = 0;

      // V:AI ARALIĞINI TARAMA
      if (Array.isArray(item.faydaliSaat)) {
        const flatCells = item.faydaliSaat.flat();

        // Sadece temizlenmiş, geçerli saatleri filtrele
        const validHours = flatCells
          .map(cell => parseToNumericHour(cell))
          .filter((v): v is number => v !== null && v > 0);

        // Temiz dizi doluysa sadece oradaki MIN değeri al
        if (validHours.length > 0) {
          finalMinHour = Math.min(...validHours);
        }
      } else {
        // Tek bir değer gelirse (V:AI yerine tek hücre atanmışsa)
        finalMinHour = parseToNumericHour(item.faydaliSaat) || 0;
      }

      // Final Check: Eğer sonuç her şeye rağmen 1000+ veya 1900 ise sıfırla
      if (finalMinHour >= 1000 || Math.round(finalMinHour) === 1900 || Math.round(finalMinHour) === 1899) {
        finalMinHour = 0;
      }

      const finalHourInteger = Math.floor(finalMinHour);

      return {
        kuyrukNo: kuyrukNo,
        cagriKodu: `ORMAN-${kuyrukNo.split('-')[1] || 'XX'}`,
        durum: (analysis.code !== 'F') ? Status.GAYRI_FAAL : Status.FAAL,
        durumTipi: analysis.code === 'B' || analysis.code === 'BB' ? StatusType.BAKIM : 
                   analysis.code === 'A' || analysis.code === 'PB' ? StatusType.ARIZA : StatusType.NONE,
        durumAyrintisi: String(item.durumAyrintisi || '-'),
        konum: String(item.konum || 'ANKARA'),
        faydaliSaat: finalHourInteger, 
        govdeUcusSaati: String(item.govdeUcusSaati || '-'),
        aciklama: String(item.aciklama || ''),
        guncellemeTarihi: new Date().toLocaleString('tr-TR'),
        durumBaslangic: new Date().toISOString().split('T')[0],
        maintenanceHours: [{ bakimTuru: 'PERİYODİK', kalanSaat: finalHourInteger }],
        photos: [`https://picsum.photos/seed/${kuyrukNo}/800/600`],
        platformTipi: 'H',
        tip: config.aircraftType,
        assignedCode: analysis.code,
        aiInterpretation: analysis.interpretation
      };
    });
  } catch (error) {
    console.error("Faydalı saat işleme kritik hatası:", error);
    return [];
  }
};

