      hours = h + (m / 60);
    } else {
      const n = Number(s);
      if (!isNaN(n)) {
        hours = n < 10 ? n * 24 : n;
      }
    }
  }

  if (!hours || isNaN(hours)) return null;
  if (hours < 0.1) return null;
  if (hours >= 1000) return null;

  return hours;
};

