import { SheetConfig, Aircraft, Status, StatusType, DailyStatusCode } from '../types';

/**
 * Durum metinlerini analiz ederek faaliyet kodunu belirler.
 */
export const analyzeStatus = (item: any): { code: DailyStatusCode, interpretation: string } => {
  const detail = String(item.durumAyrintisi || '').toLocaleLowerCase('tr-TR').trim();
  const desc = String(item.aciklama || '').toLocaleLowerCase('tr-TR').trim();
  const durumStr = String(item.durum || '').toLocaleUpperCase('tr-TR').trim();
  const fullText = `${detail} ${desc}`;

  if (fullText.includes('kaza') || fullText.includes('kırım') || fullText.includes('hasar')) 
    return { code: 'KK', interpretation: 'Kaza/Kırım tespiti.' };

  if (fullText.includes('parça') && (fullText.includes('bekle') || fullText.includes('sipariş'))) {
    return { code: 'PB', interpretation: 'Parça Bekler.' };
  }

  if (fullText.includes('bakım') || fullText.includes('yıllık') || fullText.includes('periyodik') || /\b\d+h\b/.test(fullText)) {
    if (fullText.includes('bekliyor') || fullText.includes('sıra')) {
      return { code: 'BB', interpretation: 'Bakım Bekler.' };
    }
    return { code: 'B', interpretation: 'Bakımda.' };
  }

  if (fullText.includes('arıza') || fullText.includes('problem')) 
    return { code: 'A', interpretation: 'Arıza.' };

  const isGayriFaalExplicit = durumStr.includes('GAYRİ') || durumStr.includes('GAYRI') || durumStr.includes('G.FAAL');
  if (isGayriFaalExplicit) return { code: 'X', interpretation: 'Gayrı Faal.' };

  return { code: 'F', interpretation: 'Faal.' };
};

/**
 * Google Sheets'ten gelen karmaşık veriyi (Gün, Saat, String, Date) 
 * temiz bir sayısal saate çevirir. 
 */
const parseSingleCellToHour = (val: any): number | null => {
  // 0, "", null, undefined -> geçersiz
  if (val === null || val === undefined || val === '' || val === 0 || val === "0" || val === "00:00") return null;

  let totalHours: number | null = null;

  // 1. DATE OBJESİ (Sheets Süreleri: 1899-12-30T...)
  if (val instanceof Date || (val && typeof val.getTime === 'function')) {
    const d = new Date(val);
    const year = d.getFullYear();

    // Yıl 1899 veya 1900 ise bu kesinlikle bir "Duration" (Süre) verisidir
    if (year === 1899 || year === 1900) {
      // Base date 1899-12-30'dur. Aradaki fark milisaniye cinsinden süreyi verir.
      const base = new Date(1899, 11, 30, 0, 0, 0);
      totalHours = (d.getTime() - base.getTime()) / (1000 * 60 * 60);
    } else if (year > 2020) {
      // 2025 gibi bir yıl varsa bu gerçek bir tarihtir, saat değildir.
      return null;
    }
  } 
  // 2. SAYISAL DEĞER (Sheets 59:00'u "2.4583" gün olarak gönderebilir)
  else if (typeof val === 'number') {
    // 1000'den büyükse muhtemelen Date Serial'dır (Örn: 45680). 
    // Havacılıkta kalan saat 1000 olamaz.
    if (val >= 1000) return null;

    // Altın Kural: Sheets veriyi "GÜN" olarak saklar. 
    // Eğer sayı 10'dan küçükse (Örn: 2.45) bu kesinlikle gündür, 24 ile çarp.
    // Eğer sayı 10-1000 arasındaysa zaten "saat" olarak girilmiş olabilir.
    totalHours = val < 10 ? val * 24 : val;
  }
  // 3. METİNSEL DEĞER ("59:00", "59" vb.)
  else if (typeof val === 'string') {
    const s = val.trim().replace(',', '.');
    if (s.includes(':')) {
      const parts = s.split(':').map(Number);
      totalHours = (parts[0] || 0) + ((parts[1] || 0) / 60);
    } else {
      const n = parseFloat(s);
      if (!isNaN(n)) {
        totalHours = n < 10 ? n * 24 : n;
      }
    }
  }

  // Final Temizlik: Çok küçük (0.05 saat ~ 3dk) veya aşırı büyük değerleri eliyoruz.
  if (totalHours === null || isNaN(totalHours) || totalHours <= 0.05 || totalHours >= 1000) return null;

  return totalHours;
};

/**
 * Apps Script'ten verileri çeker. Her uçağın (satırın) kendi V:AI aralığını tarar.
 */
export const fetchAircraftDataFromAppsScript = async (url: string, config: SheetConfig): Promise<Partial<Aircraft>[]> => {
  try {
    const response = await fetch(url, {
      method: 'POST',
      headers: { 'Content-Type': 'text/plain;charset=utf-8' },
      body: JSON.stringify({
        sheetId: config.sheetId,
        sheetName: config.sheetName || '',
        mapping: config.mapping
      })
    });

    if (!response.ok) throw new Error(`HTTP ${response.status}`);

    const data = await response.json();
    if (!data || data.error || !Array.isArray(data)) return [];

    return data.map((item: any) => {
      const analysis = analyzeStatus(item);
      const kuyrukNo = String(item.kuyrukNo || '').trim();

      // V:AI aralığı Apps Script'ten her satır için bir dizi olarak gelir.
      // Örn: item.faydaliSaat = [0, 59, "00:00", 2.45, null...]
      const rowCells = Array.isArray(item.faydaliSaat) 
        ? item.faydaliSaat.flat(Infinity) 
        : [item.faydaliSaat];

      // SADECE BU SATIRIN verilerini işle
      const validHours = rowCells
        .map(cell => parseSingleCellToHour(cell))
        .filter((h): h is number => h !== null);

      // Bu satırdaki EN KÜÇÜK saati bul. Veri yoksa null döner.
      const finalMinHour = validHours.length > 0 ? Math.min(...validHours) : null;
      const hourInt = finalMinHour !== null ? Math.floor(finalMinHour) : null;

      return {
        kuyrukNo: kuyrukNo,
        cagriKodu: `ORMAN-${kuyrukNo.split('-')[1] || 'XX'}`,
        durum: (analysis.code !== 'F') ? Status.GAYRI_FAAL : Status.FAAL,
        durumTipi: (analysis.code === 'B' || analysis.code === 'BB') ? StatusType.BAKIM : 
                   (analysis.code === 'A' || analysis.code === 'PB') ? StatusType.ARIZA : StatusType.NONE,
        durumAyrintisi: String(item.durumAyrintisi || '-'),
        konum: String(item.konum || 'ANKARA'),
        faydaliSaat: hourInt, 
        govdeUcusSaati: String(item.govdeUcusSaati || '-'),
        aciklama: String(item.aciklama || ''),
        guncellemeTarihi: new Date().toLocaleString('tr-TR'),
        durumBaslangic: new Date().toISOString().split('T')[0],
        maintenanceHours: [{ bakimTuru: 'KALAN', kalanSaat: hourInt || 0 }],
        photos: [`https://picsum.photos/seed/${kuyrukNo}/800/600`],
        platformTipi: 'H',
        tip: config.aircraftType,
        assignedCode: analysis.code,
        aiInterpretation: analysis.interpretation
      };
    });
  } catch (error) {
