/**
 * Google Sheets'ten gelen karmaşık veriyi (Örn: "2.01.1900 11:00:00") 
 * kesin bir sayısal saate (Örn: 59) çevirir.
 */
const parseSingleCellToHour = (val: any): number | null => {
  if (val === null || val === undefined || val === '' || val === 0 || val === "0" || val === "00:00") return null;

  let totalHours: number | null = null;

  // 1. DATE OBJESİ (Apps Script'ten gelen ham Date)
  if (val instanceof Date || (val && typeof val.getTime === 'function')) {
    const d = new Date(val);
    const year = d.getFullYear();
    // 1899/1900 yılları Sheets süre başlangıcıdır
    if (year <= 1905) {
      const base = new Date(1899, 11, 30, 0, 0, 0);
      totalHours = (d.getTime() - base.getTime()) / (1000 * 60 * 60);
    } else {
      return null; // Gerçek takvim tarihi
    }
  } 
  // 2. SAYISAL DEĞER (Sheets süreleri "Gün" biriminde sayı döner. Örn: 2.4583 = 59 saat)
  else if (typeof val === 'number') {
    if (val >= 1000) return null; // Date serial filtering (45000+ is year 2023+)
    // Sayı 10'dan küçükse GÜN'dür (Örn: 2.45), saate çevir.
    totalHours = val < 10 ? val * 24 : val;
  }
  // 3. METİNSEL DEĞER (Örn: "2.01.1900 11:00:00" veya "59:00:00")
  else if (typeof val === 'string') {
    const s = val.trim().replace(',', '.');

    // Format: "2.01.1900 11:00:00"
    if (s.includes('.') && s.includes(':')) {
      try {
        const [datePart, timePart] = s.split(' ');
        const [d, m, y] = datePart.split('.').map(Number);
        const [hh, mm, ss] = timePart.split(':').map(Number);
        if (y <= 1905) {
          const dt = new Date(y, m - 1, d, hh, mm, ss || 0);
          const base = new Date(1899, 11, 30, 0, 0, 0);
          totalHours = (dt.getTime() - base.getTime()) / (1000 * 60 * 60);
        }
      } catch (e) { return null; }
    }
    // Format: "59:00:00"
    else if (s.includes(':')) {
      const parts = s.split(':').map(Number);
      totalHours = (parts[0] || 0) + (parts[1] || 0) / 60 + (parts[2] || 0) / 3600;
    } 
    // Düz Rakam: "59"
    else {
      const n = parseFloat(s);
      if (!isNaN(n)) {
        totalHours = n < 10 ? n * 24 : n;
      }
    }
  }

  // Temizlik ve Limitler
  if (totalHours === null || isNaN(totalHours) || totalHours <= 0.01 || totalHours >= 1000) return null;

  return totalHours;
};

