    const d = new Date(val);
    if (isNaN(d.getTime())) return null;

    const base = new Date(Date.UTC(1899, 11, 30, 0, 0, 0));
    const diffMs = d.getTime() - base.getTime();
    const hours = diffMs / (1000 * 60 * 60);

    return hours > 0 && hours < 1000 ? hours : null;
  }

  // 2️⃣ Date objesi (lokalde test vs.)
  if (val instanceof Date) {
    const base = new Date(1899, 11, 30, 0, 0, 0);
    const diffMs = val.getTime() - base.getTime();
    const hours = diffMs / (1000 * 60 * 60);
    return hours > 0 && hours < 1000 ? hours : null;
  }

  // 3️⃣ String → 59:00:00
  if (typeof val === 'string' && val.includes(':')) {
    const parts = val.split(':').map(Number);
    const h = parts[0] || 0;
    const m = parts[1] || 0;
    const s = parts[2] || 0;
    const total = h + m / 60 + s / 3600;
    return total > 0 ? total : null;
  }

