             <ActivityGrid activities={activities} startDate={new Date(2025, 0, 1)} endDate={new Date(2025, 0, 31)} title="OCAK 2025" onExport={() => exportTableToExcel('activity-table', 'OGM_Faaliyet_Raporu_Ocak_2025')} />
