/**
 * Saat değerini HH:mm formatına çevirir (Örn: 159.83 -> 159:50)
 */
const formatToHHMM = (totalHours: number | null): string => {
  if (totalHours === null) return '-';
  const hours = Math.floor(totalHours);
  const minutes = Math.round((totalHours - hours) * 60);
  return `${hours}:${minutes.toString().padStart(2, '0')}`;
};

/**
 * Hücre değerini sayısal saate çevirir (1899-12-30 tarih bazlı süreler için)
 */
const parseSingleCellToHour = (val: any, aircraftType: string): number | null => {
  if (val === undefined || val === null || val === "" || val === "0" || val === "00:00") return null;

  let d: Date | null = null;
  if (typeof val === 'string' && val.includes('T') && val.includes('Z')) {
    d = new Date(val);
  } else if (val instanceof Date || (val && typeof val.getTime === 'function')) {
    d = new Date(val);
  }

  // Google Sheets "Duration" (Süre) formatı genelde 1899-12-30 bazlı bir Date olarak gelir
  if (d && !isNaN(d.getTime())) {
    const year = d.getUTCFullYear();
    if (year === 1899 || year === 1900) {
      const base = new Date(Date.UTC(1899, 11, 30, 0, 0, 0));
      const diffMs = d.getTime() - base.getTime();
      const hours = diffMs / (1000 * 60 * 60);
      return hours > 0 ? hours : null;
    }
  }

  if (typeof val === 'number') {
    if (val <= 0) return null;
    // Eğer değer 1'den küçükse büyük ihtimalle Sheets gün değeridir (0.5 = 12 saat)
    if (val < 200 && aircraftType === 'AT-802') {
      return val * 24;
    }
    return val;
  }

  if (typeof val === 'string') {
    const s = val.trim().replace(',', '.');
    if (s.includes(':')) {
      const parts = s.split(':').map(Number);
      const h = parts[0] || 0;
      const m = parts[1] || 0;
      const sec = parts[2] || 0;
      const total = h + m / 60 + sec / 3600;
      return total > 0 ? total : null;
    }
    const n = parseFloat(s);
    if (!isNaN(n)) return n;
  }

  return null;
};

/**
