function doPost(e) {
  try {
    var contents = JSON.parse(e.postData.contents);
    var ss = SpreadsheetApp.openById(contents.sheetId);
    var sheetName = contents.sheetName;
    // Sayfa ismi varsa onu al, yoksa ilk sayfayı al
    var sheet = sheetName ? ss.getSheetByName(sheetName) : ss.getSheets()[0];
    var mapping = contents.mapping;

    var fieldData = {};
    var maxRows = 0;

    // Dinamik Eşleme: Frontend'den gelen her bir anahtar için veriyi çek
    for (var key in mapping) {
      if (mapping[key]) {
        var range = sheet.getRange(mapping[key]);
        var vals = range.getValues();
        fieldData[key] = vals;
        if (vals.length > maxRows) maxRows = vals.length;
      }
    }

    var results = [];
    for (var i = 0; i < maxRows; i++) {
      var item = {};
      var hasKuyruk = false;

      for (var key in fieldData) {
        var dataRow = fieldData[key][i];
        if (dataRow) {
          // Tek kolon ise direkt değer, çoklu kolon ise (V:AI gibi) dizi olarak döndür
          item[key] = (dataRow.length === 1) ? dataRow[0] : dataRow;

          // Satırın dolu olduğunu kuyrukNo'dan anlıyoruz
          if (key === 'kuyrukNo' && dataRow[0]) {
            hasKuyruk = true;
          }
        }
      }

      if (hasKuyruk) {
        results.push(item);
      }
    }

    return ContentService.createTextOutput(JSON.stringify(results))
      .setMimeType(ContentService.MimeType.JSON);
  } catch (err) {
    return ContentService.createTextOutput(JSON.stringify({ error: err.toString() }))
      .setMimeType(ContentService.MimeType.JSON);
  }
}

function doGet(e) {
  return ContentService.createTextOutput("Script Aktif. Dinamik Eşleme Modu Çalışıyor.");
}
