export default App;

import { SheetConfig, Aircraft, Status, StatusType, DailyStatusCode } from '../types';

/**
 * Durum metinlerini analiz ederek faaliyet kodunu belirler.
 */
export const analyzeStatus = (item: any): { code: DailyStatusCode, interpretation: string } => {
  const detail = String(item.durumAyrintisi || '').toLocaleLowerCase('tr-TR').trim();
  const desc = String(item.aciklama || '').toLocaleLowerCase('tr-TR').trim();
  const durumStr = String(item.durum || '').toLocaleUpperCase('tr-TR').trim();
  const fullText = `${detail} ${desc}`;

  if (fullText.includes('kaza') || fullText.includes('kırım') || fullText.includes('hasar')) 
    return { code: 'KK', interpretation: 'Kaza/Kırım tespiti.' };

  if (fullText.includes('parça') && (fullText.includes('bekle') || fullText.includes('sipariş'))) {
    return { code: 'PB', interpretation: 'Parça Bekler.' };
  }

  if (fullText.includes('bakım') || fullText.includes('yıllık') || fullText.includes('periyodik') || /\b\d+h\b/.test(fullText)) {
    if (fullText.includes('bekliyor') || fullText.includes('sıra')) {
      return { code: 'BB', interpretation: 'Bakım Bekler.' };
    }
    return { code: 'B', interpretation: 'Bakımda.' };
  }

  if (fullText.includes('ariiza') || fullText.includes('problem') || fullText.includes('arıza')) 
    return { code: 'A', interpretation: 'Arıza.' };

  const isGayriFaalExplicit = durumStr.includes('GAYRİ') || durumStr.includes('GAYRI') || durumStr.includes('G.FAAL');
  if (isGayriFaalExplicit) return { code: 'X', interpretation: 'Gayrı Faal.' };

  return { code: 'F', interpretation: 'Faal.' };
};

const formatToHHMM = (totalHours: number | null): string => {
  if (totalHours === null) return '-';
  const hours = Math.floor(totalHours);
  const minutes = Math.round((totalHours - hours) * 60);
  return `${hours}:${minutes.toString().padStart(2, '0')}`;
};

const formatValueToString = (val: any): string => {
  if (val === undefined || val === null || val === "" || val === "0") return '-';
  if (Array.isArray(val)) return formatValueToString(val[0]);

  const s = String(val).trim();
  // ISO Tarih kontrolü
  if (s.includes('T') && s.includes('Z')) {
    const d = new Date(s);
    if (!isNaN(d.getTime())) return d.toLocaleDateString('tr-TR');
  }
  return s;
};

const parseSingleCellToHour = (val: any, aircraftType: string): number | null => {
  if (val === undefined || val === null || val === "" || val === "0" || val === "00:00") return null;

  if (typeof val === 'number') {
    if (val <= 0) return null;
    if (val < 100 && aircraftType === 'AT-802') return val * 24;
    return val;
  }

  if (typeof val === 'string') {
    const s = val.trim().replace(',', '.');
    if (s.includes(':')) {
      const parts = s.split(':').map(Number);
      if (parts.length >= 2) return parts[0] + parts[1] / 60;
    }
    const n = parseFloat(s);
    if (!isNaN(n)) return n;
  }
  return null;
};

const formatGovdeHour = (val: any, aircraftType: string): string => {
  const deepFlatten = (v: any): any => {
    if (Array.isArray(v)) return v.length > 0 ? deepFlatten(v[0]) : null;
    return v;
  };
  const raw = deepFlatten(val);
  if (raw === undefined || raw === null || String(raw).trim() === "" || String(raw).trim() === "0") return "-";

  const parsed = parseSingleCellToHour(raw, aircraftType);
  if (parsed !== null) {
    if (aircraftType === 'AT-802') return formatToHHMM(parsed);
    return parsed.toFixed(1).replace('.', ':');
  }
  return String(raw).trim().replace(',', ':').replace('.', ':');
};

export const fetchAircraftDataFromAppsScript = async (url: string, config: SheetConfig): Promise<Partial<Aircraft>[]> => {
  try {
    const response = await fetch(url, {
      method: 'POST',
      headers: { 'Content-Type': 'text/plain;charset=utf-8' },
      body: JSON.stringify({
        sheetId: config.sheetId,
        sheetName: config.sheetName || '',
        mapping: config.mapping
      })
    });

    const data = await response.json();
    if (!data || data.error) return [];

    const now = new Date();
    const timestamp = now.toLocaleDateString('tr-TR') + ' ' + now.toLocaleTimeString('tr-TR', { hour: '2-digit', minute: '2-digit' });

    return data.map((item: any) => {
      const analysis = analyzeStatus(item);
      const kuyrukNo = String(item.kuyrukNo || '').trim();

      const faydaliRaw = Array.isArray(item.faydaliSaat) ? item.faydaliSaat.flat(Infinity) : [item.faydaliSaat];
      const validHours = faydaliRaw.map(v => parseSingleCellToHour(v, config.aircraftType)).filter((h): h is number => h !== null);
      const minHour = validHours.length > 0 ? Math.min(...validHours) : null;

      const result: Partial<Aircraft> = {
        kuyrukNo,
        cagriKodu: `ORMAN-${kuyrukNo.split('-')[1] || 'XX'}`,
        durum: (analysis.code !== 'F') ? Status.GAYRI_FAAL : Status.FAAL,
        durumTipi: (analysis.code === 'B' || analysis.code === 'BB') ? StatusType.BAKIM : 
                   (analysis.code === 'A' || analysis.code === 'PB') ? StatusType.ARIZA : StatusType.NONE,
        durumAyrintisi: String(item.durumAyrintisi || '-'),
        konum: String(item.konum || 'ANKARA'),
        faydaliSaat: minHour !== null ? Math.floor(minHour) : null,
        govdeUcusSaati: formatGovdeHour(item.govdeUcusSaati, config.aircraftType),
        aciklama: String(item.aciklama || ''),
        guncellemeTarihi: timestamp,
        durumBaslangic: new Date().toISOString().split('T')[0],
        maintenanceHours: [{ bakimTuru: 'KALAN', kalanSaat: minHour !== null ? Math.floor(minHour) : 0 }],
        photos: [`https://picsum.photos/seed/${kuyrukNo}/800/600`],
        tip: config.aircraftType,
        platformTipi: 'H',
        assignedCode: analysis.code,
        seriNo: formatValueToString(item.seriNo || item.govdeSN),
        motor: config.aircraftType === 'Bell-429' ? '2x Pratt & Whitney PW207D1' : formatValueToString(item.motor),
        uretimYili: Number(item.uretimYili) || 0
      };

      if (config.aircraftType === 'Bell-429') {
        result.govdeSN = formatValueToString(item.govdeSN);
        result.motor1SN = formatValueToString(item.motor1SN);
        result.motor2SN = formatValueToString(item.motor2SN);
        result.motor1UcusSaati = formatGovdeHour(item.motor1UcusSaati, config.aircraftType);
        result.motor2UcusSaati = formatGovdeHour(item.motor2UcusSaati, config.aircraftType);
        result.bakim50H = formatValueToString(item.bakim50H);
        result.bakimTakvim = formatValueToString(item.bakimTakvim);
      }

      if (config.aircraftType === 'AT-802') {
        result.at802Bakimlar = {
          kalan25H: formatGovdeHour(item.kalan25H, config.aircraftType),
          kalan50H: formatGovdeHour(item.kalan50H, config.aircraftType),
          kalan100H: formatGovdeHour(item.kalan100H, config.aircraftType),
          kalan200H: formatGovdeHour(item.kalan200H, config.aircraftType),
          kalan300H: formatGovdeHour(item.kalan300H, config.aircraftType),
          kalan300M: formatGovdeHour(item.kalan300M, config.aircraftType),
          kalan400H: formatGovdeHour(item.kalan400H, config.aircraftType),
          kalan800H: formatGovdeHour(item.kalan800H, config.aircraftType),
          kalan1000H: formatGovdeHour(item.kalan1000H, config.aircraftType),
          yillikBakim: formatValueToString(item.yillikBakim)
        };
      }

      return result;
    });
  } catch (error) {
    console.error(`Sync Hatası:`, error);
    return [];
  }
};

