function doPost(e) {
  try {
    var params = JSON.parse(e.postData.contents);
    var sheetId = params.sheetId;
    var sheetName = params.sheetName;
    var mapping = params.mapping;

    var ss = SpreadsheetApp.openById(sheetId);
    var sheet = sheetName ? ss.getSheetByName(sheetName) : ss.getSheets()[0];

    var results = [];
    var keys = Object.keys(mapping);

    // Veri aralıklarını bir kerede çekelim (performans için)
    var ranges = {};
    keys.forEach(function(key) {
      ranges[key] = sheet.getRange(mapping[key]).getValues();
    });

    // Satır sayısını belirle (ilk sütun aralığına göre)
    var rowCount = ranges[keys[0]].length;

